window.AIEP={"groups":[{"id":"base","name":"배움터·클래스룸","lead":"배움터 화면과 클래스, 구글 클래스룸 연결을 다뤄요. 다른 도구를 쓸 때도 바탕이 돼요.","keys":["aischool","googleclassroom"]},{"id":"make","name":"자료·작품 만들기","lead":"수업 자료와 학생 작품을 만드는 도구","keys":["miricanvas","canva","vrew","bookcreator","wetoon"]},{"id":"quiz","name":"퀴즈·게임 수업","lead":"실시간 퀴즈와 게임으로 참여를 끌어내는 도구","keys":["quizn","zepquiz","tkbell","classgame"]},{"id":"subject","name":"영어·수학·글쓰기","lead":"영어 독서와 단어, 수학 학습지, 글쓰기를 돕는 도구","keys":["readingn","vocatrain","matamath","jajak"]},{"id":"etc","name":"탐구·정리·마음·코딩","lead":"백과 찾기, 학급 운영 노트, 마음일기, 코딩 수업에 쓰는 도구","keys":["doopedia","notion","aidiary","codle"]}],"decks":[{"key":"aischool","name":"경북AI배움터","title":"경북AI배움터 사용 안내서 · 플랫폼 기본편","group":"base","sub":"클래스 · 과제 · 수업꾸러미로 한 차시 수업 꾸리기","fee":"","feeKind":"","feeNote":"","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 경북AI배움터 사이트 구조 한눈에 보기"},{"start":4,"num":"1","label":"배움터 시작하기","desc":"배움터에 로그인하고 메인 화면, 메뉴, 내 메뉴, 화면 구성을 살펴봐요"},{"start":12,"num":"2","label":"클래스","desc":"AI 교수학습 플랫폼에서 클래스를 고르고 클래스 홈과 관리 메뉴를 익혀요"},{"start":19,"num":"3","label":"자료와 과제","desc":"개별과제와 자료과제를 만들고 제출 현황을 확인해요"},{"start":28,"num":"4","label":"수업꾸러미","desc":"수업꾸러미를 만들어 클래스에 등록해요"},{"start":39,"num":"5","label":"알림과 누가기록","desc":"알림, 누가기록, 우리반 홈을 써요"},{"start":43,"num":"6","label":"콘텐츠와 대시보드","desc":"수업콘텐츠, LCMS, 자료실, 대시보드를 둘러봐요"},{"start":49,"num":"","label":"마무리","desc":"유의사항, 수업 활용 아이디어, 마무리"}],"slides":[{"n":1,"t":"경북AI배움터 사용 안내서","sec":0,"x":"AIEP 석적초 교내 연수 · 플랫폼 기본편 / 클래스 · 과제 · 수업꾸러미로 한 차시 수업 꾸리기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 에듀테크 도구 하나가 아니라 경북AI배움터라는 플랫폼 자체를 함께 살펴보겠습니다. 배움터 메인에서 시작해서, AI 교수학습 플랫폼의 클래스에 자료와 과제를 올리고, 수업꾸러미를 만들어 클래스에 등록하는 데까지 해 보겠습니다. 화면은 모두 연수를 준비하면서 실제로 만들어 본 것입니다. 실습용으로 만든 것에는 이름 앞에 [연수 실습]을 붙였고, 학생에게는 배부하지 않았습니다.","alt":["수업꾸러미 첫 화면과 나의 수업꾸러미 목록"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 배움터 시작하기 / 로그인, 메인 화면, 메뉴, 화면 구성 / 04–11쪽 / STEP 2 / 클래스 / 클래스 선택, 클래스 홈, 클래스 관리 / 12–18쪽 / STEP 3 / 자료와 과제 / 개별과제, 자료과제, 제출 현황 / 19–27쪽 / STEP 4 / 수업꾸러미 / 성취기준 + 콘텐츠로 차시 만들고 클래스에 등록 / 28–38쪽 / STEP 5 / 알림과 누가기록 / 클래스 알림, 누가기록, 우리반 홈 / 39–42쪽 / STEP 6 / 콘텐츠와 대시보드 / 수업콘텐츠, LCMS, 자료실, 대시보드, 활용 / 43–50쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 STEP 3 자료와 과제, STEP 4 수업꾸러미만 꼭 해 보세요. 두 가지만 익혀도 한 차시 수업을 배움터 안에서 꾸릴 수 있습니다.","alt":[]},{"n":3,"t":"배움터는 여러 사이트가 이어진 플랫폼이에요","sec":0,"x":"시작하기 전에 / 입구 / 경북AI배움터 / aischool.gbe.kr / 로그인 한 번으로 아래 사이트에 모두 들어가요. 에듀테크 25종, 수업·학습 자료실도 여기에 있어요. / AI 교수학습 플랫폼 / 클래스: 자료 · 과제 · 꾸러미 · 누가기록 · 알림 aiep.gbe.kr · STEP 2·3·5 / 수업꾸러미 / 성취기준 + 콘텐츠로 차시 설계 aiep-courseware.gbe.kr · STEP 4 / 학습 콘텐츠 관리(LCMS) / 콘텐츠 등록 · 저작도구 8종 aiep-lcms.gbe.kr · STEP 6 / 학습 분석 대시보드 / 클래스 · 에듀테크 이용 현황 dashboard.gbe.kr · STEP 6","no":"배움터를 쓰다 보면 주소가 자꾸 바뀌어서 헷갈리실 수 있습니다. 배움터는 입구 역할을 하고, 실제 수업은 AI 교수학습 플랫폼의 클래스에서, 차시 설계는 수업꾸러미 사이트에서 합니다. 콘텐츠를 직접 만들고 싶을 때는 LCMS, 아이들 이용 현황은 대시보드에서 봅니다. 모두 배움터 로그인 한 번으로 이어집니다.","alt":[]},{"n":4,"t":"로그인 방식 고르기","sec":1,"x":"1 / 간편인증 / 네이버, 카카오, 금융기관 앱 등의 전자서명으로 로그인해요. / 2 / 공동인증서 / 컴퓨터나 USB에 있는 인증서로 로그인해요. / 3 / AI 교수학습 플랫폼 로그인 / 플랫폼 아이디로 들어가는 방식이에요. 학생은 주로 여기로 들어와요. / TIP / 화면 안내대로 교사는 위쪽 정부 통합로그인(1·2), 그 밖의 사용자는 아래쪽(3)을 써요.","no":"배움터 주소는 aischool.gbe.kr입니다. 로그인을 누르면 경상북도교육청 통합 인증 시스템으로 넘어갑니다. 화면 안내 문구에 교사와 기업회원 외에는 아래쪽 AI 교수학습 플랫폼 로그인을 쓰라고 되어 있습니다. 선생님들은 간편인증이나 공동인증서로 들어오시면 됩니다. 비밀번호나 인증은 꼭 선생님 본인이 직접 입력해 주세요.","alt":["통합 인증 시스템의 로그인 방식 선택 화면"]},{"n":5,"t":"메인 화면 한눈에 보기","sec":1,"x":"1 / 상단 메뉴 4개 / 마우스를 올리면 하위 메뉴가 펼쳐져요. / 2 / 통합검색 / 자료와 서비스를 한 번에 찾아요. / 3 / 학급 관리 바로가기 / 학생정보시스템으로 이동해요. / 4 / 위젯 편집하기 / 메인 화면 배치를 바꿔요(11쪽). / 5 / 내 이름 / 누르면 내 메뉴가 열려요(10쪽).","no":"로그인하면 이름과 함께 인사 문구가 나오는 메인 화면이 보입니다. 위쪽 메뉴와 통합검색, 학급 관리 바로가기, 위젯 편집하기 정도만 기억하시면 됩니다. 오른쪽 위에는 언어 선택과 화면 크기 조정, 알림도 있습니다. 화면 속 이름은 흐리게 처리했습니다.","alt":["경북AI배움터 메인 화면 윗부분"]},{"n":6,"t":"상단 메뉴: 플랫폼 서비스와 수업·학습 공간","sec":1,"x":"1 / 에듀테크 서비스 / 미리캔버스부터 클래스게임까지 / 2 / 수업 지원 서비스 / 구글·웨일 클래스, 학습 콘텐츠 관리 등 / 3 / 나의 강의실 / 웨일 클래스, 구글 클래스로 바로 / 4 / 수업·학습 자료실 / 선생님들이 올린 자료 모음(45쪽) / 5 / 학습 분석 대시보드 / 이용 현황 보기(46–48쪽)","no":"상단 메뉴는 플랫폼 서비스, 수업·학습 공간, 정보 소통 게시판, 이용 안내 네 가지입니다. 플랫폼 서비스에는 에듀테크 25종과 수업 지원 서비스가 있습니다. 수업 지원 서비스의 학습 콘텐츠 관리가 뒤에서 볼 LCMS입니다. 수업·학습 공간에는 나의 강의실, 수업·학습 자료실, 학습 분석 대시보드가 있습니다.","alt":["플랫폼 서비스 메뉴의 에듀테크 서비스와 수업 지원 서비스 목록","수업·학습 공간 메뉴"]},{"n":7,"t":"메인의 에듀테크 서비스","sec":1,"x":"1 / 서비스 바로가기 / 누르면 새 탭에서 배움터 계정으로 열려요. / 2 / 간단한 설명 / 마우스를 올리면 여기에 나타나요. / 3 / 수정하기 / 자주 쓰는 서비스 위주로 고를 수 있어요. / 4 / 쪽 넘기기 / 한 쪽에 8개씩, 모두 4쪽이에요. / TIP / 도구별 사용법은 에듀테크 안내서(미리캔버스·퀴즈앤·젭 퀴즈·띵커벨)를 함께 보세요.","no":"메인 화면을 조금 내리면 에듀테크 서비스가 있습니다. 아이콘을 누르면 새 탭이 열리고 배움터 계정으로 바로 로그인됩니다. 수정하기를 누르면 자주 쓰는 서비스 위주로 고를 수 있습니다. 도구별 자세한 사용법은 앞서 만든 에듀테크 안내서를 참고해 주세요.","alt":["메인 화면의 에듀테크 서비스 위젯"]},{"n":8,"t":"나의 강의실: 클래스로 들어가는 문","sec":1,"x":"1 / 내 강의 카드 / 연결된 구글·웨일 클래스가 보여요. / 2 / 강의 입장 / 그 클래스(예: 구글 클래스룸)로 바로 가요. / 3 / 우리반 등록하기 / AI 교수학습 플랫폼의 내 클래스 화면이 열려요. / 4 / 탭 / 전체 · 웨일 클래스 · 구글 클래스룸 / TIP / '우리반 등록하기'는 '전체' 탭에서 보여요. 주소 aiep.gbe.kr로 바로 들어가도 돼요.","no":"메인 화면의 나의 강의실은 우리 반 수업 공간으로 들어가는 문입니다. 구글 클래스룸이나 웨일 클래스와 연결된 강의가 카드로 보이고, 강의 입장을 누르면 그 클래스로 이동합니다. 오늘 연수의 중심인 AI 교수학습 플랫폼은 전체 탭의 우리반 등록하기 버튼으로 들어갑니다. 탭 이름이 AI 맞춤형 교수학습 플랫폼으로 바뀌면 제대로 들어간 것입니다.","alt":["메인 화면의 공지사항과 나의 강의실 위젯"]},{"n":9,"t":"메인 아래쪽: 자료실·일정·급식·묻고 답하기","sec":1,"x":"1 / 수업·학습 자료실 / 새로 올라온 자료를 넘겨 보며 확인해요. / 2 / 학사일정 / 달력에서 날짜를 누르면 일정이 보여요. / 3 / 급식표 / 조식 · 중식 · 석식, 날짜 이동 / 4 / FAQ · Q&A / 학생 계정, LMS 연동 같은 질문이 모여 있어요. / TIP / 막히면 FAQ부터 찾아보세요. 학생 계정 비밀번호 초기화 방법도 있어요.","no":"메인 화면 아래쪽에는 수업·학습 자료실의 새 자료, 학사일정, 급식표, FAQ와 Q&A가 있습니다. Q&A에는 구글 클래스룸 연동이나 학생 계정 비밀번호처럼 선생님들이 실제로 많이 묻는 내용이 올라와 있어서, 막힐 때 먼저 찾아보시면 좋습니다.","alt":["메인 화면 아래쪽의 수업·학습 자료실, 학사일정, 급식표, FAQ, Q&A 위젯"]},{"n":10,"t":"내 이름을 누르면 나오는 메뉴","sec":1,"x":"1 / 나의 정보 확인 / 내 계정 정보를 확인해요. / 2 / 학급 관리 / 학생정보시스템(aiep-sis.gbe.kr)으로 가요. 우리 반 학생 계정과 수업 목록을 봐요. / 3 / 학습 콘텐츠 관리 / LCMS로 가요. 콘텐츠를 등록하고 저작도구를 써요(44쪽). / 4 / 메시지 보내기 / 네이버 웍스로 연결돼요. / 주의 / 학급 관리 화면에는 학생 이름과 계정이 그대로 보여요. 수업 중 TV에 띄우지 마세요.","no":"오른쪽 위 내 이름을 누르면 메뉴가 열립니다. 학급 관리는 학생정보시스템으로 연결되는데, 여기에는 우리 반 학생 이름과 계정이 그대로 보이니 교실 TV에 띄울 때 조심해 주세요. 그래서 이 자료에서도 학생정보시스템 화면은 넣지 않았습니다. 학습 콘텐츠 관리는 LCMS로, 메시지 보내기는 네이버 웍스로 연결됩니다.","alt":["사용자 메뉴: 나의 정보 확인, 학급 관리, 학습 콘텐츠 관리, 메시지 보내기 등"]},{"n":11,"t":"나의 화면 구성하기: 위젯과 테마","sec":1,"x":"왼쪽 · 위젯 설정 / 1 / 위젯 설정 탭 / 2 / 페이지 너비 / 기본 / 전체 너비 / 3 / 위젯 배치 / 끌어서 순서, 체크로 표시, 칸 수 선택 / 4 / 저장 / 오른쪽 · 테마 설정 / 5 / 테마 템플릿 / 푸름 · 그린 · 퍼플 · 직접 설정 / 6 / 배너 영역 / 켜고 끄고, 그림 고르기","no":"메인 화면의 위젯 편집하기를 누르면 나의 화면 구성하기 창이 열립니다. 위젯 설정에서는 페이지 너비와 위젯 순서, 표시 여부, 칸 수를 바꿀 수 있고, 테마 설정에서는 색 테마와 배너를 고릅니다. 마음에 안 들면 기본값으로 초기화를 누르면 됩니다. 꼭 저장을 눌러야 반영됩니다.","alt":["위젯 설정 화면","테마 설정 화면"]},{"n":12,"t":"AI 교수학습 플랫폼: 클래스 선택","sec":2,"x":"1 / 왼쪽 전체 메뉴 / 내 클래스 · 우리반 · 학습콘텐츠 / 2 / 우리반 현황 / 담임 학급과 학생 수가 보여요. / 3 / 담임클래스 바로가기 / 4 / 클래스 만들기 / 교과·동아리 클래스를 새로(14쪽) / 5 / 클래스 현황 / 내가 맡은 클래스 카드 목록 / TIP / 처음 들어오면 이 화면이 보여요. 맨 위 '전체 메뉴'를 누르면 메뉴를 접고 펼 수 있어요.","no":"AI 교수학습 플랫폼에 들어오면 클래스 선택 화면이 먼저 보입니다. 위쪽 우리반 현황에는 담임 학급이, 아래쪽 클래스 현황에는 내가 맡은 클래스가 카드로 나옵니다. 연수에서는 학생이 없는 실습용 클래스 [연수 실습] 구글 클래스룸 익히기를 사용했습니다. 실제 우리 반 클래스에는 아무것도 올리지 않았습니다.","alt":["AI 교수학습 플랫폼의 클래스 선택 화면"]},{"n":13,"t":"클래스 카드 읽기","sec":2,"x":"1 / 클래스 만들기 / 2 / 부교사 · 학생 수 / 학생 수가 0명이면 아직 배정 전이에요. / 3 / 클래스 보관하기 / 다 쓴 클래스를 목록에서 정리해요. / 4 / 클래스 바로가기 / 클래스 홈으로 들어가요(16쪽). / TIP / 카드의 클래스룸 아이콘은 구글 클래스룸과 연결된 클래스라는 뜻이에요.","no":"클래스 카드에는 부교사와 학생 수가 나옵니다. 오른쪽 실습용 클래스는 학생 수가 0명이라서 자료나 과제를 올려도 학생에게 가지 않습니다. 연수 실습을 이 클래스에서 한 이유입니다. 클래스 바로가기를 누르면 클래스 홈으로 들어갑니다.","alt":["클래스 현황의 클래스 카드 두 개"]},{"n":14,"t":"클래스 만들기: 4단계","sec":2,"x":"1 / 진행 단계 / 안내 → 만들기 방식 → 기본 정보 → 학생 배정 / 2 / 클래스명 / 30자까지 / 3 / 클래스 소개 / 200자까지 / 4 / 다음 / TIP / 2단계에서 '직접 클래스 만들기' 또는 '파일 업로드(csv, xlsx)'로 여러 클래스를 한 번에 만들 수 있어요.","no":"클래스 만들기는 네 단계입니다. 만들기 방식에서 직접 만들기를 고르면 클래스명과 소개를 넣고 다음으로 넘어갑니다. 여러 반을 한꺼번에 만들 때는 csv나 xlsx 파일로 올리는 방식도 있습니다. 마지막 단계에서 학생을 배정합니다. 다만 다음 쪽처럼 권한이 없다는 창이 뜰 때가 있습니다.","alt":["클래스 만들기 3단계 기본 정보 입력 화면"]},{"n":15,"t":"'권한이 없습니다'가 뜰 때","sec":2,"x":"1 / 권한 안내 창 / 기본 정보를 넣고 '다음'을 누르자 떴어요. / 연수 준비 때 있었던 일 / 같은 계정으로 실습용 클래스는 먼저 만들어졌는데, 두 번째 클래스를 만들 때 이 창이 떴어요. 원인은 확인하지 못했어요. / 이럴 땐 / 이미 있는 클래스를 먼저 쓰고, 계속 막히면 학교 플랫폼 운영 담당과 의논해요.","no":"연수를 준비하면서 실습용 클래스 [연수 실습] 구글 클래스룸 익히기는 같은 계정으로 문제없이 만들어졌습니다. 그런데 이번 자료를 만들며 클래스를 하나 더 만들어 보려 하자, 기본 정보를 넣고 다음을 누른 순간 해당 기능에 대한 권한이 없다는 창이 떴습니다. 원인은 확인하지 못했습니다. 그래서 이후 실습은 이미 만들어 둔 학생 0명짜리 실습용 클래스에서 진행했습니다. 같은 창이 뜨면 기존 클래스를 먼저 활용해 보세요.","alt":["해당 기능에 대한 권한이 없습니다 안내 창"]},{"n":16,"t":"클래스 홈 둘러보기","sec":2,"x":"1 / 클래스 메뉴 / 홈 · 자료 · 알림 · 관리 / 2 / 클래스 정보 / 소개, 담당교사, 배정학생 수 / 3 / 학생배정 / 학생을 클래스에 넣어요(18쪽). / 4 / 최신 알림 / 5 / 탭 4개 / 자료 · 과제 · 꾸러미 · 누가기록 / 6 / 자료올리기 / 자료 탭에서 바로 올려요(25쪽).","no":"클래스 홈이 수업의 중심입니다. 가운데 탭 네 개, 자료, 과제, 꾸러미, 누가기록을 기억해 주세요. 오늘 연수의 STEP 3와 STEP 4가 모두 이 탭에서 이루어집니다. 왼쪽 메뉴의 클래스 관리에서는 LMS 연결과 학생 배정을 합니다.","alt":["실습용 클래스의 클래스 홈 화면"]},{"n":17,"t":"클래스 관리 ① LMS 연결","sec":2,"x":"1 / 관리 탭 / 기본정보 · LMS · 학생관리 · 학생배정 / 2 / 연결 조건 / 클래스를 만든 지 15분 뒤부터, LMS는 1개만 / 3 / 웨일클래스 / 구글 클래스룸 / 연결하기 → 연결완료 / 4 / 저장 / TIP / 실습용 클래스는 구글 클래스룸과 '연결완료' 상태예요.","no":"클래스 관리의 LMS 관리에서는 이 클래스를 웨일클래스나 구글 클래스룸 가운데 하나와 연결합니다. 화면 안내대로 클래스를 처음 만든 뒤 15분이 지나야 연결할 수 있고, LMS는 하나만 고를 수 있습니다. 사용할 LMS는 연결한 뒤에 선택합니다.","alt":["클래스 관리의 LMS 관리 화면"]},{"n":18,"t":"클래스 관리 ② 학생배정","sec":2,"x":"1 / 학년 · 반으로 검색 / 배정할 학생을 먼저 찾아요. / 2 / 학생 일괄배정 / 체크한 학생을 한 번에 넣어요. / 3 / 배정 / 한 명씩 넣을 때는 이 칸을 써요. / 주의 / 자료·과제·꾸러미는 배정된 학생에게만 가요. 연수 실습 클래스는 일부러 0명으로 두었어요.","no":"학생배정에서는 학년과 반으로 학생을 검색한 뒤 일괄배정하거나 한 명씩 배정합니다. 배정된 학생에게만 자료와 과제가 보이므로, 실제 수업 클래스라면 이 단계를 먼저 해 두셔야 합니다. 연수 실습 클래스는 학생에게 아무것도 가지 않도록 일부러 배정하지 않았습니다. 학생 이름이 나오는 화면이라 검색 결과 화면은 싣지 않았습니다.","alt":["클래스 관리의 학생배정 화면"]},{"n":19,"t":"과제는 두 가지: 개별과제와 자료과제","sec":3,"x":"개별과제 / 과제 탭 › 과제등록에서 바로 만들어요. 과제만 따로 낼 때 좋아요. / 20–24쪽 / 자료과제 / 자료를 올리면서 '과제 설정: 사용'으로 붙여요. 활동지를 주고 결과를 받을 때 좋아요. / 25–27쪽 / 1 / 과제 탭 / 클래스 홈의 두 번째 탭 / 2 / 유형 거르기 / 전체유형 · 자료과제 · 개별과제 / 3 / 과제등록 / 개별과제를 만들어요. / TIP / 두 과제 모두 과제 탭에 함께 모여요. 제출 현황 보는 방법도 같아요.","no":"과제는 두 가지 길로 만들 수 있습니다. 과제 탭에서 바로 만드는 개별과제, 그리고 자료를 올리면서 과제를 붙이는 자료과제입니다. 연수에서는 두 가지를 모두 만들어 보았습니다. 개별과제는 가을 하면 떠오르는 낱말 세 가지, 자료과제는 설명하는 글 요약하기 활동지를 사진으로 찍어 내는 과제입니다.","alt":["과제 탭의 유형 선택 목록과 과제등록 버튼"]},{"n":20,"t":"개별과제 만들기 ① 과제명과 내용","sec":3,"x":"1 / 클래스 선택 / 다른 클래스에도 같이 낼 때만 눌러요(21쪽). / 2 / 과제명 / 50자까지 / 3 / 과제내용 / 편집기에서 글자, 표, 그림을 넣어요. 예시를 함께 주면 좋아요. / 4 / 첨부파일 / 활동지나 참고 자료를 붙여요. / TIP / '공책에 쓴 것을 사진으로 찍어 첨부해도 돼요'처럼 제출 방법을 내용에 꼭 적어 주세요.","no":"과제등록을 누르면 과제 만들기 화면이 나옵니다. 과제명과 과제내용은 꼭 넣어야 하는 칸입니다. 연수에서는 [연수 실습] 가을 하면 떠오르는 낱말 세 가지라는 과제를 만들었고, 내용에는 낱말 세 개를 쓰고 고른 까닭을 한 문장씩 쓰라는 안내와 예시를 넣었습니다.","alt":["과제 만들기 화면 윗부분"]},{"n":21,"t":"클래스 선택: 여러 반에 한 번에 내기","sec":3,"x":"1 / 함께 낼 클래스 체크 / 지금 클래스 말고 내가 맡은 다른 클래스가 보여요. / 2 / 등록 / 고른 클래스가 과제 만들기 화면에 표시돼요. / 아무것도 고르지 않으면? / 지금 들어와 있는 클래스에만 등록돼요. 한 반에만 낼 때는 이 단계를 건너뛰어요. / 주의 / 체크한 클래스 학생에게도 바로 과제가 나가요. 연수 실습에서는 실제 반(5-6)을 고르지 않고 취소했어요.","no":"과제 만들기의 클래스 선택 버튼은 같은 과제를 여러 반에 한 번에 낼 때 씁니다. 교과 전담 선생님께 특히 편한 기능입니다. 화면 안내에도 나오듯 따로 선택하지 않으면 지금 클래스에만 등록됩니다. 연수에서는 실제 학생이 있는 반이 목록에 보여서 체크하지 않고 창을 닫았습니다.","alt":["클래스 검색 창"]},{"n":22,"t":"개별과제 만들기 ② 제출기간과 저장","sec":3,"x":"1 / 파일 끌어다 놓기 / 또는 '추가'로 골라요. / 2 / 제출기간 사용 / 미사용이면 언제든 낼 수 있어요. / 3 / 시작 ~ 마감 / 달력 아이콘으로 날짜를 골라요. / 4 / 목록 / 저장하지 않고 나가요. / 5 / 저장 / 주의 / 달력으로 고르면 시간이 01:00으로 들어가요. 마감이 그날 새벽 1시로 잡히니 하루 넉넉히 정하세요.","no":"제출기간을 사용으로 두면 시작일과 마감일을 정할 수 있습니다. 화면 안내대로 기간을 정하지 않으면 언제든 제출할 수 있습니다. 실습할 때 날짜 칸에 직접 입력은 되지 않았고, 달력에서 날짜를 고르니 시간이 01시로 들어갔습니다. 16일까지 받으려고 16일을 골랐다면 실제로는 16일 새벽 1시에 닫힐 수 있으니, 마감일을 하루 뒤로 잡아 주세요. 연수 과제는 10월 2일부터 16일까지로 저장했습니다.","alt":["과제 만들기 화면 아랫부분의 첨부파일, 제출기간, 저장"]},{"n":23,"t":"과제 탭에 생긴 과제 카드","sec":3,"x":"1 / 검색 / 유형 · 상태 · 과제명으로 찾아요. / 2 / 과제 카드 / 누르면 상세와 제출 현황이 열려요. / 3 / 제출 0/0명 / 제출한 학생 / 배정된 학생 / 4 / 제출 기간 / 5 / 과제등록 / 새 과제를 더 만들어요. / TIP / 뒤 숫자가 0이면 아직 배정된 학생이 없다는 뜻이에요(18쪽).","no":"저장하면 과제 탭에 카드가 생깁니다. 카드에는 제출 인원과 기간, 작성자가 나옵니다. 실습 클래스는 학생이 0명이라 제출 0/0명으로 보입니다. 실제 반이라면 제출 3/23명처럼 표시됩니다.","alt":["과제 탭의 과제 카드 목록"]},{"n":24,"t":"과제 상세와 제출 현황","sec":3,"x":"1 / 과제 제목 · 작성 일시 / 2 / 과제내용 / 학생에게 보이는 그대로예요. / 3 / 상태와 기간 / 제출가능 · 26-10-02 ~ 26-10-16 / 4 / 학생별 현황표 / 제출여부 · 제출일시 · 피드백여부 · 점수 / 5 / 엑셀파일다운로드 / 현황을 엑셀로 받아요. / 6 / 수정 / 내용과 기간을 고쳐요.","no":"과제 카드를 누르면 위쪽에 과제 내용이, 아래쪽에 과제 현황이 나옵니다. 현황표에는 학생별 제출 여부, 제출 일시, 피드백 여부, 점수 칸이 있어서 누가 냈는지 한눈에 볼 수 있고, 엑셀로 내려받아 정리할 수도 있습니다. 실습 클래스는 학생이 없어서 표가 비어 있습니다.","alt":["과제 상세의 제목과 과제내용","과제 현황 표와 엑셀파일다운로드"]},{"n":25,"t":"자료 올리기 ① 제목, 내용, 첨부파일","sec":3,"x":"1 / 클래스 선택 / 과제와 같아요. 한 반이면 건너뛰어요. / 2 / 자료 제목 / 50자까지 / 3 / 내용 / 1000자까지. 학생이 할 일을 적어요. / 4 / 첨부파일 / 활동지 PDF(150KB)를 올렸어요. / TIP / '인쇄해서 써도 되고, 태블릿에서 내려받아 써도 돼요'처럼 쓰는 방법을 함께 안내해요.","no":"클래스 홈 자료 탭의 자료올리기를 누르면 이 화면이 나옵니다. 연수에서는 [연수 실습] 설명하는 글 요약하기 활동지라는 자료를 만들고, 직접 만든 한 쪽짜리 활동지 PDF를 첨부했습니다. 활동지에는 문단별 중심 내용 표, 설명 방법, 세 문장 요약 칸이 들어 있습니다.","alt":["자료 올리기 화면 윗부분"]},{"n":26,"t":"자료 올리기 ② 수업일정과 자료과제","sec":3,"x":"1 / 추가 · 삭제 / 첨부파일을 더 올리거나 빼요. / 2 / 수업일정 / 그날 접속한 학생에게 이 자료가 먼저 보여요. / 3 / 과제 설정: 사용 / 학생에게 과제 제출 칸이 생겨요. / 4 / 과제명 / 5 / 과제내용 / '사진을 찍어 첨부해 제출해요' / 6 / 제출기간 / 개별과제와 같아요(01:00 주의). / TIP / 자료를 주고 결과를 받는 일을 한 번에 끝내요. 저장하면 과제 탭에도 '자료과제'로 생겨요.","no":"자료 화면을 내리면 수업일정과 과제 설정이 나옵니다. 수업일정을 정하면 그날 들어온 학생에게 이 자료가 먼저 보입니다. 과제 설정을 사용으로 바꾸면 과제명, 과제내용, 제출기간 칸이 열리고, 저장하면 자료와 과제가 함께 만들어집니다. 연수에서는 수업일을 10월 6일로, 제출기간을 10월 6일부터 9일까지로 정했습니다.","alt":["자료 올리기의 수업일정과 과제 설정","자료과제의 과제내용과 제출기간"]},{"n":27,"t":"올린 자료와 과제 확인하기","sec":3,"x":"1 / 자료 카드 / 제목, 내용, 첨부가 한 장에 / 2 / 수업일 / '수업일순'으로 정렬돼요. / 3 / 제출 현황 / 과제를 붙인 자료에만 보여요. / 4 / 개별과제 / 과제 탭에서 만든 과제 / 5 / 자료과제 / 연한 파란 카드, 아래에 자료 이름","no":"왼쪽은 자료 탭, 오른쪽은 과제 탭입니다. 자료에 붙인 과제는 과제 탭에 연한 파란색 카드로 따로 보이고, 카드 안에 어떤 자료에서 나온 과제인지 이름이 적혀 있습니다. 개별과제와 자료과제의 제출 현황은 모두 과제 탭에서 같은 방법으로 확인합니다.","alt":["자료 탭의 자료 카드","과제 탭의 개별과제와 자료과제 카드"]},{"n":28,"t":"수업꾸러미는 한 차시를 묶은 학습 꾸러미","sec":4,"x":"성취기준 + 콘텐츠 = 꾸러미 / 성취기준을 고르고 그에 맞는 영상·문서·링크를 순서대로 놓으면, 학생은 클래스에서 차례대로 학습해요. / 1 / 성취기준 고르기 / 학년 · 교과 · 과목으로 찾아 끌어다 놓아요. / 2 / 콘텐츠 놓기 / 플랫폼 콘텐츠나 내 파일·링크를 칸에 놓아요. / 3 / 이름 짓고 등록 / 공개 범위를 정하고 미리보기로 확인해요. / 4 / 클래스에 등록 / 클래스 홈 꾸러미 탭에서 내 꾸러미를 넣어요. / 연수 실습 / [연수 실습] 설명하는 글 요약하기 · 국어 5학년 [6국02-01] · 영상 2개 + 활동지 1개 · 비공개","no":"수업꾸러미는 성취기준 하나에 맞춰 영상, 문서, 링크 같은 콘텐츠를 순서대로 묶은 한 차시 학습 꾸러미입니다. 꾸러미는 수업꾸러미 사이트에서 만들고, 만든 꾸러미를 클래스의 꾸러미 탭에 등록하면 학생이 클래스에서 학습합니다. 연수에서는 국어 5학년 설명하는 글 요약하기 꾸러미를 영상 두 개와 직접 만든 활동지로 만들어 보았습니다.","alt":[]},{"n":29,"t":"클래스의 꾸러미 탭에서 출발해요","sec":4,"x":"1 / 꾸러미 탭 / 이 클래스에 등록된 꾸러미가 보여요. / 2 / 꾸러미등록 관리 / 아래 창이 열려요. / 3 / 수정 안내 / 꾸러미를 고치면 제외 후 다시 등록해야 바뀌어요. / 4 / 내 꾸러미 / 내가 만든 꾸러미 목록 / 5 / 꾸러미 만들기 / 수업꾸러미 사이트가 새 탭으로 열려요. / 6 / 클래스 꾸러미 / 이 클래스에 등록된 꾸러미","no":"클래스 홈의 꾸러미 탭에서 꾸러미등록 관리를 누르면 창이 열립니다. 왼쪽은 내 꾸러미, 오른쪽은 이 클래스에 등록된 꾸러미입니다. 내 꾸러미 위의 꾸러미 만들기를 누르면 수업꾸러미 사이트가 새 탭으로 열립니다. 맨 위 안내문처럼 꾸러미를 고친 뒤에는 클래스에서 한 번 제외하고 다시 등록해야 수정한 내용이 반영됩니다.","alt":["클래스 홈의 꾸러미 탭","꾸러미등록 관리 창"]},{"n":30,"t":"수업꾸러미 사이트 첫 화면","sec":4,"x":"1 / 위쪽 메뉴 / 홈 · 전체 수업꾸러미 · 꾸러미 만들기 / 2 / 자유롭게 꾸러미 제작 / 빈 판에서 새로 만들어요. / 3 / 공유된 꾸러미로 제작 / 다른 선생님이 공개한 꾸러미에서 시작해요. / 4 / 나의 수업꾸러미 / 내가 만든 꾸러미, 전체보기 / TIP / 주소는 aiep-courseware.gbe.kr이에요. 배움터 로그인이 그대로 이어져요.","no":"수업꾸러미 사이트 첫 화면입니다. 처음부터 만들 때는 자유롭게 꾸러미 제작을, 다른 선생님이 공개한 꾸러미를 바탕으로 만들 때는 공유된 꾸러미로 제작을 누릅니다. 아래쪽에는 내가 만든 꾸러미가 쌓입니다. 맨 앞의 [연수 실습] 설명하는 글 요약하기가 이번 연수에서 만든 꾸러미입니다.","alt":["수업꾸러미 사이트 첫 화면"]},{"n":31,"t":"꾸러미 만들기 화면 구성","sec":4,"x":"1 / 왼쪽 아이콘 / 성취기준 · 콘텐츠 · 파일/링크 패널 / 2 / 성취기준 찾기 / 학년 · 교과군 · 과목 / 3 / 수업꾸러미 이름 / 4 / 공개 범위 · 순차학습 / 5 / 차시 판 / 성취기준 1칸 + 콘텐츠 칸 / 6 / 미리보기 · 임시저장 · 등록하기 / TIP / 왼쪽 패널에서 끌어다 판에 놓는 방식이에요. 오른쪽 위 '매뉴얼 다운로드'도 있어요.","no":"꾸러미 만들기 화면입니다. 왼쪽 패널에서 성취기준과 콘텐츠를 골라 가운데 판에 끌어다 놓는 방식입니다. 화면 안내에도 하단 패널에서 요소를 드래그 앤 드롭해 수업꾸러미 설계를 시작하라고 되어 있습니다. 자세한 설명이 필요하면 오른쪽 위의 매뉴얼 다운로드를 눌러 보세요.","alt":["꾸러미 만들기 빈 화면"]},{"n":32,"t":"1단계: 성취기준 놓기","sec":4,"x":"1 / 학년 · 교과 · 과목 / 초등학교 5학년 · 국어과 · 국어 / 2 / 성취기준 끌어오기 / [6국02-01] 글의 구조를 고려하여 주제나 주장을 파악하고… / 3 / 성취기준 칸에 쏙 / 교과목에 '국어'가 표시돼요. / 4 / 안내 문구 / '콘텐츠를 추가해야 등록이 가능합니다' / TIP / 성취기준 코드나 낱말로 검색할 수도 있어요.","no":"먼저 학년, 교과, 과목을 고르면 성취기준 목록이 나옵니다. 연수에서는 5학년 국어의 [6국02-01] 성취기준을 판의 첫 칸으로 끌어다 놓았습니다. 성취기준만 놓으면 위쪽에 빨간 안내가 뜹니다. 콘텐츠를 하나 이상 넣어야 등록할 수 있다는 뜻입니다.","alt":["성취기준을 판에 놓은 화면"]},{"n":33,"t":"2단계: 콘텐츠 끌어다 놓기","sec":4,"x":"1 / 콘텐츠 패널 열기 / 2 / 거르기 / 타입 · 제작사, 성취기준 칩, 내 콘텐츠만 / 3 / 콘텐츠 목록 / 동영상 · 문서 등, 유형이 함께 보여요. / 4 / 콘텐츠1 · 2에 놓기 / 설명 방법의 종류, 얼음 창고의 역사 / 5 / 초록 안내로 바뀜 / '등록이 가능한 상태입니다' / TIP / 카드를 누른 채 칸 위까지 끌고 가서 놓아요. 칸 사이 화살표 순서대로 학습해요.","no":"다음으로 콘텐츠 패널을 엽니다. 넣어 둔 성취기준이 위쪽에 칩으로 걸려 있어서 관련 콘텐츠를 찾기 쉽습니다. 연수에서는 설명 방법의 종류와 얼음 창고의 역사 두 영상을 콘텐츠1과 콘텐츠2 칸에 끌어다 놓았습니다. 콘텐츠가 들어가면 위쪽 안내가 초록색 등록 가능 상태로 바뀝니다.","alt":["콘텐츠 두 개를 판에 놓은 화면"]},{"n":34,"t":"3단계: 내 파일이나 링크 넣기","sec":4,"x":"1 / 파일 업로드 / 활동지 PDF 등을 올려요. / 2 / 링크 / 3 / 주소 넣고 추가 / 4 / 제목 · 설명 / 설명을 비우면 제목과 같게 저장돼요. / 5 / 과목 / 6 / 구매 여부 · 저작권 / 공공누리 유형을 골라요. / 7 / 확인 / TIP / 올린 파일은 수업콘텐츠 목록에도 쌓여 다시 쓸 수 있어요(43쪽).","no":"플랫폼 콘텐츠 말고 선생님 자료를 넣고 싶을 때는 파일/링크 패널을 씁니다. 파일 업로드를 누르면 오른쪽 같은 설정 창이 뜨고, 제목과 설명, 과목, 구매 여부, 저작권 유형을 정한 뒤 확인을 누릅니다. 연수에서는 직접 만든 설명하는 글 요약하기 활동지 PDF를 올려 콘텐츠3 칸에 넣었습니다. 링크는 주소를 넣고 추가하면 목록에 생깁니다. 목록의 다른 링크 이름은 흐리게 처리했습니다.","alt":["파일/링크 패널","파일 업로드 설정 창"]},{"n":35,"t":"4단계: 이름, 공개 범위, 차시 제목","sec":4,"x":"1 / 수업꾸러미 이름 / 2 / 공개 범위 / 처음엔 '비공개'로, 다듬은 뒤 공개해요. / 3 / 순차학습 / 순서대로 학습하게 하는 설정. 물음표(?)에 설명 / 4 / 차시 제목 / '1차시 설명하는 글 읽고 요약하기' / 5 / 콘텐츠 3개 / 영상 2개 → 활동지 / TIP / 차시 제목을 누르면 고칠 수 있어요. 다음 줄에 차시를 이어 붙여 단원 꾸러미로 키워요.","no":"콘텐츠를 다 놓았으면 꾸러미 이름과 공개 범위를 정합니다. 연수 꾸러미는 비공개로 두었습니다. 전체공개로 바꾸면 다른 선생님들도 전체 수업꾸러미에서 보고 가져다 쓸 수 있습니다. 차시 제목은 기본값이 그대로 남아 있을 수 있으니, 꼭 이번 차시에 맞게 고쳐 주세요. 실습 때도 앞서 썼던 제목이 남아 있어서 고쳐 넣었습니다.","alt":["이름과 차시 제목을 넣고 콘텐츠 세 개를 놓은 꾸러미"]},{"n":36,"t":"5단계: 학습화면 미리보기 후 등록하기","sec":4,"x":"1 / 콘텐츠 화면 / 학생이 보는 그대로 재생돼요. / 2 / 커리큘럼 / 차시와 콘텐츠 순서 / 3 / 진도율 / 3개 중 1개 = 33.3% / 4 / 학습 목표 / 넣은 성취기준이 나와요. / 5 / 앞뒤 이동 / 1/3 → 2/3 → 3/3 / TIP / 창을 닫고 '등록하기'를 눌러야 완성돼요. 아직이면 '임시저장'.","no":"등록하기 전에 미리보기를 눌러 학생 화면을 확인합니다. 오른쪽 커리큘럼에 차시와 콘텐츠 순서가 나오고, 하나를 보면 진도율이 올라갑니다. 학습 목표에는 처음에 넣은 성취기준이 그대로 나옵니다. 확인했으면 창을 닫고 등록하기를 누릅니다.","alt":["학습화면 미리보기"]},{"n":37,"t":"6단계: 만든 꾸러미를 클래스에 등록","sec":4,"x":"1 / 체크 / 내 꾸러미에서 고르기 / 2 / 등록하기 / 오른쪽으로 옮겨져요. / 3 / 클래스 꾸러미 / 빼려면 체크 후 '제외하기' / 4 / 꾸러미 카드 / 꾸러미 탭에 생겼어요. / 5 / 등록 관리 / 고친 뒤엔 제외 → 다시 등록","no":"다시 클래스로 돌아와 꾸러미등록 관리를 엽니다. 방금 만든 꾸러미가 내 꾸러미에 보이면 체크하고 등록하기를 누릅니다. 오른쪽 클래스 꾸러미로 옮겨지고, 창을 닫으면 꾸러미 탭에 카드가 생깁니다. 꾸러미를 고친 경우에는 여기서 제외하기를 누른 뒤 다시 등록해야 바뀐 내용이 학생에게 보입니다.","alt":["꾸러미등록 관리에서 내 꾸러미를 클래스 꾸러미로 등록한 모습","클래스 꾸러미 탭에 생긴 꾸러미 카드"]},{"n":38,"t":"전체 수업꾸러미에서 찾아 쓰기","sec":4,"x":"1 / 거르기와 검색 / 학년 · 교과군 · 과목 · 성취기준 · 검색어 / 2 / 내 수업꾸러미만 보기 / 3 / 꾸러미 카드 / 과목 · 이름 · 만든 날. 촬영 때 모두 72개 / TIP / 비슷한 단원 꾸러미를 찾았다면 '공유된 꾸러미로 제작'으로 가져와 우리 반에 맞게 고쳐요.","no":"전체 수업꾸러미에는 공개된 꾸러미가 모여 있습니다. 학년과 과목, 성취기준으로 거를 수 있고, 내 수업꾸러미만 보기를 켜면 내가 만든 것만 남습니다. 처음부터 만들기 부담스러우시면 비슷한 꾸러미를 찾아 바탕으로 쓰시는 것을 추천합니다.","alt":["전체 수업꾸러미 목록"]},{"n":39,"t":"클래스 알림 쓰기","sec":5,"x":"1 / 알림 제목 / 무엇을 알리는지 한눈에 / 2 / 알림내용 / 편집기로 글자·표·그림 / 3 / 첨부파일 / hwp, pdf, pptx, 사진, zip 등 / 4 / 댓글 허용 / 허용하면 학생이 질문을 남겨요. / 5 / 저장 / 클래스 홈 '최신 알림'에도 떠요.","no":"클래스 메뉴의 클래스 알림에서 알림 등록을 누르면 이 화면이 나옵니다. 제목과 내용은 꼭 넣어야 하고, 첨부할 수 있는 파일은 zip, doc, docx, hwp, pdf, jpg, jpeg, png, pptx입니다. 연수에서는 [연수 실습] 다음 주 국어 시간 준비물 안내를 썼고 댓글은 허용안함으로 두었습니다.","alt":["클래스 알림 작성 화면 윗부분","클래스 알림 작성 화면 아랫부분의 댓글 허용과 저장"]},{"n":40,"t":"등록한 알림 확인하기","sec":5,"x":"1 / 알림 등록 / 새 알림을 써요. / 2 / 알림 카드 / 제목, 내용 앞부분, 등록 일시 / 3 / 아이콘 숫자 / 클립 = 첨부 수, 종 = 확인 인원, 말풍선 = 댓글 수 / TIP / 준비물, 과제 마감, 수업 장소 변경처럼 짧게 알릴 일에 써요.","no":"저장하면 클래스 알림 목록에 카드가 생깁니다. 카드 아래 아이콘은 첨부 수, 확인 인원, 댓글 수를 보여 줍니다. 실습 클래스는 학생이 없어서 모두 0입니다. 담당교사 이름은 흐리게 처리했습니다.","alt":["클래스 알림 목록과 알림 카드"]},{"n":41,"t":"누가기록 탭","sec":5,"x":"1 / 검색 / 상태 · 검색대상 · 검색어 / 2 / 누가기록 공개 설정 / 공개 / 비공개. 처음엔 비공개예요. / 3 / 학생별 목록 / 최근 접속일 · 기록수 · 최근 기록일 · 상태 / 주의 / 학생 이름과 기록이 나오는 화면이에요. 공개로 바꾸기 전에, 수업 중 화면에 띄우기 전에 한 번 더 확인해요.","no":"누가기록 탭에서는 학생별 기록 수와 최근 기록일, 최근 접속일을 한 줄씩 볼 수 있습니다. 기록 공개 설정은 처음에 비공개로 되어 있습니다. 실습 클래스는 학생이 없어서 표시할 데이터가 없다고 나옵니다. 실제 반에서는 학생 이름이 그대로 나오니 화면 공유할 때 조심해 주세요.","alt":["클래스 홈의 누가기록 탭"]},{"n":42,"t":"우리반 홈: 담임 학급 공간","sec":5,"x":"1 / 우리반 메뉴 / 우리반 홈 · 알림 · 관리 / 2 / 학급 정보 / 학년 · 반, 담임 · 부담임, 학생 수 / 3 / 탭 3개 / 알림 · 과제 · 누가기록 / 4 / 알림 등록 / 우리 반 전체에 알려요. / TIP / 학급 일은 우리반, 교과 수업은 클래스로 나눠 쓰면 헷갈리지 않아요.","no":"왼쪽 메뉴의 우리반은 담임 학급 공간입니다. 클래스 홈과 비슷하게 알림, 과제, 누가기록 탭이 있습니다. 이곳은 실제 학생이 있는 우리 반이어서 연수 준비 때는 화면만 살펴보고 아무것도 올리지 않았습니다. 담임과 부담임 이름은 흐리게 처리했습니다.","alt":["우리반 홈 화면"]},{"n":43,"t":"수업콘텐츠: 플랫폼의 콘텐츠 창고","sec":6,"x":"1 / 거르기 / 학년 · 교과목 · 등록유형 · 콘텐츠타입 · 이름 / 2 / 콘텐츠 수 / 촬영 때 49,471개 / 3 / 수업콘텐츠 관리 / 4 / 콘텐츠 카드 / 유형 · 이름 · 조회수 · 만든 사람 · 날짜 / TIP / 꾸러미에 올린 활동지 PDF도 여기 맨 앞에 생겼어요. 한 번 올린 자료는 다시 쓸 수 있어요.","no":"AI 교수학습 플랫폼 왼쪽 메뉴의 학습콘텐츠, 수업콘텐츠에 들어가면 플랫폼에 등록된 콘텐츠를 모두 볼 수 있습니다. 촬영할 때 4만 9천 개가 넘었습니다. 수업꾸러미에서 올린 활동지 PDF도 이 목록 맨 앞에 생긴 것을 확인했습니다. 카드의 만든 사람 이름은 흐리게 처리했습니다.","alt":["학습콘텐츠의 수업콘텐츠 목록"]},{"n":44,"t":"학습 콘텐츠 관리(LCMS)와 저작도구","sec":6,"x":"1 / 콘텐츠 · 저작도구 / 2 / 거르기 / CP사 · 타입 · 학교급 · 학년 · 교과목 / 3 / 상태 / 등록중 · 사용전 · 사용중 · 만료 · 중지 / 4 / 공개 범위 / 전체공개(11개 시도) · 소속학교만 · 비공개 / 5 / 등록 / 6 / 저작도구 8종 / 인터랙티브 비디오·슬라이드, 빈칸 채우기, 드래그 텍스트, 단어 선택, 객관식(복수·단일), O/X 퀴즈","no":"LCMS는 내 메뉴의 학습 콘텐츠 관리, 또는 플랫폼 서비스의 수업 지원 서비스에서 들어갑니다. 콘텐츠 등록/조회에서 콘텐츠를 찾거나 등록하고, 저작도구 메뉴에서는 인터랙티브 비디오나 빈칸 채우기 같은 활동형 콘텐츠를 직접 만들 수 있습니다. 공개 범위는 전체공개, 소속학교만, 비공개 세 가지입니다. 이번에는 메뉴 구성만 살펴보고 실제 콘텐츠는 등록하지 않았습니다. 만든 사람 이름은 흐리게 처리했습니다.","alt":["LCMS 콘텐츠 등록/조회 화면","저작도구 선택 목록"]},{"n":45,"t":"수업·학습 자료실","sec":6,"x":"1 / 검색어 / 2 / 상세 조건 / 학교급 · 학년 · 교과목 · 난이도 · 자료 유형 · 제공사 / 3 / 보기 방식 · 정렬 / 카드/목록, 12개씩, 조회순 / 4 / 자료 카드 / 촬영 때 모두 98건 / TIP / 경북 여러 학교 선생님들이 올린 수업 자료예요. 같은 학년 자료부터 둘러보세요.","no":"배움터의 수업·학습 공간 메뉴에서 수업·학습 자료실로 들어갑니다. 학교급, 학년, 교과목, 난이도, 자료 유형으로 거를 수 있고, 조회순으로 정렬하면 많이 본 자료부터 나옵니다. 촬영할 때는 98건이 있었습니다.","alt":["수업·학습 자료실 검색 화면"]},{"n":46,"t":"메인의 학습 분석 대시보드","sec":6,"x":"1 / 학습 활동 분석 평균 / 수업페이지 · 퀴즈 · 과제 · 동료 평가 · 게시판 / 2 / 수업 콘텐츠 분포도 / 3 / 학습 시간 분포도 / 요일 × 시간, 진할수록 많이 접속 / 4 / 종합 대시보드 2종 / 에듀테크 / 클래스, 다음 쪽에서 봐요.","no":"배움터 메인에도 학습 분석 대시보드 위젯이 있습니다. 학습 시간 분포도는 요일과 시간대별로 아이들이 언제 많이 접속했는지 진한 색으로 보여 줍니다. 오른쪽 위 버튼을 누르면 에듀테크 종합 대시보드와 클래스 종합 대시보드로 넘어갑니다.","alt":["메인 화면의 학습 분석 대시보드 위젯"]},{"n":47,"t":"클래스 종합 대시보드","sec":6,"x":"1 / 위쪽 탭 / 클래스 | 에듀테크 서비스 / 2 / 한 줄 요약 / 진행 중 클래스 · 활성 학습자 · 총 학습자 · 평균 학습 시간 / 3 / 진행 중인 클래스 / 클래스별 개설일과 학생 수 / 4 / 활동 분석 / 학습 활동 · 콘텐츠 분포 · 게시판 활동 TOP5 / TIP / 과제를 낸 다음 날 '활성 학습자'와 '평균 학습 시간'을 보면 참여 정도를 가늠할 수 있어요.","no":"클래스 종합 대시보드는 내가 맡은 클래스의 이용 현황을 모아 보여 줍니다. 진행 중인 클래스 카드에는 개설일과 학생 수가 나오고, 아래쪽에는 학습 활동, 콘텐츠 분포, 게시판 활동 상위 학습자가 나옵니다. 화면 속 선생님 이름은 흐리게 처리했습니다.","alt":["클래스 종합 대시보드"]},{"n":48,"t":"에듀테크 종합 대시보드","sec":6,"x":"1 / 에듀테크 서비스 탭 / 2 / 활성 현황 요약 / 총 학생수 · 활성 에듀테크 수 · 주간 학습 시간 · 콘텐츠 완료율 / 3 / 주간 출석률 추이 / 날짜 × 시간 칸이 진할수록 많이 접속 / 4 / 일일 접속자 수 / 옆에 월간 로그인 평균 추이도 있어요. / TIP / 지난주와 비교한 증감도 함께 나와요. 학년 협의 때 에듀테크 활용 자료로 써 보세요.","no":"에듀테크 종합 대시보드는 학생들이 배움터 에듀테크를 얼마나 쓰고 있는지 보여 줍니다. 주간 학습 시간과 콘텐츠 완료율은 지난주와 비교한 증감도 함께 나옵니다. 출석률 추이와 일일 접속자 수 그래프로 언제 많이 접속하는지 볼 수 있습니다.","alt":["에듀테크 종합 대시보드"]},{"n":49,"t":"꼭 알아 둘 점","sec":7,"x":"정리 / 학생배정이 먼저 / 자료·과제·꾸러미는 배정된 학생에게만 가요. '제출 0/0명'이면 배정부터 확인해요. / 클래스 선택 조심 / 체크한 다른 반 학생에게도 바로 나가요. 한 반이면 누르지 않아요. / 마감 시각 확인 / 달력으로 고르면 01:00으로 들어가요. 마감일은 하루 넉넉히. / 꾸러미 고친 뒤엔 / 클래스에서 제외하고 다시 등록해야 학생 화면이 바뀌어요. / 공개 범위와 저작권 / 전체공개 전엔 학생 정보가 없는지, 올린 파일의 저작권 유형은 맞는지 봐요. / 권한과 연결 조건 / 클래스 만들기가 '권한 없음'으로 막힐 때가 있어요. LMS 연결은 생성 15분 뒤, 1개만.","no":"여섯 가지만 기억해 주세요. 학생배정이 먼저이고, 과제 만들 때 클래스 선택은 여러 반에 낼 때만 씁니다. 마감 시각은 01시로 들어가니 하루 여유를 두시고, 꾸러미를 고치면 클래스에서 제외 후 다시 등록합니다. 공개하기 전에는 학생 정보와 저작권을 한 번 더 확인해 주세요. 클래스 만들기에서 권한이 없다는 창이 뜨면 이미 있는 클래스를 먼저 써 주세요.","alt":[]},{"n":50,"t":"수업에 이렇게 써 보세요","sec":7,"x":"정리 / 예습 · 복습 / 차시 꾸러미 / 성취기준 영상 2개 + 활동지로 한 차시를 묶어 클래스에 등록해요. / 활동지 수업 / 자료 + 자료과제 / 활동지를 올리고, 다 쓴 결과를 사진으로 받아요. / 짧은 글쓰기 / 개별과제 / 기간을 정해 받고, 현황표와 엑셀로 정리해요. / 전담 수업 / 여러 반에 한 번에 / 같은 과제를 클래스 선택으로 맡은 반 모두에 내요. / 학급 소식 / 알림 / 준비물·일정 안내, 필요하면 댓글로 질문 받기 / 돌아보기 / 대시보드 / 언제, 얼마나 학습했는지 보고 다음 수업을 정해요.","no":"처음부터 모두 쓰실 필요는 없습니다. 이번 주에 활동지 하나를 자료과제로 올려 보시고, 다음 주에 성취기준 하나로 꾸러미를 만들어 보시는 정도로 시작해 보세요. 전담 선생님은 클래스 선택으로 여러 반에 한 번에 내는 기능이 특히 편하실 겁니다.","alt":[]},{"n":51,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":7,"x":"연수가 끝난 뒤에도 / 우리 반 클래스 점검 / 학생배정과 LMS 연결을 함께 확인해요. / 첫 꾸러미 같이 만들기 / 단원 성취기준에 맞는 콘텐츠를 함께 골라요. / 과제 결과 정리 / 제출 현황과 엑셀 내려받기를 함께 봐요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 우리 반 클래스 점검이나 첫 꾸러미 만들기를 할 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,48274],[48274,51894],[100168,61374],[161542,75490],[237032,66542],[303574,74294],[377868,61076],[438944,67460],[506404,107828],[614232,68380],[682612,75186],[757798,69534],[827332,62642],[889974,52004],[941978,51074],[993052,57676],[1050728,63162],[1113890,58236],[1172126,62144],[1234270,72390],[1306660,56078],[1362738,61754],[1424492,60612],[1485104,67782],[1552886,64900],[1617786,76416],[1694202,62172],[1756374,60592],[1816966,71916],[1888882,72506],[1961388,63418],[2024806,60364],[2085170,67428],[2152598,66324],[2218922,75504],[2294426,72564],[2366990,64572],[2431562,87156],[2518718,56458],[2575176,58488],[2633664,52268],[2685932,56718],[2742650,80366],[2823016,79538],[2902554,88214],[2990768,58848],[3049616,67818],[3117434,68066],[3185500,61748],[3247248,54264],[3301512,39364]],"toffs":[[0,5090],[5090,4290],[9380,5066],[14446,4988],[19434,5274],[24708,5934],[30642,4936],[35578,5252],[40830,7248],[48078,5806],[53884,6480],[60364,5966],[66330,5192],[71522,4412],[75934,3950],[79884,4854],[84738,5032],[89770,4468],[94238,5142],[99380,5770],[105150,4602],[109752,5166],[114918,5064],[119982,5244],[125226,5240],[130466,5954],[136420,4902],[141322,5452],[146774,6258],[153032,6012],[159044,5138],[164182,4772],[168954,5506],[174460,5638],[180098,5798],[185896,6128],[192024,5756],[197780,6468],[204248,4230],[208478,4540],[213018,3902],[216920,4852],[221772,6502],[228274,6646],[234920,6140],[241060,4774],[245834,5230],[251064,5314],[256378,4440],[260818,3868],[264686,3840]],"packSize":3340876,"thumbSize":268526},{"key":"googleclassroom","name":"구글 클래스룸","title":"구글 클래스룸 사용 안내서","group":"base","sub":"배움터 클래스와 연결해 공지·과제·퀴즈 수업 운영하기","fee":"무료 범위","feeKind":"free","feeNote":"","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 구글 클래스룸과 배움터 연결 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 구글 클래스룸을 열고 계정을 확인해요"},{"start":7,"num":"2","label":"수업 만들고 연결하기","desc":"배움터에서 클래스를 만들고 LMS로 구글 클래스룸과 연결해요"},{"start":15,"num":"3","label":"수업 화면과 공지","desc":"수업 화면 구성을 살펴보고 공지를 올려요"},{"start":17,"num":"4","label":"수업 과제","desc":"주제, 과제, 질문을 만들어 수업 과제를 내요"},{"start":23,"num":"5","label":"Gemini로 퀴즈 만들기","desc":"Gemini로 퀴즈를 만들고 검토한 뒤 퀴즈 과제로 내요"},{"start":30,"num":"6","label":"학생과 설정","desc":"학생 과제물, 초대, 수업 설정과 유의사항, 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"구글 클래스룸","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 배움터 클래스와 연결해 공지·과제·퀴즈 수업 운영하기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 수업 지원 서비스 가운데 구글 클래스룸을 함께 써 보겠습니다. 구글 클래스룸은 공지, 과제, 퀴즈를 한곳에서 내고 걷는 온라인 교실입니다. 오른쪽 화면도 연수를 준비하면서 배움터에서 클래스를 직접 만들고 구글 클래스룸과 연결한 뒤 공지와 과제를 올려 본 것입니다.","alt":["연수 실습으로 만든 구글 클래스룸 수업 게시판에 공지, 과제, 퀴즈, 질문이 올라간 모습"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 구글 클래스룸, 계정 확인 / 04–06쪽 / STEP 2 / 수업 만들고 연결하기 / 배움터 클래스 만들기, LMS 연결 / 07–14쪽 / STEP 3 / 수업 화면과 공지 / 화면 구성, 공지 올리기 / 15–16쪽 / STEP 4 / 수업 과제 / 주제, 과제와 학습지, 질문 / 17–22쪽 / STEP 5 / Gemini로 퀴즈 / 퀴즈 생성, 검토, 퀴즈 과제 / 23–29쪽 / STEP 6 / 학생과 설정 / 과제물 확인, 초대, 수업 설정 / 30–34쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 수업 만들고 연결하기와 4단계 수업 과제만 꼭 해 보세요. 5단계는 클래스룸 안에 들어 있는 Gemini 도구로 퀴즈를 만들고, 그 결과를 검토해서 퀴즈 과제로 내는 순서입니다.","alt":[]},{"n":3,"t":"구글 클래스룸으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 게시판 공지 / 공지와 자료를 한 화면에 올려요 / 과제 배부와 회수 / 학습지를 학생별 사본으로 나눠 주고 걷어요 / 퀴즈 과제 / 설문지 퀴즈로 자동 채점해요 / Gemini 도구 / 퀴즈·기준표 초안을 AI로 만들어요 / 배움터와 연결하면 / 배움터 클래스가 클래스룸 수업으로 / 배움터 'AI 맞춤형 교수학습 플랫폼'에서 클래스를 만들고 LMS로 구글 클래스룸을 연결하면, 클래스룸에 같은 이름의 수업이 생겨요. / 클래스룸은 배움터 구글 계정 (@aiep.gbe.kr)으로 열려요.","no":"구글 클래스룸은 공지를 올리고, 과제를 나눠 주고 걷고, 퀴즈로 채점하는 흐름으로 씁니다. 클래스룸 안에는 Gemini 도구도 들어 있어서 퀴즈나 기준표 초안을 만들 수 있습니다. 배움터에서는 클래스를 먼저 만든 뒤 구글 클래스룸을 연결하는 방식으로 쓰는데, 연결하고 나면 클래스룸에 같은 이름의 수업이 생기는 것을 확인할 수 있었습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 구글 클래스룸 열기","sec":1,"x":"1 / 수업 지원 서비스 / 배움터에 교원으로 로그인한 뒤 메인 화면을 내리면 에듀테크 서비스 아래에 있어요. / 2 / 구글 클래스룸 / 누르면 새 탭에서 클래스룸이 열려요. / TIP / 크롬에 다른 구글 계정이 함께 로그인돼 있어도 이 타일로 들어가면 배움터 계정으로 열렸어요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 메인 화면을 조금 내리면 에듀테크 서비스 아래에 수업 지원 서비스가 나옵니다. 구글 클래스룸을 누르면 새 탭이 열립니다. 연수를 준비한 컴퓨터에는 개인 구글 계정도 로그인돼 있었는데, 이 타일로 들어가니 배움터 구글 계정으로 클래스룸이 열렸습니다.","alt":["배움터 메인 화면의 수업 지원 서비스와 구글 클래스룸 타일"]},{"n":5,"t":"클래스룸 첫 화면","sec":1,"x":"1 / Gemini / 교사용 AI 도구 모음이에요. / 2 / 수업 목록 / 내 수업과 확인할 과제가 모여요. / 3 / + 버튼 / 수업 참여하기 · 수업 만들기","no":"클래스룸 첫 화면입니다. 왼쪽 메뉴의 Gemini는 교사용 AI 도구 모음이고, 수업 아래에는 내가 맡은 수업이 차례로 보입니다. 오른쪽 위 더하기 버튼으로 수업을 만들거나 참여할 수 있는데, 오늘은 배움터에서 클래스를 만들고 연결하는 방법을 먼저 해 보겠습니다.","alt":["구글 클래스룸 홈 화면과 왼쪽 메뉴, 오른쪽 위 + 메뉴"]},{"n":6,"t":"'수업을 찾을 수 없음'이 뜨면 계정 전환","sec":1,"x":"1 / 계정 전환 / 수업이 다른 구글 계정으로 열렸다는 뜻이에요. / 2 / @aiep.gbe.kr 계정 선택 / 배움터 계정을 고르면 수업이 바로 열려요.","no":"연수를 준비하면서 실제로 겪은 일입니다. 배움터 클래스 홈의 클래스룸 아이콘을 눌렀더니, 크롬에 먼저 로그인돼 있던 개인 구글 계정으로 열려서 수업을 찾을 수 없다는 창이 떴습니다. 계정 전환을 누르고 aiep.gbe.kr로 끝나는 배움터 계정을 고르니 수업이 바로 열렸습니다. 학교 컴퓨터에 여러 계정이 로그인돼 있다면 이 화면을 먼저 떠올려 주세요.","alt":["수업을 찾을 수 없음 안내 창과 계정 전환 버튼","구글 계정 선택 화면에서 aiep.gbe.kr 계정을 고르는 모습"]},{"n":7,"t":"배움터에서 클래스 만들기 시작","sec":2,"x":"1 / 우리반 등록하기 / 배움터 메인 '나의 강의실' 오른쪽 위에 있어요. / 2 / 구글 클래스룸 탭 / 클래스룸과 연결된 강의실만 모아 봐요. / 3 / 클래스 만들기 / 새 탭 'AI 맞춤형 교수학습 플랫폼'에서 눌러요.","no":"배움터 메인 화면의 나의 강의실에서 우리반 등록하기를 누르면 AI 맞춤형 교수학습 플랫폼이 새 탭으로 열립니다. 여기에서 클래스 현황 오른쪽의 클래스 만들기를 누릅니다. 화면 속 5-6 클래스는 이미 구글 클래스룸과 연결해 둔 클래스라서 클래스룸 아이콘이 함께 보입니다.","alt":["배움터 메인의 나의 강의실과 우리반 등록하기 버튼","AI 맞춤형 교수학습 플랫폼의 클래스 선택 화면과 클래스 만들기 버튼"]},{"n":8,"t":"클래스 만들기 1–2단계","sec":2,"x":"1 / 안내 확인 / '모두 숙지하였습니다'에 체크해요. / 2 / 다음 / 만들기 방식 선택으로 넘어가요. / 3 / 직접 클래스 만들기 / 한 반씩 만들 때 골라요. / 4 / 다음 / 기본 정보 입력으로 넘어가요. / TIP / 여러 반을 한꺼번에 만들 때는 '파일 업로드로 클래스 만들기'(csv, xlsx)를 써요.","no":"클래스 만들기는 네 단계로 진행됩니다. 1단계 안내에는 학생 배정은 클래스를 만든 뒤 클래스 관리의 학생배정 화면에서 할 수 있고, 접속 학교에 등록된 학생이 대상이라고 적혀 있습니다. 2단계에서는 직접 클래스 만들기를 고릅니다. 여러 반을 한 번에 만들 때는 파일 업로드 방식을 쓰면 됩니다.","alt":["클래스 만들기 1단계 안내 확인 체크와 다음 버튼","클래스 만들기 2단계 직접 클래스 만들기 선택"]},{"n":9,"t":"클래스 만들기 3–4단계","sec":2,"x":"1 / 클래스명 / 최대 30자예요. / 2 / 클래스 소개 / 선택, 최대 200자 / 3 / 다음 → 확인 / 이때 클래스가 만들어져요. / 4 / 학생 배정 / 지금 안 해도 돼요. / 5 / 만들기 / 배정 없이 진행 → 확인","no":"3단계에서 클래스명과 소개를 쓰고 다음을 누르면, 입력한 정보로 클래스를 만들고 학생배정 단계로 넘어간다는 확인 창이 뜹니다. 확인을 누르는 순간 클래스가 만들어집니다. 4단계에서는 학년과 반으로 학생을 검색해 배정할 수 있습니다. 연수용 실습 클래스는 학생 없이 만들었고, 만들기를 누르면 배정 없이 진행할지 한 번 더 묻습니다.","alt":["3단계 기본 정보 입력에 클래스명과 소개를 쓴 화면","4단계 학생 배정 화면과 만들기 버튼"]},{"n":10,"t":"클래스 만들기 완료","sec":2,"x":"1 / 내 클래스 바로가기 / 방금 만든 클래스 홈으로 가요. / 2 / 학생배정 바로가기 / 접속 학교에 등록된 학생 중에서 골라요. / TIP / 완료 화면 안내처럼 학생 배정과 자료 등록을 마쳐야 수업을 제대로 진행할 수 있어요.","no":"클래스가 만들어졌습니다. 만들어진 클래스는 배움터의 내 클래스 화면에서 다시 찾을 수 있습니다. 실제 수업에 쓸 클래스라면 학생배정 바로가기로 들어가 우리 반 학생을 배정해 주세요. 이제 이 클래스에 구글 클래스룸을 연결하겠습니다.","alt":["클래스만들기가 완료되었습니다 화면과 바로가기 버튼"]},{"n":11,"t":"LMS 관리에서 구글 클래스룸 연결하기","sec":2,"x":"1 / LMS 관리 / 내 클래스 › 클래스 관리 › LMS 관리 탭 / 2 / 15분 뒤에 연결 / 클래스를 처음 만든 시각부터 15분이 지나야 해요. / 3 / 구글 클래스룸 연결하기 / 웨일클래스와 구글 클래스룸 중 하나를 써요. / TIP / 15분 전에는 '연결하기'가 회색이에요. 그사이 클래스룸 화면을 둘러봐요.","no":"왼쪽 메뉴 내 클래스에서 클래스 관리로 들어가 LMS 관리 탭을 엽니다. 처음 열면 사용 설정된 LMS가 없다는 창이 뜨는데 확인을 누르면 됩니다. 화면 안내처럼 LMS 연결은 클래스를 처음 만든 시각을 기준으로 15분이 지나야 할 수 있고, 클래스마다 LMS를 하나만 고를 수 있습니다. 연수 준비 때도 클래스를 만들고 15분을 기다린 뒤 연결하기가 파랗게 바뀐 것을 확인했습니다.","alt":["클래스 관리의 LMS 관리 탭과 구글 클래스룸 연결하기 버튼"]},{"n":12,"t":"연결중 → 연결완료, 그리고 저장","sec":2,"x":"1 / 연결중 / 요청 뒤 몇 분 걸려요. 연수 준비 때는 3분쯤이었어요. / 2 / 선택 / 연결완료가 되면 구글 클래스룸 동그라미를 눌러요. / 3 / 연결완료 / 버튼 글자가 바뀌었는지 확인해요. / 4 / 저장 / 수정 확인 → 저장 완료 / TIP / '연결중'이 오래 보이면 다른 탭을 눌렀다가 LMS 관리로 다시 들어오거나 새로고침해 보세요.","no":"연결하기를 누르면 연결 요청되었다는 창이 뜨고 버튼이 연결중으로 바뀝니다. 연수 준비 때는 3분쯤 지나 구글 클래스룸에 같은 이름의 수업이 먼저 생겼고, 배움터 화면은 다시 들어가야 연결완료로 바뀌었습니다. 연결완료가 되면 구글 클래스룸 앞 동그라미를 고르고 저장을 눌러야 클래스 홈에 클래스룸 아이콘이 나타납니다.","alt":["연결 요청 뒤 구글 클래스룸 버튼이 연결중으로 바뀐 화면","연결완료 뒤 구글 클래스룸을 선택하고 저장하는 화면"]},{"n":13,"t":"배움터 클래스와 클래스룸 수업이 이어졌어요","sec":2,"x":"1 / Classroom 아이콘 / 배움터 클래스 홈에서 누르면 클래스룸 수업으로 바로 가요. / 2 / 같은 이름의 수업 / 클래스룸 수업 목록에도 '[연수 실습] 구글 클래스룸 익히기'가 생겼어요. / 3 / 수업 코드 / 학생이 직접 들어올 때 쓰는 코드예요.","no":"저장하고 클래스 홈으로 가면 오른쪽 위에 Classroom 아이콘이 생깁니다. 이 아이콘을 누르면 클래스룸의 같은 수업으로 넘어갑니다. 클래스룸 쪽에서도 수업 목록에 같은 이름의 수업이 생겼고, 게시판 왼쪽에 학생 초대용 수업 코드가 보입니다. 앞에서 본 것처럼 다른 구글 계정으로 열리면 계정 전환을 해 주세요.","alt":["배움터 클래스 홈 오른쪽 위에 생긴 Classroom 아이콘","구글 클래스룸에 새로 생긴 연수 실습 수업의 게시판"]},{"n":14,"t":"클래스룸에서 바로 만들 수도 있어요","sec":2,"x":"1 / 건너뛰기 / + › 수업 만들기를 누르면 먼저 SIS 창이 떠요. / 2 / 수업명 / 섹션·대상 학년은 선택이에요. / 3 / 만들기 / 이럴 때 알아 두기 / 이렇게 만든 수업은 배움터 클래스와 이어지지 않아요. 학생 명단을 배움터에서 관리하려면 앞의 연결 방법을 권해요.","no":"클래스룸 첫 화면의 더하기 버튼에서 수업 만들기를 눌러도 수업을 만들 수 있습니다. 처음에 SIS 연결 창이 뜨는데, 배움터 계정에서는 연결 가능한 수업이 없다고 나와서 건너뛰기를 누르면 됩니다. 다만 이렇게 만든 수업은 배움터 클래스와 이어지지 않습니다. 연수 준비 때는 화면만 확인하고 실제로 만들지는 않았습니다.","alt":["수업 만들기 첫 화면인 SIS 연결 및 SIS에서 가져오기 창과 건너뛰기 버튼","수업 만들기 창의 수업명 입력칸과 만들기 버튼"]},{"n":15,"t":"수업 화면 한눈에 보기","sec":3,"x":"1 / 다섯 개의 탭 / 게시판 · 수업 과제 · 사용자 · 성적 · 분석 / 2 / 수업 코드 / 네모 아이콘을 누르면 크게 띄워요. / 3 / 새 공지사항 / 과제를 올리면 게시판에도 알림이 쌓여요. / 4 / 캘린더 · 드라이브 · 설정 / 드라이브는 이 수업의 파일 폴더예요.","no":"수업을 열면 게시판이 먼저 보입니다. 위쪽 탭으로 수업 과제, 사용자, 성적, 분석 화면을 오갑니다. 왼쪽의 수업 코드는 학생이 직접 수업에 들어올 때 씁니다. 화면 속 게시판에는 연수 준비 때 올린 공지와, 수업 과제 탭에서 만든 과제·퀴즈·질문 알림이 함께 쌓여 있습니다. 오른쪽 위 드라이브 아이콘은 이 수업의 첨부 파일이 모이는 폴더입니다.","alt":["연수 실습 수업의 게시판 화면과 탭, 수업 코드, 새 공지사항 버튼"]},{"n":16,"t":"공지 올리기","sec":3,"x":"1 / 대상 / 전체 학생 또는 몇 명만 / 2 / 내용 / 굵게·목록 꾸미기 가능 / 3 / 첨부 / 드라이브·유튜브·파일·링크 / 4 / 게시 / 바로 올라가요. / 5 / 예약 · 임시저장 / 화살표를 눌러 골라요.","no":"새 공지사항을 누르면 작성 창이 열립니다. 대상은 기본이 전체 학생이고, 일부 학생에게만 보낼 수도 있습니다. 연수 준비 때는 한글날 과제와 퀴즈를 확인하라는 공지를 올려 보았습니다. 게시 버튼 옆 화살표를 누르면 예약과 임시저장이 나오는데, 아침 시간에 맞춰 공지를 미리 걸어 둘 때 예약을 쓰면 편합니다.","alt":["공지 작성 창의 대상, 내용, 첨부 아이콘","게시 버튼 옆 화살표를 눌러 나온 게시, 예약, 임시저장 메뉴"]},{"n":17,"t":"수업 과제 탭의 '만들기' 메뉴","sec":4,"x":"1 / 만들기 / 2 / 과제 · 퀴즈 과제 · 질문 · 자료 / 과제: 파일 제출과 채점 퀴즈 과제: 설문지 퀴즈 질문: 짧은 답이나 객관식 자료: 읽기만 하는 자료 / 3 / Gemini Notebook · Gem / 학생에게 주는 AI 학습 도구예요. / 4 / 주제 / 단원별로 과제를 묶어요.","no":"수업 과제 탭에서 만들기를 누르면 과제, 퀴즈 과제, 질문, 자료, 게시물 재사용이 나옵니다. 게시물 재사용은 다른 반에 올렸던 과제를 그대로 가져올 때 씁니다. 아래쪽 Gemini Notebook과 Gem은 학생에게 AI 학습 도구를 주는 메뉴입니다. 맨 아래 주제로 단원을 먼저 만들어 두면 과제가 단원별로 정리됩니다.","alt":["수업 과제 탭에서 만들기를 눌러 연 메뉴"]},{"n":18,"t":"주제로 단원별 정리하기","sec":4,"x":"1 / 주제 이름 / 단원명이나 행사 이름, 100자까지 / 2 / 주제 추가 / 수업 과제 탭에 칸이 생겨요. / 3 / 주제 묶음 / 화살표로 접고 펼 수 있어요. / 4 / 새 글은 위로 / 질문 · 퀴즈 · 과제 순으로 쌓였어요.","no":"연수 준비 때는 한글날 계기교육이라는 주제를 먼저 만들고, 과제와 퀴즈, 질문을 모두 이 주제에 넣었습니다. 과제를 만들 때 오른쪽 주제 칸에서 고르면 됩니다. 나중에 올린 글이 위로 쌓이니, 순서를 바꾸고 싶으면 글을 끌어서 옮기면 됩니다.","alt":["주제 추가 창에 한글날 계기교육을 입력한 모습","한글날 계기교육 주제 아래에 질문, 퀴즈, 과제가 모인 수업 과제 목록"]},{"n":19,"t":"과제 만들기 화면","sec":4,"x":"1 / 제목 · 안내 / 할 일을 순서대로 적어요. / 2 / 첨부 학습지 / 다음 장에서 자세히 / 3 / 파일 공유 옵션 / 학생별로 사본 제공 / 4 / 기한 / 마감일 이후 제출 닫기도 가능 / 5 / 주제 / 한글날 계기교육 / 6 / 점수 / 기본 100점, 점수 없음도 가능 / 7 / 과제 만들기 / 누르면 바로 게시돼요.","no":"연수 준비 때 만든 과제는 내가 좋아하는 우리말 낱말 소개하기입니다. 안내에는 낱말과 뜻, 고른 까닭, 낱말을 넣은 문장을 차례로 적도록 했습니다. 오른쪽에서 기한을 10월 9일로, 주제를 한글날 계기교육으로 골랐습니다. 기한을 정하면 마감일 이후 제출 닫기 체크 칸이 새로 나타납니다. 점수는 기본이 100점입니다.","alt":["과제 작성 화면의 제목, 안내, 첨부 학습지, 기한, 주제, 점수, 과제 만들기 버튼"]},{"n":20,"t":"학습지 붙이고 '학생별로 사본 제공'","sec":4,"x":"1 / 만들기 / 새 파일을 바로 만들어 붙여요. / 2 / Docs 등 / 새 탭에서 열려 내용을 써요. / 3 / 보기 권한 / 모두 같은 파일을 읽기만 해요. / 4 / 수정 권한 / 모두 한 파일을 함께 고쳐요. / 5 / 학생별로 사본 / 한 명씩 자기 학습지를 받아요.","no":"첨부의 만들기를 누르면 Docs, Slides, Sheets, Drawings, 설문지, Google Vids 가운데 하나를 새로 만들 수 있습니다. 연수 준비 때는 Docs를 골라 우리말 낱말 소개 학습지를 만들었는데, 이 문서는 수업 폴더에 저장되었습니다. 첨부한 뒤 파일 공유 옵션을 학생별로 사본 제공으로 바꾸면, 학생마다 자기 이름이 붙은 사본을 받아 각자 씁니다. 과제를 게시하기 전에 꼭 이 옵션을 확인해 주세요.","alt":["첨부의 만들기를 눌러 연 Docs, Slides, Sheets 등 새 파일 메뉴","파일 공유 옵션 세 가지: 보기 권한, 수정 권한, 학생별로 사본 제공"]},{"n":21,"t":"게시 방법과 올린 과제 확인","sec":4,"x":"1 / 과제 만들기 · 예약 / 지금 또는 정한 시각에 올려요. / 2 / 임시저장 / 목록에 '초안'으로 남아요. / 3 / 제출함 · 할당됨 / 낸 학생 수와 받은 학생 수 / 4 / 첨부 학습지 / 원본은 선생님 드라이브에 있어요.","no":"과제 만들기 버튼 옆 화살표를 누르면 예약과 임시저장이 나옵니다. 임시저장한 글은 수업 과제 목록에 초안으로 표시되고, 학생에게는 보이지 않습니다. 게시한 과제를 목록에서 누르면 펼쳐지면서 제출함과 할당됨 숫자가 보입니다. 연수용 수업에는 학생이 없어서 둘 다 0으로 나옵니다.","alt":["과제 만들기 옆 화살표 메뉴의 과제 만들기, 예약, 임시저장","수업 과제 목록에서 펼친 과제와 제출함, 할당됨 숫자, 첨부 학습지"]},{"n":22,"t":"질문으로 생각 모으기","sec":4,"x":"1 / 질문 / 한 문장으로 묻는 것이 좋아요. / 2 / 단답형 · 객관식 / 두 가지 중에서 골라요. / 3 / 답글 · 답 수정 / '학생들이 서로 답글을 달 수 있음'은 기본으로 켜져 있어요. / 4 / 질문하기","no":"질문은 짧은 답을 모을 때 씁니다. 연수 준비 때는 한글 자음과 모음 가운데 가장 마음에 드는 글자와 그 까닭을 묻는 단답형 질문을 올렸습니다. 학생들이 서로 답글을 달 수 있음이 기본으로 켜져 있어서, 친구의 답을 보고 의견을 나누게 할 수 있습니다. 답을 고쳐 쓸 수 있게 하려면 아래 칸도 체크해 주세요.","alt":["질문 작성 화면의 질문, 질문 유형, 답글 설정, 질문하기 버튼"]},{"n":23,"t":"클래스룸 안의 Gemini 도구","sec":5,"x":"1 / Gemini 메뉴 / 클래스룸 왼쪽 메뉴에서 열어요. / 2 / 분류 / 추천 · 계획 · 교육 자료 · 평가 · 학생 지원 · 행정 업무 / 3 / 퀴즈 생성 / 오늘 해 볼 도구예요.","no":"클래스룸 왼쪽 메뉴의 Gemini를 누르면 교육자를 위한 AI 도구 화면이 열립니다. 수업 계획 개요 작성, 퀴즈 생성, 기준표 만들기, 어휘 목록 만들기, 텍스트 번역 같은 도구가 있습니다. 오늘은 이 가운데 퀴즈 생성을 써서 한글날 퀴즈를 만들어 보겠습니다.","alt":["교육자를 위한 AI 도구 살펴보기 화면과 퀴즈 생성 카드"]},{"n":24,"t":"퀴즈 생성: 학습 목표부터 질문 유형까지","sec":5,"x":"1 / 대상 학년 · 질문 수 / 5학년, 5문제로 정했어요. / 2 / 주제와 목표 / 성취기준 문장처럼 써요. / 3 / 학습 목표 생성 / 목표 초안이 먼저 나와요. / 4 / 추천 학습 목표 / 바로 고쳐 쓸 수 있어요. / 5 / 질문 유형 / 객관식 · 참 또는 거짓을 골랐어요. / 6 / 질문 생성 / 10초쯤 걸렸어요.","no":"퀴즈 생성에는 대상 학년, 질문 수, 주제와 학생이 보여 주었으면 하는 지식을 씁니다. 연수 준비 때는 5학년, 5문제, 그리고 훈민정음을 만든 까닭과 한글 자음·모음을 만든 원리를 설명할 수 있다는 목표를 넣었습니다. 학습 목표 생성을 누르면 추천 학습 목표가 먼저 나오는데, 여기에도 손볼 곳이 있었습니다. 자음자 17자가 발음 기관의 모양을 본떴다고 나왔지만, 발음 기관을 본뜬 것은 기본자 다섯 자이고 나머지는 획을 더하거나 모양을 달리해 만든 글자입니다. 목표 칸은 바로 고칠 수 있으니 읽어 보고 고친 뒤 질문을 만들어 주세요.","alt":["퀴즈 생성 입력 화면에 대상 학년 5, 질문 수 5, 주제를 쓴 모습","Gemini가 만든 추천 학습 목표와 질문 유형 선택, 질문 생성 버튼"]},{"n":25,"t":"생성된 퀴즈 살펴보기","sec":5,"x":"1 / \"실수를 할 수 있으니\" / 화면 맨 위에도 다시 확인하라는 안내가 있어요. / 2 / 펼쳐서 재생성 · 수정 / 입력한 조건을 바꿔 다시 만들어요. / 3 / 정답 / 문제마다 정답이 함께 나와요. / TIP / 이 화면은 미리보기 전용이에요. 문제를 손으로 고치려면 설문지(Forms)로 내보내요.","no":"질문 생성을 누르고 10초쯤 지나자 다섯 문제가 정답과 함께 나왔습니다. 맨 위에는 Gemini가 실수할 수 있으니 다시 확인하라는 안내가 있습니다. 이 화면에서는 글자를 직접 고칠 수 없고, 고치려면 Forms로 내보내야 한다고 적혀 있습니다. 다음 장에서 실제로 검토하면서 찾은 문제를 보여 드리겠습니다.","alt":["Gemini가 만든 한글날 퀴즈 미리보기와 정답 표시"]},{"n":26,"t":"AI가 만든 문제는 꼭 검토해요","sec":5,"x":"처음 만든 4번 문제 / 프롬프트로 고친 뒤 / 1 / ㅁ → ㅂ도 가획 / ㄱ → ㅋ처럼 획을 더한 글자라 정답이 될 수 있어요. / 2 / 정답은 a) 하나뿐 / 그대로 냈다면 정답이 두 개인 문제가 됐어요. / 3 / ㅁ → ㅇ으로 고침 / '프롬프트를 사용해 수정'에 이유를 적었더니 d)만 바꿔 줬어요.","no":"연수 준비 때 실제로 나온 문제입니다. 4번은 획을 더해 새 글자를 만든 예로 알맞은 것을 고르는 문제였는데, 정답으로 표시된 ㄱ에서 ㅋ 말고도 보기 d의 ㅁ에서 ㅂ 역시 획을 더한 글자라 정답이 두 개가 되었습니다. 결과 아래 프롬프트를 사용해 수정 칸에 4번은 정답이 두 개이니 d를 가획이 아닌 보기로 바꿔 달라고 적었더니, d만 ㅁ에서 ㅇ으로 바뀌었습니다. AI가 만든 문제는 이렇게 한 문제씩 읽어 보고 내 주세요.","alt":["4번 문제 보기 d가 ㅁ에서 ㅂ으로, 정답은 a 하나로 표시된 처음 결과","보기 d가 ㅁ에서 ㅇ으로 바뀐 수정 결과"]},{"n":27,"t":"내보내기 › 수업에 추가","sec":5,"x":"1 / 내보내기 / 결과 맨 아래에 있어요. / 2 / 세 가지 길 / 수업에 추가 · Docs · Forms / 3 / 수업 / 연수 실습 수업을 골랐어요. / 4 / 퀴즈 과제 / 과제 · 질문 · 자료도 있어요. / 5 / 확인 / 1분쯤 걸린다고 나와요. / 겪어 본 일 / 설문지는 만들어졌는데 과제 창에 붙지 않았어요. 수업 과제 탭의 '초안'을 열고 첨부 › Drive에서 설문지를 직접 골라 붙였어요.","no":"퀴즈 결과 아래 내보내기를 누르면 수업에 추가, Docs로 내보내기, Forms로 내보내기가 나옵니다. 수업에 추가를 고르고 수업과 수업 과제 유형을 정한 뒤 확인을 누르면, Forms로 내보내는 중이라는 안내가 뜨고 1분 안쪽으로 설문지가 만들어집니다. 다만 연수 준비 때는 이어서 열린 과제 창에 설문지가 붙지 않았습니다. 수업 과제 탭에 제목 없는 과제가 초안으로 남아 있어서, 그 초안을 열고 첨부의 Drive에서 방금 만들어진 설문지를 골라 붙였습니다.","alt":["퀴즈 결과 아래 내보내기 메뉴의 수업에 추가, Docs로 내보내기, Forms로 내보내기","수업에 추가 창에서 수업과 퀴즈 과제를 고른 모습"]},{"n":28,"t":"설문지에서 제목·정답·배점 확인","sec":5,"x":"1 / 제목 고치기 / 마지막에 쓴 수정 프롬프트가 제목으로 붙어 있었어요. / 2 / 정답 체크 / 초록 체크가 정답이에요. / 3 / 답안 (1점) / 문제마다 배점을 바꿔요. / 4 / 총점 / 다섯 문제, 총점 5점 / 5 / 게시됨 / 이미 응답을 받을 수 있는 상태예요.","no":"첨부한 설문지를 눌러 열어 보니, 파일 이름과 설문지 제목이 제가 마지막에 쓴 수정 프롬프트 문장으로 붙어 있었습니다. 학생 화면에 그대로 보이니 꼭 한글날 퀴즈처럼 알맞은 제목으로 고쳐 주세요. 문제를 누르면 초록 체크로 정답이, 아래 답안 옆에 배점이 보입니다. Gemini가 만든 설문지는 문제당 1점, 총점 5점이었고 이미 게시된 상태였습니다.","alt":["구글 설문지 퀴즈 편집 화면의 제목, 정답 체크, 답안 배점, 총점, 게시됨 표시"]},{"n":29,"t":"퀴즈 과제로 내기","sec":5,"x":"1 / 첨부된 설문지 / 고친 제목으로 보여요. / 2 / Chromebook 잠금 모드 / 크롬북에서 다른 창을 막아요. / 3 / 성적 가져오기 / 퀴즈 점수를 클래스룸으로 / 4 / 주제 / 한글날 계기교육 / 5 / 과제 만들기 / TIP / 성적 가져오기를 켜면 학생은 한 번만 응답하고, 같은 도메인 계정으로만 응답해요.","no":"설문지를 붙이면 그 아래에 성적 가져오기가 나타나고 기본으로 켜져 있습니다. 화면 안내처럼 켜 두면 학생은 설문지마다 한 번만 응답할 수 있고, 이메일 주소가 수집되며, 도메인 안의 사용자만 응답할 수 있습니다. 점수는 클래스룸 성적으로 가져올 수 있습니다. 크롬북을 쓰는 교실이라면 잠금 모드를 켜서 퀴즈를 푸는 동안 다른 창을 열지 못하게 할 수 있습니다. 제목은 한글날 퀴즈 Gemini로 만든 5문제로 정하고 과제 만들기를 눌러 게시했습니다.","alt":["설문지가 붙은 퀴즈 과제 작성 화면의 성적 가져오기, 잠금 모드, 주제, 과제 만들기"]},{"n":30,"t":"학생 과제물 화면에서 확인하고 돌려주기","sec":6,"x":"1 / 안내 · 학생 과제물 / 과제 제목을 누르면 나와요. / 2 / 돌려주기 · 점수 / 점수를 매기고 학생에게 돌려줘요. / 3 / 제출함 · 할당됨 / 4 / 제출이 허용됨 / 끄면 더 이상 낼 수 없어요. / 5 / SIS로 내보내기 / 연결된 SIS로 성적을 보내는 버튼 / TIP / 연수용 수업은 학생이 없어 비어 있어요. 학생이 생기면 이 목록에 이름과 제출 상태가 나타나요.","no":"과제를 열고 학생 과제물 탭으로 가면 제출함과 할당됨 숫자, 학생 목록이 보입니다. 점수를 매긴 뒤 돌려주기를 누르면 학생에게 결과가 전달됩니다. 제출이 허용됨을 끄면 더 이상 제출을 받지 않습니다. 오른쪽 위 SIS로 내보내기는 배움터처럼 연결된 SIS가 있을 때 성적을 보내는 버튼으로 보이는데, 연수 준비 때는 학생이 없어 눌러 보지는 않았습니다.","alt":["과제의 학생 과제물 탭과 돌려주기, 점수, 제출함, 제출 허용, SIS로 내보내기"]},{"n":31,"t":"사용자 탭: 학생과 공동 교사 초대","sec":6,"x":"1 / 교사 초대 / 동학년 선생님과 함께 운영 / 2 / 학생 초대 / 3 / 그룹 / 모둠별로 과제를 낼 때 / 4 / 초대 링크 / 복사해서 알림장에 붙여요. / 5 / SIS에서 가져오기 / 연결된 명단에서 불러와요. / 6 / 이메일로 초대 / 이름이나 이메일을 입력","no":"사용자 탭에서는 교사와 학생을 초대합니다. 교사 쪽 아이콘으로 동학년 선생님을 공동 교사로 부를 수 있습니다. 학생 쪽 아이콘을 누르면 초대 링크, SIS에서 가져오기, 이메일 초대가 한 창에 나옵니다. 배움터와 연결된 수업이라 SIS에서 가져오기가 보이는 것으로 생각합니다. 다만 배움터에서 배정한 인원과 클래스룸 학생 수가 다르게 보이는 경우가 있었습니다. 시연 계정의 5-6 클래스는 배움터 배정이 23명인데 클래스룸 학생은 4명이었습니다. 첫 수업 때 이 화면에서 명단을 꼭 확인해 주세요.","alt":["사용자 탭의 교사 초대, 학생 초대 아이콘과 학생·그룹 버튼","학생 초대 창의 초대 링크, SIS에서 가져오기, 이메일 입력칸"]},{"n":32,"t":"수업 설정 살펴보기","sec":6,"x":"1 / SIS 통합 / '이 수업은 SIS에 연결되어 있습니다' — 배움터와 이어진 수업이라는 표시예요. / 2 / 초대 코드 관리 / 명단이 다 들어오면 사용 중지로 바꿔 둘 수 있어요. / 3 / 초대 링크 · 수업 코드 / '수업 코드 표시'로 TV에 크게 띄워요. / 4 / 게시판 권한 / 학생이 게시·댓글을 쓸 수 있는지 정해요. / 주의 / SIS 통합의 '연결 해제'는 누르지 마세요. 배움터와의 연결이 끊어져요.","no":"수업 화면 오른쪽 위 톱니바퀴를 누르면 수업 설정이 열립니다. 배움터에서 연결한 수업에는 일반 항목 맨 위에 SIS 통합이 있고, 이 수업은 SIS에 연결되어 있다고 나옵니다. 그 옆 연결 해제는 배움터와의 연결을 끊는 버튼이니 누르지 않도록 해 주세요. 초대 코드는 사용 설정과 사용 중지를 고를 수 있고, 수업 코드 표시를 누르면 코드를 화면 가득 띄울 수 있습니다. 게시판은 기본으로 학생이 게시와 댓글을 쓸 수 있게 되어 있습니다.","alt":["수업 설정의 SIS 통합, 초대 코드, 게시판 권한"]},{"n":33,"t":"꼭 알아 둘 점","sec":6,"x":"계정 확인 / 클래스룸은 @aiep.gbe.kr 계정으로 써요. '수업을 찾을 수 없음'이면 계정 전환. / 연결은 15분 뒤 / 클래스를 만들고 15분 뒤 연결, 요청 뒤 몇 분은 '연결중'이에요. / 학생 명단 확인 / 배움터 배정 인원과 클래스룸 학생 수가 다를 수 있어요. 첫 시간에 사용자 탭 확인. / AI 결과 검토 / 정답이 두 개인 문제, 어긋난 학습 목표가 실제로 나왔어요. / 게시 전 확인 / 학습지의 '학생별로 사본 제공', 설문지 제목을 게시 전에 봐요. / 연결 해제 주의 / 수업 설정의 SIS '연결 해제'를 누르면 배움터와 끊어져요.","no":"연수를 준비하면서 실제로 부딪힌 것들을 모았습니다. 다른 구글 계정으로 열리는 문제, 15분 기다림과 연결중 상태, 배움터 배정 인원과 클래스룸 학생 수 차이, 그리고 Gemini가 만든 문제와 학습 목표의 오류입니다. 학습지 공유 옵션과 설문지 제목은 학생 화면에 그대로 드러나니 게시하기 전에 한 번 더 확인해 주세요.","alt":[]},{"n":34,"t":"수업에 이렇게 써 보세요","sec":6,"x":"학습지 배부와 회수 / '학생별로 사본 제공'으로 내고 제출함에서 확인 / 계기교육 퀴즈 / Gemini 퀴즈 생성 → 검토 → 퀴즈 과제로 자동 채점 / 생각 나누기 / 단답형 질문에 '서로 답글'을 켜고 친구 생각 읽기 / 단원별 정리 / 주제로 과제·자료를 묶고 다른 반에 재사용 / 다른 에듀테크 결과물도 모아 두세요 / 퀴즈앤 Mission 공유 창에도 구글 클래스룸 버튼이 있어요. 배움터 에듀테크로 만든 과제 링크를 클래스룸 수업 과제로 올리면 학생이 한곳에서 찾을 수 있어요.","no":"오늘 해 본 기능만으로도 학습지 배부와 회수, 계기교육 퀴즈, 생각 나누기, 단원별 정리까지 할 수 있습니다. 처음에는 학습지 한 장을 학생별 사본으로 내 보는 것부터 시작해 보시기를 권해 드립니다. 퀴즈앤 안내서에서 보았던 Mission 공유 창에도 구글 클래스룸 버튼이 있었으니, 다른 에듀테크 과제도 클래스룸에 모아 두면 학생들이 찾기 쉽습니다.","alt":[]},{"n":35,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 연결 함께하기 / 배움터 클래스를 만들고 클래스룸과 연결해 드려요. / 첫 과제 함께 내기 / 학습지를 학생별 사본으로 내는 것까지 옆에서 도와드려요. / AI 퀴즈 함께 검토 / Gemini가 만든 문제를 같이 읽고 고쳐요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 배움터 클래스를 처음 연결하거나 첫 과제를 내실 때, 그리고 Gemini 퀴즈를 검토하실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,47468],[47468,50204],[97672,62136],[159808,55460],[215268,53324],[268592,46760],[315352,53562],[368914,73208],[442122,60694],[502816,49076],[551892,65482],[617374,64982],[682356,69770],[752126,63208],[815334,67752],[883086,56908],[939994,62322],[1002316,58246],[1060562,68756],[1129318,70070],[1199388,60150],[1259538,54970],[1314508,67108],[1381616,82796],[1464412,77022],[1541434,64198],[1605632,64334],[1669966,59838],[1729804,70170],[1799974,62580],[1862554,60392],[1922946,70036],[1992982,59858],[2052840,59212],[2112052,39980]],"toffs":[[0,4328],[4328,4204],[8532,5230],[13762,4850],[18612,4826],[23438,3920],[27358,4484],[31842,5374],[37216,4854],[42070,3774],[45844,5438],[51282,4994],[56276,5866],[62142,4962],[67104,5572],[72676,4510],[77186,5134],[82320,4796],[87116,5454],[92570,5936],[98506,4978],[103484,4534],[108018,5356],[113374,6108],[119482,5344],[124826,4948],[129774,5148],[134922,4960],[139882,5268],[145150,5098],[150248,4644],[154892,5262],[160154,4172],[164326,4668],[168994,3922]],"packSize":2152032,"thumbSize":172916},{"key":"miricanvas","name":"미리캔버스","title":"미리캔버스 사용 안내서","group":"make","sub":"경북AI배움터로 접속해 교육용 Pro로 수업 자료 만들기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"배움터로 들어가면 교원 계정에 교육용 Pro가 적용돼요(2027. 2. 28.까지). 학생은 Pro 대상이 아니에요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 미리캔버스와 교육용 Pro 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 미리캔버스에 접속하고 내 드라이브를 살펴봐요"},{"start":7,"num":"2","label":"디자인 시작하기","desc":"새 디자인을 만들고 템플릿을 적용해요"},{"start":13,"num":"3","label":"편집 기본","desc":"글자, 요소, 사진, 업로드, 배경, 페이지를 편집해요"},{"start":22,"num":"4","label":"AI 도구","desc":"AI 도구로 일러스트를 만들고 크레딧을 확인해요"},{"start":25,"num":"5","label":"공유 · 다운로드 · 발표","desc":"공유, 게시, 다운로드, 슬라이드쇼로 자료를 내보내요"},{"start":30,"num":"6","label":"꼭 알아 둘 점","desc":"교육용 요금제 유의사항과 수업 활용 아이디어"}],"slides":[{"n":1,"t":"미리캔버스","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 교육용 Pro로 수업 자료 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 미리캔버스를 함께 써 보겠습니다. 배움터로 접속하면 교원은 교육용 Pro로 쓸 수 있어서, 왕관 표시가 있는 프리미엄 템플릿까지 수업 자료에 활용할 수 있습니다. 화면 속 슬라이드도 연수 준비하면서 실제로 만들어 본 예시입니다.","alt":["미리캔버스로 만든 '오늘의 주제' 수업 슬라이드"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 미리캔버스, 내 드라이브 / 04–06쪽 / STEP 2 / 디자인 시작하기 / 새 디자인, 템플릿, 자동 저장 / 07–12쪽 / STEP 3 / 편집 기본 / 글자·요소·사진·업로드·배경·페이지 / 13–21쪽 / STEP 4 / AI 도구 / AI 일러스트 만들기와 크레딧 / 22–24쪽 / STEP 5 / 공유·다운로드·발표 / 링크 공유, 게시, PDF·PPTX, 슬라이드쇼 / 25–29쪽 / STEP 6 / 유의사항과 활용 / 교육용 요금제, 수업 활용 아이디어 / 30–32쪽","no":"오늘은 여섯 단계로 진행합니다. 접속부터 편집, AI 도구, 공유와 다운로드까지 한 번씩 직접 따라 해 보시면 됩니다. 시간이 부족하면 3단계 편집 기본과 5단계 다운로드만 꼭 해 보세요.","alt":[]},{"n":3,"t":"미리캔버스로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 템플릿으로 빠르게 / 수업 PPT, 학습지, 카드뉴스, 포스터 / 요소 · 사진 · 글꼴 / 일러스트와 사진, 저작권 안심글꼴 / AI 도구 / AI 일러스트·이미지 생성, PPT 초안 / 공유 · 내보내기 / 링크 공유, PDF·PPTX·이미지·영상 / 경북 교원 혜택 / 배움터로 접속하면 '교육용 Pro' / 왕관 표시가 붙은 프리미엄 템플릿·요소·사진과 PDF·PPTX 가져오기를 쓸 수 있어요. / 교원 Pro 지원: 2027년 2월 28일까지 학생은 Pro 대상이 아니에요.","no":"미리캔버스는 템플릿을 고르고 글자와 그림만 바꾸면 수업 자료가 완성되는 디자인 도구입니다. 경북AI배움터를 거쳐 들어가면 교원 계정에 교육용 Pro가 적용되어서, 평소 유료인 왕관 표시 콘텐츠도 쓸 수 있습니다. 지원 기간은 2027년 2월 28일까지이고, 학생은 Pro를 쓸 수 없다는 점은 배움터 Q&A 답변으로 확인했습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 미리캔버스 열기","sec":1,"x":"1 / 에듀테크 서비스 → 미리캔버스 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 미리캔버스가 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 따로 회원가입하거나 비밀번호를 넣지 않아도 돼요. 배움터 로그인 한 번이면 충분해요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 메인 화면의 에듀테크 서비스 첫 칸에서 미리캔버스를 누르면 새 탭이 열리면서 자동으로 로그인됩니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록"]},{"n":5,"t":"접속하면 처음 보이는 화면","sec":1,"x":"1 / 디자인 만들기 / 빈 디자인을 바로 시작해요. / 2 / 프로필 동그라미 / 누르면 내 워크스페이스(내 드라이브)로 가요. / 3 / 템플릿 · 추천 기능 / 주제별 템플릿과 자주 쓰는 기능을 둘러봐요. / TIP / 어느 화면에서든 오른쪽 위 디자인 만들기와 프로필 버튼 자리는 같아요.","no":"처음 열리는 화면은 템플릿 목록일 수 있습니다. 당황하지 마시고 오른쪽 위 두 버튼만 기억하시면 됩니다.","alt":["미리캔버스 접속 직후 템플릿 화면"]},{"n":6,"t":"내 워크스페이스(내 드라이브) 살펴보기","sec":1,"x":"1 / '교육용 Pro' 표시 확인 / 이 표시가 보이면 왕관 표시 프리미엄 콘텐츠를 쓸 수 있어요. / 2 / 새 디자인 만들기 / 만들 자료의 종류와 크기를 고르고 시작해요. / 3 / miricle AI로 만들기 / 주제만 넣고 AI로 디자인을 시작해요. / 4 / 내 드라이브 / 만든 디자인이 모두 모이는 곳이에요. 폴더 정리와 휴지통도 여기 있어요.","no":"왼쪽 위 이름 아래에 교육용 Pro라고 떠 있으면 배움터 연동이 잘 된 것입니다. 만든 디자인은 저장 버튼 없이도 이곳 내 드라이브에 모입니다.","alt":["미리캔버스 워크스페이스 내 드라이브 화면"]},{"n":7,"t":"무엇을 만들지 고르기","sec":2,"x":"1 / 프레젠테이션 1920×1080 / 수업 PPT를 만들 때 / 2 / 문서 서식 세로형 794×1123 / A4 세로 크기 — 학습지, 가정통신문, 안내문 / 3 / 파일 가져오기 (PDF·PPTX) / 쓰던 자료를 불러와 이어서 편집 / 4 / 직접 입력 / 원하는 크기를 숫자로 지정 / TIP / 위쪽 검색창에 '학습지', '포스터'처럼 만들 것을 입력해도 돼요.","no":"새 디자인 만들기를 누르면 이 창이 뜹니다. 수업 PPT는 프레젠테이션, 학습지는 문서 서식 세로형을 고르시면 됩니다.","alt":["새 디자인 만들기 창의 종류 선택 화면"]},{"n":8,"t":"편집 화면 한눈에 보기","sec":2,"x":"1 / 메뉴 바 / 템플릿·요소·텍스트·사진·업로드·AI 도구·배경 / 2 / 메뉴 패널 / 고른 메뉴의 내용이 열리는 곳 / 3 / 캔버스 / 지금 편집하는 페이지 / 4 / 페이지 목록 / 페이지 추가와 이동, 순서 바꾸기 / 5 / 공유 · 슬라이드쇼 · 다운로드 / 완성한 자료를 내보내는 버튼","no":"편집 화면은 다섯 구역만 기억하시면 됩니다. 왼쪽 메뉴를 누르면 옆 패널이 바뀌고, 가운데 캔버스에서 고치고, 아래에서 페이지를 고르고, 오른쪽 위에서 내보냅니다.","alt":["미리캔버스 편집 화면 구성"]},{"n":9,"t":"템플릿 검색하기","sec":2,"x":"1 / 검색창에 주제어 입력 / 예: 오늘의 수업, 학습목표, 퀴즈 / 2 / 디자인 종류 필터 / 지금 만드는 종류(프레젠테이션)에 맞는 템플릿만 보여 줘요. / 3 / 마우스를 올려 미리보기 / 다른 페이지가 넘어가며 보여요. 숫자는 페이지 수, 왕관은 프리미엄이에요. / TIP / 왕관(프리미엄) 템플릿도 교육용 Pro라서 그대로 쓸 수 있어요.","no":"오늘의 수업이라고 검색하면 초등 수업용 템플릿이 많이 나옵니다. 썸네일에 마우스를 올리면 안쪽 페이지도 미리 볼 수 있습니다.","alt":["템플릿 메뉴에서 오늘의 수업을 검색한 화면"]},{"n":10,"t":"템플릿 적용하기","sec":2,"x":"1 / '이 템플릿으로 덮어쓰기' / 템플릿의 모든 페이지가 한 번에 들어와요. / 2 / 필요한 페이지만 클릭 / 고른 페이지만 내 디자인에 추가돼요. / TIP / 이미 만들던 디자인이라면 덮어쓰기보다 필요한 페이지만 넣는 쪽이 안전해요.","no":"템플릿을 누르면 상세 패널이 열립니다. 새 디자인이면 덮어쓰기를, 만들던 디자인이면 필요한 페이지만 골라 넣으시면 됩니다.","alt":["템플릿 상세 패널의 덮어쓰기 버튼과 페이지 미리보기"]},{"n":11,"t":"적용 결과와 자동 저장","sec":2,"x":"1 / 실시간 자동 저장 / 저장 버튼을 따로 누르지 않아도 돼요. / 2 / 제목 입력 / 내 드라이브에서 찾기 쉽게 꼭 이름을 붙여요. 예: [5학년 과학] 오늘의 수업 / 3 / 페이지 목록 / 템플릿 9쪽이 모두 들어온 모습이에요. / 4 / 어울리는 요소 찾기 / AI가 디자인에 맞는 요소를 추천해요. 필요 없으면 X로 닫아요.","no":"덮어쓰기를 누르면 아홉 쪽이 한 번에 들어옵니다. 저장은 자동이니 제목만 꼭 바꿔 주세요. 오른쪽에 뜨는 어울리는 요소 찾기 창은 닫아도 됩니다.","alt":["템플릿이 적용된 편집 화면과 자동 저장 안내"]},{"n":12,"t":"AI로 프레젠테이션 초안 만들기","sec":2,"x":"1 / 'AI 프레젠테이션 시작하기' / 새 프레젠테이션을 열면 뜨는 안내 창에서 시작해요. / 2 / 'AI로 프레젠테이션 만들기' / 캔버스 왼쪽 아래 버튼으로도 열 수 있어요. / TIP / 주제를 입력하면 AI가 초안을 만들어 줘요. 내용은 꼭 직접 확인하고 다듬어 주세요.","no":"빈 프레젠테이션을 만들면 AI로 초안을 만들어 보겠냐는 창이 뜹니다. 주제만 넣으면 초안이 나오는데, 사실 관계와 표현은 선생님이 꼭 확인하셔야 합니다.","alt":["새 프레젠테이션에서 뜨는 AI 프레젠테이션 안내 창"]},{"n":13,"t":"글자 고치기","sec":3,"x":"1 / 글상자 두 번 클릭 / 커서가 생기면 내용을 지우고 새로 입력해요. / 2 / 작은 도구 막대 / 복제·삭제·잠금 등을 바로 할 수 있어요. / 3 / 왼쪽 속성 패널 / 글꼴, 크기, 굵게, 정렬, 색, 외곽선·그림자·곡선·세로쓰기 / TIP / 템플릿 속 학교 이름과 선생님 이름 자리부터 바꿔 보세요.","no":"예시에서는 비즈 초등학교를 석적초등학교로, 김미리 선생님을 5학년 과학으로 바꿨습니다. 글상자를 한 번 누르면 왼쪽에 속성 패널이 열리고, 두 번 누르면 글자를 고칠 수 있습니다.","alt":["글상자를 선택하고 속성 패널이 열린 화면"]},{"n":14,"t":"글자 새로 넣기","sec":3,"x":"1 / 제목 · 부제목 · 본문 추가 / 누르면 캔버스에 글상자가 생겨요. / 2 / '스타일' 탭 / 미리 꾸며 둔 글자 디자인을 골라 넣어요. / 3 / 저작권 안심글꼴 / 저작권 걱정을 덜어 주는 글꼴 모음이에요.","no":"새 글상자가 필요하면 텍스트 메뉴에서 제목, 부제목, 본문 중 하나를 누르시면 됩니다.","alt":["텍스트 메뉴 패널"]},{"n":15,"t":"요소(그림·아이콘) 검색하기","sec":3,"x":"1 / 검색어 입력 / 스타일과 용도를 함께 쓰면 AI가 더 잘 찾아요. 예: 귀여운 현미경 / 2 / 종류 탭 / 일러스트, 도형, 선, 스마트 요소 등 / 3 / 필터 / 잘 어울리는 · 색상 변경 가능 · 3D · 픽셀 / 4 / 클릭해서 추가 / 누르면 캔버스 가운데에 들어가요.","no":"요소 검색창에 마우스를 올리면 스타일과 용도를 함께 입력하라는 안내가 뜹니다. 귀여운 현미경처럼 꾸밈말을 붙이면 원하는 그림을 빨리 찾을 수 있습니다.","alt":["요소 메뉴에서 귀여운 현미경을 검색한 결과"]},{"n":16,"t":"요소 옮기고 꾸미기","sec":3,"x":"1 / 끌어서 옮기기 / 모서리 점을 끌면 크기가 바뀌어요. / 2 / 작은 도구 막대 / 복제·삭제·잠금 등 / 3 / 색상 바꾸기 / 색 칸을 눌러 자료 분위기에 맞춰요. / 4 / 비슷한 요소 / 같은 스타일의 다른 그림을 바로 찾아요.","no":"요소를 누르면 왼쪽에 색상과 비슷한 요소가 나옵니다. 같은 그림체로 여러 개를 쓰고 싶을 때 비슷한 요소가 편합니다.","alt":["현미경 일러스트를 선택하고 속성 패널이 열린 화면"]},{"n":17,"t":"사진 넣기","sec":3,"x":"1 / 무료 AI 도구 / AI로 원하는 사진 만들기, 흰 배경 이미지 만들기 등 / 2 / 사진 검색 / 예: 식물 관찰하는 어린이 / 3 / 골라서 클릭 / 캔버스에 바로 들어가요. 왕관 사진도 교육용 Pro로 쓸 수 있어요.","no":"사진 메뉴 위쪽에는 무료 AI 도구가, 검색하면 아래에 사진이 나옵니다.","alt":["사진 메뉴의 무료 AI 도구와 사진 검색 결과"]},{"n":18,"t":"내 파일 올리기","sec":3,"x":"1 / 업로드 / 내 컴퓨터의 사진·이미지를 올려요. / 2 / PDF · PPTX 가져오기 / 기존 자료 파일을 편집할 수 있는 디자인으로 불러와요. / 3 / 새 폴더 / 올린 파일을 단원별로 정리해요. / 4 / 올린 파일 목록 / 한 번 올리면 다른 디자인에서도 다시 쓸 수 있어요.","no":"업로드한 파일은 계정에 남아서 다른 디자인을 만들 때도 다시 꺼내 쓸 수 있습니다.","alt":["업로드 메뉴 패널"]},{"n":19,"t":"쓰던 PPT 그대로 가져와 고치기","sec":3,"x":"1 / 업로드 → PDF·PPTX 가져오기 / 새 디자인 만들기 → 파일 가져오기로도 할 수 있어요. / 2 / 살아 있는 상태로 열림 / 원본의 텍스트·이미지·도형을 그대로 고칠 수 있어요. / 3 / 미리캔버스로 다듬기 / 템플릿·요소·AI 도구를 더해 예전 자료를 새로 꾸며요. / TIP / 가져온 뒤에는 글꼴과 배치가 원본과 같은지 한 번 훑어보세요.","no":"편집 화면에 처음 들어가면 이 안내 창이 뜹니다. 예전에 만든 PPT를 버리지 않고 미리캔버스에서 이어서 고칠 수 있다는 점이 가장 반응이 좋은 기능입니다.","alt":["PPTX 가져오기 기능 업데이트 안내 창"]},{"n":20,"t":"배경 바꾸기","sec":3,"x":"1 / 배경색 / 색 칸을 눌러 단색 배경으로 / 2 / 그래픽 배경 / 그라데이션·물결 같은 디자인 배경 / 3 / 텍스처 배경 / 종이·벽 같은 질감 배경 / 4 / AI로 배경 만들기 / '몽환적인 배경 만들기' 등 무료 AI 도구","no":"배경 메뉴에서 색, 그래픽, 텍스처를 고를 수 있습니다. 템플릿 배경을 그대로 두고 싶으면 손대지 않으셔도 됩니다.","alt":["배경 메뉴 패널"]},{"n":21,"t":"페이지 추가 · 복제 · 삭제","sec":3,"x":"1 / 페이지에서 오른쪽 클릭 / 페이지 추가(Shift+Enter) · 복제(Ctrl+D) · 삭제(Delete) / 2 / 페이지 목록 / 편집할 페이지를 눌러 이동해요. / TIP / 같은 틀의 활동지를 여러 장 만들 때는 '페이지 복제'가 가장 빨라요.","no":"아래 페이지 목록에서 오른쪽 버튼을 누르면 추가, 복제, 삭제 메뉴가 나옵니다. 단축키도 함께 적혀 있습니다.","alt":["페이지 목록에서 오른쪽 클릭으로 연 메뉴"]},{"n":22,"t":"AI 도구 모아 보기","sec":4,"x":"1 / AI로 시각자료 생성 / 시각 페이지 · 인포그래픽 / 2 / 이미지 분해 / 그림 속 요소나 글자를 떼어 내 고치기 / · / AI로 이미지 생성 / 아이콘 · AI 포토 · 일러스트 · 3D 아이콘 · 글자 이미지 · 캐릭터 · 명화 스타일 / · / AI로 디자인 생성 / 포스터 · SNS 카드뉴스 · 썸네일 · 만화&웹툰 / · / AI로 영상 생성 · AI로 편집 / 동영상 · 애니메이션 장면 / 사이즈 변경 · 이미지 확장 · 번역 · 배경 교체","no":"AI 도구 메뉴를 내리면 이런 묶음이 차례로 나옵니다. 오늘은 이 가운데 일러스트 만들기를 직접 해 보겠습니다.","alt":["AI 도구 메뉴 패널"]},{"n":23,"t":"AI 일러스트 직접 만들어 보기","sec":4,"x":"1 / AI 도구 → 일러스트 / 'AI로 이미지 생성하기' 묶음 안에 있어요. / 2 / 스타일 고르기 / 준비된 그림체 가운데 하나를 골라요. / 3 / 결과물 묘사 / 장면을 자세히 써요. 예: 돋보기로 화분의 새싹을 관찰하는 초등학생, 밝고 따뜻한 색감 / 4 / 생성 / 30초 정도 기다리면 그림이 나와요.","no":"결과물 묘사 칸에 누가, 무엇을, 어떤 느낌으로를 넣으면 원하는 그림에 가까워집니다. 연수 준비 때 이 문장으로 실제 생성해 보니 30초 남짓 걸렸습니다.","alt":["AI 이미지 생성 메뉴와 일러스트 만들기 입력 화면"]},{"n":24,"t":"생성 결과와 크레딧","sec":4,"x":"1 / 결과 그림 클릭 / 캔버스에 넣고 크기와 위치를 맞춰요. / 2 / 다시 생성 · 추가 편집 / 마음에 안 들면 다시 만들고, 세부는 추가 편집으로 고쳐요. / 3 / 크레딧 버튼 / 남은 크레딧을 확인해요. / 4 / 크레딧 안내 / Pro는 매일 1,000 크레딧이 충전되고, 그날 받은 크레딧은 그날만 쓸 수 있어요. / TIP / 생성할 때마다 크레딧이 쓰여요. 묘사를 구체적으로 써서 한 번에 원하는 그림을 얻어 보세요.","no":"크레딧 안내 문구는 화면에 뜬 내용을 그대로 옮겼습니다. 하루 단위로 충전되고 그날 지나면 사라지니 아껴 둘 필요는 없지만, 한 번에 많이 쓰면 그날은 부족할 수 있습니다.","alt":["AI 일러스트 생성 결과와 AI 크레딧 안내 창"]},{"n":25,"t":"공유하기","sec":5,"x":"1 / 이름 · 이메일 입력 / 함께 편집할 선생님을 추가해요. / 2 / 접근 권한 / 처음에는 '제한됨(추가된 사용자만)'으로 되어 있어요. / 3 / 링크 복사 / 공유 링크를 복사해 메신저로 보내요. / 4 / 맞춤법 검사 / 공유하기 전에 맞춤법 검사를 먼저 제안해 줘요.","no":"오른쪽 위 공유를 누르면 이 창이 열립니다. 동학년 선생님과 같이 고치려면 이름이나 이메일로 추가하시면 됩니다.","alt":["공유 패널"]},{"n":26,"t":"접근 권한 바꾸기","sec":5,"x":"1 / 제한됨(추가된 사용자만) / 초대한 사람만 열 수 있어요. / 2 / 링크가 있는 누구나 / 링크를 아는 사람은 누구나 열 수 있어요. / TIP / 학생·학부모에게 보여 줄 때는 '링크가 있는 누구나'로 바꾼 뒤 링크를 복사하세요. 개인정보가 담긴 자료는 '제한됨'으로 두세요.","no":"링크만 보내면 열리지 않는 경우가 많은데, 대부분 접근 권한이 제한됨으로 되어 있어서입니다.","alt":["접근 권한 선택 목록"]},{"n":27,"t":"게시: 웹 문서로 공개하기","sec":5,"x":"1 / 디자인 문서 공개 / 켜면 링크로 볼 수 있는 웹 문서가 돼요. / 2 / 페이지 스타일 / 좌우 슬라이드 등 보는 방식을 골라요. / 3 / 상세 옵션 / 세부 설정을 더 바꿀 수 있어요. / 4 / 템플릿 링크 공유 / 받은 사람이 이 디자인을 자기 사본으로 가져가 편집할 수 있어요. / TIP / 템플릿 링크로 학생 과제를 나눠 주기 전에, 선생님 계정 둘로 먼저 시험해 보세요.","no":"게시 탭에서는 디자인을 웹 문서처럼 공개하거나 템플릿 링크로 나눠 줄 수 있습니다. 학생 활용 전에는 꼭 미리 시험해 보시길 권합니다.","alt":["공유 창의 게시 탭"]},{"n":28,"t":"다운로드하기","sec":5,"x":"1 / 파일 형식 / PNG·JPG 이미지, PDF(웹용·인쇄용), PPTX, MP4·GIF / 2 / 페이지 선택 / 전체 또는 필요한 페이지만 / 3 / 고해상도 다운로드 / 설정을 마치고 누르면 내려받아요. / 4 / PPTX / 글자를 고칠 수 있는 파워포인트 파일로 받아요. / TIP / 학습지 인쇄는 'PDF(인쇄용)', 화면 수업용은 'PDF(웹용)'이나 PPTX가 편해요.","no":"다운로드를 누르면 파일 형식과 페이지를 고를 수 있습니다. 한글이나 파워포인트에서 더 고치고 싶으면 PPTX로 받으시면 됩니다.","alt":["다운로드 패널과 파일 형식 목록"]},{"n":29,"t":"슬라이드쇼로 바로 수업하기","sec":5,"x":"1 / 오른쪽 위 '슬라이드쇼' / 누르면 바로 전체 화면으로 바뀌어요. / 2 / 방향키로 넘기기 / → 다음 장, ← 이전 장 / 3 / Esc로 나가기 / 편집 화면으로 돌아와요. / TIP / PPT로 내려받지 않아도 미리캔버스에서 바로 수업할 수 있어요.","no":"슬라이드쇼를 누르면 곧바로 전체 화면이 됩니다. 수업 중 고칠 게 생기면 Esc로 나와서 고치고 다시 슬라이드쇼를 누르시면 됩니다.","alt":["슬라이드쇼 전체 화면"]},{"n":30,"t":"교육용 요금제 유의사항","sec":6,"x":"1 / 교육 · 학습용으로만 사용 / 교육 목적 밖에서 프리미엄 콘텐츠를 단독으로 소유하거나 쓸 수 없어요. / · / 교원은 Pro, 학생은 무료 기능 / 배움터 Q&A 답변(2026.9.22) 기준, 학생은 Pro를 쓸 수 없어요. / · / 교원 Pro 지원 기간 / 2027년 2월 28일까지 / TIP / 수업 자료, 학급 안내, 교육 활동 홍보물처럼 교육 목적 안에서 써 주세요.","no":"편집 화면 위쪽 교육용 버튼을 누르면 이 안내가 뜹니다. 교원 지원 기간과 학생 Pro 불가는 경북AI배움터 Q&A와 미리캔버스 헬프센터 안내를 근거로 했습니다.","alt":["교육용 요금제 유의사항 안내 창"]},{"n":31,"t":"수업에 이렇게 써 보세요","sec":6,"x":"수업 PPT / 오늘의 수업 템플릿 → 글자 바꾸기 → 슬라이드쇼로 바로 수업 / 학습지 · 안내문 / 문서 서식 세로형(A4) → PDF(인쇄용)로 내려받아 인쇄 / 수업 삽화 / AI 일러스트로 단원에 꼭 맞는 그림 만들기 / 쓰던 PPT 새 단장 / PPTX 가져오기 → 템플릿·요소로 꾸미기 / 학생과 함께 쓰려면 / 배움터에서 학생 배정이 먼저 필요하고, 에듀테크 활용 개인정보 동의서(가정통신문)를 받아야 해요. 학생은 무료 기능으로 써요.","no":"오늘 배운 기능만으로도 수업 PPT, 학습지, 수업 삽화, 예전 PPT 새 단장까지 할 수 있습니다. 학생과 함께 쓰실 분은 학생 배정과 개인정보 동의서가 필요하니 말씀해 주세요. 동의서 가정통신문은 배움터 공지의 공식 양식을 인쇄해서 가져다 드리겠습니다.","alt":[]},{"n":32,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 계정 · 학생 배정 설정 / 교사 계정 생성부터 학생 배정까지 함께 처리해 드려요. / 도구 활용법 안내 / 수업에 맞는 활용법을 교실로 찾아가 알려 드려요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 계정 설정과 학생 배정은 교실로 찾아가 함께 처리해 드리겠습니다.","alt":[]}],"offs":[[0,43338],[43338,50614],[93952,56684],[150636,58456],[209092,69718],[278810,71240],[350050,71166],[421216,64152],[485368,81034],[566402,64152],[630554,94598],[725152,60322],[785474,72254],[857728,60042],[917770,79772],[997542,72856],[1070398,91334],[1161732,72888],[1234620,65170],[1299790,65266],[1365056,57206],[1422262,92580],[1514842,87286],[1602128,87636],[1689764,79964],[1769728,63096],[1832824,85460],[1918284,66570],[1984854,61962],[2046816,70614],[2117430,54536],[2171966,41638]],"toffs":[[0,4088],[4088,4162],[8250,4994],[13244,4746],[17990,5528],[23518,5846],[29364,5720],[35084,5288],[40372,6516],[46888,5412],[52300,7606],[59906,5004],[64910,5544],[70454,5234],[75688,6974],[82662,5984],[88646,7152],[95798,6292],[102090,6040],[108130,5696],[113826,4582],[118408,7392],[125800,7428],[133228,7558],[140786,6672],[147458,5560],[153018,7458],[160476,5412],[165888,5796],[171684,5942],[177626,4408],[182034,3980]],"packSize":2213604,"thumbSize":186014},{"key":"canva","name":"캔바","title":"캔바 사용 안내서","group":"make","sub":"경북AI배움터로 접속해 수업 자료와 학생 활동 만들기","fee":"교육용 Canva","feeKind":"paid","feeNote":"교육용 Canva는 요건을 갖춘 초중고 교사·학생에게 무료이고 프리미엄 기능도 쓸 수 있어요. 배움터 계정으로 석적초등학교 팀에 들어가 있어요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 캔바와 교육용 Canva 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 캔바에 접속하고 계정과 학교 팀을 확인해요"},{"start":7,"num":"2","label":"디자인 시작","desc":"디자인 만들기에서 교육용 템플릿으로 프레젠테이션을 시작해요"},{"start":12,"num":"3","label":"편집 기본","desc":"글자, 요소, 도구로 템플릿을 우리 수업에 맞게 고쳐요"},{"start":16,"num":"4","label":"AI로 만들기","desc":"AI 그래픽 생성과 Canva AI 학생 활동 만들기를 써 보고 결과를 검토해요"},{"start":25,"num":"5","label":"공유·발표·배정","desc":"공유, 다운로드, 발표, 배정으로 만든 디자인을 쓰고 다시 찾아요"},{"start":32,"num":"6","label":"교실과 학생","desc":"교실 메뉴에서 학급과 학생 초대를 살펴보고 유의사항과 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"캔바","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 수업 자료와 학생 활동 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 캔바를 함께 써 보겠습니다. 캔바는 템플릿을 고른 뒤 글자와 그림만 바꾸면 수업 자료가 만들어지는 디자인 도구입니다. 오른쪽 표지도 연수를 준비하면서 교육용 템플릿을 고치고 AI로 만든 그림을 넣어 직접 만들어 본 것입니다.","alt":["캔바로 만든 '오늘 배우는 단풍 관찰' 수업 표지 슬라이드"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 캔바, 계정과 학교 팀 / 04–06쪽 / STEP 2 / 디자인 시작 / 디자인 만들기, 교육용 템플릿 / 07–11쪽 / STEP 3 / 편집 기본 / 글자 고치기, 요소 넣기, 도구 / 12–15쪽 / STEP 4 / AI로 만들기 / AI 그래픽, 학생 활동 만들기 / 16–24쪽 / STEP 5 / 공유·발표·배정 / 링크, 다운로드, 발표, 배정 / 25–31쪽 / STEP 6 / 교실과 학생 / 학급, 학생 초대, 유의사항 / 32–38쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 디자인 시작과 4단계 AI로 만들기만 꼭 해 보시면 좋겠다고 생각합니다. 6단계 학생 초대는 학급마다 사정이 달라서, 화면을 함께 보며 설명만 드리도록 했습니다.","alt":[]},{"n":3,"t":"캔바로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 수업 자료 디자인 / 프레젠테이션 · 학습지 포스터 · 동영상 / AI로 만들기 / 그림 생성, 학생 활동지 만들기 / 함께 쓰기 / 링크 공유, 학교 팀과 같이 편집 / 학생에게 배정 / 교실 메뉴, 과제 검토, Google 클래스룸 / 경북 교원 혜택 / 배움터로 접속하면 '교육용 Canva' / 배움터 계정(아이디@aiep.gbe.kr)으로 로그인되고, 석적초등학교 팀에 들어가 있어요. / 교육용 Canva는 요건을 갖춘 초중고 교사·학생에게 무료이고, 프리미엄 기능도 쓸 수 있어요. (Canva 요금제 안내 기준)","no":"캔바는 수업 자료를 디자인하고, AI로 그림이나 활동지를 만들고, 링크로 함께 쓰고, 학생에게 과제로 배정하는 데까지 쓸 수 있습니다. 배움터를 거쳐 들어가면 배움터 계정으로 로그인되고 우리 학교 팀에 들어가 있는 것을 확인할 수 있었습니다. 교육용 Canva가 무료라는 내용과 프리미엄 기능 이야기는 Canva 요금제 페이지의 교육용 안내를 기준으로 했습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 캔바 열기","sec":1,"x":"1 / 에듀테크 서비스 → 캔바 / 목록 2쪽에 있어요. 누르면 새 탭에서 열려요. / 2 / 마우스를 올리면 설명 / 문서·발표 자료·이미지를 만드는 올인원 디자인 서비스 / 3 / 목록 넘기기 / 1/4 옆 화살표(›)를 눌러 2쪽으로 가요. / TIP / 따로 회원가입하지 않아도 돼요. 배움터 로그인 상태로 캔바 홈이 바로 열렸어요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 메인 화면을 조금 내리면 에듀테크 서비스 목록이 보이는데, 캔바는 그 목록의 2쪽에 있습니다. 캔바를 누르면 새 탭이 열리면서 배움터 계정으로 로그인된 캔바 홈이 바로 나왔습니다.","alt":["경북AI배움터 에듀테크 서비스 목록 2쪽의 캔바와 설명"]},{"n":5,"t":"접속하면 처음 보이는 화면 (홈)","sec":1,"x":"1 / 검색창 / 템플릿이나 내 디자인을 찾아요. / 2 / 디자인 종류 / 프레젠테이션, Docs, 화이트보드 등으로 바로 시작해요. / 3 / 왼쪽 메뉴 / 만들기 · 홈 · 교실 · 프로젝트 · 템플릿 · Canva AI / 4 / 디자인 계속하기 / 최근에 만든 디자인을 이어서 고쳐요.","no":"처음 들어오면 '오늘은 어떤 수업을 진행하시나요?'라는 문구와 검색창이 보입니다. 교사 계정이라 수업 중심으로 화면이 구성되어 있다고 보시면 됩니다. 왼쪽 메뉴 가운데 오늘은 만들기, 교실, 프로젝트, Canva AI를 주로 쓰겠습니다. 왼쪽 아래 프로필 부분은 개인정보라 흐리게 처리했습니다.","alt":["캔바 홈 화면: 검색창, 디자인 종류 아이콘, 왼쪽 메뉴, 디자인 계속하기"]},{"n":6,"t":"내 계정과 학교 팀 확인하기","sec":1,"x":"1 / 왼쪽 아래 프로필 / 동그라미를 누르면 계정 메뉴가 열려요. / 2 / 계정 / 이름과 배움터 계정(아이디@aiep.gbe.kr)이 보여요. / 3 / 팀 '석적초등학교' / 경상북도교육청 인증 표시와 팀원 수가 함께 보여요. / TIP / 팀 이름이 우리 학교로 보이면 준비 끝이에요. 같은 팀 선생님끼리는 디자인을 '석적초등학교' 범위로 공유할 수 있어요(26쪽).","no":"왼쪽 아래 프로필 동그라미를 누르면 계정 메뉴가 열립니다. 위에는 이름과 배움터 계정이, 그 아래에는 팀으로 석적초등학교가 보입니다. 연수를 준비할 때 화면에는 경상북도교육청 인증 표시와 팀원 52명이 함께 나왔습니다. 이름과 이메일은 흐리게 처리했습니다.","alt":["왼쪽 아래 프로필을 눌러 연 계정 메뉴: 계정과 석적초등학교 팀"]},{"n":7,"t":"+ 만들기 → 디자인 만들기 창","sec":2,"x":"1 / 어떤 걸 만들고 싶으세요? / 만들 종류를 검색해요. / 2 / 종류 목록 / 교육용, 프레젠테이션, Doc, 화이트보드, 시트, 맞춤형 크기 등 / 3 / 인기 디자인 / 프레젠테이션, A4 문서, 워크시트 등을 바로 골라요. / TIP / 왼쪽 맨 위 보라색 '+ 만들기'를 누르면 이 창이 열려요.","no":"새 디자인은 왼쪽 맨 위의 만들기 버튼에서 시작합니다. 창이 열리면 왼쪽에서 종류를 고르거나, 위 검색창에 '학습지', '상장'처럼 만들 것을 입력해도 됩니다. 오늘은 교육용 안에 있는 프레젠테이션으로 시작하겠습니다.","alt":["디자인 만들기 창: 검색, 종류 목록, Canva의 인기 디자인"]},{"n":8,"t":"교육용에서 프레젠테이션 고르기","sec":2,"x":"1 / 교육용 / 수업에 맞춘 디자인만 모아 보여 줘요. / 2 / Canva 라이브러리 살펴보기 / 과목·학년에 맞춘 학습 자료를 찾아 써요. / 3 / 교육용 디자인 종류 / 수업 · 프레젠테이션 · 교육 동영상 · 인포그래픽 / 오늘 실습 / '프레젠테이션'을 눌러 새 디자인을 열어 보세요. 편집 화면이 새 탭으로 열려요.","no":"교육용 탭을 누르면 커리큘럼에 맞춘 학습 자료 안내와 함께 수업, 프레젠테이션, 교육 동영상, 교육 인포그래픽이 나옵니다. 여기서 프레젠테이션을 누르면 새 탭에 빈 편집 화면이 열립니다. 이제 함께 프레젠테이션을 눌러 보겠습니다.","alt":["디자인 만들기 창의 교육용 탭: Canva 라이브러리와 수업·프레젠테이션 등 교육용 디자인"]},{"n":9,"t":"편집 화면 둘러보기","sec":2,"x":"1 / 왼쪽 도구 모음 / 템플릿 · 요소 · 텍스트 · 업로드 · 도구 / 2 / 템플릿 목록 / EDU 표시는 교육용 템플릿 / 3 / 캔버스 / 지금 고치는 슬라이드 / 4 / 페이지 추가 (+) / 빈 슬라이드를 한 장 더 / 5 / 공유 · 배정 / STEP 5에서 다뤄요 / 6 / 저장 상태 (구름) / 고칠 때마다 자동 저장돼요","no":"편집 화면은 왼쪽 도구 모음, 그 옆의 패널, 가운데 캔버스로 나뉩니다. 처음 열면 교육 프레젠테이션 템플릿이 패널에 바로 검색되어 나오는데, EDU 표시가 붙은 것이 교육용 템플릿입니다. 저장 버튼이 따로 없고, 위쪽 구름 아이콘이 저장 상태를 보여 줍니다.","alt":["빈 프레젠테이션 편집 화면: 왼쪽 도구 모음, 템플릿 목록, 캔버스, 페이지 추가, 공유·배정, 저장 상태"]},{"n":10,"t":"템플릿 고르기","sec":2,"x":"1 / 템플릿 정보 / 이름, 크기(1920×1080), 만든 사람 / 2 / 12페이지 모두 추가 / 템플릿 전체를 한 번에 넣어요. / 3 / 페이지 미리보기 / 필요한 페이지만 골라 넣을 수도 있어요. / 오늘 실습 / '오늘 배우는 수업제목' 템플릿에서 12페이지 모두 추가를 눌렀어요.","no":"템플릿을 한 번 누르면 바로 들어가지 않고 이렇게 상세 패널이 열립니다. 여기서 몇 페이지짜리인지 확인하고 모두 추가를 누르면 템플릿 전체가 들어갑니다. 실습에서는 초록색 '그린 파스텔 학교 초등학생 프레젠테이션' 템플릿을 골랐습니다.","alt":["템플릿을 누르면 나오는 상세 패널: 템플릿 정보, 12페이지 모두 추가, 페이지 미리보기"]},{"n":11,"t":"템플릿이 들어간 모습","sec":2,"x":"1 / 페이지 목록 / 12쪽이 한꺼번에 들어왔어요. 눌러서 쪽을 옮겨 다녀요. / 2 / 페이지 도구 / 바꾸기 · 넘김 시간 · 배경색 · 애니메이션 / 3 / 쪽수 (1 / 12) / 지금 보는 쪽과 전체 쪽수 / TIP / 템플릿의 글꼴과 색은 그대로 두고 글자와 그림만 바꿔도 충분해요.","no":"모두 추가를 누르면 아래쪽 페이지 목록에 12쪽이 한꺼번에 들어옵니다. 오른쪽 아래에는 지금 보는 쪽과 전체 쪽수가 1/12처럼 나옵니다. 디자인을 처음부터 짜기보다 템플릿을 그대로 두고 내용만 바꾸는 쪽이 시간도 덜 들고 결과도 깔끔하다고 생각합니다.","alt":["템플릿 12페이지가 들어간 편집 화면과 아래쪽 페이지 목록"]},{"n":12,"t":"글자 고치기","sec":3,"x":"1 / 두 번 클릭 / 글자가 파랗게 선택되면 그대로 새로 입력해요. / 2 / 글꼴 · 크기 / − / + 로 크기를 조절해요. / 3 / 색 · 굵게 · 정렬 · 목록 / 한글 문서처럼 버튼으로 바꿔요. / 4 / 효과 · 애니메이션 · 위치 / 그림자, 등장 효과, 앞뒤 순서 / TIP / 제목을 '단풍 관찰'로 고치자 디자인 이름도 저절로 바뀌었어요. 위쪽 이름을 눌러 직접 바꿀 수도 있어요.","no":"글자는 두 번 클릭하면 편집 상태가 되고, 위쪽에 글자 도구 모음이 나옵니다. 실습에서는 '수업제목'을 '단풍 관찰'로, 아래 선생님 이름 자리를 '[연수 실습] 가을 수업'으로 바꿨습니다. 제목 글자를 고치자 '제목 없는 디자인'이던 디자인 이름이 '단풍 관찰'로 저절로 바뀌었고, 나중에 위쪽 이름을 눌러 '[연수 실습] 단풍 관찰'로 정리했습니다. 글자가 너무 길면 두 줄로 넘어가니 제목은 짧게 쓰시는 편이 좋습니다.","alt":["제목 글자 '수업제목'을 두 번 눌러 선택한 모습과 위쪽 글자 도구 모음"]},{"n":13,"t":"목차 바꾸고 줄 맞추기","sec":3,"x":"1 / 목차 다섯 줄 / 줄마다 글상자가 따로 있어요. 하나씩 두 번 클릭해 고쳐요. / 2 / 2쪽 / 페이지 목록에서 눌러 옮겨 왔어요. / 해 보니 이랬어요 / 템플릿 글상자가 가운데 정렬이라, 글자 길이가 달라지자 줄 머리가 들쭉날쭉해졌어요. / → Shift를 누른 채 다섯 글상자를 모두 고르고 정렬 버튼을 '왼쪽'으로 바꾼 뒤, 함께 끌어 점 옆으로 옮겼어요.","no":"2쪽 목차는 다섯 줄이 각각 따로 된 글상자였습니다. 처음에는 가운데 정렬이라 글자 수가 다르면 줄 머리가 어긋났는데, Shift를 누른 채 다섯 개를 함께 고른 다음 정렬을 왼쪽으로 바꾸고 한꺼번에 옮겨서 맞췄습니다. 글상자 가운데를 누르면 이동 손잡이가 잡히니, 여러 개를 고를 때는 글자 왼쪽 부분을 누르시면 편합니다.","alt":["2쪽 '오늘의 수업 내용은?' 목차 다섯 줄을 단풍 수업 내용으로 바꾼 모습"]},{"n":14,"t":"요소 검색해서 그림 넣기","sec":3,"x":"1 / 요소 → 검색어 / '단풍잎'을 입력했어요. / 2 / 검색 (보라색) / 옆 '생성'은 AI 만들기(16쪽) / 3 / 결과 분류 / 그래픽 · 사진 · 동영상 · 프레임 / 4 / 그래픽 한 번 클릭 / 캔버스 가운데에 들어가요. / 5 / 크기 · 위치 / 모서리를 끌면 크기, 가운데는 이동 / 6 / 요소 도구 / 배경 제거 · 지우개 · 뒤집기","no":"왼쪽 요소 메뉴에서 '단풍잎'을 검색했습니다. 결과는 그래픽, 사진, 동영상, 프레임 등으로 나뉘어 나오고, 그래픽을 한 번 누르면 캔버스 가운데에 크게 들어갑니다. 들어온 그림은 모서리 손잡이를 끌어 줄이고, 가운데를 끌어 원하는 자리로 옮겼습니다. 그림을 고르면 위쪽에 배경 제거, 지우개, 뒤집기 같은 도구가 나옵니다.","alt":["요소 패널에서 '단풍잎'을 검색해 그래픽을 넣고 크기를 줄여 옮긴 모습"]},{"n":15,"t":"도구: 그리기 · 메모 · 표","sec":3,"x":"1 / 도구 메뉴 / 왼쪽 도구 모음의 '도구'를 눌러요. / 2 / 세로 도구 모음 / 선택 · 펜 · 도형 · 선 · 메모지 · 글상자 · 표 등 / TIP / 펜과 메모지는 화이트보드처럼 판서하거나 아이디어를 붙일 때 쓰기 좋아요. 끝나면 위쪽 ×로 닫아요.","no":"도구 메뉴를 누르면 패널 대신 세로로 된 작은 도구 모음이 나옵니다. 펜으로 그리거나, 도형과 선, 메모지, 글상자, 표를 바로 넣을 수 있습니다. 수업 중에 슬라이드 위에 표시하며 설명할 때 쓰기 좋다고 생각합니다.","alt":["왼쪽 도구 메뉴를 누르면 나오는 세로 도구 모음"]},{"n":16,"t":"요소 패널의 '생성'으로 만들 것 고르기","sec":4,"x":"1 / 생성 옆 ▾ / AI로 만들 종류를 골라요. / 2 / 만들 수 있는 것 / 이미지 · 그래픽 · 동영상 · 코드 · 음악 · 사운드 효과 · 음성 해설 · 도형 · 3D / 해 보니 이랬어요 / 종류를 고르는 순간 바로 만들기가 시작돼요. 그때 입력돼 있던 '단풍잎'으로 단풍잎만 4장 나왔어요. 설명을 먼저 다 쓰고 종류를 고르세요.","no":"요소 패널 검색창 아래 '생성' 버튼 옆 화살표를 누르면 AI로 만들 수 있는 종류가 나옵니다. 오늘은 수업 그림을 만들려고 그래픽을 골랐습니다. 다만 그래픽을 누르자마자 그때 입력돼 있던 '단풍잎'으로 바로 생성이 시작되었습니다. 그래서 설명을 먼저 다 쓰고 종류를 고르시거나, 설명을 고친 뒤 생성 버튼을 다시 누르시면 됩니다.","alt":["요소 패널 생성 버튼 옆 화살표를 눌러 연 생성 종류 목록"]},{"n":17,"t":"설명을 쓰면 그래픽이 나와요","sec":4,"x":"1 / 설명 쓰기 / '돋보기로 단풍잎을 관찰하는 초등학생, 귀여운 일러스트' / 2 / 생성 / '생각하는 중이에요…'가 잠시 보여요. / 3 / 결과 4개 / 마음에 드는 것을 눌러 넣어요. / 4 / 비슷한 검색 결과 / 아래에 이미 있는 그래픽도 함께 나와요. / TIP / 누가 · 무엇을 · 어떤 그림체로를 넣어 쓰면 원하는 그림에 가까워져요.","no":"설명을 '돋보기로 단풍잎을 관찰하는 초등학생, 귀여운 일러스트'로 고치고 생성을 다시 눌렀더니, 십여 초 뒤 설명에 맞는 그래픽 네 개가 나왔습니다. 결과 아래에는 '이 새로운 기술은 거듭 발전 중이에요'라는 안내가 함께 나오고, 그 밑에는 비슷한 기존 그래픽 검색 결과도 보입니다. 누가, 무엇을, 어떤 그림체로 그릴지 넣어 쓰면 원하는 그림에 더 가까워진다고 느꼈습니다.","alt":["'돋보기로 단풍잎을 관찰하는 초등학생, 귀여운 일러스트'로 만든 그래픽 4개"]},{"n":18,"t":"완성된 표지 한 장","sec":4,"x":"1 / AI로 만든 그래픽 / 크기를 줄여 왼쪽 아래에 두었어요. / 2 / 검색해 넣은 단풍잎 / 겹치지 않게 오른쪽 위로 옮겼어요. / 3 / 고친 제목 / 템플릿 글꼴과 색은 그대로예요. / 오늘 실습 목표 / 템플릿 하나 + 글자 고치기 + 그림 두 개. 이 정도면 수업 첫 화면으로 충분해요.","no":"지금까지 한 것을 모으면 이런 표지가 됩니다. 템플릿을 고르고, 제목을 고치고, 검색한 단풍잎과 AI로 만든 그림을 넣은 것이 전부입니다. 연수 시간에는 이 정도 한 장을 직접 만들어 보시는 것을 목표로 하시면 좋겠습니다.","alt":["AI 그래픽과 단풍잎 그림, 고친 제목이 들어간 완성 표지"]},{"n":19,"t":"Canva AI: 말로 설명해서 만들기","sec":4,"x":"1 / 왼쪽 메뉴 Canva AI / 홈 화면 왼쪽 메뉴에서 눌러요. / 2 / 입력창 / 만들고 싶은 것을 글로 쓰거나 마이크로 말해요. / 3 / 만들기 종류 / 학생 활동 만들기 · 디자인 · 이미지 · Docs · 코드 · 동영상 클립","no":"이번에는 왼쪽 메뉴의 Canva AI로 들어가 보겠습니다. 채팅하듯 만들고 싶은 것을 설명하면 디자인이나 문서를 만들어 주는 곳입니다. 입력창 아래에 학생 활동 만들기, 디자인, 이미지, Docs, 코드, 동영상 클립 버튼이 있는데, 선생님들께는 첫 번째인 학생 활동 만들기가 가장 쓸모 있다고 생각해서 이것으로 실습해 보았습니다.","alt":["Canva AI 첫 화면: '오늘은 무엇을 만들어 볼까요?' 입력창과 만들기 종류 버튼"]},{"n":20,"t":"학생 활동 만들기 ① 주제 쓰기","sec":4,"x":"1 / 주제를 간략하게 / '가을에 나뭇잎의 색이 변하는 까닭을 알아보는 퀴즈 활동' / 2 / 학생 활동 만들기 / 선택된 상태(보라색)인지 확인해요. / 3 / 학년 · 과목 · 학습 목표 / 초등학교 5학년, 과학을 골랐어요. / 4 / 보내기 (→) / 주제를 쓰면 보라색 화살표가 생겨요.","no":"학생 활동 만들기를 누르면 입력창 아래에 학년, 과목, 학습 목표를 고르는 칸이 생깁니다. 학년은 유아원부터 고를 수 있었고, 과목은 언어, 과학, 수학, 미술 같은 목록에서 고릅니다. 실습에서는 초등학교 5학년, 과학을 고르고 '가을에 나뭇잎의 색이 변하는 까닭을 알아보는 퀴즈 활동'이라고 썼습니다. 학습 목표는 비워 두었는데, 다음 화면에서 AI가 목표를 먼저 제안해 주었습니다.","alt":["학생 활동 만들기에 주제를 쓰고 학년(초등학교 5학년)과 과목(과학)을 고른 모습"]},{"n":21,"t":"학생 활동 만들기 ② 목표 확인과 활동 고르기","sec":4,"x":"1 / 학습 목표 확인 / AI가 주제로 학습 목표를 먼저 정리해 줘요. / 2 / 활동 3가지 중 고르기 / 실천하기 · 원인과 결과 파악하기 · 요약문 작성 / 3 / 생성 / 활동을 고르면 오른쪽 아래 버튼이 보라색이 돼요. / TIP / 다 만들어지면 위쪽에 '1개의 활동 중에 1개가 생성되었어요' 알림이 떠요. '최근 생성된 항목'에서 눌러 열어요.","no":"보내기를 누르면 바로 활동지가 나오지 않고, AI가 학습 목표를 먼저 정리해서 보여 줍니다. 실습에서는 '가을 나뭇잎 색 변화 원인 탐구'라는 목표가 나왔습니다. 그 아래 활동 세 가지 가운데 '가을 나뭇잎 색 변화 퀴즈 & 적용 문제'를 고르고 생성을 눌렀고, 30초쯤 기다리니 완성 알림이 떴습니다.","alt":["AI가 제안한 학습 목표와 활동 3가지 가운데 퀴즈 활동을 고른 모습"]},{"n":22,"t":"학생 활동 만들기 ③ AI가 만든 활동지","sec":4,"x":"1 / 제목과 표지 그림 / 문서(Doc) 형태로 만들어져요. / 2 / 활동 안내 / 학생에게 오늘 할 일을 알려 줘요. / 3 / 과학 지식 쌓기 / 엽록소 · 광합성 등 용어 표와 읽기 지문 / 4 / 배정 / 검토가 끝나면 여기서 학생에게 내요. / TIP / 보통 디자인처럼 글자를 두 번 눌러 바로 고칠 수 있어요.","no":"완성된 활동지를 열면 캔바 문서 편집 화면이 나옵니다. 제목, 활동 안내, 과학 지식 쌓기 순서로 되어 있고, 용어 표와 읽기 지문까지 들어 있었습니다. 위쪽 오른쪽에 배정 버튼이 있어서 검토만 끝나면 바로 학생에게 낼 수 있습니다. 실습 활동지는 '[연수 실습] 가을 나뭇잎 활동지'로 이름을 바꿔 두었습니다.","alt":["AI가 만든 문서 활동지 '가을에 나뭇잎의 색이 변하는 까닭 퀴즈' 첫 부분"]},{"n":23,"t":"활동지 안을 살펴보면","sec":4,"x":"1 / '이 지문은 인공지능을 통해 작성되었습니다' / AI가 쓴 지문 끝에 이렇게 표시돼요. / 2 / 개념 연결하기 / 핵심 개념마다 '당신의 이해'와 '왜 중요한가요?'를 채우는 표예요. / 3 / 스스로 확인하기 / 배운 원리를 다른 상황에 적용하는 질문으로 이어져요. / 내용 확인 / 노란 단풍(엽록소가 줄며 숨어 있던 노란·주황 색소가 드러남)과 붉은 단풍(당분이 쌓여 안토시아닌이 새로 생김)을 나눠 설명해, 과학 내용은 맞게 나왔어요.","no":"활동지를 내려 보면 읽기 지문 끝에 인공지능으로 작성되었다는 표시가 붙어 있습니다. 이어서 개념을 정리하는 표와 스스로 확인하기 질문이 나옵니다. 지문 내용은 노란 단풍과 붉은 단풍이 생기는 까닭을 나눠서 설명하고 있었고, 과학 내용 자체는 맞게 나왔다고 보았습니다.","alt":["활동지 가운데: 인공지능 작성 표시, 개념 연결하기 표, 스스로 확인하기 제목"]},{"n":24,"t":"학생에게 내기 전에 꼭 검토하세요","sec":4,"x":"1 / 스스로 확인하기 질문 3개 / 노란색으로 변하는 까닭, 붉은 단풍, 여름에 단풍이 들지 않는 까닭 / 2 / 'Magic Media나 Elements 기능' / 영어 기능 이름이 학생 안내문에 그대로 섞여 나왔어요. / 검토할 점 (실제 결과에서) / · 이름은 '퀴즈'인데 실제로는 표에 써 넣는 활동지였어요. / · 영어 기능 이름은 '요소 메뉴의 생성'처럼 우리말로 고쳐요. / · 표 첫 줄에 예시 답이 미리 들어 있어요. 남길지 지울지 정해요.","no":"AI가 만든 활동지는 그대로 내기보다 한 번 읽어 보고 내시기를 권합니다. 실제로 만들어 보니 이름은 퀴즈인데 객관식 문제가 아니라 표에 써 넣는 활동지였고, 마지막 안내문에는 Magic Media, Elements 같은 영어 기능 이름이 그대로 섞여 있었습니다. 개념 연결하기 표 첫 줄에는 예시 답이 미리 들어 있어서, 남길지 지울지도 정하셔야 합니다.","alt":["활동지의 스스로 확인하기 질문 3개와 배운 내용 표현하기 안내"]},{"n":25,"t":"공유 버튼 살펴보기","sec":5,"x":"1 / 사용자 추가 / 함께 고칠 선생님을 이름이나 이메일로 넣어요. / 2 / 액세스 레벨 / 링크로 누가 열 수 있는지 정해요. 처음엔 '나만 액세스 가능'(26쪽) / 3 / 링크 복사 / 메신저로 보낼 때 써요. / 4 / 학습 세션 · 다운로드 · 배정 · 공개 보기 링크 / 다운로드는 27쪽, 배정은 30쪽에서 다뤄요. / 5 / 프레젠테이션 · Google 클래스룸 · 모두 보기 / 다른 서비스로 보내거나 바로 발표해요.","no":"편집 화면 오른쪽 위의 공유를 누르면 이 창이 열립니다. 위쪽은 함께 편집할 사람과 링크로 열 수 있는 범위를 정하는 곳이고, 아래쪽 아이콘들은 다운로드, 배정, 발표처럼 디자인을 밖으로 내보내는 메뉴입니다. 다음 쪽에서 액세스 레벨부터 보겠습니다.","alt":["편집 화면 오른쪽 위 공유를 눌러 연 디자인 공유 창"]},{"n":26,"t":"액세스 레벨 3가지","sec":5,"x":"1 / 나만 액세스 가능 / 링크가 있어도 나만 열 수 있어요. 처음 만든 디자인의 기본값이에요. / 2 / 석적초등학교 / 우리 학교 팀 누구나 링크로 열 수 있어요. 동학년 자료 나눌 때 좋아요. / 3 / 링크가 있는 모든 사용자 / 링크만 있으면 누구나 열어요. / 주의 / 학생 이름·사진이 들어간 디자인은 '링크가 있는 모든 사용자'로 열지 마세요.","no":"액세스 레벨은 세 가지입니다. 처음 만든 디자인은 나만 액세스 가능으로 되어 있었습니다. 같은 학교 선생님과 나눌 때는 석적초등학교를 고르시면 되고, 링크가 있는 모든 사용자는 학교 밖 누구나 열 수 있으니 학생 정보가 들어간 자료에는 쓰지 않으시는 편이 안전합니다. 실습에서는 바꾸지 않고 나만 액세스 가능으로 두었습니다.","alt":["액세스 레벨 목록: 나만 액세스 가능, 석적초등학교, 링크가 있는 모든 사용자"]},{"n":27,"t":"파일로 내려받기 (다운로드)","sec":5,"x":"1 / 파일 형식 / 처음에는 PNG(추천)로 되어 있어요. 눌러서 바꿔요(28쪽). / 2 / 크기 · 품질 / 왕관 표시는 프리미엄 기능이에요. / 3 / 페이지 선택 / 전체 · 이 페이지만 · 맞춤형(골라서) / 4 / 다운로드 / 누르면 컴퓨터에 파일이 저장돼요. / TIP / 공유 → 다운로드 순서로 들어가요.","no":"공유 창에서 다운로드를 누르면 파일 형식, 크기, 품질, 페이지 선택이 나옵니다. 왕관 표시가 붙은 항목은 프리미엄 기능입니다. 슬라이드 한 장만 그림으로 쓰고 싶을 때는 페이지 선택에서 이 페이지를 고르시면 됩니다. 연수 준비 때는 형식만 확인하고 실제로 내려받지는 않았습니다.","alt":["공유 창에서 다운로드를 누른 화면: 파일 형식, 크기, 품질, 페이지 선택, 다운로드 버튼"]},{"n":28,"t":"어떤 파일로 받을까요?","sec":5,"x":"1 / PDF / 학습지·안내문을 인쇄할 때 / 2 / PPTX / 파워포인트에서 열어 수업할 때 / 3 / MP4 동영상 / 애니메이션을 넣은 디자인을 영상으로 / 4 / JPG · PNG / 그림 파일로. 그 밖에 SVG, GIF도 있어요. / TIP / PPTX로 받으면 학교 컴퓨터에 없는 글꼴은 다르게 보일 수 있어요. 열어서 한 번 확인해 주세요.","no":"파일 형식은 PDF, PPTX, MP4 동영상, JPG, PNG, SVG, GIF 가운데 고를 수 있었습니다. 인쇄할 학습지는 PDF, 교실 컴퓨터의 파워포인트로 수업하실 때는 PPTX가 편합니다. 다만 캔바 글꼴이 학교 컴퓨터에 없으면 모양이 달라질 수 있어서, 받은 뒤 한 번 열어 보시기를 권합니다.","alt":["다운로드 파일 형식 목록: PDF, PPTX, MP4 동영상, JPG, PNG, SVG, GIF"]},{"n":29,"t":"수업 시간에 바로 발표하기","sec":5,"x":"1 / 프레젠테이션 ▾ / 화살표를 누르면 발표 방식을 골라요. / 2 / 전체 화면 / 교실 TV에 크게 띄워요. / 3 / 발표자 보기 / 발표자 노트와 다음 슬라이드를 함께 봐요. / 4 / 녹화 · 자동 재생 / 발표하는 모습 녹화, 정한 속도로 넘기기 / TIP / 편집 화면 아래 '발표자 노트'에 할 말을 적어 두세요.","no":"캔바에서 만든 슬라이드는 파일로 내려받지 않고도 바로 발표할 수 있습니다. 프레젠테이션 버튼 옆 화살표를 누르면 전체 화면, 발표자 보기, 프레젠테이션 및 녹화, 자동 재생이 나옵니다. 발표자 보기를 쓰시려면 편집 화면 아래 발표자 노트에 미리 할 말을 적어 두시면 됩니다.","alt":["프레젠테이션 버튼 옆 화살표로 연 발표 방식 목록"]},{"n":30,"t":"학생에게 배정하기","sec":5,"x":"1 / 배정 버튼 / 편집 화면 맨 오른쪽 위에 있어요. / 2 / 학생마다 사본이 따로 / '학생들에게 각자의 사본이 개별적으로 전달됩니다.' 원본은 그대로예요. / 3 / 배정 방법 4가지 / 링크로 · Canva에서 학생에게 · Google 클래스룸 · Microsoft Teams / TIP / 방법을 고르고 '지침(선택 사항)'에 활동 안내를 쓴 뒤 '계속'을 눌러요. 연수 준비 때는 실제 학급에 배정하지 않고 이 화면까지만 확인했어요.","no":"배정은 디자인을 학생 과제로 내는 기능입니다. 화면 안내대로 학생마다 각자의 사본이 전달되기 때문에 원본이 고쳐질 걱정은 없습니다. 배정 방법은 링크, Canva에서 학생에게, Google 클래스룸, Microsoft Teams 네 가지였습니다. 연수 준비 때는 실제 학급 학생들에게 알림이 갈 수 있어서 방법 목록까지만 확인했습니다.","alt":["배정 창: 안내 문구와 배정 방법 4가지"]},{"n":31,"t":"만든 디자인 다시 찾기 (프로젝트)","sec":5,"x":"1 / 프로젝트 / 왼쪽 메뉴에서 눌러요. / 2 / 검색 / 디자인·폴더·업로드 항목을 찾아요. / 3 / 최근 / 오늘 만든 [연수 실습] 디자인 2개 / 4 / 폴더 및 수업 자료 / AI 학생 활동은 '수업'으로 묶여 저장돼요. / TIP / 자동 저장이라 창을 닫아도 괜찮아요. 여기서 다시 열면 이어서 고칠 수 있어요.","no":"만든 디자인은 왼쪽 메뉴의 프로젝트에 모입니다. 최근 항목 맨 앞에 오늘 만든 실습 디자인 두 개가 보이고, 학생 활동 만들기로 만든 활동지는 폴더 및 수업 자료에 '수업'으로 따로 묶여 있었습니다. 저장 버튼을 누르지 않아도 되니 창을 닫으셔도 괜찮습니다.","alt":["프로젝트 화면: 검색창, 최근 디자인, 폴더 및 수업 자료"]},{"n":32,"t":"교실 메뉴 둘러보기","sec":6,"x":"1 / 교실 / 왼쪽 메뉴의 학사모 아이콘 / 2 / 과제 / 모두 보기 · 검토 필요 · 검토 완료 / 3 / 제출물 · 과제 현황 / 검토할 제출물과 낸 과제 수 / 4 / 학급 목록 / 사용자 초대 · 만들기 · 관리 / TIP / 학생이 검토받으려고 보낸 디자인은 '검토 필요'에 모여요.","no":"왼쪽 메뉴의 교실은 학생과 함께 쓰는 공간입니다. 과제는 모두 보기, 검토 필요, 검토 완료로 나뉘어 있고, 가운데에는 검토할 제출물과 만든 과제 수가 나옵니다. 화면 안내대로 학생들은 언제든 선생님께 검토받을 디자인을 보낼 수 있습니다. 학급 목록의 구성원 사진은 흐리게 처리했습니다.","alt":["교실 페이지: 왼쪽 과제 메뉴, 제출물과 과제 현황, 학급 목록"]},{"n":33,"t":"학급(수업) 목록","sec":6,"x":"1 / 학급 메뉴 / 교실 안의 두 번째 메뉴 / 2 / + 수업 만들기 / 우리 반을 새로 만들어요. / 3 / 직접 만든 학급 / 예: 5학년 6반 (구성원 24명) / 4 / 자동 동기화 그룹 / 조직 관리자 · 학교 팀 관리자 · 교사","no":"교실 안의 학급 메뉴에 들어가면 수업 목록이 나옵니다. 5학년 6반처럼 선생님이 직접 만든 학급이 있고, 조직 관리자, 학교 팀 관리자, 교사처럼 '자동 동기화됨'이라고 표시된 그룹도 함께 보입니다. 새 학급은 오른쪽 위 수업 만들기로 만듭니다.","alt":["학급 메뉴의 수업 목록: 5학년 6반과 자동 동기화된 그룹들, 수업 만들기 버튼"]},{"n":34,"t":"학급 안: 과제와 팀원","sec":6,"x":"1 / 팀원 탭 / 옆 과제 탭에는 배정한 과제와 완료율이 나와요. / 2 / 수업 역할 / 선생님은 수업 관리자, 학생은 수업 회원 / 3 / + 사용자 추가 / 학생 초대 창이 열려요(35쪽). / 개인정보 / 학생 이름과 프로필은 흐리게 처리했어요. 연수 화면을 띄울 때도 이 탭은 조심해 주세요.","no":"학급을 누르면 과제와 팀원 두 탭이 나옵니다. 과제 탭에는 그 학급에 배정한 과제와 완료율이, 팀원 탭에는 학생 목록과 수업 역할이 보입니다. 학생 이름은 개인정보라 흐리게 처리했고, 실제 연수 때도 이 화면은 띄우지 않고 설명만 드리려고 합니다.","alt":["학급의 팀원 탭: 이름(흐림 처리)과 수업 역할 목록"]},{"n":35,"t":"학생 초대하는 방법 4가지","sec":6,"x":"1 / 누구를 초대할 수 있나 / 석적초등학교 이메일이 있는 사용자만 초대돼요. / 2 / 초대 링크 복사 / 링크를 학급 공지로 보내요. / 3 / 이메일로 초대 / 이름·수업·이메일을 넣고 초대장 보내기 / 4 / 코드 사용 / 교실에서 코드를 보여 주고 입력하게 해요(36쪽). / 5 / Google 클래스룸 / 클래스룸 학생을 그대로 불러와요.","no":"팀원 탭의 더하기 버튼을 누르면 수업에 사용자 초대하기 창이 열립니다. 맨 위 안내처럼 석적초등학교 이메일이 있는 사용자만 초대할 수 있으니, 학생 계정이 준비되어 있는지 먼저 확인해 주세요. 방법은 초대 링크, 이메일, 코드, Google 클래스룸 네 가지입니다. 실습에서는 실제로 초대를 보내지는 않았습니다.","alt":["수업에 사용자 초대하기 창: 초대 링크 복사, 이메일로 초대, 코드 사용, Google 클래스룸"]},{"n":36,"t":"코드로 초대하기","sec":6,"x":"1 / 4시간마다 새로 바뀌어요 / '이 초대 코드는 4시간 후 자동으로 새로고침됩니다.' / 2 / 초대 코드 / 세 묶음으로 된 코드 (흐림 처리) / 3 / 복사 · 새로고침 · 크게 보기 / 크게 보기로 교실 TV에 띄워요. / 4 / 링크 복사 / 링크로 들어와 코드를 넣게 안내해요. / TIP / 코드는 수업 시간 안에 바로 쓰고, 지난 코드는 다시 쓰지 마세요.","no":"코드 사용을 누르면 세 묶음으로 된 초대 코드와 링크가 나옵니다. 화면 안내대로 코드는 4시간이 지나면 자동으로 바뀌니, 학생들이 들어오는 그 수업 시간에 바로 쓰시면 됩니다. 크게 보기를 누르면 교실 TV에 띄우기 좋습니다. 화면 속 코드는 흐리게 처리했습니다.","alt":["코드 사용을 누른 화면: 4시간마다 바뀌는 초대 코드(흐림 처리)와 링크 복사"]},{"n":37,"t":"꼭 알아 둘 점","sec":6,"x":"배움터로 접속 / 배움터 계정으로 들어가야 석적초등학교 팀의 교육용 Canva가 열려요. / 공유 범위 / 처음은 '나만'. 학생 정보가 있으면 '링크가 있는 모든 사용자'는 피해요. / AI 결과 검토 / 활동 형태 · 용어 · 미리 채운 답을 확인한 뒤 배정해요. / AI 사용 한도 / 요금제마다 다르다고 안내돼 있어요. 연습은 필요한 만큼만. / 자동 저장 / 저장 버튼이 없어요. 지운 디자인은 프로젝트의 휴지통에서 찾아요. / 학생 초대 / 학교 이메일이 있는 학생만 초대돼요. 초대 코드는 4시간마다 바뀌어요.","no":"마지막으로 꼭 기억하실 점을 여섯 가지로 정리했습니다. AI 사용 한도는 Canva 요금제 페이지에 '사용 한도와 AI 디자인 도구 제공 사항은 요금제마다 다르다'고만 나와 있어서, 정확한 횟수는 적지 않았습니다. 휴지통은 프로젝트와 교실 화면 왼쪽 아래에 있습니다. 나머지는 오늘 직접 해 보면서 확인한 내용입니다.","alt":[]},{"n":38,"t":"수업에 이렇게 써 보세요","sec":6,"x":"수업 PPT 빨리 만들기 / EDU 템플릿을 고르고 글자와 그림만 바꾸기 / 단원 맞춤 그림 / 요소 → 생성으로 우리 단원에 맞는 그래픽 / AI 활동지 → 배정 / 학생 활동 만들기 → 검토 → 학급에 배정 / 학생 작품 받기 / 포스터·카드뉴스를 학생이 만들고 '검토 필요'로 받기 / 만든 디자인은 계속 다시 쓸 수 있어요 / 프로젝트에 자동으로 모이니, 내년 같은 단원이나 다른 반에서 다시 열어 고쳐 쓰면 돼요. 동학년과는 '석적초등학교' 범위로 나눠요.","no":"오늘 해 본 기능만으로도 수업 자료 만들기부터 학생 활동지, 학생 작품 받기까지 할 수 있습니다. 처음에는 다음 주 수업 자료 한 장을 템플릿으로 만들어 보시는 것부터 시작하시기를 권해 드립니다. 동학년 선생님들과는 학교 팀 범위로 공유하시면 서로 만든 자료를 함께 쓸 수 있습니다.","alt":[]},{"n":39,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 디자인 같이 만들기 / 단원에 맞는 템플릿을 함께 골라 드려요. / 학급 만들고 학생 초대 / 처음 초대할 때 옆에서 도와드려요. / AI 활동지 검토 / 학생에게 내기 전에 함께 읽어 봐요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 디자인을 만들거나 학생을 처음 초대하실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,40560],[40560,46940],[87500,60112],[147612,60902],[208514,82552],[291066,81968],[373034,61398],[434432,73602],[508034,63614],[571648,59252],[630900,76902],[707802,85730],[793532,88378],[881910,88612],[970522,62082],[1032604,85728],[1118332,83574],[1201906,81792],[1283698,55852],[1339550,57814],[1397364,80022],[1477386,76580],[1553966,96760],[1650726,89242],[1739968,80720],[1820688,80436],[1901124,67268],[1968392,71912],[2040304,70110],[2110414,84728],[2195142,79232],[2274374,65102],[2339476,54788],[2394264,55972],[2450236,79356],[2529592,72556],[2602148,56606],[2658754,55912],[2714666,38018]],"toffs":[[0,4010],[4010,3846],[7856,4968],[12824,4970],[17794,6560],[24354,6602],[30956,5882],[36838,6484],[43322,5174],[48496,4258],[52754,6110],[58864,6544],[65408,6432],[71840,7266],[79106,5316],[84422,7088],[91510,6894],[98404,6492],[104896,4768],[109664,4616],[114280,5658],[119938,5834],[125772,6548],[132320,6392],[138712,7002],[145714,6602],[152316,6154],[158470,6146],[164616,6258],[170874,6600],[177474,6020],[183494,4968],[188462,4688],[193150,4250],[197400,6530],[203930,5908],[209838,3896],[213734,4564],[218298,3726]],"packSize":2752684,"thumbSize":222024},{"key":"vrew","name":"브루","title":"브루 사용 안내서","group":"make","sub":"경북AI배움터로 접속해 자막 넣고 AI로 영상 만들기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"배움터로 들어가면 비즈니스 요금제가 적용되어 매달 12,000 크레딧이 채워져요. 이용 기간 ~2027. 2. 28.(내 요금제 화면 표시)","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 브루와 경북 이용권 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 브루에 접속하고 요금제와 크레딧을 확인해요"},{"start":7,"num":"2","label":"영상 불러오기","desc":"영상을 불러와 음성 분석으로 자동 자막을 만들어요"},{"start":12,"num":"3","label":"자막 다듬기","desc":"자막을 고치고 무음을 줄이고 클립과 서식을 다듬어요"},{"start":18,"num":"4","label":"AI로 채우기","desc":"AI 목소리, 무료 이미지, 텍스트로 비디오로 영상을 채워요"},{"start":28,"num":"5","label":"저장·내보내기","desc":"클라우드에 저장하고 mp4와 자막으로 내보내요"},{"start":33,"num":"6","label":"크레딧과 활용","desc":"크레딧 사용량, 유의사항, 수업 활용을 정리해요"}],"slides":[{"n":1,"t":"브루","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 자막 넣고 AI로 영상 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 브루(Vrew)를 함께 써 보겠습니다. 브루는 영상 속 말소리를 받아써서 자막을 자동으로 만들어 주는 영상 편집 도구입니다. 오른쪽 화면은 연수를 준비하면서 주제 한 줄로 직접 만들어 본 영상입니다.","alt":["브루 편집 화면: 텍스트로 만든 단풍 영상"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 브루, 요금제와 크레딧 / 04–06쪽 / STEP 2 / 영상 불러오기 / 음성 분석으로 자동 자막 / 07–11쪽 / STEP 3 / 자막 다듬기 / 고치기, 무음 줄이기, 나누기, 서식 / 12–17쪽 / STEP 4 / AI로 채우기 / AI 목소리, 무료 이미지, 텍스트로 비디오 / 18–27쪽 / STEP 5 / 저장·내보내기 / 클라우드 저장, mp4·자막·글 / 28–32쪽 / STEP 6 / 크레딧과 활용 / 크레딧, 유의사항, 수업 아이디어 / 33–35쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 영상 불러오기와 3단계 자막 다듬기만 꼭 해 보세요. 실습용 영상 파일은 미리 나눠 드리겠습니다.","alt":[]},{"n":3,"t":"브루로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 자동 자막 / 영상 속 말을 받아써서 자막을 만들어 줘요 / 문서처럼 편집 / 자막 글자를 고치듯 영상을 자르고 다듬어요 / AI 목소리 / 문장을 쓰면 AI 성우가 읽어 줘요 / 텍스트로 비디오 / 주제만 넣으면 대본·그림· 목소리까지 만들어요 / 경북 교원 혜택 / 배움터로 접속하면 '비즈니스' 요금제 / 매달 12,000 크레딧이 채워지고, 클라우드 저장 공간 60GB를 쓸 수 있어요. / 이용 기간: ~ 2027. 2. 28. (실습 계정의 '내 요금제' 화면 기준)","no":"브루는 말소리를 자막으로 바꿔 주는 기능이 가장 큰 장점입니다. 자막을 고치면 영상도 함께 고쳐지기 때문에 문서를 편집하듯 영상을 다룰 수 있습니다. 배움터를 거쳐 들어가면 경상북도교육청 이용권이 적용되어 비즈니스 요금제로 쓸 수 있습니다. 크레딧과 저장 공간은 실습 계정 화면을 기준으로 정리했습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 브루 열기","sec":1,"x":"1 / 에듀테크 서비스 → 브루 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 웹 브루(vrew.ai)가 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 프로그램을 설치하지 않고 브라우저에서 바로 써요. 오늘 실습도 웹 브루로 진행해요.","no":"배움터 주소는 aischool.gbe.kr입니다. 에듀테크 서비스 목록이 여러 쪽으로 넘어가기 때문에 브루가 보이지 않으면 아래 화살표로 넘겨 보세요. 브루는 설치 버전도 있지만, 배움터에서 누르면 웹 버전이 열립니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록과 브루 설명"]},{"n":5,"t":"처음 들어가면 보이는 화면","sec":1,"x":"위 · 처음 접속할 때 / 1 / 로그인 성공 알림 / 배움터 계정으로 자동 로그인돼요. / 2 / 연령대 설문 / 답하지 않고 X로 닫아도 괜찮아요. / 아래 · 홈 화면 / 1 / 새로 만들기 / 새 영상을 시작해요. / 2 / 프로젝트 열기 / 저장해 둔 작업을 이어서 해요.","no":"처음 접속하면 연령대를 묻는 설문 창이 뜹니다. 실습 때는 답하지 않고 오른쪽 위 X로 닫았습니다. 그다음부터는 홈 화면에서 새로 만들기와 프로젝트 열기 가운데 하나를 고르면 됩니다.","alt":["첫 로그인 알림과 연령대 설문 창","브루 홈 화면의 새로 만들기와 프로젝트 열기"]},{"n":6,"t":"내 요금제와 크레딧 확인","sec":1,"x":"1 / 비즈니스 요금제 / 경북 이용권이 적용된 요금제와 이용 기간이 보여요. / 2 / 잔여 크레딧 / 매달 12,000 크레딧이 다시 채워져요. 다음 충전일도 여기에 나와요. / 3 / 사용 기록 지우개 / 이번 달 크레딧을 다 썼을 때 사용 내역 일부를 지워 크레딧을 되찾는 기능이에요. / TIP / 왼쪽 위 내 이름을 누르면 이 화면이 열려요. 음성 분석, AI 목소리, AI 이미지에 크레딧이 들어가요.","no":"왼쪽 위 이름을 누르면 계정 화면이 열립니다. 실습 계정은 비즈니스 요금제였고 잔여 크레딧이 12,000으로 표시되었습니다. 사용 기록 지우개는 물음표 아이콘에 마우스를 올리면 설명이 나오는데, 이번 기간 크레딧을 다 썼을 때 사용 내역 일부를 지워 크레딧을 되찾는 기능이라고 안내되어 있습니다.","alt":["계정 화면의 비즈니스 요금제와 잔여 크레딧"]},{"n":7,"t":"새로 만들기: 시작 방법 8가지","sec":2,"x":"1 / 비디오·오디오 불러오기 / 찍은 영상에 자막 달기 (오늘 실습) / 2 / 텍스트로 비디오 만들기 / 주제·대본으로 영상 만들기 (오늘 실습) / 3 / 숏폼 비디오 만들기 / 세로형 짧은 영상 / 4 / AI 목소리로 시작하기 / 글을 AI 목소리로 읽기 / 5 / 템플릿으로 시작하기 / 만들어진 틀에 내용 채우기 / 6 / 이미지로 비디오 만들기 / 사진·그림을 영상으로 / 7 / 슬라이드로 비디오 만들기 / 발표 자료를 영상으로 / 8 / 녹화·녹음으로 시작하기 / 바로 녹화하거나 녹음하기","no":"홈 화면에서 새로 만들기를 누르면 여덟 가지 시작 방법이 나옵니다. 오늘은 가장 많이 쓰는 비디오 불러오기와, 요즘 많이 찾으시는 텍스트로 비디오 만들기를 해 보겠습니다.","alt":["새로 만들기 창의 8가지 시작 방법"]},{"n":8,"t":"영상 불러오기: PC 또는 휴대폰","sec":2,"x":"1 / PC에서 불러오기 / 컴퓨터의 영상·음성 파일을 골라요. mp4, mov, mp3, wav 등 / 2 / 모바일에서 불러오기 / 화살표(∨)를 눌러 고르면 QR 코드 창이 열려요. / 3 / QR 코드 찍기 / 휴대폰 카메라로 찍으면 휴대폰 영상을 원본 화질 그대로 PC로 보내요.","no":"비디오·오디오 불러오기 카드의 화살표를 누르면 PC에서 불러올지, 휴대폰에서 불러올지 고를 수 있습니다. 휴대폰으로 찍은 수업 영상은 QR 코드를 찍어 바로 보낼 수 있습니다. 실습 때는 미리 만든 26초짜리 연습 영상(연수실습_가을이야기.mp4)을 PC에서 불러왔습니다. QR 코드는 열 때마다 새로 만들어지는 것이라 화면에서는 흐리게 처리했습니다.","alt":["비디오·오디오 불러오기의 PC에서 불러오기와 모바일에서 불러오기 메뉴","모바일에서 불러오기 QR 코드 창(QR은 흐림 처리)"]},{"n":9,"t":"음성 분석 설정","sec":2,"x":"1 / Basic / Plus / Basic은 1분에 1크레딧, Plus는 1분에 5크레딧이에요. Plus는 정확도가 더 높고 소리도 감지해요. / 2 / 언어 / 영상 속 말의 언어를 골라요. 영어 수업 영상이면 English로 바꿔요. / 3 / AI 자막 교정 / 문맥을 보고 고유명사·약어 등을 고쳐 줘요. 100자에 1크레딧이에요. / 4 / 확인 / 누르면 음성 분석이 시작돼요. / TIP / 실습 영상은 Basic으로도 잘 받아써졌어요. 기계음으로 읽은 영상이었는데도 몇 군데만 틀렸어요.","no":"파일을 고르면 영상 불러오기 창이 열립니다. 음성 분석을 켜 두면 영상 속 말을 받아써서 자막을 만들어 줍니다. 실습 때는 Basic, 한국어, AI 자막 교정 켜기로 진행했습니다.","alt":["영상 불러오기 창의 음성 분석 설정"]},{"n":10,"t":"고급 설정은 필요할 때만","sec":2,"x":"1 / 클립 나누기 / 자막 한 줄을 최대 30자, 의미 단위로 나눠요. (기본값) / 2 / 자동 씬 나누기 / 켜면 장면에 따라 씬을 나눠요. 기본은 꺼져 있어요. / 3 / 원고 불러오기 / 대본(원고)이 있으면 불러와 자막에 쓸 수 있어요. 기본은 '자동 자막 사용'이에요. / TIP / 처음에는 고급 설정을 그대로 두고 시작해도 괜찮아요.","no":"고급 설정을 펼치면 클립 나누기, 자동 씬 나누기, 원고 불러오기가 있습니다. 실습 때는 기본값 그대로 두었습니다. 대본을 미리 써 둔 영상이라면 원고 불러오기를 활용해 볼 수 있습니다.","alt":["영상 불러오기 창의 고급 설정"]},{"n":11,"t":"받아쓰기와 자막 교정이 끝나면","sec":2,"x":"1 / 문장 추출 / 영상 속 말을 글자로 받아써요. / 2 / 진행률 / 26초짜리 실습 영상은 1분 안에 끝났어요. / 3 / 자막 교정 완료 / AI가 고친 자막 수와 예시를 보여 줘요. / 4 / 미리보기 / 완료를 누르면 자막이 들어간 영상이 보여요.","no":"확인을 누르면 오른쪽 아래에 진행 창이 뜹니다. 문장 추출, 자막 교정 순서로 진행되고 끝나면 자막 교정 완료 창이 나옵니다. 같은 영상을 두 번 불러와 보았는데, 한 번은 자막 2개, 한 번은 1개가 교정되었습니다. 결과가 매번 조금씩 다를 수 있다는 것을 알 수 있었습니다.","alt":["문장 추출 진행 창","자막 교정 완료 창과 자막이 들어간 미리보기"]},{"n":12,"t":"편집 화면 한눈에 보기","sec":3,"x":"1 / 메뉴 탭 / 파일·홈·편집·자막·서식·삽입 등 / 2 / 미리보기 / 자막이 들어간 영상을 바로 확인 / 3 / 단어 칸 / 인식된 말이 단어별로. [?]는 말이 없는 구간 / 4 / 자막 줄 / 실제로 화면에 나오는 자막 / 5 / 썸네일과 시간 / 클립이 시작하는 시각 + 길이 / 6 / 내보내기 / 완성한 영상을 파일로","no":"편집 화면은 왼쪽 미리보기와 가운데 클립 목록으로 나뉩니다. 말 한 덩어리가 클립 하나가 되고, 클립마다 위쪽 단어 칸과 아래쪽 자막 줄이 있습니다. 단어 칸의 [?]는 말소리가 없는 구간입니다.","alt":["자막이 만들어진 브루 편집 화면"]},{"n":13,"t":"틀린 자막 고치기","sec":3,"x":"고친 뒤 / 1 / 자막 줄에서 고치기 / 아래쪽 자막 줄을 클릭해 틀린 글자를 지우고 바르게 써요. / 2 / 미리보기 확인 / '피에놀입니다' → '계절입니다'. 고친 자막이 영상에 바로 반영돼요. / 꼭 확인하세요 / AI 교정을 켜도 틀린 곳이 남아요. 실습 때 '나뭇잎이 빨갛고'가 '나무숲이 밝았고'로 나온 줄도 직접 고쳤어요.","no":"자막은 아래쪽 자막 줄에서 문서처럼 고치면 됩니다. 실습 영상에서는 계절입니다가 피에놀입니다로 받아써졌습니다. 고친 줄은 파란 글씨로 바뀌어 구분이 됩니다. AI 자막 교정을 켰는데도 틀린 줄이 남아 있었기 때문에 처음부터 끝까지 한 번은 꼭 읽어 보시기를 권해 드립니다.","alt":["자막 줄에서 틀린 글자를 선택한 화면","고친 자막 줄"]},{"n":14,"t":"무음 구간 줄이기","sec":3,"x":"1 / 찾을 길이 / 0.5초 이상 말이 없는 곳을 찾아요. / 2 / 줄일 길이 / 찾은 구간을 0.2초로 줄여요. / 3 / [?] 구간도 함께 / 음성 미인식 구간까지 같이 줄여요. / 4 / 적용 / '7개의 무음 구간 줄이기'를 눌러요. / 5 / 노란 표시 / 줄어들 구간이 미리 노랗게 보여요. / TIP / 26초 영상이 22초로 줄었어요. 옆의 되돌리기로 원래대로 돌려요.","no":"홈 탭의 무음 구간 줄이기를 누르면 오른쪽에 창이 열립니다. 말과 말 사이 쉬는 시간을 한 번에 줄여 주기 때문에 수업 영상을 짧게 다듬을 때 편합니다. 실습에서는 0.5초 이상 무음을 0.2초로 줄였고, 영상 길이가 26초에서 22초가 되었습니다.","alt":["무음 구간 줄이기 창과 노랗게 표시된 무음 구간"]},{"n":15,"t":"클립 나누기","sec":3,"x":"위 · 나누기 전 / 1 / 나눌 곳 클릭 / 위쪽 단어 칸에서 나눌 단어 앞을 클릭하고 Enter를 눌러요. / 아래 · 나눈 뒤 / 2 / 앞 클립 / '다음 시간에는 가을, 열매를 찾아보겠습니다' / 3 / 새 클립 / '감사합니다'가 따로 떨어져요. / TIP / 반대로 붙이고 싶으면 두 클립을 고르고 홈 탭 '클립 합치기'를 눌러요.","no":"한 줄 자막이 너무 길면 클립을 나눕니다. 단어 칸에서 나눌 단어 앞을 클릭하고 Enter를 누르면 됩니다. 실습에서는 다음 시간에는 가을, 열매를 찾아보겠습니다 감사합니다를 두 클립으로 나눴습니다.","alt":["나눌 단어 앞에 커서를 둔 화면","Enter로 클립이 둘로 나뉜 화면"]},{"n":16,"t":"자막 모양 바꾸기 (서식 탭)","sec":3,"x":"1 / 기본 서식 / 바꾸면 모든 자막에 함께 적용돼요. / 2 / 글자 크기 / 100 → 125로 키웠어요. / 3 / 배경 / 자막 뒤에 색 상자를 깔아요. / 4 / 색과 불투명도 / 진한 청록, 불투명도 80%로 했어요. / 5 / 위치 / 좌우·상하 정렬과 자리를 정해요. / 6 / 미리보기 / 바뀐 모양을 바로 확인해요.","no":"서식 탭에서 글꼴, 크기, 색, 테두리, 배경, 그림자, 위치를 바꿀 수 있습니다. 실습에서는 크기를 125로 키우고 진한 청록 배경을 80퍼센트 불투명도로 깔았습니다. 기본 서식을 바꾸면 다른 클립 자막도 함께 바뀌는 것을 확인했습니다.","alt":["서식 탭에서 글자 크기와 배경 색을 바꾼 화면"]},{"n":17,"t":"메뉴 탭 한눈에 보기","sec":3,"x":"탭 / 주요 기능 / 파일 / 새로 만들기, 프로젝트 열기·저장, 화면 비율, 영상으로 내보내기, 다른 형식으로 내보내기 / 홈 / 자주 쓰는 기능 모음: 되돌리기, 클립 합치기·나누기, 무음 구간 줄이기, 글꼴·크기 / 편집 / 클립 선택, 자동 클립·씬 나누기, 마커, 찾아서 편집하기, 원본 보기 / 자막 / 원고·자막 파일 불러오기, 전체 자막 복사하기, AI 자막 번역, 맞춤법 검사, AI 자막 교정 / 서식 / 글꼴, 크기, 색, 테두리, 배경, 형광펜, 그림자, 간격, 위치 / 삽입 / 텍스트, 내 이미지·비디오, 무료 이미지·비디오, AI 이미지, 캐릭터, 배경 음악, 효과음, 녹화·녹음 / AI 목소리 / AI 목소리 클립 삽입, AI 목소리 효과음, AI 자막 더빙, 발음 사전 / 템플릿 · 효과 / 템플릿, 프레임 / 필터, 확대·회전, 잡음 제거, 화면 전환, 볼륨, 배속","no":"위쪽 메뉴 탭마다 들어 있는 기능을 정리했습니다. 실습 화면에서 탭을 하나씩 눌러 확인한 내용입니다. 처음에는 홈 탭만으로도 대부분의 작업을 할 수 있습니다.","alt":[]},{"n":18,"t":"AI 목소리 클립 넣기","sec":4,"x":"1 / AI 목소리 탭 / 위쪽 메뉴에서 골라요. / 2 / AI 목소리 클립 삽입 / 고른 클립 뒤에 새 클립이 생겨요. / 3 / 문장 입력 / AI가 읽을 문장을 써요. Shift+Enter로 줄을 바꿔요. / 4 / 목소리 설정 / 누르면 목소리 고르는 창이 열려요. / 5 / 확인 / AI 목소리와 자막이 함께 만들어져요.","no":"AI 목소리 탭의 AI 목소리 클립 삽입을 누르면 새 클립이 생기고 문장 입력 칸이 나옵니다. 실습에서는 오늘 배운 가을의 모습을 그림으로 그려 보세요라고 입력했습니다. 한글 입력은 다른 칸과 똑같이 하시면 됩니다.","alt":["AI 목소리 탭에서 새 클립에 문장을 입력하는 화면"]},{"n":19,"t":"목소리 고르기","sec":4,"x":"1 / 크레딧 필터 / '무료'를 누르면 FREE 목소리만 모아 보여요. / 2 / #다정한 #또박또박 같은 태그를 보고 골라요. / 3 / 음량·속도·높이 / 기본값에서 바꿀 수 있어요. / 4 / 미리 듣기 / 헤드셋 아이콘으로 들어 봐요. / 5 / 확인 / 고른 목소리로 바로 만들어져요. / TIP / 추천 목록에만 130개 목소리가 있고, 그중 한국어가 80개예요.","no":"목소리 설정 창에는 추천 목록만 130개 목소리가 있고 한국어 목소리가 80개였습니다. 실습에서는 무료 필터를 켜고 손서현 목소리를 골랐습니다. 아이들에게 들려줄 영상이라면 미리 듣기로 말투를 꼭 들어 보시기를 권해 드립니다.","alt":["AI 목소리 설정 창"]},{"n":20,"t":"AI 목소리 클립 완성","sec":4,"x":"1 / 새 클립 / 목소리 이름(손서현), 단어, 자막이 자동으로 생겨요. / 2 / 미리보기 / 배경을 넣지 않아 아직 검은 화면이에요. / TIP / 검은 배경에는 다음 장처럼 이미지를 넣어 채워요. 목소리를 바꾸려면 이름 옆 설정 버튼을 다시 눌러요.","no":"확인을 누르면 몇 초 만에 AI 목소리 클립이 만들어집니다. 자막도 문장에 맞춰 자동으로 생깁니다. 새로 만든 클립에는 영상이 없어서 미리보기가 검게 보입니다.","alt":["AI 목소리로 만들어진 7번 클립과 미리보기"]},{"n":21,"t":"무료 이미지로 배경 채우기","sec":4,"x":"결과 · '잘라서 채우기'로 화면 전체를 채웠어요. / 1 / 삽입 탭 / 위쪽 메뉴에서 골라요. / 2 / 무료 이미지·비디오 / 오른쪽에 검색 창이 열려요. / 3 / 추천 검색어 / 자막 속 낱말(가을, 오늘…)이 검색어로 떠요. / 4 / 이미지 클릭 / 고른 클립에 바로 들어가요. / 5 / 채우기 / '잘라서 채우기'로 화면을 꽉 채워요.","no":"삽입 탭의 무료 이미지·비디오를 누르면 오른쪽에 검색 창이 열립니다. 자막에 있는 낱말이 추천 검색어로 떠서 가을을 눌러 찾았습니다. 이미지를 누르면 선택한 클립에 바로 들어가고, 채우기 메뉴에서 잘라서 채우기를 고르면 화면 전체가 채워집니다.","alt":["삽입 탭의 무료 이미지·비디오 창에서 가을 이미지를 넣는 화면","잘라서 채우기로 화면을 채운 결과"]},{"n":22,"t":"텍스트로 비디오 ① 스타일 고르기","sec":4,"x":"1 / 3단계로 진행 / 스타일 고르기 → 대본 작성 → 비디오 꾸미기 / 2 / 바로 시작하기 / 스타일 없이 시작해요. / 3 / 추천 비디오 스타일 / 정보 전달, 다큐멘터리, 명언 등. 실습은 정보 전달 스타일 / 4 / 다음 / 대본 작성으로 넘어가요.","no":"새로 만들기에서 텍스트로 비디오 만들기를 고르면 세 단계 창이 열립니다. 먼저 영상 스타일을 고릅니다. 수업용으로는 정보 전달 스타일이 무난하다고 보고 이 스타일로 실습했습니다.","alt":["텍스트로 비디오 만들기 첫 단계 스타일 고르기"]},{"n":23,"t":"텍스트로 비디오 ② 대본 작성","sec":4,"x":"1 / 주제 / '단풍잎은 왜 빨갛고 노랗게 물들까?' / 2 / 대본 프롬프트 / 대상과 말투를 적어요. '초등 4학년에게 설명하듯 친절한 선생님 말투로' / 3 / 글자 수 설정 / 켜고 400자로 정했어요. / 4 / AI 글쓰기 / 누르면 오른쪽에 대본이 써져요. / TIP / 대본을 직접 써 넣어도 돼요. 이미 쓴 수업 대본이 있다면 오른쪽 칸에 붙여 넣으면 돼요.","no":"대본 작성 단계에서는 주제와 대본 프롬프트를 적고 AI 글쓰기를 누릅니다. 대상 학년과 말투를 적어 주면 그에 맞는 대본이 나옵니다. 직접 쓴 대본을 붙여 넣어 영상만 만들 수도 있습니다.","alt":["대본 작성 단계에서 주제와 프롬프트를 입력한 화면"]},{"n":24,"t":"AI가 쓴 대본은 꼭 읽어 보기","sec":4,"x":"1 / 대본 / 오른쪽 칸에서 직접 고칠 수 있어요. / 2 / 글자 수 / 400자로 정했더니 342자가 나왔어요. / 3 / 다음 / 비디오 꾸미기로 넘어가요. / 꼭 확인하세요 / 대본에 '엽록소라는 초록색 요술 물감을 감춰버려요' 같은 비유가 들어갔어요. 실제로는 가을에 엽록소가 분해되면서 노란 색소가 드러나는 것이라, 과학 개념은 교과서와 맞는지 확인하고 고쳐 써 주세요.","no":"AI가 쓴 대본은 아이들 눈높이에 맞게 잘 나왔지만 비유가 많았습니다. 엽록소가 물감을 감춘다는 표현은 실제 과정과 다르기 때문에 수업에 쓰신다면 고쳐 주시는 것이 좋겠다고 생각합니다. 퀴즈앤 AI 문제와 마찬가지로 AI가 만든 내용은 한 번씩 검토해 주세요.","alt":["AI 글쓰기로 만들어진 대본"]},{"n":25,"t":"텍스트로 비디오 ③ 비디오 꾸미기","sec":4,"x":"1 / 화면 비율 / 16:9(가로), 9:16(세로), 1:1 등 / 2 / 자막·AI 목소리·배경음악 / 켜고 끄거나 종류를 바꿔요. / 3 / AI 이미지 / 생성 모델과 크레딧이 보여요. 실습 모델은 이미지 1장에 5크레딧 / 4 / 예시 화면 / 고른 설정이 어떻게 보일지 미리 봐요.","no":"마지막 단계에서는 화면 비율, 자막, AI 목소리, 배경음악, AI 이미지를 정합니다. 기본으로 자막은 하단, AI 목소리는 현지, 배경음악은 유쾌한으로 되어 있었고 그대로 두었습니다.","alt":["비디오 꾸미기 단계 설정 화면"]},{"n":26,"t":"그림 분위기 정하고 완료","sec":4,"x":"1 / 이미지 프롬프트 / '밝고 따뜻한 수채화 그림책 느낌, 초등학생 눈높이의 단풍 숲' / 2 / 고화질 / 켜면 이미지 1장에 5크레딧이 더 들어요. / 3 / 무료 비디오 / 일관성 있는 결과를 위해 꺼져 있어요. / 4 / 완료 / '비디오 생성을 시작할까요?' → 확인","no":"이미지 프롬프트에는 그림의 분위기를 적습니다. 무료 비디오는 결과가 일관되도록 꺼 두었다는 안내가 나왔습니다. 완료를 누르고 확인하면 영상 만들기가 시작됩니다.","alt":["이미지 프롬프트를 입력한 비디오 꾸미기 화면"]},{"n":27,"t":"주제 한 줄로 만든 48초 영상","sec":4,"x":"1 / 미리보기 / 그림, 자막, 목소리가 들어간 영상 / 2 / 배경음악 / '요리조리 도망'이 깔렸어요. / 3 / AI 목소리 / '현지' 목소리로 읽어요. / 4 / 클립마다 그림 / AI 이미지가 클립별로 들어가요. / 꼭 확인하세요 / 실습 때 2분 남짓 걸렸어요. 만드는 동안 창을 닫으면 영상이 만들어지지 않아요.","no":"완료를 누르고 2분 남짓 기다리니 48초짜리 영상이 만들어졌습니다. 수채화 그림책 느낌을 요청했는데 귀여운 단풍잎 캐릭터 그림이 나와서, 그림이 프롬프트와 다르게 나올 수 있다는 것도 알 수 있었습니다. 마음에 들지 않는 그림은 클립별로 바꿀 수 있습니다.","alt":["텍스트로 비디오로 만들어진 영상 편집 화면"]},{"n":28,"t":"저장은 클라우드에","sec":5,"x":"1 / 프로젝트 저장하기 / 지금 작업을 저장해요. / 2 / 다른 이름으로 저장 / '브라우저에 저장' 또는 '클라우드에 저장'을 골라요. / 브라우저 / 지금 쓰는 컴퓨터의 이 브라우저에만 남아요. / 클라우드 / 다른 컴퓨터, 설치 버전에서도 이어서 해요. / TIP / 학교 컴퓨터는 브라우저 기록이 지워지는 경우가 있어서 클라우드에 저장해 두면 안심이에요.","no":"파일 탭의 다른 이름으로 저장을 누르면 브라우저에 저장과 클라우드에 저장이 나옵니다. 브라우저에 저장하면 그 컴퓨터의 그 브라우저에서만 열 수 있습니다. 클라우드에 저장하면 다른 컴퓨터나 설치 버전에서도 이어서 작업할 수 있습니다.","alt":["파일 탭의 다른 이름으로 저장 메뉴"]},{"n":29,"t":"클라우드에 프로젝트 저장하기","sec":5,"x":"1 / 프로젝트 이름 / 찾기 쉽게 이름을 바꿔요. 예) [연수 실습] 가을 이야기 / 2 / 저장 공간 / 60GB 가운데 얼마나 썼는지 보여요. / 3 / 클라우드에 저장 / 누르면 올라가고 '완료되었습니다'가 떠요. / TIP / 저장하면 탭 제목에 '클라우드에 저장됨'이 보여요. 실습 때는 그 뒤에 고친 내용도 잠시 뒤 저절로 저장됐어요.","no":"클라우드에 저장 창에서 프로젝트 이름을 정하고 저장합니다. 이름을 정하지 않으면 영상이나 파일 이름으로 저장되기 때문에 나중에 찾기 어렵습니다. 실습 계정은 저장 공간 60GB 가운데 1MB 정도만 쓴 상태였습니다.","alt":["클라우드에 프로젝트 저장하기 창"]},{"n":30,"t":"저장한 프로젝트 이어서 하기","sec":5,"x":"1 / 최근 프로젝트 / 최근에 연 작업이 모여 있어요. / 2 / 내 브라우저 프로젝트 / 이 브라우저에 저장한 것 / 3 / 클라우드 프로젝트 / 클라우드에 저장한 것 / 4 / 프로젝트 카드 / 눌러서 열어요. 카드에 저장 위치와 크기가 나와요. / TIP / 홈 탭 → 프로젝트 열기로 들어가요.","no":"홈 탭의 프로젝트 열기를 누르면 저장한 프로젝트가 나옵니다. 카드 아래에 클라우드에 저장됨인지 표시되어 있어서 어디에 저장했는지 확인할 수 있습니다.","alt":["프로젝트 열기 창"]},{"n":31,"t":"내보내기: 영상, 자막, 글로","sec":5,"x":"1 / 내보내기 / 오른쪽 위 파란 버튼 / 2 / 영상 파일(mp4) / 완성 영상을 파일로 / 3 / 자막 파일(srt) / 자막만 따로 파일로 / 4 / 텍스트(txt) / 받아쓴 글만 따로 / 5 / 오디오 파일(mp3, wav) / 소리만 따로 / 6 / 회색 메뉴 / 투명 배경 자막 영상(mov), Premier Pro, Final Cut Pro는 설치 버전에서만 돼요.","no":"오른쪽 위 내보내기를 누르면 영상 파일과 다른 형식이 나옵니다. 텍스트로 내보내면 받아쓴 내용을 글로 받을 수 있어서 발표 원고나 수업 기록으로 쓰기 좋습니다. 회색 메뉴에 마우스를 올리면 설치 버전에만 지원하는 기능이라고 나옵니다.","alt":["내보내기 메뉴"]},{"n":32,"t":"영상 파일(mp4)로 내보내기","sec":5,"x":"1 / 대상 클립 / 모든 씬·모든 클립 / 현재 씬 / 선택한 클립 / 2 / 해상도 / 실습 영상은 원본(1280 x 720) / 3 / 내보내기 / 누르면 mp4 파일을 만들어 내 컴퓨터로 내려받아요. / TIP / 고급 설정에서 프레임(30fps)과 하드웨어 가속을 바꿀 수 있어요. 처음에는 그대로 두세요.","no":"영상 파일을 고르면 동영상 내보내기 창이 열립니다. 보통은 모든 씬, 모든 클립과 원본 해상도 그대로 내보내면 됩니다. 실습 때는 내보내기 창 설정까지 확인했습니다.","alt":["동영상 내보내기 창"]},{"n":33,"t":"크레딧은 이렇게 쓰여요","sec":6,"x":"1 / 잔여 크레딧 / 12,000 → 11,953 / 2 / 사용 내역 / 날짜와 기능별로 쓴 크레딧이 나와요. / 오늘 실습에서 쓴 기능 / 크레딧 / AI 이미지 (그림 8장 × 5) / 40 / AI 목소리 / 4 / AI 자막 교정 / 2 / 음성 분석 / 1 / 합계 / 47 / TIP / 그림을 많이 만드는 '텍스트로 비디오'가 크레딧을 가장 많이 써요. 그래도 한 달 12,000 크레딧이면 넉넉해요.","no":"연수 준비 실습을 모두 마친 뒤 크레딧 사용 내역을 확인했습니다. 음성 분석, 자막 교정, AI 목소리, 텍스트로 비디오까지 해 보고 47크레딧을 썼습니다. 그림 한 장에 5크레딧이 들어가는 AI 이미지가 대부분을 차지했습니다.","alt":["잔여 크레딧과 크레딧 사용 내역"]},{"n":34,"t":"꼭 알아 둘 점","sec":6,"x":"이용 기간과 크레딧 / 2027. 2. 28.까지 매달 12,000 크레딧 충전 / 자막은 꼭 다시 읽기 / AI 자막 교정을 켜도 틀린 곳이 남아요. / AI 결과물 검토 / 대본의 사실, 그림이 요청과 맞는지 확인해요. / 클라우드에 저장 / 브라우저 저장은 그 컴퓨터에만 남아요. / 웹 버전의 범위 / mov·Premier Pro·Final Cut Pro 내보내기는 설치 버전에서만 / 학생 얼굴과 목소리 / 학생이 나오는 영상은 공개 범위와 동의를 먼저 살펴요.","no":"이용 기간과 크레딧은 실습 계정의 내 요금제 화면을 기준으로 했습니다. 자막과 AI 대본은 실습 때 실제로 틀린 부분이 있었기 때문에 꼭 다시 읽어 보셔야 합니다. 학생이 나오는 영상을 만들 때는 학교의 개인정보 지침에 따라 공개 범위를 먼저 정해 주시면 좋겠습니다.","alt":[]},{"n":35,"t":"수업에 이렇게 써 보세요","sec":6,"x":"안내 영상에 자막 / 과제·실험 안내 영상에 자막을 달아 누구나 따라오게 / 학생 발표 영상 / 발표를 찍어 자막을 달고 받아쓴 글로 되돌아보기 / 단원 도입 영상 / 텍스트로 비디오로 궁금증을 여는 1분 영상 / 영어 수업 / 언어를 English로 받아쓰고 AI 자막 번역 메뉴 활용 / 한 번 만든 프로젝트는 클라우드에 남아요 / 다른 반 수업 전에 자막만 손보거나 AI 목소리 클립을 더해 다시 쓸 수 있어요. 받아쓴 글은 텍스트(txt)로 내보내 수업 기록으로 모아 두세요.","no":"오늘 해 본 기능만으로도 안내 영상 자막, 학생 발표 영상, 단원 도입 영상까지 만들 수 있습니다. 처음에는 휴대폰으로 찍은 1분짜리 안내 영상에 자막을 달아 보는 것부터 시작해 보시기를 권해 드립니다.","alt":[]},{"n":36,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 자막 영상 함께 / 찍어 둔 영상에 자막 다는 것부터 같이 해요. / 텍스트로 비디오 / 단원에 맞는 주제로 함께 만들어 봐요. / 저장과 내보내기 / 클라우드 저장과 mp4 내보내기를 함께 확인해요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 자막 영상을 만드시거나 텍스트로 비디오를 처음 해 보실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,49196],[49196,48220],[97416,54672],[152088,59712],[211800,50122],[261922,60144],[322066,81932],[403998,69882],[473880,71438],[545318,61556],[606874,61210],[668084,69002],[737086,57938],[795024,75284],[870308,66598],[936906,65438],[1002344,69558],[1071902,59594],[1131496,76824],[1208320,52386],[1260706,109920],[1370626,67310],[1437936,64512],[1502448,89792],[1592240,67434],[1659674,66750],[1726424,92714],[1819138,85892],[1905030,62396],[1967426,70606],[2038032,62636],[2100668,53878],[2154546,57392],[2211938,52642],[2264580,58420],[2323000,37902]],"toffs":[[0,3460],[3460,4020],[7480,4640],[12120,4642],[16762,4102],[20864,4942],[25806,7050],[32856,5554],[38410,5402],[43812,4788],[48600,4848],[53448,5184],[58632,4140],[62772,5320],[68092,4838],[72930,5472],[78402,5178],[83580,4484],[88064,6190],[94254,3798],[98052,7168],[105220,5368],[110588,5110],[115698,5760],[121458,5568],[127026,5200],[132226,5774],[138000,5946],[143946,5000],[148946,5750],[154696,5376],[160072,4902],[164974,4830],[169804,4072],[173876,4606],[178482,3784]],"packSize":2360902,"thumbSize":182266},{"key":"bookcreator","name":"북크리에이터","title":"북크리에이터 사용 안내서","group":"make","sub":"경북AI배움터로 접속해 우리 반 디지털 책 만들기","fee":"무료 범위 · 공모 선정자 유료","feeKind":"part","feeNote":"배움터 공모로 선정된 선생님께는 유료 계정이 나가요(배움터 공지 2026. 4. 20.). 연수는 무료 요금제(라이브러리 1개, 책 40권) 기준이에요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 북크리에이터와 경북 계정 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 북크리에이터에 접속하고 첫 화면과 계정을 살펴봐요"},{"start":7,"num":"2","label":"라이브러리 준비","desc":"라이브러리를 설정하고 학생을 초대해요"},{"start":11,"num":"3","label":"책 만들기","desc":"새 책을 만들고 글, 사진, 그림, 만화를 넣어요"},{"start":25,"num":"4","label":"AI와 읽어 주기","desc":"AI 이미지 설명과 읽어 주기를 써 봐요"},{"start":28,"num":"5","label":"읽기와 공유","desc":"읽기 화면, 할당, 출판, PDF로 책을 나눠요"},{"start":33,"num":"6","label":"작품 관리와 활용","desc":"클래스 뷰, 댓글, 합치기로 학생 작품을 관리하고 유의사항과 활용을 정리해요"}],"slides":[{"n":1,"t":"북크리에이터","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 우리 반 디지털 책 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 북크리에이터를 함께 써 보겠습니다. 북크리에이터는 글, 사진, 그림, 녹음을 넣어 디지털 책을 만드는 도구입니다. 오른쪽 화면은 연수를 준비하면서 직접 만든 실습 책을 읽기 화면에서 펼쳐 본 모습입니다.","alt":["실습으로 만든 그림책을 읽기 화면에서 펼친 모습"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 북크리에이터, 첫 화면 / 04–06쪽 / STEP 2 / 라이브러리 준비 / 설정, 학생 초대, 학생 로그인 / 07–10쪽 / STEP 3 / 책 만들기 / 글 · 사진 · 그림 · 만화 / 11–24쪽 / STEP 4 / AI와 읽어 주기 / AI 이미지 설명, 읽어 주기 / 25–27쪽 / STEP 5 / 읽기와 공유 / 할당, 출판, PDF / 28–32쪽 / STEP 6 / 작품 관리와 활용 / 클래스 뷰, 댓글, 합치기 / 33–39쪽","no":"여섯 단계로 진행하겠습니다. 시간이 부족하면 3단계 책 만들기에서 표지 한 장만 같이 만들어 보시고, 6단계 학생 작품 관리는 화면으로만 보셔도 괜찮습니다.","alt":[]},{"n":3,"t":"북크리에이터로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 디지털 책 만들기 / 글 · 사진 · 그림 · 녹음을 한 쪽에 담아요 / 우리 반 라이브러리 / 초대 코드로 학생을 한 책장에 모아요 / 읽어 주기와 댓글 / 소리로 듣고, 댓글로 서로 피드백해요 / 출판과 내보내기 / 온라인 출판 링크, PDF로 나눠요 / 경북 교원 계정 / 배움터로 들어가면 바로 로그인 / 따로 회원가입하지 않아도 배움터 계정으로 북크리에이터를 쓸 수 있어요. / 연수 준비 계정은 무료 요금제였어요. 라이브러리 1개 · 책 40권까지 (2026. 10. 2. 계정 메뉴 기준)","no":"북크리에이터는 책을 만들고, 반 학생들을 한 라이브러리에 모으고, 함께 읽고 댓글을 남기고, 출판하거나 PDF로 내보내는 흐름으로 씁니다. 배움터를 거쳐 들어가면 따로 가입하지 않아도 됩니다. 다만 연수를 준비하면서 확인해 보니 이 계정은 무료 요금제로 표시되어 있었고, 라이브러리는 1개, 책은 40권까지 만들 수 있었습니다. 퀴즈앤처럼 유료 이용권이 붙어 있지는 않은 것으로 보입니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 북크리에이터 열기","sec":1,"x":"1 / 에듀테크 서비스 → 북크리에이터 / 배움터 메인 화면 아래 목록에 있어요. 목록이 여러 쪽이라 < > 로 넘겨 찾아요. / 2 / 마우스를 올리면 설명 표시 / 누르면 새 탭에서 북크리에이터가 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 회원가입이나 비밀번호 입력 없이 배움터 로그인 한 번이면 충분해요.","no":"배움터 주소는 aischool.gbe.kr입니다. 에듀테크 서비스 목록이 네 쪽으로 나뉘어 있어서 북크리에이터가 바로 안 보이면 화살표로 넘겨 보시면 됩니다. 마우스를 올리면 오른쪽에 짧은 설명이 뜨고, 누르면 새 탭이 열리면서 자동으로 로그인됩니다.","alt":["경북AI배움터 에듀테크 서비스 목록과 북크리에이터 설명"]},{"n":5,"t":"첫 화면: 라이브러리(책장)","sec":1,"x":"1 / 라이브러리 이름 / ≡ 를 누르면 내 라이브러리 목록이 열려요. / 2 / 보기 바꾸기 / 책장 · 저자(학생) · 클래스 뷰를 오가요. / 3 / 학생 추가 / 초대 코드를 받아 학생을 불러요(8쪽). / 4 / 새 책 / 빈 책 · 테마 · 만화로 새 책을 만들어요. / 5 / 라이브러리 설정 / 학생에게 허용할 기능을 정해요(7쪽). / 6 / 책장 / 표지를 누르면 바로 편집 화면이 열려요.","no":"처음 들어오면 라이브러리, 즉 책장 화면이 열립니다. 위쪽 가운데 아이콘 세 개로 책장, 저자 목록, 클래스 뷰를 오갈 수 있습니다. 책장에 꽂힌 표지를 누르면 바로 편집 화면으로 들어갑니다. 오른쪽 위 노란 새 책 버튼이 가장 많이 누르게 될 버튼입니다.","alt":["북크리에이터 라이브러리 첫 화면"]},{"n":6,"t":"계정 메뉴와 무료 요금제 한도","sec":1,"x":"1 / 라이브러리 1개 / ‘1개 중 1개 사용 중’이라고 나와요. 새로 만들려 하면 아래 안내창이 떠요. / 2 / 책 40권까지 / 라이브러리 카드에도 ‘책 40권 중 ○권’으로 보여요. / 3 / 요금제 업그레이드 / 유료 안내 화면이에요. 연수에서는 누르지 않아도 돼요.","no":"오른쪽 위 사람 모양 아이콘을 누르면 계정 메뉴가 열립니다. 화면 속 이메일은 흐리게 처리했습니다. 40 책이라는 표시와 왼쪽의 1개 중 1개 라이브러리 사용 중이라는 문구를 보면 무료 요금제라는 것을 알 수 있습니다. 새 라이브러리를 만들려고 하면 아래 안내창처럼 무료 요금제는 라이브러리 1개만 쓸 수 있다고 나옵니다. 그래서 한 반에 라이브러리 하나를 쓴다고 생각하시면 됩니다.","alt":["내 라이브러리 화면과 계정 메뉴","무료 요금제는 1개의 활성 라이브러리만 허용한다는 안내창"]},{"n":7,"t":"라이브러리 설정: 학생에게 허용할 기능","sec":2,"x":"1 / 이미지 검색 / 책 안에서 사진 검색을 쓸지 정해요. / 2 / 서로의 책 읽기 / 켜 두면 같은 라이브러리 친구 책을 읽을 수 있어요. / 3 / 책 출판 / 기본은 꺼져 있어요. 꺼 두면 학생은 온라인 출판을 못 해요. / 4 / 댓글 추가 / 학생도 책에 댓글을 남길 수 있게 해요. / 5 / 접근성 / 번역 · 받아쓰기(음성 → 글) · 읽어 주기(글 → 음성) · AI 이미지 설명 / TIP / 무료 요금제는 라이브러리가 하나뿐이라, 이 화면 맨 위에서 이름을 ‘6학년 ○반’처럼 바꿔 두면 편해요.","no":"책장 화면 오른쪽 위 톱니바퀴나 라이브러리 카드의 점 세 개 메뉴에서 설정으로 들어옵니다. 학생에게 허용할 기능이 위에, 접근성 기능이 아래에 있습니다. 실습 계정에서는 학생 책 출판만 꺼져 있었고 나머지는 대부분 켜져 있었습니다. 화면에는 자신의 책 편집하기, 여러 책 만들기, 맞춤법 검사, 콘텐츠 삽입 항목도 함께 있습니다.","alt":["라이브러리 설정 화면의 학생 허용 항목과 접근성 항목"]},{"n":8,"t":"학생 초대: 초대 코드와 링크","sec":2,"x":"1 / 초대 코드 / 학생은 app.bookcreator.com에서 이 코드를 넣고 들어와요. / 2 / 초대 링크 복사하기 / 클래스룸이나 학급 게시판에 링크로 나눠도 돼요. / 3 / 초대 코드 만료 / 코드를 더 이상 못 쓰게 막아요. / TIP / 화면에도 ‘코드를 안전하게 보관하고 소셜 미디어에 공유하지 마세요’라고 나와요. 자료 속 코드는 흐리게 처리했어요.","no":"책장 화면 위쪽의 학생들을 이 라이브러리에 추가하세요 버튼이나 저자 목록의 학생 추가하기를 누르면 이 창이 열립니다. 코드를 칠판에 써 주시거나 링크를 복사해 나눠 주시면 됩니다. 코드가 반 밖으로 퍼졌다면 아래 초대 코드 만료를 눌러 막아 두시는 것이 좋습니다.","alt":["저자 추가 창의 초대 코드와 초대 링크 복사 버튼"]},{"n":9,"t":"학생 로그인 방법","sec":2,"x":"학생 로그인 화면 / ① Google ② Microsoft ③ QR 코드로 로그인해요. 위의 ‘교사로 전환’은 선생님용이에요. / ④ 학생 로그인 만들기 / 계정 메뉴 → 학생 로그인. 이름을 한 줄에 한 명씩 넣으면 QR 코드·개인 링크로 들어오는 계정이 생겨요. / TIP / 학생이 어떤 방법으로 들어올지는 학교 계정 사정에 맞게 정해요. 구글·MS 계정이 없으면 ‘학생 로그인 만들기’가 간편해요.","no":"학생 로그인 화면에는 구글, 마이크로소프트, QR 코드 로그인이 있습니다. 학생에게 구글이나 오피스 계정이 없을 때는 선생님 계정 메뉴의 학생 로그인에서 이름만 넣어 학생 계정을 만들 수 있다고 안내되어 있습니다. 연수에서는 실제 학생 계정을 만들지는 않았고 창까지만 열어 보았습니다.","alt":["학생 로그인 화면: 구글, 마이크로소프트, QR 코드 로그인","학생 로그인 만들기 창: 학생 이름을 한 줄에 한 명씩 입력"]},{"n":10,"t":"저자 목록과 데모 학생","sec":2,"x":"1 / 학생 추가하기 / 초대 코드 창이 열려요. / 2 / 공동 교사 추가 / 다른 선생님을 함께 초대하는 버튼이에요. / 3 / 데모 학생 / 실제 학생 없이 학생 화면을 체험하는 계정이에요. / 4 / 학생으로 로그인 / 데모 학생 화면으로 바뀌어요(33쪽). / TIP / 데모 학생에서 나올 때는 로그아웃 → 배움터에서 북크리에이터를 다시 누르면 선생님 계정으로 돌아와요.","no":"위쪽 가운데 사람 두 명 아이콘을 누르면 저자 목록이 나옵니다. 처음에는 선생님 본인과 데모 학생만 있습니다. 데모 학생으로 로그인하면 학생이 보는 화면을 그대로 확인할 수 있어서 수업 전에 미리 보기 좋습니다. 데모 학생에서 로그아웃하면 학생 로그인 화면이 뜨는데, 당황하지 마시고 배움터 탭으로 가서 북크리에이터를 한 번 더 누르시면 됩니다.","alt":["라이브러리 저자 목록: 라이브러리 소유자와 데모 학생"]},{"n":11,"t":"새 책: 판형 고르기","sec":3,"x":"1 / 빈 책 · 테마 · 즐겨찾기 · 수입 / 빈 책으로 시작하거나 꾸며진 테마, 파일 가져오기를 골라요. / 2 / 빈 책 판형 / 세로 · 가로 · 스퀘어 가운데 하나를 골라요. / 3 / 만화 판형 / 아랫줄을 고르면 칸 나누기 · 말풍선 도구가 함께 나와요(24쪽). / TIP / 오늘 실습 책은 ‘가로’ 빈 책으로 만들었어요. 학생 화면에서도 같은 화면이 나와요.","no":"책장 화면에서 새 책을 누르면 판형을 고르는 화면이 나옵니다. 윗줄은 빈 책, 아랫줄은 만화책 판형입니다. 오늘은 가로 빈 책으로 그림책을 만들고, 데모 학생은 가로 만화 판형으로 만들어 보았습니다.","alt":["새 책 만들기 화면의 빈 책 판형과 만화 판형"]},{"n":12,"t":"테마로 시작하기, 파일 가져오기","sec":3,"x":"테마 / Newspaper, Comic, Yearbook처럼 꾸며진 틀로 시작해요. 사용하기 쉬운 레이아웃이 미리 잡혀 있어요. / 수입(가져오기) / PDF나 Book Creator ePub 파일을 끌어다 놓거나, Google Drive에서 가져와요.","no":"새 책 화면 위쪽 탭에서 테마를 누르면 신문, 만화, 졸업앨범 같은 테마가 나옵니다. 수입 탭은 가져오기라는 뜻으로, PDF 파일을 책으로 가져올 수 있습니다. 학습지 PDF를 가져와 그 위에 활동하게 하는 방법도 생각해 볼 수 있습니다.","alt":["테마 목록: Newspaper, Antique, Photobook, Comic, Yearbook 등","PDF 또는 EPUB 파일 가져오기 화면"]},{"n":13,"t":"편집 화면 한눈에 보기","sec":3,"x":"1 / 라이브러리 · 페이지 / 책장으로 / 쪽 순서 정리 / 2 / 실행 취소 / 방금 한 일 되돌리기 / 3 / 책 제목 / 누르면 이름을 바꿔요 / 4 / 공유 / 할당 · 출판 · 다운로드 · 인쇄 / 5 / + 추가 / 글 · 사진 · 펜 · 녹음 넣기 / 6 / i 꾸미기 / 고른 요소 · 쪽 배경 꾸미기 / 7 / ▶ 읽기 / 완성된 책처럼 넘겨 보기 / 8 / 다음 쪽 / 마지막 쪽에서는 + 로 바뀌어 새 쪽이 생겨요","no":"편집 화면은 단순합니다. 오른쪽 위 버튼 네 개만 기억하시면 됩니다. 공유, 더하기, i, 재생 버튼입니다. 더하기로 무엇을 넣고, i로 꾸미고, 재생으로 읽어 봅니다. 책 제목은 가운데 제목을 누르면 바꿀 수 있는데, 오늘 실습 책은 연수 실습 우리 반 가을 그림책으로 바꿨습니다. 마지막 쪽에서 오른쪽 화살표가 더하기 모양으로 바뀌는데, 누르면 새 쪽이 생깁니다.","alt":["북크리에이터 편집 화면 상단 메뉴와 실습 책 표지"]},{"n":14,"t":"+ 메뉴: 도구 · 미디어 · 앱","sec":3,"x":"도구 / 이미지 · 카메라 · 펜 · 텍스트 · 녹음. 가장 많이 쓰는 다섯 가지예요. / 미디어 / 템플릿 · 모양 · 아이콘 · 파일 · 임베드 / 앱 / Canva · 구글 드라이브 · 지도 · 3D 모델 등 / TIP / 앱 탭 아래에는 ‘체험할 앱’ 목록이 따로 있어요(27쪽). 카메라와 녹음은 처음 누를 때 브라우저가 카메라·마이크 사용을 물어볼 수 있어요. 교실 컴퓨터라면 ‘허용’을 눌러 주세요.","no":"노란 더하기 버튼을 누르면 도구, 미디어, 앱 세 탭이 나옵니다. 처음에는 도구 탭의 다섯 가지면 충분합니다. 미디어 탭에는 페이지 템플릿과 모양, 아이콘이 있고, 앱 탭에는 캔바와 여러 외부 앱이 있습니다. 앱 가운데 AI Image Generator는 27쪽에서 따로 보겠습니다.","alt":["+ 메뉴 도구 탭: 이미지, 카메라, 펜, 텍스트, 녹음","+ 메뉴 미디어 탭: 템플릿, 모양, 아이콘, 파일, 임베드","+ 메뉴 앱 탭: Canva와 체험할 앱 목록"]},{"n":15,"t":"글 넣기: 텍스트","sec":3,"x":"1 / 굵게 · 기울임 · 밑줄 · 링크 / 고른 글자에만 적용돼요. / 2 / 글자색 · 형광펜 / 강조하고 싶은 낱말에 써요. / 3 / 마이크 · 언어 / 말로 받아쓰기. EN 옆 ▾에서 언어를 골라요. / 4 / 아래 도구 / 확대 · 특수 문자 · 수식 · 번역 · 읽어 주기 / 5 / 완료 / 누르면 쪽 위에 글상자가 놓여요. / TIP / 글상자를 놓으면 아래에 스피커 버튼이 생겨요. 누르면 쓴 글을 바로 읽어 줘요.","no":"더하기, 도구, 텍스트를 누르면 이 창이 뜹니다. 실습에서는 표지 제목으로 우리 반 가을 그림책을 썼습니다. 오른쪽 위 마이크는 받아쓰기 기능인데, 언어가 영어로 되어 있을 수 있으니 한국어로 바꿔서 쓰시면 됩니다. 아래쪽에는 번역과 읽어 주기 버튼도 있습니다.","alt":["텍스트 입력 창과 서식 도구"]},{"n":16,"t":"글 꾸미기: i 버튼","sec":3,"x":"1 / 글자 크기 / 슬라이더나 − / + 로 조절해요(표지 제목 72). / 2 / 정렬 · 굵게 · 기울임 · 밑줄 / 글상자 전체에 한 번에 적용돼요. / 3 / 글꼴 / 화면에는 ‘세례반’으로 번역돼 있어요. 기본은 Open Sans. / 4 / 색상 · 배경 / 글자색과 글상자 바탕색을 바꿔요. / 5 / 앞 · 뒤 · 잠금 / 겹친 순서를 바꾸거나 움직이지 않게 고정해요. / 6 / 번역 / 글을 다른 언어로 바꿔 줘요.","no":"글상자를 한 번 눌러 고른 뒤 오른쪽 위 i 버튼을 누르면 꾸미기 창이 나옵니다. 글꼴 항목이 세례반이라고 나오는데, 영어 font를 잘못 번역한 것이라 글꼴이라고 생각하시면 됩니다. 글상자 양옆 파란 점을 끌면 너비가 바뀌고, 위쪽 초록 점을 끌면 돌아갑니다.","alt":["글상자를 고르고 i 버튼을 눌렀을 때 나오는 텍스트 설정"]},{"n":17,"t":"사진 넣기: 이미지 검색","sec":3,"x":"1 / 검색어 입력 / 한글로 검색해도 돼요. 실습에서는 ‘단풍’을 찾았어요. / 2 / 사진 고르기 / Pixabay 사진이라 자유롭게 쓰고 고칠 수 있다고 안내돼요. / 3 / 출처 주소 / 고른 사진의 원래 페이지 주소가 아래에 보여요. / 4 / 추가 / 쪽에 사진이 들어가요. / TIP / 검색 창 아래 ‘내 컴퓨터에서 업로드’로 직접 찍은 사진도 넣을 수 있어요.","no":"더하기, 도구, 이미지를 누르면 이미지 검색 창이 뜹니다. 검색 결과는 픽사베이 사진이고, 화면에도 자유롭게 사용하고 수정할 수 있다고 나옵니다. 사진을 누르면 아래에 출처 주소가 표시되고, 추가를 누르면 쪽에 들어갑니다.","alt":["이미지 검색 창에서 단풍을 검색하고 사진 한 장을 고른 모습"]},{"n":18,"t":"사진 꾸미기와 출처 남기기","sec":3,"x":"1 / 출처 · 페이지에 속성 추가 / 누르면 사진 아래에 ‘pixabay.com의 ○○ 이미지’가 붙어요. / 2 / 투명성 / 사진을 흐리게 해 배경처럼 써요. / 3 / 이미지 설명 / 대체 텍스트예요. 옆 버튼으로 AI가 써 줘요(25쪽). / 4 / 앞 · 뒤 · 잠금 / 실습에서는 사진을 ‘뒤’로 보내 제목이 위에 오게 했어요. / 5 / 배경 제거(AI) · 이미지 자르기 / 사람이나 물건만 남기거나 필요한 부분만 잘라요. / TIP / 출처 남기기는 학생들과 함께 연습하기 좋은 습관이에요.","no":"사진을 고르고 i를 누르면 이미지 설정이 나옵니다. 가장 먼저 보여 드리고 싶은 것은 페이지에 속성 추가입니다. 누르면 사진 아래에 출처 문구가 자동으로 붙습니다. 실습에서는 사진이 제목을 가려서 뒤 버튼으로 사진을 뒤로 보냈습니다. 배경 제거에는 AI 표시가 붙어 있는데, 오늘은 눌러 보지 않았습니다.","alt":["사진을 고르고 i 버튼을 눌렀을 때 나오는 이미지 설정"]},{"n":19,"t":"따라 해 보기: 표지 완성","sec":3,"x":"이 순서로 만들었어요 / 1 / + → 텍스트로 제목 쓰기 / 2 / i 에서 크기 72 · 굵게 · 주황색 / 3 / + → 이미지 → ‘단풍’ 검색 → 추가 / 4 / 사진을 ‘뒤’로 보내고 출처 추가 / 5 / 제목 글상자 배경을 흰색으로 / TIP / 사진 위에 글을 올릴 때는 글상자 배경을 흰색으로 두면 잘 읽혀요.","no":"지금까지 본 기능으로 표지를 완성한 모습입니다. 오른쪽 순서대로 같이 해 보시겠습니다. 처음 해 보시면 사진이 글을 덮어 버리는 경우가 많은데, 사진을 고르고 i에서 뒤 버튼을 누르시면 됩니다.","alt":["완성된 실습 책 표지: 단풍 사진 위에 우리 반 가을 그림책 제목"]},{"n":20,"t":"그림 그리기: 펜","sec":3,"x":"1 / 색 / 그림 물감 · 커스텀 · 매직 잉크(반짝이 · 무지개) 중에서 골라요. / 2 / 펜 종류 / 질감이 다른 펜 네 가지와 자동 그리기 펜이 있어요. / 3 / 지우개 / 그린 선을 지워요. / 4 / 이모지 도장 / 이모지를 검색해 도장처럼 찍어요. / 5 / AUTO 펜 / 그린 모양을 알아보고 비슷한 그림을 제안해 주는 자동 그리기 펜이에요. / 6 / 굵기 / 다섯 단계 가운데 골라요. / TIP / 다 그리면 오른쪽 위 ‘완료’. 그림은 사진처럼 한 덩어리로 쪽에 붙어서 크기와 위치를 옮길 수 있어요.","no":"더하기, 도구, 펜을 누르면 그리기 화면으로 바뀝니다. 위쪽 첫 아이콘이 색, 두 번째가 펜 종류와 굵기입니다. AUTO라고 적힌 펜은 대충 그린 모양을 알아보고 비슷한 그림을 골라 주는 펜인데, 저학년 아이들이 재미있어할 기능입니다. 완료를 누르면 그린 그림이 하나의 이미지가 되어 쪽에 붙습니다.","alt":["펜 도구 화면: 색, 펜 종류, 지우개, 이모지, 자동 그리기 펜, 굵기"]},{"n":21,"t":"색 고르기와 그린 결과","sec":3,"x":"색 팔레트 / 그림 물감 · 커스텀 · 매직 잉크 / 실습 2쪽 / 갈색 줄기, 노란 잎, 주황 낙엽을 펜으로 그리고 아래에 글상자를 놓았어요. / TIP / 매직 잉크는 반짝이·무지개 색이 칠해지는 펜이에요. 아이들이 꾸미기를 좋아해요.","no":"왼쪽이 색 팔레트입니다. 아래쪽 동그라미들이 매직 잉크인데, 반짝이나 무지개 색으로 칠해집니다. 오른쪽은 실습 책 2쪽으로, 펜으로 느티나무를 그리고 아래에 글을 넣었습니다.","alt":["펜 색 팔레트와 매직 잉크","실습 2쪽: 크레용 펜으로 그린 노란 느티나무와 글"]},{"n":22,"t":"쪽 배경 바꾸기","sec":3,"x":"1 / 단색 / 쪽 바탕색을 한 번에 바꿔요. 실습 3쪽은 하늘색으로 했어요. / 2 / 카테고리 / 만화 · 종이 · 테두리 · 패턴 · 텍스처 배경을 골라요. / TIP / 쪽의 빈 곳을 눌러 아무것도 고르지 않은 상태에서 i 를 누르면 ‘페이지’ 설정이 나와요.","no":"i 버튼은 무엇을 골랐느냐에 따라 내용이 바뀝니다. 글상자를 고르면 글 설정, 사진을 고르면 이미지 설정, 아무것도 고르지 않으면 쪽 배경 설정이 나옵니다. 종이나 패턴 배경을 쓰면 손으로 만든 책 느낌이 납니다.","alt":["아무것도 고르지 않고 i 를 눌렀을 때 나오는 페이지 배경 설정"]},{"n":23,"t":"페이지 템플릿","sec":3,"x":"1 / 템플릿 검색 / 필요한 틀을 낱말로 찾아요. / 2 / 무료 / 무료 요금제에서 쓸 수 있는 템플릿만 모아 봐요. / 3 / 분류 / 그래픽 오거나이저 · 포트폴리오 · 레이아웃 · 만화 · 장르 · 테마 / TIP / + → 미디어 → 템플릿에서 열어요. 영어로 된 틀이 많아서 글자만 바꿔 쓰면 돼요.","no":"더하기, 미디어, 템플릿을 누르면 페이지 템플릿 창이 열립니다. 무료를 누르면 지금 계정에서 쓸 수 있는 템플릿만 모아 볼 수 있습니다. 표, 동물 보고서, 3-2-1 돌아보기 같은 틀이 있어서 수업 정리 활동에 바로 쓸 만합니다.","alt":["페이지 템플릿 창의 무료 템플릿 목록"]},{"n":24,"t":"만화 판형: 칸 · 말풍선","sec":3,"x":"만화 도구 / 만화 판형이면 + 메뉴에 칸 · 말풍선 · 생각 풍선 · 효과음이 더 생겨요. / 칸 나누기 / 원하는 칸 모양을 골라요. / 데모 학생 작품 / 말풍선을 두 번 눌러 글을 쓰고, 칸 안의 + → 이미지로 사진을 칸에 맞춰 넣었어요.","no":"새 책에서 아랫줄 만화 판형을 고르면 더하기 메뉴에 만화 도구가 추가됩니다. 칸 나누기로 쪽을 나누고, 말풍선을 놓은 뒤 두 번 누르면 글을 쓸 수 있습니다. 칸을 누르면 가운데 더하기가 나오는데, 여기서 이미지를 넣으면 사진이 칸 모양에 맞게 잘려 들어갑니다. 오른쪽은 데모 학생 계정으로 만든 쪽입니다.","alt":["만화 판형의 + 메뉴: 칸, 말풍선, 생각 풍선, 효과음 스티커","칸 나누기 모양 목록","데모 학생이 만든 만화 쪽: 말풍선과 은행잎 사진"]},{"n":25,"t":"AI 이미지 설명(대체 텍스트)","sec":4,"x":"1 / AI 표시 / AI가 만든 설명이라는 뜻이에요. / 2 / 설명 확인 / 실습에서는 영어 문장으로 나왔어요. 고쳐서 저장할 수 있어요. / 3 / 저장 / 사진의 이미지 설명 칸에 들어가요. / TIP / 이미지 설명은 화면 읽기 프로그램이 읽어 주는 글이에요. 시각장애 학생을 위한 배려를 함께 이야기해 보세요.","no":"사진을 고르고 i를 누른 뒤 이미지 설명 칸 옆 버튼을 누르면 AI가 사진 설명을 만들어 줍니다. 실습에서는 코스모스 사진을 분홍, 하양, 진한 빨강 코스모스가 맑은 하늘 아래 핀 들판이라는 뜻의 영어 문장으로 설명해 주었습니다. 라이브러리 설정의 AI가 생성한 이미지 설명이 켜져 있어야 쓸 수 있습니다.","alt":["AI가 만든 이미지 설명을 확인하는 창"]},{"n":26,"t":"읽어 주기와 설정","sec":4,"x":"1 / 읽어주기 / 읽기 화면 오른쪽 위에 있어요. / 2 / 단어 읽기 / 단어를 하나씩 눌러 들을 수 있게 해요. / 3 / 목소리 / 한국어 목소리(Microsoft Heami)로 되어 있었어요. / 4 / 단어 강조하기 / 읽는 낱말을 색으로 따라가요. / 5 / 페이지 자동으로 넘기기 / 다 읽으면 다음 쪽으로 넘어가요. / 6 / 설정 저장 / 이 책의 기본 설정으로 저장해요. / TIP / 속도도 다섯 단계로 바꿀 수 있어요. 저학년 함께 읽기나 영어 책 듣기에 좋아요.","no":"재생 버튼으로 읽기 화면에 들어가면 오른쪽 위에 읽어주기 버튼이 있습니다. 옆 톱니바퀴를 누르면 읽어 주기 설정이 나옵니다. 목소리가 한국어로 잡혀 있어서 우리말 책도 자연스럽게 읽어 줍니다. 설정 저장을 누르면 이 책을 여는 사람에게 같은 설정이 적용됩니다.","alt":["읽기 화면의 읽어주기 버튼과 설정 창"]},{"n":27,"t":"AI Image Generator는 계정 연결이 필요해요","sec":4,"x":"1 / 글로 그림 만들기 / 무료·프리미엄 사용자 모두 Adobe Express for Education 계정으로 쓸 수 있다고 안내돼요. / 2 / 앱 활성화 / 누르면 외부 계정 연결이 시작돼요. / 연수에서는 켜지 않았어요 / 외부 계정을 새로 만들어 연결해야 해서 실습하지 않았어요. 학생에게 쓰게 하려면 학교 정책과 개인정보 동의를 먼저 확인해 주세요.","no":"더하기, 앱 탭의 체험할 앱 목록에 AI Image Generator가 있습니다. 누르면 상세 내용 창이 뜨는데, 무료와 프리미엄 사용자 모두 어도비 익스프레스 에듀케이션 계정을 통해 쓸 수 있다고 나옵니다. 계정을 새로 만들어 연결해야 하는 기능이라 연수에서는 켜지 않았습니다.","alt":["AI Image Generator 앱 상세 내용 창"]},{"n":28,"t":"읽기 화면: 완성된 책처럼 보기","sec":5,"x":"1 / 편집 / 편집 화면으로 돌아가요. / 2 / 확대 · 전체 화면 / TV로 함께 읽을 때 좋아요. / 3 / 공유 / 전자책으로 다운로드 · 인쇄 / 4 / 쪽 모아 보기 / 원하는 쪽으로 바로 가요. / 5 / 설정 / 양면 페이지 · 읽어 주기 설정 / 6 / 읽어주기 / 쓴 글을 소리 내어 읽어 줘요.","no":"편집 화면 오른쪽 위 재생 버튼을 누르면 읽기 화면이 열립니다. 책처럼 두 쪽이 펼쳐지고 옆 화살표로 넘깁니다. 교실 TV로 함께 읽을 때는 전체 화면 버튼을 누르시면 됩니다.","alt":["읽기 화면에서 실습 책 2쪽과 3쪽을 펼친 모습"]},{"n":29,"t":"공유 메뉴","sec":5,"x":"1 / 할당 / 이 책을 학생마다 한 권씩 나눠 줘요(30쪽). / 2 / 출판 / 온라인 출판 링크를 만들어요(31쪽). / 3 / 협업 / 왕관 표시가 붙은 유료 기능이에요. / 4 / 다운로드 / 누르니 PDF가 새 탭에 열렸어요(32쪽). / 5 / 인쇄 / 종이 책으로 뽑아요. / TIP / 데모 학생의 편집 화면에는 공유 버튼이 보이지 않았어요. 학생 출판은 라이브러리 설정에서 켜야 해요.","no":"편집 화면 오른쪽 위 공유 버튼을 누르면 할당, 출판, 협업, 다운로드, 인쇄가 나옵니다. 협업에는 왕관 표시가 있어 유료 기능으로 보입니다. 학생 계정에서는 출판 허용이 꺼져 있어서 공유 버튼 자체가 보이지 않았습니다.","alt":["편집 화면 공유 버튼을 눌렀을 때 나오는 메뉴"]},{"n":30,"t":"할당: 학생마다 한 권씩 나눠 주기","sec":5,"x":"1 / 할당 대상 / 라이브러리에 있는 모든 학생에게 나눠 줘요. / 2 / 원본 책 숨기기 / 학생에게는 선생님 원본이 보이지 않아요. / 3 / 페이지 잠금 / 학생이 쪽을 추가 · 삭제 · 순서 변경하지 못하게 해요. / 4 / 할당 / 학생이 라이브러리에 들어오면 책을 한 권씩 받아요. / TIP / 학생 책도 라이브러리의 책 40권 안에 들어가요. 데모 학생이 책을 만들자 책 수가 하나 늘었어요.","no":"할당은 선생님이 만든 책을 학생 수만큼 복사해서 나눠 주는 기능입니다. 학습지처럼 틀을 만들어 두고 할당하면 학생마다 자기 책이 생깁니다. 연수 계정에는 학생이 없어서 할당 직전까지만 해 보았습니다. 무료 요금제는 라이브러리 책이 40권까지라서, 학생 수가 많은 반은 한 번에 나눠 줄 수 있는 양을 생각해 두셔야 합니다.","alt":["책 할당 창"]},{"n":31,"t":"출판: 온라인 링크 만들기","sec":5,"x":"1 / 제목 · 저자 / 출판했을 때 보이는 이름이에요. / 2 / 설명 / 200자까지 책 소개를 써요. / 3 / 찾을 수 있는 대상 / 비공개는 링크를 아는 사람만 봐요. 언제든 게시를 취소할 수 있어요. / 4 / 리믹스 / 켜면 다른 사람이 사본을 받아 고칠 수 있어요(CC-BY 3.0). / 5 / 온라인 출판 / 누르면 책이 온라인에 올라가요. / TIP / 연수에서는 출판 직전까지만 해 봤어요. 학생 사진이나 이름이 들어간 책은 비공개를 권해요.","no":"공유, 출판을 누르면 이 창이 나옵니다. 기본값은 비공개, 리믹스 끄기입니다. 비공개로 출판하면 링크를 받은 사람만 볼 수 있어서 학부모님께 링크로 보내 드리기 좋습니다. 연수에서는 실제로 출판하지는 않았습니다.","alt":["책 상세 내용 확인 창: 제목, 저자, 설명, 공개 범위, 리믹스"]},{"n":32,"t":"다운로드: PDF로 열기","sec":5,"x":"1 / 쪽 미리 보기 / 3쪽짜리 실습 책이 그대로 PDF가 됐어요. / 2 / 저장 / PDF 파일로 내려받아요. / 3 / 인쇄 / 바로 종이로 뽑을 수 있어요.","no":"공유, 다운로드를 누르니 새 탭에서 PDF가 바로 열렸습니다. 사진 출처 문구까지 그대로 들어가 있습니다. 읽기 화면의 공유 버튼에는 전자책으로 다운로드가 따로 있습니다.","alt":["실습 책을 PDF로 연 화면"]},{"n":33,"t":"학생 화면 미리 보기(데모 학생)","sec":6,"x":"1 / 학생 계정 표시 / 오른쪽 위가 웃는 얼굴로 바뀌어요. / 2 / 새 책 / 학생도 직접 책을 만들어요. / 3 / 라이브러리 책 넘겨 보기 / ‘서로의 책 읽기’가 켜져 있으면 선생님과 친구 책이 보여요. / 4 / 라이브러리 · 공유 · 읽기 / 고른 책을 바로 읽어요. / TIP / 데모 학생에서 로그아웃하면 학생 로그인 화면이 떠요. 배움터에서 북크리에이터를 다시 누르면 선생님 계정으로 돌아와요.","no":"저자 목록에서 데모 학생의 학생으로 로그인을 누르면 이 화면이 나옵니다. 학생은 라이브러리의 책을 넘겨 보며 읽고, 새 책 버튼으로 자기 책을 만듭니다. 24쪽의 만화 쪽도 이 화면에서 만들었습니다.","alt":["데모 학생으로 로그인했을 때의 라이브러리 화면"]},{"n":34,"t":"클래스 뷰: 학생 작업 한눈에 보기","sec":6,"x":"1 / 과제 · 종류 / 할당한 과제만 골라 보거나 정렬해요(종류는 왕관 표시). / 2 / 학생 이름 · 책 제목 / 마지막으로 고친 시간이 함께 보여요. / 3 / 쪽 미리 보기 / 쪽마다 고친 시간이 보이고, 누르면 그 쪽이 바로 열려요. / TIP / 무료 요금제에서는 모든 학생 책을 다 보려면 업그레이드가 필요하다는 안내가 함께 떠요.","no":"위쪽 가운데 세 번째 아이콘이 클래스 뷰입니다. 학생별로 어떤 쪽을 언제 고쳤는지 한눈에 보입니다. 쪽을 누르면 그 학생 책의 해당 쪽이 열려서 바로 댓글을 남길 수 있습니다. 화면 아래에는 모든 학생의 작업을 보려면 업그레이드하라는 안내가 함께 나왔습니다.","alt":["클래스 뷰에서 데모 학생과 선생님 책의 쪽 미리 보기"]},{"n":35,"t":"댓글로 피드백하기","sec":6,"x":"1 / 선생님 댓글 / 쪽 옆에 남아서 학생이 책을 열면 볼 수 있어요. / 2 / 댓글 추가 / 글 · 영상 · 녹음 · 이모지로 남겨요. 130개 이상 언어로 번역도 돼요. / TIP / 학생 책은 선생님이 바로 고칠 수도 있어요. 고쳐 주기보다 댓글로 질문을 남기면 학생이 스스로 다듬어요.","no":"학생 책을 열고 오른쪽 위 말풍선 버튼을 누르면 댓글 창이 열립니다. 실습에서는 은행잎 사진과 말풍선이 잘 어울려요, 다음 칸에는 어떤 가을을 찾았는지 그려 볼까요라고 남겼습니다. 글 말고도 영상, 녹음, 이모지로 댓글을 남길 수 있습니다.","alt":["데모 학생 책에 선생님 댓글을 남긴 화면"]},{"n":36,"t":"합치기: 학급 문집 만들기","sec":6,"x":"1 / 책 고르기 / 책장 → 선택 → 합칠 책을 차례로 눌러요. / 2 / 합치기 / 위쪽 메뉴에서 눌러요. / 3 / 순서 확인 / 아래 줄 순서대로 합쳐져요. / 4 / 제목 쓰고 책 만들기 / 원래 책들은 그대로 남아요. / 5 / 표지가 자동으로 / 새 표지가 붙은 7쪽짜리 문집이 생겼어요.","no":"학생들이 각자 만든 책을 하나로 묶을 때 합치기를 씁니다. 책장에서 선택을 누르고 합칠 책을 고른 뒤 합치기를 누르면 제목을 쓰는 창이 뜹니다. 실습에서는 선생님 그림책과 데모 학생 만화책을 합쳐 우리 반 가을 문집을 만들었고, 새 표지가 붙은 7쪽짜리 책이 생겼습니다. 원래 책들은 그대로 남지만, 합친 책도 한 권으로 세기 때문에 40권 한도를 생각해 두셔야 합니다.","alt":["책장 선택 모드에서 두 책을 고르고 합치기를 누르는 화면","합친 책의 제목과 저자를 쓰는 창","합치기로 만든 문집의 자동 표지"]},{"n":37,"t":"꼭 알아 둘 점","sec":6,"x":"라이브러리 1개 · 책 40권 / 무료 요금제 한도예요. 학생 책과 합친 책도 40권 안에 들어가요. / 출판과 공개 범위 / 학생 사진·이름이 있으면 비공개로. 학생 출판은 설정에서 켜야 해요. / 초대 코드 관리 / 코드는 우리 반에만 알려요. 퍼졌으면 ‘초대 코드 만료’. / 사진 출처 / 검색 사진은 Pixabay예요. ‘페이지에 속성 추가’로 출처를 남겨요. / AI 기능 / 이미지 설명은 영어로 나와요. AI Image Generator는 외부 계정이 필요해요. / 데모 학생에서 돌아오기 / 로그아웃한 뒤 배움터에서 북크리에이터를 다시 눌러요.","no":"가장 중요한 것은 첫 번째 카드입니다. 연수 준비 계정은 무료 요금제라 라이브러리 1개, 책 40권까지였습니다. 학생이 만든 책, 할당한 책, 합친 책이 모두 이 안에서 셉니다. 다 쓴 책은 PDF로 받아 두고 정리하시면 공간을 다시 쓸 수 있습니다.","alt":[]},{"n":38,"t":"수업에 이렇게 써 보세요","sec":6,"x":"우리 반 그림책 · 문집 / 한 사람이 한두 쪽씩 만들고 합치기로 묶기 / 소리 내어 읽기 기록 / 쓴 글을 녹음해 넣고 읽어 주기와 비교하기 / 만화로 개념 정리 / 만화 판형으로 사회·과학 내용을 네 칸에 / 영어 미니북 / 영어 문장을 쓰고 읽어 주기로 들어 보기 / 할당으로 학습지 책 나눠 주기 / 선생님이 틀을 만들어 할당하면 학생마다 자기 책이 생기고, 클래스 뷰에서 쪽마다 진행 상황을 볼 수 있어요.","no":"처음에는 우리 반 가을 그림책처럼 한 사람이 한 쪽씩 맡아 만들고 합치기로 묶는 활동을 권해 드립니다. 책 수를 아끼면서도 반 전체 작품이 한 권으로 남습니다.","alt":[]},{"n":39,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 라이브러리 함께 설정 / 반 이름 바꾸기와 학생 허용 기능을 같이 정해요. / 첫 책 함께 만들기 / 표지 한 장부터 옆에서 같이 만들어요. / 학생 초대 도와드리기 / 초대 코드와 학생 로그인을 함께 확인해요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 라이브러리 설정이나 첫 책 만들기, 학생 초대를 할 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,65234],[65234,47358],[112592,58556],[171148,61206],[232354,61760],[294114,79508],[373622,78670],[452292,61030],[513322,72728],[586050,91608],[677658,53260],[730918,70238],[801156,117664],[918820,57800],[976620,57926],[1034546,60954],[1095500,102436],[1197936,184460],[1382396,159772],[1542168,70510],[1612678,63990],[1676668,94352],[1771020,62396],[1833416,66816],[1900232,88146],[1988378,115620],[2103998,95256],[2199254,94104],[2293358,57388],[2350746,74758],[2425504,82108],[2507612,108334],[2615946,115328],[2731274,77720],[2808994,58722],[2867716,60290],[2928006,59912],[2987918,54780],[3042698,40120]],"toffs":[[0,4248],[4248,3932],[8180,5044],[13224,4820],[18044,5272],[23316,5810],[29126,6542],[35668,4860],[40528,5362],[45890,7428],[53318,4540],[57858,6004],[63862,7732],[71594,4460],[76054,5220],[81274,5426],[86700,8098],[94798,9698],[104496,9176],[113672,6610],[120282,5540],[125822,5904],[131726,5316],[137042,6248],[143290,6214],[149504,8280],[157784,7520],[165304,7026],[172330,4720],[177050,6370],[183420,6510],[189930,6082],[196012,8426],[204438,6186],[210624,4886],[215510,4748],[220258,4298],[224556,4444],[229000,3948]],"packSize":3082818,"thumbSize":232948},{"key":"wetoon","name":"위툰","title":"위툰 사용 안내서","group":"make","sub":"줄거리만 쓰면 AI가 그려 주는 4컷 웹툰 만들기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"배움터 계정에 프리미엄 요금제가 적용돼요. 마이 페이지에 '프리미엄 요금제 이용중입니다.'가 보이면 돼요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 위툰 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 위툰에 접속하고 첫 화면과 요금제를 확인해요"},{"start":7,"num":"2","label":"이야기 쓰기","desc":"프로젝트를 만들고 AI 질문과 의견을 받으며 이야기를 써요"},{"start":12,"num":"3","label":"AI로 그리기","desc":"그림체, 캐릭터, 시나리오, 컷 그림을 AI와 함께 골라요"},{"start":18,"num":"4","label":"컷 꾸미기","desc":"편집 모드에서 말풍선과 글자를 꾸미고 저장해요"},{"start":24,"num":"5","label":"완성·내보내기","desc":"제목을 정하고 내려받으며, 애니메이션 크레딧과 마이 갤러리를 확인해요"},{"start":29,"num":"6","label":"수업 활용","desc":"클래스룸, 위툰랩, 유의사항, 수업 활용 아이디어"}],"slides":[{"n":1,"t":"위툰","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 줄거리만 쓰면 AI가 그려 주는 4컷 웹툰 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 위툰을 함께 써 보겠습니다. 오른쪽 네 컷은 연수를 준비하면서 실제로 만들어 본 웹툰입니다. 전학 온 친구에게 먼저 말을 거는 이야기를 한 줄 적었더니, 질문과 시나리오, 그림, 말풍선까지 AI가 거의 다 만들어 주었습니다. 처음부터 끝까지 20분이 채 걸리지 않았습니다.","alt":["위툰으로 만든 4컷 웹툰 '공룡 친구 민준이'"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 위툰, 첫 화면, 요금제 확인 / 04–06쪽 / STEP 2 / 이야기 쓰기 / 글 종류, 핵심 내용, AI 질문과 의견 / 07–11쪽 / STEP 3 / AI로 그리기 / 그림체·캐릭터·시나리오·컷 고르기 / 12–17쪽 / STEP 4 / 컷 꾸미기 / 말풍선, 글자, 그림 다시 그리기, 저장 / 18–23쪽 / STEP 5 / 완성·내보내기 / 제목, 컷 순서, 다운로드, 애니메이션 / 24–28쪽 / STEP 6 / 수업 활용 / 클래스룸, 위툰랩, 유의사항, 아이디어 / 29–33쪽","no":"여섯 단계로 진행하겠습니다. 웹툰 한 편을 처음부터 끝까지 만드는 순서 그대로입니다. 시간이 빠듯하면 2단계 이야기 쓰기와 4단계 말풍선 넣기만큼은 꼭 직접 해 보시길 권합니다.","alt":[]},{"n":3,"t":"위툰으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 이야기 쓰기 도움 / AI가 질문을 던지고, 쓴 글에 의견을 줘요 / AI가 그리는 그림 / 그림체 6가지, 캐릭터와 컷을 AI가 그려요 / 말풍선 · 글자 꾸미기 / 대사가 말풍선에 자동으로 들어가요 / 완성 · 내보내기 / 내려받기, 인쇄, 클래스룸에서 평가 / 경북AI배움터 혜택 / 배움터로 접속하면 '프리미엄 요금제' / 배움터를 거쳐 들어가면 프리미엄 요금제가 자동으로 적용돼요. 마이 페이지에서 확인할 수 있어요. / 교사·학생 모두 배움터 → 위툰으로 접속해요. (배움터 '위툰 이용 방법 안내' 기준)","no":"위툰은 줄거리만 입력하면 AI가 시나리오를 만들고, 그림체 선택과 컷 편집까지 도와주는 웹툰 제작 도구입니다. 배움터 안내 자료실의 위툰 이용 안내를 보니, 교사와 학생 모두 배움터를 거쳐 위툰에 들어가고 그렇게 이용하면 프리미엄 요금제가 자동으로 적용된다고 되어 있었습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 위툰 열기","sec":1,"x":"1 / 에듀테크 서비스 다음 쪽으로 / 메인 화면을 내려 목록 아래 ›를 눌러요. 위툰은 2쪽에 있었어요. / 2 / 위툰 누르기 / 새 탭에서 위툰이 열리고 배움터 계정으로 바로 로그인돼요. / 3 / 마우스를 올리면 설명 / 오른쪽 칸에 서비스 소개가 떠요. / TIP / 따로 회원가입하거나 비밀번호를 넣지 않아도 돼요. 배움터 로그인 한 번이면 충분해요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 메인 화면의 에듀테크 서비스 목록에서 오른쪽 화살표를 눌러 다음 쪽으로 넘기면 첫 칸에 위툰이 있었습니다. 누르면 새 탭이 열리면서 로그인까지 자동으로 됩니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 2쪽과 위툰 설명"]},{"n":5,"t":"첫 화면과 메뉴 살펴보기","sec":1,"x":"1 / ＋ 말풍선 / 새 웹툰 프로젝트를 만들어요. / 2 / 위툰 제작하기 / 지금 보이는 첫 화면이에요. 언제든 여기서 새로 시작해요. / 3 / 마이 갤러리 | 클래스룸 / 내가 만든 웹툰과 학생 작품을 모아 봐요. / 4 / 마이 페이지 / 적용된 요금제를 확인해요.","no":"배움터에서 들어오면 투니라는 말풍선 캐릭터가 인사를 하고, 가운데에 더하기 말풍선이 나타납니다. 이걸 누르면 바로 새 웹툰을 시작할 수 있습니다. 위쪽 메뉴 가운데 위툰랩은 뒤에서 따로 소개하겠습니다.","alt":["위툰 제작하기 첫 화면과 위쪽 메뉴"]},{"n":6,"t":"프리미엄 요금제 확인하기","sec":1,"x":"1 / '프리미엄 요금제 이용중입니다.' / 이 문구가 보이면 배움터 연동이 잘 된 거예요. / · / 확인하는 곳 / 위쪽 메뉴 마이 페이지 → 화면을 아래로 내리기 / TIP / 결제 관리나 요금제 변경은 누르지 않아도 돼요. 배움터 계정에는 이미 적용되어 있어요.","no":"마이 페이지 아래쪽에 프리미엄 요금제 이용중이라는 파란 상자가 보이면 정상입니다. 화면에 나온 이메일과 이름은 흐리게 처리했습니다.","alt":["마이 페이지의 프리미엄 요금제 이용 안내"]},{"n":7,"t":"새 프로젝트 만들기","sec":2,"x":"1 / 프로젝트 제목 / 20자 이내로 적어요. 오른쪽 마이크로 말해서 넣을 수도 있어요. / 2 / 확인 / 제목을 넣어야 확인 버튼이 켜져요. / TIP / 학생에게는 '번호_제목'처럼 형식을 정해 주면 나중에 갤러리에서 찾기 쉬워요.","no":"첫 화면의 더하기 말풍선을 누르면 프로젝트 제목 창이 뜹니다. 실습에서는 '[연수 실습] 우리 반 이야기'라고 넣었습니다.","alt":["프로젝트 제목 입력 창"]},{"n":8,"t":"어떤 글을 쓸지 고르기","sec":2,"x":"1 / 글의 종류 / 웹툰 · 일기 · 시 · 기사 · SNS · 설명문 · 홍보/광고 중에서 골라요. / 2 / 건너뛰기 / 고르지 않고 바로 이야기 쓰기로 넘어가요. / TIP / 오늘 실습은 맨 위 '웹툰'으로 해 보세요.","no":"첫 질문은 어떤 종류의 글을 써 보고 싶은지입니다. 실습에서는 웹툰을 골랐습니다. 다른 종류를 고르면 뒤에 나오는 질문이 달라질 것 같은데, 이번에는 거기까지 확인하지 못했습니다.","alt":["글의 종류를 고르는 화면"]},{"n":9,"t":"꼭 넣고 싶은 내용 적기","sec":2,"x":"1 / 기초 · 기본 · 심화 / 고른 수준에 맞춰 AI가 질문 3개를 만들어 줘요. / 2 / 핵심 내용 / 한두 문장이면 충분해요. 500자까지 쓸 수 있어요. / 3 / 음성 입력 / 타자가 느린 학생은 말로 넣어도 돼요. / 4 / 다음 / AI가 질문을 만들어요.","no":"여기에 넣은 한 줄이 이야기의 씨앗이 됩니다. 실습에서는 '전학 온 친구에게 먼저 말을 걸어 친한 친구가 되는 이야기'라고 적었습니다. 기초, 기본, 심화 버튼은 질문의 수준을 정하는 버튼이고, 저는 기본으로 해 보았습니다.","alt":["꼭 넣고 싶은 내용을 적는 화면"]},{"n":10,"t":"AI가 던진 질문에 답하기","sec":2,"x":"1 / AI가 만든 질문 / 적은 내용에 맞춰 질문 3개가 나와요. / 2 / 답 쓰기 / 500자까지 써요. 비워 두어도 다음으로 넘어가요. / 3 / 제출하기 / 이야기를 다 쓰면 켜져요. / TIP / 실습 때 나온 질문: '주인공은 왜 먼저 말을 걸었을까?' '친해지는 계기를 어떻게 만들면 좋을까?'","no":"질문 세 개가 나왔습니다. 주인공은 왜 먼저 말을 걸었을까, 친해지는 계기를 어떻게 만들면 좋을까, 마지막 장면은 어떻게 따뜻하게 끝날까. 줄거리를 짜기 전에 생각을 정리하게 돕는 질문이라 수업에 쓰기 좋겠다고 생각했습니다. 오른쪽 위 제출하기는 실습 때 누르지 않았는데도 다음 단계로 잘 넘어갔습니다.","alt":["AI가 만든 질문과 답을 쓰는 칸"]},{"n":11,"t":"이야기 쓰고 AI 의견 받기","sec":2,"x":"1 / AI에게 의견 받기 / 네 번째 칸에 줄거리를 쓴 뒤 눌러요. / 2 / AI 의견 / 점수 없이 잘된 점과 더 좋아질 점을 알려 줘요. / 3 / 진행 막대 / 지금 몇 번째 단계인지 보여 줘요. / 4 / 다음 / 그림체 고르기로 넘어가요.","no":"네 번째 칸에 세 질문의 답을 바탕으로 줄거리를 씁니다. AI 의견을 받아 보니 '지우와 민준이의 마음이 잘 드러나서 따뜻해요. 다음에는 둘의 표정이나 말 한마디를 더 넣으면 장면이 더 생생해질 거예요'처럼 칭찬과 제안을 함께 주었습니다. 점수를 매기지 않는다고 화면에 적혀 있어서 학생들이 부담을 덜 느끼겠다고 보았습니다.","alt":["이야기 쓰기 칸 아래의 AI 의견"]},{"n":12,"t":"그림체 고르기","sec":3,"x":"1 / 그림체 선택 / 6가지 중 하나를 누르면 노란 테두리가 생겨요. / 2 / 화살표 / 옆으로 넘기면 나머지 그림체가 보여요. / TIP / 그림체에 따라 웹툰 분위기가 크게 달라져요. 실습에서는 아이들 느낌이 나는 입체 그림체를 골랐어요.","no":"그림체는 여섯 가지가 있습니다. 실사에 가까운 그림, 도트 그림, 입체 애니메이션 느낌 등 분위기가 꽤 다릅니다. 고른 뒤 아래쪽 다음을 누르면 됩니다.","alt":["그림체 6가지 중 하나를 고르는 화면"]},{"n":13,"t":"주인공 캐릭터 설정하기","sec":3,"x":"1 / 이름 / 떠오르지 않으면 'AI 추천'을 눌러요. / 2 / 성별 / 남자 / 여자 / 3 / 나이 / 아이 · 청소년 · 어른 · 노인 / 4 / 특징 / 50자 이내로 쓰거나 아래 해시태그를 눌러 넣어요.","no":"실습에서는 이름 지우, 여자, 아이로 정하고 특징에 단발머리, 노란 티셔츠, 밝은 미소, 초등학생을 적었습니다. 해시태그는 귀여움 하나를 눌러 보았습니다. 학생들에게는 실명 대신 지어낸 이름을 쓰게 하면 좋겠습니다.","alt":["캐릭터 이름, 성별, 나이, 특징을 정하는 화면"]},{"n":14,"t":"AI가 그린 캐릭터 고르기","sec":3,"x":"1 / 캐릭터 후보 / 마음에 드는 캐릭터를 눌러 골라요. / 2 / 추가 생성 / 마음에 드는 게 없으면 더 그려 달라고 해요. / 3 / 다음 / 시나리오를 만들어요. / TIP / 그림을 그리는 동안 '이미지를 생성 중입니다' 화면이 떠요. 새로고침하지 말고 기다려 주세요.","no":"다음을 누르고 30초쯤 기다리니 캐릭터 후보 네 명이 나왔습니다. 기다리는 동안에는 미니 게임 버튼도 함께 떴습니다. 노란 티셔츠라고 적었더니 후보 대부분이 노란 옷을 입고 있었습니다.","alt":["AI가 그린 캐릭터 후보 4명과 추가 생성 버튼"]},{"n":15,"t":"시나리오 3가지 중 고르기","sec":3,"x":"1 / 시나리오 고르기 / AI가 4컷 시나리오를 3가지 만들어 줘요. 하나를 눌러 골라요. / 2 / 편집 / 컷마다 내용과 대사를 고칠 수 있어요. / TIP / 세 시나리오의 대사를 비교하며 '어떤 대사가 더 자연스러울까?' 이야기 나누기 좋아요.","no":"시나리오는 세 가지가 나오고, 각각 네 컷으로 되어 있습니다. 컷마다 내용, 즉 장면 설명과 대사가 들어 있습니다. 실습에서는 두 번째 시나리오를 골랐습니다.","alt":["AI가 만든 4컷 시나리오 3가지"]},{"n":16,"t":"컷 내용과 대사 고치기","sec":3,"x":"1 / 대사 / 50자까지 써요. 이 대사가 나중에 말풍선에 그대로 들어가요. / 2 / 캐릭터 없음 / 있음 / 주인공이 나오지 않는 장면이면 없음을 골라요. / 3 / 적용 / 고친 내용을 반영해요. / TIP / 장면 설명(내용)은 100자까지 쓸 수 있어요.","no":"편집을 누르면 내용과 대사를 고칠 수 있습니다. 첫 컷 대사를 '민준아, 안녕? 나는 지우야!'로 바꾸고 적용했더니, 뒤에서 말풍선을 넣을 때 이 대사가 그대로 들어갔습니다.","alt":["시나리오 컷의 편집 모드"]},{"n":17,"t":"컷마다 그림 고르기","sec":3,"x":"1 / 그림 후보 / 컷마다 2장씩 그려져요. 하나를 눌러 골라요. / 2 / 편집하기 / 고른 그림에 말풍선과 글자를 넣어요. / 3 / 추가 컷 생성하기 / 다른 그림이 필요하면 더 그려요. / 4 / 미리보기 / 지금까지 만든 웹툰을 이어서 봐요.","no":"시나리오를 고르고 1분쯤 지나니 네 컷의 그림이 컷마다 두 장씩 나왔습니다. AI가 컷마다 따로 그리다 보니 같은 주인공이라도 머리 모양이나 옷이 조금씩 달라지기도 했습니다. 마음에 드는 그림을 고르고, 영 아니다 싶으면 추가 컷 생성하기를 누르면 됩니다.","alt":["컷별 그림 후보 2장과 편집하기 버튼"]},{"n":18,"t":"편집 모드 살펴보기","sec":4,"x":"1 / 추가 / 이미지 수정 · 말풍선 · 텍스트 · 사진(내 파일)을 넣어요. / 2 / 스타일 · 색상 · 글꼴 · 외곽선 / 고른 말풍선이나 글자를 꾸며요. / 3 / 저장 / 꾸민 컷을 저장해요. / TIP / 화면 안내에 따르면 그림 위를 빠르게 두 번 눌러도 말풍선이 생겨요.","no":"편집하기를 누르면 왼쪽에 그림, 오른쪽에 편집 도구가 열립니다. 처음에는 추가 탭이 열려 있고, 말풍선이나 글자를 고르면 스타일, 색상, 글꼴, 외곽선 탭이 차례로 켜집니다.","alt":["컷 편집 모드의 추가 메뉴"]},{"n":19,"t":"말풍선 넣기","sec":4,"x":"1 / 말풍선 / 시나리오의 대사가 들어간 말풍선이 생겨요. / 2 / 말풍선 버튼 / 추가 메뉴에서 눌러요. / TIP / 말풍선과 글자는 따로 움직여요. 말풍선을 옮긴 뒤 글자도 끌어서 그 안에 넣어 주세요.","no":"말풍선 버튼을 누르니 앞에서 고쳐 둔 대사가 들어간 말풍선이 왼쪽 위에 생겼습니다. 말풍선을 끌어서 옮겼더니 글자는 제자리에 남아 있어서, 글자도 따로 끌어다 넣었습니다. 연수 때 많이 헷갈릴 부분이라 미리 말씀드립니다.","alt":["대사가 자동으로 들어간 말풍선"]},{"n":20,"t":"말풍선 모양 바꾸기","sec":4,"x":"1 / 고른 말풍선 / 모서리 손잡이로 지우기 · 돌리기 · 크기 조절을 해요. / 2 / 말풍선 모양 / 동그라미, 네모, 육각형, 구름 모양 등에서 골라요. / 3 / 색상 / 말풍선 색도 바꿀 수 있어요.","no":"말풍선을 누르면 주황색 테두리와 손잡이가 생기고, 오른쪽에 스타일 탭이 열립니다. 외치는 장면이면 뾰족한 모양, 속마음이면 구름 모양처럼 장면에 맞게 바꿔 보면 좋겠습니다.","alt":["말풍선을 고르고 모양을 바꾸는 스타일 탭"]},{"n":21,"t":"글자 꾸미기","sec":4,"x":"1 / 고른 글자 / 오른쪽 가운데 손잡이를 당기면 줄이 바뀌어요. / 2 / 글꼴 / 프리텐다드, 나눔스퀘어, 교보손글씨 등 / 3 / 막대 · 정렬 / 글자 모양과 줄 맞춤을 조절해요. / 4 / 색상 · 글꼴 · 외곽선 / 색상 탭에는 'AI 추천 색상'도 있어요.","no":"글자가 말풍선 밖으로 삐져나와서, 글자 상자의 오른쪽 손잡이를 안쪽으로 당겼더니 두 줄로 바뀌면서 말풍선 안에 쏙 들어갔습니다. 글꼴은 교보손글씨처럼 손글씨 느낌도 있어서 학생들이 좋아할 것 같습니다.","alt":["글자를 고르고 글꼴을 바꾸는 화면"]},{"n":22,"t":"그림 다시 그리기 (이미지 수정)","sec":4,"x":"1 / 지문 고치기 / 장면 설명을 고치고 캐릭터 있음/없음을 정해요. / 2 / 생성 / 고친 지문으로 프롬프트를 만들어요. / 3 / 프롬프트로 이미지 생성하기 / 만든 프롬프트로 새 그림을 그려요. / TIP / 이번 실습에서는 메뉴만 열어 보았어요. 그림이 장면과 많이 다를 때 써 보세요.","no":"추가 메뉴의 이미지 수정을 누르면 이 화면이 나옵니다. 화면 설명대로라면 지문, 즉 장면 설명을 고쳐서 프롬프트를 만들고, 그 프롬프트로 그림을 새로 그리는 두 단계입니다. 이번에는 직접 생성까지 해 보지는 않았습니다.","alt":["이미지 수정 메뉴의 지문과 프롬프트 생성"]},{"n":23,"t":"컷마다 꼭 저장하기","sec":4,"x":"1 / 저장 확인 창 / 저장하지 않고 닫으면 이렇게 물어봐요. '저장'을 누르세요. / 2 / 저장 / 꾸민 뒤 오른쪽 위 저장 → '저장이 완료 되었습니다' / TIP / 실습해 보니 저장한 컷만 미리보기에 그림으로 나왔어요. 네 컷 모두 '편집하기 → 저장'을 해 두면 안심이에요.","no":"편집 창을 그냥 닫으려고 하면 저장하겠냐고 묻습니다. 저장하지 않으면 편집한 내용은 복구되지 않는다고 나옵니다. 첫 컷만 저장하고 미리보기를 열었을 때는 나머지 컷이 그림 대신 글로만 보였고, 네 컷을 모두 저장한 뒤에야 그림으로 보였습니다.","alt":["저장하지 않고 닫을 때 뜨는 확인 창"]},{"n":24,"t":"웹툰 제목 정하기","sec":5,"x":"1 / 제목 / 12자 이내로 적어요. / 2 / AI 추천 / AI가 제목을 추천해 줘요. / 3 / 확인 / 완성 화면으로 넘어가요. / TIP / AI 추천 제목이 '추천 주제: **공룡친'처럼 잘려서 나오기도 했어요. 직접 다듬어 주세요.","no":"컷 편집 단계에서 다음을 누르면 웹툰 제목 창이 뜹니다. AI 추천을 눌러 보니 글자 수 제한에 걸렸는지 제목이 어색하게 잘려 나와서, '공룡 친구 민준이'로 직접 고쳤습니다.","alt":["웹툰 제목 입력 창과 AI 추천"]},{"n":25,"t":"컷 순서 바꾸기와 한 컷 내려받기","sec":5,"x":"1 / 내리기 · 올리기 / 컷 순서를 바꿔요. / 2 / 편집 / 다시 편집 모드로 들어가요. / 3 / 다운로드 / 이 컷만 그림 파일로 받아요. / 4 / 삭제 / 컷이 4개보다 많을 때만 지울 수 있어요.","no":"완성 화면에서 컷을 한 번 누르면 아래에 메뉴가 나옵니다. 컷이 네 개뿐일 때는 최소 네 컷은 남겨야 한다는 안내와 함께 삭제가 막혀 있었습니다.","alt":["완성 화면에서 컷을 누르면 나오는 메뉴"]},{"n":26,"t":"더 그리기 · 내려받기 · 저장","sec":5,"x":"1 / 추가 컷 생성하기 / 컷을 더 만들어 이야기를 늘려요. / 2 / 공유 / 페이스북 · X · 카카오톡 · 링크 공유 / 3 / 전체 다운로드 / 웹툰 전체를 내려받아요. / 4 / 저장 / 꼭 눌러서 마이 갤러리에 남겨요. / TIP / 완성 화면 오른쪽 위에는 '인쇄' 버튼도 있어요.","no":"완성 화면 맨 아래에 이 버튼들이 있습니다. 저장을 누르면 저장이 완료되었다는 창이 뜹니다. 학생 작품은 SNS로 공유하기보다 내려받거나 클래스룸으로 모으는 편이 안전하겠다고 생각합니다.","alt":["완성 화면 아래쪽의 추가 컷, 공유, 다운로드, 저장 버튼"]},{"n":27,"t":"애니메이션은 크레딧이 필요해요","sec":5,"x":"1 / 크레딧 소진 안내 / AI 보이스나 영상을 만들려고 하면 이 창이 떠요. / 2 / 아니오 / 구매하지 말고 아니오를 눌러요. / · / 드는 크레딧(요금제 화면) / 보이스 1 · 5초 이하 영상 10 · 5초 초과 영상 20 / TIP / 10월 1일에 확인해 보니 배움터 계정의 크레딧은 0이었어요. 웹툰 완성까지는 크레딧 없이 돼요.","no":"완성 화면에서 다음을 누르면 Step 08 애니메이션 만들기가 나옵니다. 컷을 골라 대사를 AI 목소리로 읽히고 움직이는 영상으로 만드는 기능인데, 보이스를 만들어 보려 하니 크레딧이 모두 소진되었다는 창이 떴습니다. 배움터 계정에는 크레딧이 들어 있지 않아서, 연수에서는 웹툰 완성까지만 다루겠습니다. 직접 녹음하는 탭도 있었지만 마이크 권한이 필요해서 이번에는 시험해 보지 못했습니다.","alt":["크레딧이 모두 소진되었다는 안내 창"]},{"n":28,"t":"마이 갤러리에서 이어 만들기","sec":5,"x":"1 / 내 웹툰 / 누르면 마지막으로 작업한 단계에서 다시 열려요. / 2 / 설정(톱니바퀴) / 제목 · 색상 · 설명을 바꾸거나 삭제해요. / 3 / ＋ / 새 웹툰을 시작해요. / 4 / 클래스룸 / 학생 작품을 보는 곳이에요.","no":"만든 웹툰은 마이 갤러리에 카드로 남습니다. 카드를 누르니 마지막으로 보던 애니메이션 단계에서 바로 열렸습니다. 한 차시에 다 못 끝내도 다음 시간에 이어서 할 수 있겠습니다.","alt":["마이 갤러리에 저장된 웹툰 프로젝트"]},{"n":29,"t":"클래스룸: 학생의 생각 과정이 남아요","sec":6,"x":"1 / 클래스룸 / 학생 카드 → 작품을 누르면 열려요. / 2 / 누가 · 언제 / 제출한 날짜와 학생 이름이 보여요. / 3 / 질문에 쓴 답 / 꼭 넣고 싶은 내용, 질문 답, 줄거리가 그대로 남아요. / 4 / 인쇄 / 작품을 종이로 출력해요. / TIP / 지금 계정에서는 '예시 클래스룸'만 보여요. 학생 작품이 실제로 모이는지는 학생 배정 후 확인해 드릴게요.","no":"클래스룸을 누르면 예시 클래스룸이라는 안내와 함께 홍길동 학생의 예시 작품이 나옵니다. 열어 보면 학생이 답한 질문, 그림체, 줄거리, 캐릭터 설정, 시나리오, 완성 웹툰까지 순서대로 나옵니다. 결과물만이 아니라 생각한 과정을 볼 수 있다는 점이 과정 중심 평가에 쓰기 좋겠다고 보았습니다.","alt":["클래스룸에서 연 예시 학생 작품"]},{"n":30,"t":"클래스룸: 자체 평가와 수행평가 기록","sec":6,"x":"1 / 수행평가 결과 / 선생님이 피드백을 적어요. / 2 / 평가점수 / 점수를 입력해요. / 3 / 임시저장 · 저장 / 평가 내용을 저장해요. / TIP / 바로 위에는 학생이 직접 쓴 '학생 자체 평가' 칸도 함께 보여요.","no":"예시 작품의 맨 아래에는 학생 자체 평가, 그 아래에 선생님이 쓰는 수행평가 결과와 평가 점수 칸이 있습니다. 예시에는 열심히 만들었습니다, 참 잘했어요, 100점이 들어 있었습니다.","alt":["예시 작품의 수행평가 결과와 점수 입력 칸"]},{"n":31,"t":"위툰랩: 새로 나오는 실험 도구","sec":6,"x":"1 / 위툰 문집 만들기 1.0 (베타) / 학생 웹툰을 모아 학급 문집이나 학생별 만화책을 만들어요. / 2 / 분류 탭 / 수업 도구 · 문서 도구 · 콘텐츠 제작 · AI 실험실 · 신규 기능 / TIP / 위쪽 메뉴 '위툰랩'을 누르면 새 탭으로 열려요. 아직 베타라서 기능이 바뀔 수 있어요.","no":"위툰랩은 교육 현장의 불편함을 해결하려고 위툰과 연계해 만든 AI 실험 도구 모음이라고 소개되어 있습니다. 10월 1일 기준으로는 위툰 문집 만들기 1.0 하나가 베타 테스트 중이었고, 이번에는 소개 화면만 살펴보았습니다.","alt":["위툰랩 첫 화면과 위툰 문집 만들기 1.0"]},{"n":32,"t":"쓰기 전에 꼭 알아 둘 점","sec":6,"x":"배움터를 거쳐 들어가기 / 그래야 프리미엄 요금제가 적용돼요. / 애니메이션은 크레딧 / 보이스·영상은 크레딧이 필요해요. 웹툰 완성까지는 크레딧 없이 돼요. / 실명 대신 지어낸 이름 / 캐릭터 이름과 대사에 학생 실명을 넣지 않게 해요. / AI 그림은 매번 달라요 / 같은 주인공도 컷마다 조금씩 달라요. 고르고 고치는 과정도 공부가 돼요. / 기다림도 미리 안내해 주세요 / 그림이 그려지는 동안에는 새로고침하지 말고 기다려 주세요. 한 번에 30초~1분 정도 걸렸어요.","no":"마지막으로 쓰기 전에 알아 두실 점입니다. 배움터를 거쳐 들어가야 요금제가 적용되고, 애니메이션은 크레딧이 필요해서 웹툰 완성까지만 쓰시면 됩니다. 학생들이 캐릭터 이름에 친구 실명을 넣지 않도록 미리 말해 주시고, AI 그림이 매번 다르게 나온다는 점도 알려 주시면 좋겠습니다. 오히려 어떤 그림이 이야기에 더 맞는지 고르는 과정 자체가 좋은 공부가 된다고 생각합니다.","alt":[]},{"n":33,"t":"수업에 이렇게 써 보세요","sec":6,"x":"국어 · 뒷이야기 상상 / 읽은 이야기의 뒷이야기를 4컷으로 이어 그리기 / 사회 · 역사 인물 / 인물이 겪은 어려움과 해결을 4컷으로 정리하기 / 도덕 · 사회정서 / 갈등 상황과 해결 방법을 웹툰으로 표현하기 / 창체 · 학급 행사 홍보 / '홍보 / 광고' 글 종류로 행사 안내 웹툰 만들기 / 학생과 함께 쓰려면 / 배움터에서 학생 배정이 먼저 필요하고, 에듀테크 활용 개인정보 동의서(가정통신문)를 받아야 해요. 학생도 배움터 → 위툰으로 접속해요.","no":"이야기 쓰기 단계에서 AI가 질문을 던져 주기 때문에, 국어의 뒷이야기 상상하기나 사회의 역사 인물 정리처럼 생각을 정리하는 활동과 잘 맞는다고 생각합니다. 예시 클래스룸에 들어 있던 작품도 홍길동전을 4컷으로 정리한 것이었습니다. 학생과 함께 쓰실 분은 학생 배정과 개인정보 동의서가 먼저 필요하니 말씀해 주세요.","alt":[]},{"n":34,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 계정 · 학생 배정 설정 / 교사 계정 생성부터 학생 배정까지 함께 처리해 드려요. / 도구 활용법 안내 / 수업에 맞는 활용법을 교실로 찾아가 알려 드려요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 만들어 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 계정 설정과 학생 배정은 교실로 찾아가 함께 처리해 드리겠습니다.","alt":[]}],"offs":[[0,66832],[66832,49300],[116132,61136],[177268,63150],[240418,74876],[315294,49542],[364836,53082],[417918,41560],[459478,54204],[513682,55458],[569140,51806],[620946,81798],[702744,47672],[750416,57610],[808026,61568],[869594,65064],[934658,71880],[1006538,81742],[1088280,76942],[1165222,77004],[1242226,82080],[1324306,86966],[1411272,66098],[1477370,45920],[1523290,71768],[1595058,54054],[1649112,68820],[1717932,50798],[1768730,61366],[1830096,54706],[1884802,89738],[1974540,58982],[2033522,59252],[2092774,41638]],"toffs":[[0,6166],[6166,4072],[10238,5350],[15588,5016],[20604,7354],[27958,4156],[32114,5464],[37578,3208],[40786,4256],[45042,4338],[49380,4260],[53640,6788],[60428,4170],[64598,5130],[69728,4236],[73964,4490],[78454,5680],[84134,7266],[91400,6966],[98366,7768],[106134,7930],[114064,8090],[122154,5332],[127486,4284],[131770,7112],[138882,5056],[143938,5834],[149772,4418],[154190,5072],[159262,4992],[164254,7144],[171398,4662],[176060,4620],[180680,3980]],"packSize":2134412,"thumbSize":184660},{"key":"quizn","name":"퀴즈앤","title":"퀴즈앤 사용 안내서","group":"quiz","sub":"경북AI배움터로 접속해 실시간 퀴즈 수업 만들기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"배움터로 들어가면 경상북도교육청 이용권이 적용되어 'PRO 이용중'으로 보여요. 이용 기간 2026. 7. 24. ~ 2027. 2. 28.(My Show 화면 표시)","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 퀴즈앤과 경북 이용권 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 퀴즈앤에 접속하고 My Show를 살펴봐요"},{"start":6,"num":"2","label":"Show 만들기","desc":"Show를 만들고 선택형·OX형·초성퀴즈 문제를 입력해요"},{"start":13,"num":"3","label":"빠르게 만들기","desc":"AI 퀴즈, 문제 가져오기, 엑셀로 빠르게 만들어요"},{"start":18,"num":"4","label":"실시간 Play","desc":"실시간 Play를 열고 학생 참여부터 랭킹까지 진행해요"},{"start":29,"num":"5","label":"Mission","desc":"Mission으로 기간을 정해 과제로 내요"},{"start":33,"num":"6","label":"결과와 활용","desc":"Reports로 결과를 보고 찾아보기와 유의사항, 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"퀴즈앤","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 실시간 퀴즈 수업 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 퀴즈앤을 함께 써 보겠습니다. 퀴즈앤은 선생님이 만든 퀴즈를 아이들이 PIN 번호로 들어와 함께 푸는 도구입니다. 화면 속 문제도 연수를 준비하면서 직접 만들어 진행해 본 것입니다.","alt":["퀴즈앤 실시간 Play 진행 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 퀴즈앤, My Show / 04–05쪽 / STEP 2 / Show 만들기 / 기본 설정, 문제 유형, 문제 입력 / 06–12쪽 / STEP 3 / 빠르게 만들기 / AI 퀴즈, 문제 가져오기, 엑셀 / 13–17쪽 / STEP 4 / 실시간 Play / 진행 방식, 학생 참여, 결과 공개 / 18–28쪽 / STEP 5 / Mission / 기간을 정해 과제로 내기 / 29–32쪽 / STEP 6 / 결과와 활용 / Reports, 찾아보기, 유의사항 / 33–39쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 Show 만들기와 4단계 실시간 Play만 꼭 해 보세요. 4단계에서는 선생님들 휴대폰으로 직접 참여해 보시겠습니다.","alt":[]},{"n":3,"t":"퀴즈앤으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 퀴즈 Show 만들기 / 선택형 · OX · 초성퀴즈 등 문제 유형 10가지 / 실시간 퀴즈 대결 / 개인전 · 팀전 · 골든벨 / Mission(과제) / 정해진 기간에 각자 풀기 / 결과 리포트 / 문항별 정답률, 엑셀 다운로드 / 경북 교원 혜택 / 배움터로 접속하면 'PRO 이용중' / 경상북도교육청 이용권으로 Play 250명, Mission 2,000명, Board 250명까지 참여할 수 있어요. / 이용 기간: 2026. 7. 24. ~ 2027. 2. 28. (My Show 화면 왼쪽 위에 표시)","no":"퀴즈앤은 문제를 만들고, 실시간으로 함께 풀거나 과제로 내고, 결과를 확인하는 흐름으로 씁니다. 배움터를 거쳐 들어가면 경상북도교육청 이용권이 적용되어 Play 화면에 PRO 이용중이라고 표시됩니다. 참여 인원과 이용 기간은 My Show 화면 왼쪽 위에서 확인할 수 있습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 퀴즈앤 열기","sec":1,"x":"1 / 에듀테크 서비스 → 퀴즈앤 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 퀴즈앤이 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 따로 회원가입하거나 비밀번호를 넣지 않아도 돼요. 배움터 로그인 한 번이면 충분해요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 에듀테크 서비스에서 퀴즈앤을 누르면 새 탭이 열리면서 자동으로 로그인됩니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록과 퀴즈앤 설명"]},{"n":5,"t":"접속하면 처음 보이는 화면 (My Show)","sec":1,"x":"1 / 경상북도교육청 이용권 / 이용 기간과 Play · Mission · Board 참여 인원이 보여요. / 2 / 왼쪽 메뉴 / My Show(내 퀴즈), Reports(결과) 등을 오가요. / 3 / Show 만들기 / 첫 퀴즈 Show를 만들어요. / 4 / 만들기 · 찾아보기 / 새로 만들거나 다른 선생님 Show를 찾아봐요. / TIP / Show는 퀴즈 문제 묶음이에요. 한 Show 안에 여러 문제를 담아요.","no":"처음 들어오면 My Show 화면이 열립니다. 왼쪽 위에 경상북도교육청 이용권과 참여 인원이 보이는지 먼저 확인해 주세요. 아이디 부분은 개인정보라 흐리게 처리했습니다.","alt":["퀴즈앤 My Show 첫 화면"]},{"n":6,"t":"만들기 → Show","sec":2,"x":"1 / 만들기 / 위쪽 메뉴의 만들기를 눌러요. / 2 / Show / 퀴즈 문제 묶음을 만들어요. My Show의 Show 만들기 버튼과 같아요. / · / Board · Video · Class 등 / 보드, 영상, 수업 묶음도 만들 수 있어요. 오늘은 Show만 다뤄요.","no":"만들기 메뉴에는 Show 말고도 Board, Video, Class 같은 메뉴가 있습니다. 오늘은 퀴즈 Show에 집중하고, 다른 기능은 필요하실 때 따로 안내해 드리겠습니다.","alt":["만들기 메뉴 펼친 화면"]},{"n":7,"t":"Show 기본 설정","sec":2,"x":"1 / Show 제목 / 내 목록에서 찾기 쉽게 써요. / 2 / 태그 / 쉼표(,)로 구분해 2개 이상 꼭 넣어야 해요. / 3 / 공개 / 비공개 / 공개로 두면 다른 사용자에게 Show가 공유돼요. / 4 / 등록 / 문제 편집 화면으로 넘어가요. / · / 대표 이미지 / 창 위쪽에서 기본 이미지를 고르거나 내 이미지를 올려요. / TIP / 학생 사진이나 이름이 들어가는 Show는 비공개로 두세요.","no":"태그는 쉼표로 구분해 두 개 이상 넣어야 한다고 안내되어 있습니다. 실습에서는 연수, 가을 두 개를 넣었습니다. 공개로 두면 다른 선생님들이 검색해서 쓸 수 있습니다.","alt":["Show 기본 설정 창"]},{"n":8,"t":"문제 편집 화면 둘러보기","sec":2,"x":"1 / 문제 목록 / 만든 문제가 1P, 2P… 순서로 쌓여요. / 2 / Type / 문제 유형 10가지 가운데 하나를 골라요. / 3 / + Page · + Quiz · + Excel · + AI / 새 문제 추가 · 다른 Show 문제 가져오기 · 엑셀 업로드 · AI 출제 / 4 / Preview · OK · Play / 미리보기 · 저장하고 완료 · 바로 진행 / TIP / + Page는 빈 문제를, + Quiz는 다른 Show의 문제를 불러와요.","no":"편집 화면은 왼쪽 문제 목록, 가운데 미리보기, 오른쪽 설정으로 나뉩니다. 아래쪽 버튼 네 개는 3단계에서 자세히 보겠습니다.","alt":["Show 문제 편집 화면"]},{"n":9,"t":"문제 유형 10가지","sec":2,"x":"오늘 실습 / 선택형 / 최대 4지선다 객관식 / 오늘 실습 / OX형 / O, X로 푸는 간단한 문제 / 단답형 / 짧은 주관식 (15글자 이내) / 순서완성형 / 순서에 맞게 골라 완성 / 오늘 실습 / 초성퀴즈 / 자음 힌트로 맞히기 / 토론 / 서술형으로 자유롭게 의견 나누기 / 설문 / 정답 없이 선택 결과 모으기 / 영상 / 수업과 관련된 영상 넣기 / Word Cloud / 의견을 모아 워드클라우드로 / 설명 / 풀이나 다음 문제 힌트 안내 / 유형 설명: 퀴즈앤 소개 자료 기준","no":"편집 화면 오른쪽 Type에서 고르는 유형입니다. 오늘은 선택형, OX형, 초성퀴즈를 직접 만들어 보겠습니다. 토론, 설문, Word Cloud는 정답이 없는 유형이라 의견을 모을 때 쓰기 좋습니다.","alt":[]},{"n":10,"t":"선택형 문제 만들기","sec":2,"x":"1 / Question / 문제를 입력해요. (최대 75자) / 2 / Media / 이미지 · 영상 · 오디오를 붙일 수 있어요. / 3 / Answer / 보기를 쓰고, 왼쪽 체크로 정답을 표시해요. / TIP / 가운데 미리보기가 바로 안 바뀌면 왼쪽 문제 카드를 한 번 눌러 보세요.","no":"Type에서 선택형을 누르면 오른쪽에 입력 칸이 나옵니다. 보기 네 개를 쓰고 정답 보기 왼쪽 체크를 눌러 주세요. 실습 때 미리보기가 늦게 바뀌었는데, 왼쪽 문제 카드를 누르니 반영됐습니다.","alt":["선택형 문제 입력 화면"]},{"n":11,"t":"시간 · 점수 정하고 저장하기","sec":2,"x":"1 / Comment / 선생님용 메모예요. 진행 화면에는 보이지 않아요. / 2 / 시간제한 / 기본 20초예요. 문제마다 바꿀 수 있어요. / 3 / 점수 사용 · 점수 X2 / 중요한 문제는 점수를 두 배로 줄 수 있어요. / 4 / 저장 / 문제마다 꼭 눌러요. '저장되었습니다'가 떠요. / TIP / 정답 해설을 보여 주고 싶다면 다음 문제로 '설명' 유형을 넣어요.","no":"오른쪽 설정 창을 맨 아래까지 내리면 옵션과 저장 버튼이 있습니다. 저장을 누르지 않고 다른 문제로 가면 입력한 내용이 남지 않을 수 있으니 문제마다 저장해 주세요.","alt":["문제 옵션과 저장 버튼"]},{"n":12,"t":"OX형과 초성퀴즈","sec":2,"x":"위 · OX형 / 1 / Question / 문장으로 문제를 써요. / 2 / 정답 체크 / O나 X 왼쪽 칸에 체크해요. / 아래 · 초성퀴즈 / 1 / 초성 / 띄어서 입력해요. 예) ㅊ ㅅ / 2 / 정답 / 정답 낱말을 써요. (최대 15글자) / 3 / 미리보기 / 초성이 카드로 보여요. / TIP / 문제 카드의 빨간 ! 표시는 아직 완성되지 않은 문제예요.","no":"+ Page로 새 문제를 추가한 뒤 Type만 바꾸면 됩니다. OX형은 정답에 체크만, 초성퀴즈는 초성과 정답을 따로 씁니다. 저장하면 왼쪽 카드의 빨간 느낌표가 사라집니다.","alt":["OX형 입력 화면","초성퀴즈 입력 화면"]},{"n":13,"t":"+ AI로 문제 만들기","sec":3,"x":"1 / AI 퀴즈 생성 / 주제를 적어 새 문제를 만들어요. 옆 탭은 AI 퀴즈 추천이에요. / 2 / 어떤 퀴즈를 만들까요? / 학년, 주제, 범위를 300자 이내로 적어요. / 3 / 구분 · 유형 / 구분: 초등학교~전문분야 유형: 선택형 · OX형 · 단답형 / 4 / 생성하기 / 한 번에 최대 5문제까지 만들어 줘요. / TIP / '초등학교 4학년 ○○ 단원'처럼 학년과 단원을 구체적으로 쓸수록 좋아요.","no":"편집 화면 아래 + AI를 누르면 이 창이 열립니다. 실습에서는 초등학교 3~4학년이 가을의 날씨, 단풍, 추석 풍습을 알아보는 퀴즈를 요청했습니다.","alt":["AI 퀴즈 생성 창"]},{"n":14,"t":"AI가 만든 문제 골라 담기","sec":3,"x":"1 / + (퀴즈 가져오기) / 마음에 드는 문제만 하나씩 내 Show에 넣어요. / 2 / 정답 확인 / 주황색 동그라미가 AI가 고른 정답이에요. / 3 / 편집하기 / 요청 내용을 고쳐 다시 만들 수 있어요. / 꼭 검토하세요 / 실습 때 AI가 '추석의 대표 놀이' 정답을 윷놀이로 냈어요. 이런 문제는 빼고 가져왔어요. AI 문제는 꼭 한 번씩 검토해 주세요.","no":"AI가 다섯 문제를 만들어 줬는데, 그중 추석 놀이 문제는 정답이 윷놀이로 되어 있었습니다. 윷놀이는 설날에 더 많이 하는 놀이라 빼고 나머지 문제만 가져왔습니다. AI가 만든 문제는 그대로 쓰지 말고 꼭 검토해 주세요.","alt":["AI가 생성한 퀴즈 목록"]},{"n":15,"t":"+ Quiz로 다른 Show 문제 가져오기","sec":3,"x":"1 / 검색 / 주제어로 공개된 Show를 찾아요. / 2 / Show 오른쪽 + / 그 Show의 문제를 전부 복사해요. / 3 / 문제 오른쪽 + / 필요한 문제 하나만 가져와요. / TIP / 가져온 문제도 우리 반 수업에 맞는지 한 번씩 확인해요.","no":"+ Quiz를 누르면 Quiz List 창이 열립니다. 다른 선생님이 공개한 Show를 검색해서 전체를 복사하거나 문제 하나만 골라 가져올 수 있습니다. 화면 속 다른 사용자 아이디는 흐리게 처리했습니다.","alt":["Quiz List 검색 결과와 미리보기"]},{"n":16,"t":"+ Excel로 한꺼번에 올리기","sec":3,"x":"1 / 다운로드 / 퀴즈앤 엑셀 템플릿을 받아요. / 2 / 파일 선택 / 템플릿에 문제를 채워 .xlsx로 저장한 뒤 골라요. (1MB 이하) / 3 / 확인 / 파일을 올려요. / TIP / 한글이나 엑셀로 만들어 둔 문제가 많을 때 편해요.","no":"이미 만들어 둔 문제가 많다면 엑셀 템플릿에 붙여 넣어 한 번에 올리는 방법이 빠릅니다. 꼭 내려받은 템플릿 양식에 맞춰 작성해 주세요.","alt":["엑셀 업로드 창"]},{"n":17,"t":"OK를 눌러 Show 완성하기","sec":3,"x":"1 / Show 미리보기 / 진행 화면을 미리 확인해요. / 2 / 공유하기 / Show를 다른 사람과 나눠요. / 3 / 확인 / My Show로 돌아가요. 여기서 Play 또는 Mission을 시작해요. / TIP / 편집 화면 오른쪽 아래 OK를 누르면 이 창이 떠요. 다시 고치려면 편집하기를 눌러요.","no":"OK를 누르면 Show 만들기가 완료되었다는 창이 뜹니다. 확인을 누르면 My Show로 돌아가고, 방금 만든 Show 카드가 보입니다.","alt":["Show 만들기 완료 창"]},{"n":18,"t":"My Show에서 Play 시작하기","sec":4,"x":"1 / Show 카드 아래 버튼 / 왼쪽부터 Play(실시간) · Mission(과제) · 편집 / 2 / 오른쪽 미리보기 창 / 같은 Play · Mission 버튼이 있고, 문제 목록도 미리 볼 수 있어요. / TIP / Show 카드를 누르면 오른쪽 창에 그 Show의 문제가 펼쳐져요.","no":"만든 Show는 My Show에 카드로 쌓입니다. 보라색 재생 버튼이 실시간 Play, 주황색 버튼이 Mission입니다.","alt":["My Show의 Show 카드와 미리보기 창"]},{"n":19,"t":"진행 방식 고르기","sec":4,"x":"1 / 개인전 / 한 사람씩 점수를 겨뤄요. / 2 / 팀전 / 팀을 나눠 단체로 겨뤄요. / 3 / 골든벨 / 서바이벌 방식으로 진행해요. / 4 / 참여가능인원 / 경북 이용권으로 250명 (PRO 이용중) / TIP / 오늘 실습은 개인전으로 해 보겠습니다.","no":"Play를 누르면 진행 방식을 고르는 화면이 나옵니다. 단원 정리 때는 골든벨, 모둠 활동 뒤에는 팀전처럼 상황에 맞게 고르시면 됩니다.","alt":["Play 진행 방식 선택 화면"]},{"n":20,"t":"Play 옵션 정하기","sec":4,"x":"1 / 실시간 현장 Play / 한 교실에서 선생님 화면(TV)을 보며 풀어요. / 2 / 실시간 원격 Play / 각자 다른 곳에서 자기 화면으로 풀어요. / 3 / 세부 옵션 / 랭킹 화면 비노출 · 답변 노출 · 배경음악 · 닉네임 비밀번호 · 제출하기 버튼 · 다음 화면 자동 이동 / 4 / Play / 참여 대기 화면이 열려요. / TIP / 현장 Play에서 학생 화면에는 보기 글자 없이 색깔만 나와요. 글자도 보이게 하려면 '답변 노출'을 켜요.","no":"교실에서 함께 할 때는 실시간 현장 Play를 고릅니다. 배경음악은 기본으로 켜져 있으니 교실 상황에 맞게 조절해 주세요.","alt":["Play 옵션 설정 화면"]},{"n":21,"t":"학생들에게 PIN 알려 주기","sec":4,"x":"1 / quizn.show/p / 학생은 이 주소로 들어와요. / 2 / QR code · URL copy / QR을 크게 띄우거나 주소를 복사해 보내요. / 3 / PIN / 7자리 번호를 넣으면 참여돼요. / TIP / 학생은 회원가입이나 로그인 없이 PIN과 닉네임만으로 들어와요.","no":"이 화면을 교실 TV에 띄워 두면 됩니다. 휴대폰이나 태블릿 브라우저에서 quizn.show/p에 들어가 PIN을 넣으면 참여됩니다. 지금 선생님들도 휴대폰으로 함께 들어와 보세요.","alt":["PIN 번호가 보이는 참여 대기 화면"]},{"n":22,"t":"학생 화면: PIN → 닉네임","sec":4,"x":"위 · PIN 입력 / 1 / PIN번호 입력 / 선생님 화면의 번호를 넣어요. / 2 / 확인 / 아래 · 닉네임 입력 / 1 / 닉네임 / 순위 화면에 보일 이름이에요. / 2 / 확인 / 입장 완료! 선생님이 시작할 때까지 기다려요. / TIP / 닉네임은 '번호+이름'처럼 정해 주면 결과 정리가 쉬워요.","no":"학생 화면은 두 단계면 끝납니다. PIN을 넣고, 닉네임을 정하면 입장합니다. 닉네임은 순위 화면에 그대로 보이니 미리 규칙을 정해 주시면 좋습니다.","alt":["학생 PIN 입력 화면","학생 닉네임 입력 화면"]},{"n":23,"t":"참여자가 모이면 시작","sec":4,"x":"1 / 총 참여자수 / 들어온 인원이 보여요. / 2 / 참여자 닉네임 / 들어온 학생의 닉네임이 차례로 떠요. / 3 / 시작 / 모두 들어오면 눌러요. / TIP / 화면이 바로 바뀌지 않으면 새로고침(F5) 해 보세요. 실습 때 한 번 있었어요.","no":"학생이 들어오면 닉네임이 이렇게 보입니다. 실습 때 참여자가 늦게 표시된 적이 있었는데, 새로고침하니 바로 나타났습니다.","alt":["참여자 닉네임이 보이는 대기 화면"]},{"n":24,"t":"선생님 화면(TV): 문제 진행","sec":4,"x":"1 / 남은 시간 / 설정한 시간(기본 20초)이 줄어들어요. / 2 / 응답 수 / 몇 명이 답했는지 보여요. (예: 1/1) / 3 / 보기 / 번호와 색깔로 보기가 나와요. / TIP / 학생들은 이 화면을 보며 자기 기기에서 같은 색깔을 눌러요.","no":"시작하면 문제 번호와 유형이 먼저 나오고, 곧 문제와 보기가 뜹니다. 응답 수로 아직 답하지 않은 학생이 있는지 알 수 있습니다.","alt":["실시간 Play 문제 진행 화면"]},{"n":25,"t":"학생 화면: 색깔 버튼 누르기","sec":4,"x":"1 / 보기 버튼 / TV에서 본 번호 · 색깔과 같은 버튼을 눌러요. / 2 / 점수 / 닉네임 / 오른쪽 위에 내 점수와 닉네임이 보여요. / TIP / 답을 누르면 '정답을 확인하는 중…' 화면이 뜨고, 시간이 끝나면 결과가 나와요.","no":"현장 Play에서는 학생 화면에 보기 글자가 없고 색깔과 번호만 나옵니다. 그래서 TV 화면을 함께 봐야 합니다. 글자도 보이게 하려면 Play 옵션에서 답변 노출을 켜면 됩니다.","alt":["학생 기기의 보기 버튼 화면"]},{"n":26,"t":"정답 공개와 참여현황","sec":4,"x":"1 / 정답과 선택 인원 / 보기별로 몇 명이 골랐는지 막대로 보여요. / 2 / 참여현황 / 미제출 · 정답 · 오답 학생을 따로 볼 수 있어요. / 3 / 다음 / 순위 화면을 거쳐 다음 문제로 넘어가요. / TIP / 순위 화면의 '누적 랭킹'을 누르면 지금까지의 총점도 볼 수 있어요.","no":"시간이 끝나면 정답과 선택 인원이 나옵니다. 오답이 많은 문제는 여기서 잠깐 멈추고 설명하고 넘어가시면 좋습니다.","alt":["정답과 보기별 선택 인원 화면"]},{"n":27,"t":"학생 화면: 바로 받는 피드백","sec":4,"x":"위 · 맞혔을 때 / · / '참 잘했어요!' / 이번 문제 점수와 누적 점수(score)가 보여요. / 아래 · 틀리거나 시간이 지났을 때 / · / '포기하지 말고 끝까지 풀어보세요!' / 0점과 함께 격려 문구가 나와요. / TIP / 빨리 맞힐수록 점수가 높아요. 실습에서는 같은 정답도 걸린 시간에 따라 496~757점으로 달랐어요.","no":"문제마다 학생 화면에 바로 결과가 나옵니다. 점수는 빨리 맞힐수록 높아서 아이들이 집중하는 데 도움이 됩니다. 실습 때 초성퀴즈는 입력하는 사이 시간이 끝나 0점이 나왔습니다. 주관식은 시간을 넉넉히 주시는 것이 좋습니다.","alt":["정답일 때 학생 화면","오답일 때 학생 화면"]},{"n":28,"t":"마지막: Show 랭킹","sec":4,"x":"1 / 화면 캡쳐 / 시상 화면을 이미지로 남겨요. / 2 / 랭킹 더 보기 / 전체 순위를 봐요. / 3 / 다음 / 종료 화면을 거쳐 My Show로 돌아가요. / TIP / 결과는 Reports에 자동으로 남아요. 따로 저장하지 않아도 돼요.","no":"마지막 문제가 끝나면 1, 2, 3위 시상 화면이 나옵니다. 순위가 부담스러운 반이라면 Play 옵션에서 랭킹 화면 비노출을 켜 두실 수 있습니다.","alt":["Show 랭킹 시상 화면"]},{"n":29,"t":"Mission: 기간을 정해 과제로 내기","sec":5,"x":"1 / 미션명 입력 / 학생에게 보일 과제 이름이에요. / 2 / 기간 선택 / 이 기간에만 참여할 수 있어요. / 3 / 닉네임 안내문구 / 학생 닉네임 입력 화면에 그대로 떠요. 예) 번호와 이름으로 입력해 주세요. / · / 사용가능인원 2,000명 / Play보다 훨씬 많은 인원이 참여할 수 있어요. / TIP / My Show에서 Show의 Mission 버튼을 누르면 이 화면이 열려요.","no":"Mission은 실시간이 아니라 정해진 기간 동안 각자 푸는 방식입니다. 과제나 복습용으로 쓰기 좋습니다. 닉네임 안내문구를 적어 두면 학생들이 이름을 통일해서 입력해 결과 정리가 편합니다.","alt":["Mission 옵션 설정 화면 위쪽"]},{"n":30,"t":"Mission 옵션","sec":5,"x":"1 / 로그인 필요 / 끄면 닉네임만으로, 켜면 로그인해야 참여해요. / 2 / 제한시간 해제 / 켜면 시간 제한 없이 풀어요. / 3 / 재도전 사용 / 다시 풀 수 있어요. 이전 기록은 지워져요. / 4 / 만들기 / Mission이 만들어지고 공유 창이 떠요. / · / 그 밖의 옵션 / 정답 화면 비노출 · 닉네임 비밀번호 · 랭킹 화면 비노출 / TIP / 집에서 천천히 풀게 하려면 '제한시간 해제'를 켜 보세요.","no":"옵션은 모두 꺼진 상태가 기본입니다. 과제로 낼 때는 제한시간 해제, 연습용으로 여러 번 풀게 할 때는 재도전 사용을 켜 보세요.","alt":["Mission 세부 옵션과 만들기 버튼"]},{"n":31,"t":"Mission 공유하기","sec":5,"x":"1 / URL 공유 / 주소를 복사해 학급 알림장 등에 올려요. / 2 / PIN 공유 / 학생은 quizn.show/p에서 번호로 들어와요. / 3 / 구글 클래스룸에 공유 / 클래스룸 과제로 바로 보낼 수 있어요. / 4 / QR코드 저장 / 학습지나 칠판에 붙여 쓰기 좋아요. / TIP / PIN과 주소는 나중에 My Show 공유나 Reports에서 다시 볼 수 있어요.","no":"만들기를 누르면 공유 창이 뜹니다. 위쪽에 진행 기간이 다시 한번 나오니 확인해 주세요.","alt":["Mission 공유 창"]},{"n":32,"t":"학생 화면: 각자 속도로 풀기","sec":5,"x":"위 · 닉네임 입력 / · / 선생님이 쓴 안내문구 / 닉네임 입력 칸 위에 그대로 보여요. / 아래 · 문제 풀기 / 1 / 점수 / 닉네임 / 오른쪽 위에 내 점수가 쌓여요. / 2 / 문제와 보기 / 학생 화면에 바로 나오고, 누르면 정답이 표시돼요. / TIP / 실시간 Play와 달리 TV 화면 없이 학생 기기만으로 풀어요.","no":"Mission은 학생 화면에 문제와 보기가 모두 나옵니다. 그래서 집에서도 혼자 풀 수 있습니다. 화면 속 7 김가을은 실습용으로 만든 닉네임입니다.","alt":["Mission 닉네임 입력 화면","Mission 문제 풀이 화면"]},{"n":33,"t":"Reports에서 결과 찾기","sec":6,"x":"위 · 왼쪽 메뉴 / 1 / Reports / Show 진행결과 · Show 참여결과 등이 들어 있어요. / 아래 · Show 진행결과 / 1 / 전체 · Play · Mission / 진행 방식별로 골라 봐요. / 2 / 진행한 Show 목록 / 날짜, 문제 수, 걸린 시간, 참여 인원이 보여요. / TIP / Play 기록과 Mission 기록이 모두 여기 모여요.","no":"왼쪽 메뉴를 조금 내리면 Reports가 있습니다. Show 진행결과에 들어가면 지금까지 진행한 Play와 Mission이 날짜순으로 쌓여 있습니다.","alt":["왼쪽 메뉴의 Reports","Show 진행결과 목록"]},{"n":34,"t":"결과 펼쳐 보기: 랭킹","sec":6,"x":"1 / 랭킹 · 정답현황 · 종합현황 / 세 가지 탭으로 결과를 봐요. / 2 / 순위 · 정답률 · 점수 / 학생별로 한 줄씩 보여요. / 3 / ⋮ 메뉴 / 플레이 접속 · 엑셀 다운로드 · 삭제 / TIP / 목록에서 Show 제목을 누르면 이렇게 펼쳐져요.","no":"진행 결과를 누르면 아래로 펼쳐집니다. 첫 탭 랭킹에서는 학생별 정답률과 점수를 볼 수 있습니다.","alt":["Show 진행결과 랭킹 탭"]},{"n":35,"t":"정답현황: 문항별로 보기","sec":6,"x":"1 / 보기별 선택 인원과 비율 / 어느 보기에 답이 몰렸는지 보여요. / 2 / 자세히 보기 / 문항을 더 자세히 봐요. / TIP / 오답이 몰린 보기는 아이들이 헷갈리는 개념이에요. 다음 시간 도입에 다시 다뤄 보세요.","no":"정답현황 탭에서는 문항마다 보기별 선택 비율이 나옵니다. 오답이 많이 몰린 문항을 찾아 다음 시간에 다시 짚어 주시면 좋습니다.","alt":["문항별 정답현황"]},{"n":36,"t":"종합현황과 엑셀 다운로드","sec":6,"x":"위 · 종합현황 / 1 / 정답률 · 평균점수 / 전체 정답률과 평균점수를 한눈에 / 2 / 학생별 문항 결과 / 문항마다 O · X와 점수 / 걸린 시간 / 3 / 맞힌 문항 수 / 예) 4 / 6 / 아래 · ⋮ 메뉴 / 1 / 엑셀 다운로드 / 결과를 파일로 받아요. / TIP / 엑셀로 받아 형성평가 기록에 활용할 수 있어요.","no":"종합현황에서는 학생별로 어느 문항을 맞히고 틀렸는지, 몇 초 만에 답했는지까지 나옵니다. 오른쪽 위 점 세 개 메뉴에서 엑셀로 내려받을 수 있습니다.","alt":["종합현황 탭","⋮ 메뉴의 엑셀 다운로드"]},{"n":37,"t":"찾아보기: 다른 선생님 Show 쓰기","sec":6,"x":"1 / 검색 / 단원명으로 찾아요. 예) 분수의 나눗셈 / 2 / ⋮ 메뉴 / Show Detail · 공유 · 복사 · 미리보기 · 풀어보기 / 3 / Play · Mission / 오른쪽 창에서 바로 진행할 수 있어요. / TIP / 고쳐 쓰고 싶으면 '복사'로 내 Show에 가져와 편집해요.","no":"위쪽 찾아보기에서 Show를 고르면 다른 선생님이 공개한 Show를 검색할 수 있습니다. 6학년 분수의 나눗셈만 검색해도 여러 개가 나옵니다. 화면 속 다른 사용자 아이디는 흐리게 처리했습니다.","alt":["찾아보기 검색 결과와 메뉴"]},{"n":38,"t":"꼭 알아 둘 점","sec":6,"x":"이용 기간과 인원 / 2027. 2. 28.까지 Play 250명 · Mission 2,000명 · Board 250명 / 공개 설정 / 공개 Show는 다른 사용자에게 공유돼요. 학생 정보가 들어가면 비공개로. / 학생 닉네임 / 로그인 없이 닉네임으로 들어와요. 실명보다 번호 위주로 정해 주세요. / AI 문제 검토 / AI가 고른 정답이 틀릴 수 있어요. 가져오기 전에 꼭 확인해요. / 문제마다 저장 / 빨간 ! 표시는 아직 완성되지 않은 문제예요. / 앱 설치 없이 / 학생은 브라우저에서 quizn.show/p로 들어와요.","no":"이용 기간과 인원은 My Show 왼쪽 위 표시를 기준으로 했습니다. 학생은 회원가입 없이 닉네임으로 참여하기 때문에 닉네임 규칙을 미리 정해 주시면 개인정보 걱정도 줄고 결과 정리도 편합니다.","alt":[]},{"n":39,"t":"수업에 이렇게 써 보세요","sec":6,"x":"수업 도입 복습 / 지난 차시 OX 다섯 문제를 개인전으로 짧게 / 단원 정리 골든벨 / 단원 끝에 골든벨 모드로 서바이벌 / 과제로 Mission / 기간 · 재도전을 정해 집에서 풀기 / 생각 모으기 / Word Cloud · 설문 · 토론 유형으로 의견 나누기 / 만든 Show는 계속 다시 쓸 수 있어요 / 한 번 만든 Show는 다른 반에서 다시 Play하거나 Mission으로 바꿔 낼 수 있어요. 결과는 Reports → 엑셀 다운로드로 모아 두세요.","no":"오늘 해 본 기능만으로도 수업 도입 복습, 단원 정리 골든벨, 과제, 의견 모으기까지 할 수 있습니다. 처음에는 OX 다섯 문제 정도로 가볍게 시작해 보시기를 권해 드립니다.","alt":[]},{"n":40,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 Show 같이 만들기 / 단원에 맞는 문제를 함께 만들어 드려요. / 첫 Play 함께 진행 / 교실 TV로 처음 진행할 때 옆에서 도와드려요. / 결과 정리 도움 / Reports와 엑셀 다운로드를 함께 확인해요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 Show를 만들거나 처음 Play를 진행하실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,38618],[38618,48958],[87576,59780],[147356,60358],[207714,68258],[275972,55970],[331942,62754],[394696,63496],[458192,54962],[513154,56396],[569550,60992],[630542,70682],[701224,63868],[765092,63842],[828934,70012],[898946,54466],[953412,58788],[1012200,57642],[1069842,72828],[1142670,93676],[1236346,63188],[1299534,60820],[1360354,60006],[1420360,57664],[1478024,38602],[1516626,54766],[1571392,58596],[1629988,54458],[1684446,87308],[1771754,86034],[1857788,68430],[1926218,66934],[1993152,68952],[2062104,54944],[2117048,50456],[2167504,78662],[2246166,64412],[2310578,56238],[2366816,54514],[2421330,38392]],"toffs":[[0,3312],[3312,3886],[7198,5038],[12236,4670],[16906,5542],[22448,4392],[26840,5194],[32034,5174],[37208,4074],[41282,4214],[45496,5216],[50712,5190],[55902,4810],[60712,4864],[65576,5436],[71012,4522],[75534,4940],[80474,4302],[84776,5864],[90640,6788],[97428,5550],[102978,5172],[108150,5358],[113508,4938],[118446,3496],[121942,4690],[126632,4152],[130784,4456],[135240,7108],[142348,6966],[149314,5494],[154808,5524],[160332,4886],[165218,4302],[169520,4098],[173618,5626],[179244,5236],[184480,3966],[188446,4376],[192822,3832]],"packSize":2459722,"thumbSize":196654},{"key":"zepquiz","name":"젭 퀴즈","title":"젭 퀴즈 사용 안내서","group":"quiz","sub":"경북AI배움터로 접속해 메타버스 맵에서 퀴즈 풀기","fee":"무료 범위 · 공모 선정자 유료","feeKind":"part","feeNote":"배움터 공모로 선정된 선생님께는 유료 이용권이 나가요(배움터 공지 2026. 4. 20.). 연수는 Free 플랜 기준이라 번개 표시 없는 기능만 써요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 젭 퀴즈로 할 수 있는 일과 배움터 계정 안내"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 젭 퀴즈에 접속하고 첫 화면과 플랜을 확인해요"},{"start":7,"num":"2","label":"퀴즈 만들기","desc":"맵을 고르고 AI와 직접 입력으로 문제를 만든 뒤 설정을 마쳐요"},{"start":21,"num":"3","label":"수업 열기","desc":"퀴즈에 입장해 코드를 나누고 학생 입장과 수업 메뉴를 다뤄요"},{"start":27,"num":"4","label":"학생 활동","desc":"학생 화면에서 문제를 풀고 힌트, 정답 확인, 아바타를 살펴봐요"},{"start":30,"num":"5","label":"결과 보기","desc":"선생님 화면과 학습 리포트로 결과를 확인해요"},{"start":33,"num":"6","label":"더 알아보기","desc":"플래시카드, 자료실, 내 퀴즈와 유의사항, 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"젭 퀴즈","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 메타버스 맵에서 퀴즈 풀기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 젭 퀴즈를 함께 써 보겠습니다. 젭 퀴즈는 선생님이 만든 문제를 아이들이 게임 맵 속에서 아바타로 돌아다니며 푸는 도구입니다. 화면 속 퀴즈도 연수를 준비하면서 직접 만들고 학생 역할로 풀어 본 것입니다.","alt":["젭 퀴즈 운동장 맵에서 학생 아바타가 축구공 문제 옆에 있는 선생님 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 젭 퀴즈, Free 플랜 확인 / 04–06쪽 / STEP 2 / 퀴즈 만들기 / 맵 고르기, AI·직접 입력, 설정 / 07–20쪽 / STEP 3 / 수업 열기 / 입장 코드, 닉네임, 수업 메뉴 / 21–26쪽 / STEP 4 / 학생 활동 / 문제 풀기, 힌트, 아바타 / 27–29쪽 / STEP 5 / 결과 보기 / 선생님 화면, 학습 리포트 / 30–32쪽 / STEP 6 / 더 알아보기 / 자료실, 유의사항, 수업 활용 / 33–38쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 퀴즈 만들기와 3·4단계 수업 열기, 학생 활동만 꼭 해 보세요. 3단계에서는 선생님들 휴대폰이나 노트북으로 직접 입장해 학생 역할을 해 보시겠습니다.","alt":[]},{"n":3,"t":"젭 퀴즈로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 맵에서 푸는 퀴즈 / 아바타로 돌아다니며 숨은 문제 찾아 풀기 / 퀴즈 만들기 / 선택형 · 단답형 · OX · 서술형 QUIZ AI로 빠르게 / 수업 진행 / 입장 코드, 닉네임 관리, 시간 제한 · 얼음 모드 / 결과 확인 / 학생별 정답률 · 소요 시간 문항별 맞음 · 틀림 / 배움터로 접속하면 / 교육청 계정으로 자동 로그인 · Free 플랜 / 학생은 로그인 없이 입장 코드로 들어와요. 한 맵에 200명까지 함께 접속할 수 있어요. / 번개 표시가 붙은 기능은 유료(Basic · Pro)예요. 2026. 10. 2. 연수 준비 때 확인","no":"젭 퀴즈는 문제를 만들고, 그 문제를 게임 맵에 올려 아이들이 아바타로 돌아다니며 풀고, 결과를 확인하는 흐름으로 씁니다. 퀴즈앤과 달리 배움터로 들어가도 교육청 이용권은 보이지 않았고, 무료인 Free 플랜으로 표시되었습니다. 그래서 오늘은 Free 플랜에서 되는 기능 위주로 안내하고, 번개 표시가 붙은 유료 기능은 그때그때 짚어 드리겠습니다. 동시 접속 200명은 젭 퀴즈 자주 묻는 질문의 안내를 기준으로 했습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 젭 퀴즈 열기","sec":1,"x":"1 / 에듀테크 서비스 → 젭 퀴즈 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 젭 퀴즈가 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 계정은 '배움터 아이디@aiep.gbe.kr'로 만들어져요. 따로 회원가입하지 않아도 돼요.","no":"배움터 주소는 aischool.gbe.kr입니다. 에듀테크 서비스 목록 첫 화면에 젭 퀴즈가 보이지 않으면 아래 화살표로 넘겨 보세요. 누르면 새 탭에서 젭 퀴즈 자료실이 열리고, 배움터 계정으로 바로 로그인됩니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록과 젭 퀴즈 설명"]},{"n":5,"t":"첫 화면 둘러보기","sec":1,"x":"1 / 퀴즈 자료실 / 다른 선생님들이 공개한 퀴즈 / 2 / 내 퀴즈 / 내가 만든 퀴즈가 쌓이는 곳 / 3 / 검색창 / 퀴즈 제목이나 만든 사람으로 찾기 / 4 / 코드로 입장 / 입장 코드를 넣고 퀴즈에 들어가기 / 5 / + 만들기 / 퀴즈 만들기 · 보드 만들기 / TIP / 처음 들어가면 안내 창이 여러 개 떠요. X로 닫으면 돼요.","no":"젭 퀴즈를 열면 퀴즈 자료실이 먼저 나옵니다. 젤리 이벤트, Pro 체험 안내 같은 창이 연달아 뜨는데 모두 닫고 시작하시면 됩니다. 화면 속 다른 선생님 이름은 흐리게 처리했습니다.","alt":["젭 퀴즈 첫 화면인 퀴즈 자료실"]},{"n":6,"t":"내 플랜 확인하기: Free","sec":1,"x":"초록 번개 = Basic / 자료실에서 숨기기, 짝맞추기 · 순서맞추기, Basic 맵 / 파란 번개 = Pro / 학습 리포트 · 문제별 통계, AI 학습 도우미, Pro 맵 / 1 / FREE 플랜 이용 중 / 오른쪽 위 프로필을 누르면 보여요. / 2 / Free 이용 중 / 기간 제한 없이 기본 기능을 써요. / 3 / 플랜 보기 / Basic · Pro 기능을 비교해 볼 수 있어요. / TIP / 상세 프로필에서 휴대폰 인증과 마케팅 수신 동의를 하면 Pro 2주 체험권을 준다고 안내돼요.","no":"연수를 준비한 2026년 10월 2일에 배움터로 들어간 계정은 Free 플랜이었고, 이용권 보관함도 비어 있었습니다. 젭 퀴즈 화면에서 초록 번개는 Basic, 파란 번개는 Pro 기능이라는 뜻입니다. 오늘은 번개 표시가 없는 기능만으로 수업을 꾸려 보겠습니다. Pro 2주 체험은 첫 화면 안내 창의 문구를 기준으로 했고, 개인 휴대폰 인증이 필요하니 필요한 분만 선택하시면 됩니다.","alt":["플랜 관리 화면의 Free 이용 중 표시와 프로필 메뉴"]},{"n":7,"t":"+ 만들기 → 퀴즈 만들기 → 퀴즈맵 고르기","sec":2,"x":"1 / 맵 종류 / 순서 풀이 · 자유 풀이 · 라운드전 · 팀전 · 협동전 / 2 / 추천 · 무료 · Basic · Pro / '무료'를 누르면 바로 쓸 수 있는 맵만 보여요. / 3 / 무료 맵 5개 / 번개 표시가 없는 맵은 Free에서 바로 써요. / 4 / 맵 설명 · 체험하기 / 맵을 누르면 진행 방식이 오른쪽에 나와요. / 5 / 이 맵으로 퀴즈 만들기 / TIP / 맵은 나중에 설정의 '맵 변경'으로 바꿀 수 있어요.","no":"오른쪽 위 + 만들기에서 퀴즈 만들기를 누르면 먼저 퀴즈맵을 고릅니다. Free 계정은 무료 맵 다섯 개를 바로 쓸 수 있고, 번개 표시가 붙은 맵은 유료입니다. 오늘은 운동장 맵으로 만들어 보겠습니다.","alt":["퀴즈맵 선택 창의 맵 종류, 무료 맵 목록과 맵 설명"]},{"n":8,"t":"무료 맵 5가지, 이렇게 달라요","sec":2,"x":"오늘 실습 / 자유 풀이 / 운동장 / 곳곳에 숨은 문제를 원하는 순서로 찾아 풀어요. / 순서 풀이 / 마녀의 마법 / 주어진 순서대로 풀어야 끝까지 갈 수 있어요. / 라운드전 / 피크닉 동산 / 모두 같은 문제를 동시에 풀고, 탈락 없이 끝까지 참여해요. / 팀전 / 가을운동회 / 제한 시간 안에 더 많이 푼 팀이 이겨요. (3명 이상) / 협동전 / 우리 반 달콤 점수 / 제한 시간 동안 다 함께 점수를 모아 공동 목표를 이뤄요. / 수업 목적에 맞게 골라 보세요 / 혼자 복습할 때는 자유 풀이 · 순서 풀이, 다 같이 한 문제씩 짚을 때는 라운드전이 잘 맞아요. / 맵 설명: 젭 퀴즈 퀴즈맵 선택 화면 기준","no":"맵마다 문제를 푸는 방식이 다릅니다. 운동장과 마녀의 마법은 아이들이 각자 속도로 푸는 맵이고, 피크닉 동산은 모두가 같은 문제를 동시에 푸는 맵입니다. 가을운동회와 우리 반 달콤 점수는 팀이나 반 전체가 함께 점수를 모으는 맵입니다. 설명은 퀴즈맵 선택 화면에 나온 문구를 옮겼습니다.","alt":[]},{"n":9,"t":"학년과 과목 고르기","sec":2,"x":"1 / 학교급 · 학년 · 학기 / 초등 → 5학년 → 2학기 / 2 / 과목 / 창의적 체험활동 → 계기교육처럼 세부 분류도 있어요. / 3 / 고른 분류 / 퀴즈 제목 자리에 먼저 들어가요. / 4 / 학교급 선택 완료 / '다음에도 사용'에 체크하면 다음 퀴즈에도 그대로 쓰여요. / TIP / 자료실의 과목 · 학년 필터와 같은 분류예요. 제목은 설정에서 바꿔요.","no":"맵을 고르면 학교급, 학년, 학기, 과목을 차례로 고릅니다. 이번에는 한글날을 앞두고 초등 5학년 2학기 계기교육으로 골랐습니다. 고른 분류가 퀴즈 제목 자리에 먼저 들어가니, 제목은 나중에 설정 화면에서 바꿔 주세요.","alt":["추가 정보 입력 창에서 초등 5학년 2학기 계기교육을 고른 화면"]},{"n":10,"t":"어떤 방법으로 만들까요?","sec":2,"x":"1 / 직접 만들기 · 오늘 실습 / 처음부터 내가 문제를 써요. / 2 / 문제 은행으로 만들기 / 다른 선생님이 쓴 문제를 골라 가져와요. / TIP / '직접 만들기'를 골라도 다음 화면에서 QUIZ AI와 문제 은행을 함께 쓸 수 있어요.","no":"분류를 고르면 만드는 방법을 묻습니다. 직접 만들기를 고르면 편집 화면으로 들어가는데, 그 화면에서도 AI 출제와 문제 은행 가져오기를 함께 쓸 수 있어서 오늘은 직접 만들기로 진행하겠습니다.","alt":["직접 만들기와 문제 은행으로 만들기 중 고르는 창"]},{"n":11,"t":"문제를 넣는 세 가지 길","sec":2,"x":"1 / QUIZ AI / 주제 입력, 파일 · 유튜브 · 웹사이트에서 문제 뽑기 / 2 / 문제 은행에서 가져오기 / 다른 선생님 문제 골라 담기 (Beta) / 3 / 직접 만들기 / 선택형 · 단답형 · OX · 서술형 (짝맞추기 · 순서맞추기는 Basic) / 4 / 0 / 20 / 지금까지 만든 문제 수 (최대 20개로 표시) / TIP / 파일 추출은 pdf · csv · txt · docx · pptx · hwp 파일을 받아요.","no":"빈 편집 화면입니다. 위에서부터 AI로 만들기, 문제 은행에서 가져오기, 직접 만들기 순서로 놓여 있습니다. 유튜브 추출은 자막이 있는 2시간 이하 영상, 웹사이트 추출은 본문이 있는 주소를 넣으라고 안내되어 있습니다. 짝맞추기와 순서맞추기에는 초록 번개가 붙어 있어 Basic 플랜 기능입니다.","alt":["빈 편집 화면의 QUIZ AI, 문제 은행, 직접 만들기 버튼"]},{"n":12,"t":"QUIZ AI에게 주제 말하기","sec":2,"x":"1 / 추천 요청 / 고른 학년 · 과목에 맞춘 문장을 눌러도 돼요. / 2 / 원하는 퀴즈 입력 / 예) 한글날 계기교육 퀴즈를 만들어 줘. 초등 5학년 수준으로 OX 2문제, 선택형 3문제 / 3 / 무료 채팅 10회 / 보내기 버튼 옆에 남은 횟수가 보여요. / TIP / 주제 · 학년 · 문제 유형 · 개수를 한 문장에 담으면 원하는 퀴즈에 가까워져요.","no":"QUIZ AI의 주제 직접 입력을 누르면 오른쪽에 대화창이 열립니다. 연수를 준비할 때 Free 계정에서 무료 채팅 10회 남음으로 표시되었고, 한 번 보내니 9회로 줄었습니다. 횟수가 정해져 있으니 요청은 한 번에 자세히 쓰는 편이 좋습니다.","alt":["QUIZ AI 대화창에 한글날 퀴즈 요청을 입력한 화면"]},{"n":13,"t":"AI가 만든 문제 받아 보기","sec":2,"x":"1 / 문제 5개 생성 / 왼쪽 편집 화면에 바로 들어가요. / 2 / 요청과 다른 구성 / OX 2 · 선택형 3을 부탁했는데 선택형 2 · OX 3으로 나왔어요. / 3 / 이어서 요청 / 오류 고치기 · 비슷한 문제 더 · 난이도 낮추기 / 4 / 남은 횟수 9회 / 꼭 확인 / AI가 만든 문제는 개수 · 유형 · 정답 · 문장을 다시 살펴봐요.","no":"요청을 보내고 10초쯤 지나자 문제 다섯 개가 편집 화면에 들어왔습니다. 그런데 OX 2문제, 선택형 3문제를 부탁했는데 선택형 2문제, OX 3문제로 나왔습니다. 대화창 아래 버튼으로 이어서 고쳐 달라고 할 수도 있지만, 무료 채팅 횟수가 줄어드니 간단한 것은 직접 고치는 편이 빠릅니다.","alt":["AI가 만든 한글날 문제 5개와 대화창의 요약, 이어서 요청 버튼"]},{"n":14,"t":"AI 문제, 이렇게 고쳤어요","sec":2,"x":"AI가 낸 문제 (정답 X) / 훈민정음은 세종대왕이 혼자서 모든 글자를 만들고 완성하여 즉시 백성들에게 배포하였다. / '혼자서'와 '즉시 배포'가 섞여 무엇 때문에 X인지 헷갈려요. / 고친 문제 (정답 X) / 훈민정음은 만들어진 해(1443년)에 바로 백성들에게 반포되었다. / 1 / 문제 칸을 눌러 바로 고치기 / 2 / O · X 가운데 정답 누르기 / 3 / 필요하면 힌트 추가","no":"AI가 낸 4번 문제는 한 문장에 '세종대왕이 혼자서 만들었다'와 '만들자마자 배포했다'가 함께 들어 있었습니다. 혼자 만들었는지는 학계에서도 해석이 갈리는 부분이라, 아이들이 무엇 때문에 X인지 헷갈릴 수 있다고 보았습니다. 그래서 창제(1443년)와 반포(1446년)의 차이만 묻도록 고쳤습니다. 문제 칸을 누르면 바로 글자를 고칠 수 있고, 아래에서 O와 X 가운데 정답을 누르면 됩니다.","alt":["고친 OX 문제와 정답 X가 선택된 편집 화면"]},{"n":15,"t":"편집 화면 둘러보기","sec":2,"x":"1 / 문제 목록 / 누르면 그 문제로 이동해요. / 2 / QUIZ AI · 문제 은행 / 문제를 만든 뒤에도 위에 그대로 있어요. / 3 / 유형 도구 / 선택형 · 단답형 · OX · 서술형 추가 / 4 / 문제 · 설정 탭 / 5 / 이어서 작성 · 다음으로 / AI 대화창 다시 열기 · 다음 단계 / TIP / 저장은 자동이에요. 새 문제는 골라 둔 문제 바로 뒤에 들어가요.","no":"AI 대화창을 접으면 편집 화면 전체가 보입니다. 왼쪽은 문제 목록, 가운데는 문제 카드, 오른쪽은 문제 유형을 더하는 도구입니다. 위쪽에 저장 중이라는 표시가 있어 따로 저장 버튼을 누르지 않아도 됩니다. 4번 문제를 골라 둔 채 선택형을 더했더니 5번 자리에 들어갔습니다.","alt":["문제 목록, QUIZ AI, 오른쪽 유형 도구가 있는 편집 화면"]},{"n":16,"t":"선택형 문제 직접 만들기","sec":2,"x":"1 / 질문 입력 / 훈민정음을 반포한 해는? / 2 / 보기 1~4 / 왼쪽 동그라미가 정답 표시예요. / 3 / 보기 섞기 / 보기 순서를 섞어요. / 4 / 힌트 추가 / 텍스트 · 이미지 · 유튜브 / 5 / 정답 체크 주의 / 정답이 여러 개 체크돼요. 처음 켜진 1번을 꼭 꺼요. / 6 / 힌트 입력 / 학생 화면의 '힌트' 버튼에 나와요.","no":"오른쪽 도구에서 선택형을 누르면 빈 문제 카드가 생깁니다. 새 카드는 1번 보기가 정답으로 켜져 있습니다. 3번 보기를 정답으로 누르면 1번이 꺼지는 게 아니라 두 개가 함께 정답이 되니, 처음 켜진 1번을 꼭 다시 눌러 꺼 주세요. 힌트는 '만든 해(1443년)와 반포한 해는 달라요'로 넣었습니다.","alt":["빈 선택형 문제 카드","1446년이 정답으로 체크되고 힌트가 들어간 선택형 문제"]},{"n":17,"t":"단답형 문제 만들기","sec":2,"x":"1 / 질문 / 답 쓰는 형식을 예시로 알려 줘요. / 2 / 정답 / 10월 9일 / 3 / 유사 정답 / 띄어쓰기만 다른 답: 10월9일 / 4 / 유사 정답 추가 / 정답으로 인정할 답을 더 넣어요. / TIP / 아이들이 쓸 만한 다른 표기를 미리 유사 정답으로 넣어 두세요.","no":"단답형은 학생이 답을 직접 씁니다. 질문에 '예: 1월 1일'처럼 쓰는 형식을 넣어 주면 답이 덜 흩어집니다. 띄어쓰기를 빼고 쓰는 아이도 있으니 유사 정답 추가로 10월9일도 함께 넣었습니다.","alt":["정답 10월 9일과 유사 정답 10월9일을 넣은 단답형 문제"]},{"n":18,"t":"설정 탭 ① 기본 정보와 문제 설정","sec":2,"x":"1 / 맵 변경 / 문제는 그대로 두고 맵만 바꿔요. / 2 / 퀴즈 제목 / '[연수 실습] 한글날 퀴즈'로 바꿨어요. / 3 / 분류 변경 / 학년 · 과목을 다시 골라요. / 4 / 틀려도 통과 허용 / 켜 두면 틀려도 다음 문제로 넘어가요. (처음부터 켜져 있음) / 5 / 정답 보여주기 / 보여주지 않기 · 틀렸을 때만 보여주기 · 항상 보여주기 / TIP / '틀렸을 때만 보여주기'로 두면 틀린 문제의 정답을 바로 확인하며 배워요.","no":"위쪽 설정 탭을 누르면 퀴즈 전체 설정이 나옵니다. 처음에는 분류 이름이 제목으로 들어가 있으니 알아보기 쉬운 제목으로 바꿔 주세요. 정답 보여주기는 처음에 보여주지 않기로 되어 있는데, 오늘은 틀렸을 때만 보여주기로 바꿨습니다.","alt":["설정 탭의 맵 변경, 제목, 분류, 틀려도 통과 허용, 정답 보여주기"]},{"n":19,"t":"설정 탭 ② 학습 도구와 공개 범위","sec":2,"x":"1 / AI 학습 도구 / 파란 번개: Pro / 2 / 학습 자료 추가 / 퀴즈 전에 자료 보여주기 / 3 / 자료실에서 숨기기 / 초록 번개: Basic / 4 / 누르면 업그레이드 안내 / 주의 / Free에서 만든 퀴즈는 자료실에 공개돼요. 학생 이름 · 사진은 넣지 마세요.","no":"설정 탭 아래쪽에는 AI 학습 도우미, AI 문제 언어 번역, 다음 퀴즈 이어풀기, 자료실에서 숨기기가 있습니다. 모두 번개 표시가 붙어 있어 Free 계정에서는 켜지지 않고, 누르면 플랜 업그레이드 안내가 뜹니다. 특히 자료실에서 숨기기를 못 쓰기 때문에 Free 계정으로 만든 퀴즈는 모두 공개 퀴즈가 됩니다. 문제에 학생 이름이나 사진을 넣지 않도록 해 주세요.","alt":["설정 탭의 학습 도구와 고급 항목, 번개 표시","자료실에서 숨기기를 누르면 뜨는 플랜 업그레이드 안내"]},{"n":20,"t":"만들기 완료! 퀴즈 페이지","sec":2,"x":"1 / 퀴즈 정보 / 분류 · 제목 · 만든 사람 · 플레이 수 / 2 / 설정 요약 / 오답 허용 · 틀렸을 때 정답 표시 · 공개 퀴즈 / 3 / 퀴즈 입장하기 / 수업을 여는 버튼이에요. / 4 / 플래시카드 · 워크시트 · 클래스 연결 / 5 / 퀴즈 관리 / 학습 리포트 · 입장 공유 · 복사 · 수정 / TIP / 설정 탭 오른쪽 위 '만들기 완료'를 누르면 이 화면이 나와요.","no":"만들기 완료를 누르면 퀴즈 페이지로 넘어갑니다. 왼쪽에는 문제가 차례로 보이고, 오른쪽에는 수업을 여는 퀴즈 입장하기와 관리 버튼이 모여 있습니다. 공개 퀴즈라는 표시도 여기서 확인할 수 있습니다. 워크시트 저장은 요금 안내에 Pro 기능으로 적혀 있었습니다.","alt":["완성된 한글날 퀴즈 페이지와 오른쪽 버튼들"]},{"n":21,"t":"퀴즈 입장하기 → 선생님 화면","sec":3,"x":"1 / 수업 메뉴 / 시작 · 대기실 · 시간 제한 · 얼음 모드 / 2 / 학습 리포트 / 새 탭에서 학생별 결과 / 3 / 젤리 주기 · 퀴즈 랭킹 · 참여 인원 / 4 / 공유 / 입장 코드 · QR · 링크 / 5 / 축구공 = 문제 / 주황 화살표가 붙은 공마다 문제가 하나씩 있어요. / TIP / 선생님 화면을 TV에 띄우면 아이들 아바타가 움직이는 모습이 보여요.","no":"퀴즈 입장하기를 누르면 운동장 맵이 열리고, 선생님 아바타가 아래쪽 대기 공간에 섭니다. 운동장 안의 축구공 일곱 개가 각각 문제입니다. 왼쪽 위에는 수업 메뉴와 학습 리포트, 오른쪽 위에는 젤리 주기, 퀴즈 랭킹, 참여 인원이 있습니다.","alt":["운동장 맵의 선생님 화면과 왼쪽 위 수업 메뉴, 오른쪽 위 버튼들"]},{"n":22,"t":"공유 → 입장 코드 나누기","sec":3,"x":"1 / 입장 코드 / 7자리 숫자를 칠판이나 TV에 띄워요. / 2 / QR 코드 / 태블릿 카메라로 찍어 바로 들어와요. / 3 / 링크 복사 / 클래스룸 · 메신저에 붙여 넣어요. / 학생이 들어가는 주소 / quiz.zep.us/join / TIP / 같은 퀴즈는 입장 코드가 그대로예요. 퀴즈 페이지의 '입장 공유'에서도 같은 코드가 나와요.","no":"오른쪽 위 공유를 누르면 입장 코드 창이 뜹니다. 연수용 퀴즈의 입장 코드는 2267936입니다. 지금 선생님들 휴대폰으로 quiz.zep.us/join에 들어가 이 코드를 넣어 보시겠습니다. QR 코드를 찍어도 같은 곳으로 들어갑니다.","alt":["입장 코드 2267936, QR 코드, 링크 복사가 있는 창"]},{"n":23,"t":"학생 화면: 코드만 넣으면 입장","sec":3,"x":"1 / 입장 코드 / quiz.zep.us/join에서 7자리 입력 / 2 / 입장 / 로그인 없이 바로 맵에 들어가요. / 3 / 푼 문제 / 0/7처럼 진행 상황이 보여요. / 4 / 학생 버튼 / 내 아바타 · 퀴즈 랭킹 · 참여 인원 / 5 / 축구공 문제 / 가까이 가면 문제 창이 열려요. / 6 / 자동 닉네임 / '파랑새'처럼 무작위로 정해져요. 다음 장에서 바꿔요.","no":"학생은 회원가입이나 로그인 없이 입장 코드만 넣으면 바로 맵에 들어옵니다. 따로 닉네임을 묻지 않고 파랑새처럼 무작위 이름이 붙었습니다. 그래서 수업 전에 닉네임 규칙을 정하고 다음 장의 닉네임 변경 요청을 함께 쓰시기를 권합니다.","alt":["학생 입장 코드 입력 화면","입장한 학생의 맵 화면과 무작위 닉네임"]},{"n":24,"t":"참여 인원 → 설정: 닉네임 정리하기","sec":3,"x":"1 / 닉네임 모두 숨기기 / 맵에서 이름을 가려요. / 2 / 닉네임 변경 잠금 / 정한 이름을 학생이 못 바꿔요. / 3 / 전원 변경 요청 / 모든 학생에게 설정 창이 떠요. / 4 / 학생 화면 / '닉네임을 변경해 주세요'에 새 이름 입력 / 5 / 확인 / 바뀐 이름이 참여 인원 · 리포트에 나와요. / TIP / '번호 + 별명'으로 정하고, 바꾼 뒤엔 변경 잠금!","no":"참여 인원 창 오른쪽 위 톱니바퀴를 누르면 닉네임 설정이 나옵니다. 전원 닉네임 변경 요청을 보내면 학생 화면에 바로 닉네임 변경 창이 뜹니다. 01번 한글이처럼 번호를 앞에 붙이게 하면 리포트에서 번호 순으로 보기 편합니다. 모두 바꾼 뒤에는 변경 잠금을 켜 주세요.","alt":["참여 인원 설정 창의 닉네임 모두 숨기기, 변경 잠금, 전원 변경 요청","학생 화면에 뜬 닉네임 변경 창에 01번 한글이를 입력한 모습"]},{"n":25,"t":"학생 한 명씩 살피기","sec":3,"x":"1 / 학생 줄의 ⋮ 버튼 / 참여 인원 창에서 학생마다 있어요. 이름 아래에 '시작 전', '자리 비움' 같은 상태도 보여요. / 2 / 학생별 메뉴 / 젤리 주기 / 위치 보기 / 위치로 이동 / 닉네임 강제 변경 / 닉네임 변경 요청 / 얼리기 / TIP / 헤매는 학생은 '위치 보기'로 찾고, 장난스러운 닉네임은 '닉네임 강제 변경'으로 바로 고쳐요.","no":"참여 인원 창에서 학생 이름 오른쪽 점 세 개를 누르면 그 학생만 다루는 메뉴가 나옵니다. 젤리 주기, 위치 보기, 위치로 이동, 닉네임 강제 변경, 닉네임 변경 요청, 얼리기가 있습니다. 메뉴 이름은 화면 그대로 옮겼고, 하나씩 눌러 보며 익히시면 됩니다.","alt":["참여 인원 목록에서 학생 옆 더보기 메뉴를 연 모습"]},{"n":26,"t":"수업 메뉴로 진행하기","sec":3,"x":"1 / 수업 진행 / 다 함께 시작 · 대기실 닫기 · 이동 · 시간 제한 모드(기본 5분) · 얼음 모드 / 2 / 닉네임 관리 안내 / '참여 인원 › 설정'으로 옮겨졌어요. / 3 / 퀴즈 설정 / 다시 풀기 · 다시 풀 때 순서 섞기 · 랭킹 표시 · 아바타 강조 / 4 / 다 함께 시작 / 모두 시작 위치로 모여요. 풀이 기록과 랭킹은 남아요.","no":"왼쪽 위 수업 메뉴에 진행 도구가 모여 있습니다. 아이들이 다 들어오면 다 함께 시작을 눌러 모두를 시작 위치로 모읍니다. 시간 제한 모드는 처음에 5분으로 잡혀 있고, 얼음 모드를 켜면 아이들 움직임을 잠시 멈출 수 있습니다. 다시 풀기와 랭킹 표시는 처음부터 켜져 있었습니다.","alt":["수업 메뉴의 수업 진행과 퀴즈 설정 항목","다 함께 시작 확인 창"]},{"n":27,"t":"공 가까이 가면 문제가 열려요","sec":4,"x":"1 / 문제 번호 / 2 / 보기 고르기 / 3 / 제출하기 / 4 / 푼 문제 0/7 / 5 / 맞힘 알림 / '좋은 출발이에요!' 맞힌 문제 수 / 6 / 1/7로 늘어나요 / 진행 막대도 함께 차요. / 7 / 열린 자물쇠 / 푼 공은 자물쇠로 바뀌어요. / TIP / PC는 방향키로 아바타를 움직여요.","no":"학생 역할로 방향키를 눌러 운동장 안의 축구공 가까이 가 보았습니다. 공에 닿으니 문제 창이 저절로 열렸고, 보기를 고르고 제출하자 위쪽에 '좋은 출발이에요!'가 떴습니다. 푼 공은 열린 자물쇠로 바뀌고, 왼쪽 위 푼 문제 수가 1/7로 늘었습니다.","alt":["학생 화면에 열린 문제 1 창","정답을 맞힌 뒤 좋은 출발이에요 알림과 열린 자물쇠"]},{"n":28,"t":"힌트 보기와 틀렸을 때","sec":4,"x":"1 / 힌트 버튼 / 힌트를 넣은 문제에만 보여요. 보고 나서 문제로 돌아가요. / 2 / 틀림 알림 / '아직 기회가 많아요' / 3 / 내 답 · 정답 / 고른 답은 빨강, 정답은 초록으로 보여요. / 4 / 자동으로 닫힘 / 몇 초 뒤 창이 닫혀요.","no":"직접 만든 5번 문제에는 힌트를 넣어 두어서 문제 창에 힌트 버튼이 보였습니다. 일부러 1443년을 골라 틀려 보니 '아직 기회가 많아요'가 뜨고, 고른 답과 정답이 함께 표시되었습니다. 설정에서 '틀렸을 때만 보여주기'를 골라 두었기 때문입니다. 창은 몇 초 뒤 저절로 닫히고, 틀려도 통과 허용이 켜져 있어 다음 공으로 넘어갈 수 있습니다.","alt":["힌트 버튼이 있는 문제 5 창","힌트 창: 만든 해(1443년)와 반포한 해는 달라요","틀린 답과 정답이 함께 표시된 문제 창"]},{"n":29,"t":"아바타 꾸미기와 젤리 칭찬","sec":4,"x":"1 / 꾸미기 분류 / 피부 · 의상 · 헤어 · 얼굴 · 악세사리 · 이펙트 / 2 / 무료 · 젤리 아이템 / 젤리 개수가 적힌 것은 젤리로 사요. / 3 / 젤리 요청 안내 / '선생님께 젤리를 요청해 보세요!' / 4 / 칭찬 내용 / 예) 수업에 적극적으로 참여했어요 / 5 / 젤리 수 1~5 / 6 / 학생 선택 / 코드로만 들어온 학생은 '로그인이 필요해요' / 7 / 내 무료 젤리 / 선생님 계정에 100개 / TIP / 무료 아이템만으로도 꾸밀 수 있어요.","no":"학생은 내 아바타 버튼으로 아바타를 꾸밉니다. 무료 아이템도 있고, 젤리가 있어야 하는 아이템도 있습니다. 선생님 계정에는 무료 젤리 100개가 있어 칭찬으로 나눠 줄 수 있습니다. 다만 코드로만 들어온 학생 옆에는 '로그인이 필요해요'가 떠서, 젤리를 주려면 학생 로그인이 있어야 하는 것으로 보입니다.","alt":["학생 화면의 아바타 꾸미기 창","선생님 화면의 젤리 주기 창"]},{"n":30,"t":"선생님 화면에서 바로 보기","sec":5,"x":"1 / 학생 아바타 / 누가 어느 공 앞에 있는지 보여요. / 2 / 퀴즈 랭킹 / 문제를 다 푼 학생부터 순위가 나와요. / 3 / 학습 리포트 / 새 탭에서 학생별 통계가 열려요. / TIP / 아직 다 푼 학생이 없으면 랭킹에 '아직 문제를 다 푼 학생이 없어요'가 떠요.","no":"학생 역할로 두 문제를 푸는 동안 선생님 화면에서도 학생 아바타가 어디 있는지 그대로 보였습니다. 퀴즈 랭킹은 일곱 문제를 모두 푼 학생부터 순위가 나오는데, 연수 준비 때는 끝까지 푼 학생이 없어 빈 화면이었습니다. 자세한 결과는 왼쪽 위 학습 리포트에서 봅니다.","alt":["선생님 화면에 보이는 학생 아바타와 퀴즈 랭킹, 학습 리포트 버튼"]},{"n":31,"t":"학습 리포트 → 학생별 통계","sec":5,"x":"Free에서 열리는 메뉴 / 학생별 통계 / 학생마다 정답률 · 시간 · 문제별 결과 / Pro 메뉴 / 학습 리포트 · 문제별 통계 / AI 학습 도우미도 Pro예요. / 1 / 정답률 · 총 소요 시간 / 14% (1/7) · 1분 33초 / 2 / 문제별 결과 / 맞음 · 틀림 표시와 걸린 시간 / 3 / 학습 현황 / 학생 한 명의 자세한 기록 (다음 장) / 4 / 기록 다운로드 / 결과를 파일로 받아 둘 때","no":"학습 리포트 버튼을 누르면 새 탭에서 학생별 통계가 열립니다. 학생 역할로 두 문제를 풀어 1번은 맞히고 5번은 일부러 틀렸더니 정답률 14퍼센트, 1/7로 나왔습니다. 왼쪽 메뉴 가운데 학생별 통계만 Free에서 열리고, 학습 리포트와 문제별 통계, AI 학습 도우미에는 Pro 표시가 붙어 있습니다.","alt":["학생별 통계 표: 01번 한글이 정답률 14퍼센트, 1분 33초, 문제 1 맞음, 문제 5 틀림"]},{"n":32,"t":"학생 한 명의 학습 현황","sec":5,"x":"1 / 정답률 · 진행률 · 소요 시간 / 정답률은 맞힌 문제(1/7), 진행률은 푼 문제(2/7) 기준 / 2 / 문항별 한눈에 보기 / 1~7번 맞음 · 틀림 · 안 푼 문제 / 3 / 학생이 제출한 답 / 어떤 보기를 골랐는지 문제 아래에 나와요. / TIP / 틀린 학생이 어떤 보기를 골랐는지 보면 다음 수업에서 짚을 곳이 보여요.","no":"학생별 통계에서 이름 옆 학습 현황을 누르면 그 학생의 기록이 한 창에 모입니다. 두 문제를 풀고 한 문제를 맞혔기 때문에 진행률은 29퍼센트, 정답률은 14퍼센트로 나왔습니다. 문제마다 학생이 제출한 답이 함께 보여서, 어떤 오답을 골랐는지 확인하기 좋습니다.","alt":["01번 한글이의 학습 현황: 정답률, 진행률, 소요 시간, 문항별 결과와 제출한 답"]},{"n":33,"t":"플래시카드로 혼자 복습하기","sec":6,"x":"1 / 문제 카드 / Space 키를 누르면 카드가 뒤집혀요. / 2 / 모름 · 알고 있음 / 키보드 왼쪽 · 오른쪽 화살표로도 골라요. / 3 / 진행 상황 / 모름 · 알고 있음 개수와 1/7 같은 순서 / TIP / 퀴즈 페이지의 '플래시카드'(New)에서 열려요. 맵에 들어가기 전에 혼자 훑어보는 복습용으로 좋아요.","no":"퀴즈 페이지에 새로 생긴 플래시카드를 누르면 만든 문제가 카드 한 장씩 나옵니다. 화면 아래 안내대로 Space 키로 뒤집고, 왼쪽 화살표는 모름, 오른쪽 화살표는 알고 있음입니다. 아이들이 혼자 복습할 때 쓰기 좋은 기능입니다.","alt":["한글날 퀴즈 문제가 카드로 나온 플래시카드 화면"]},{"n":34,"t":"퀴즈 자료실에서 찾아 쓰기","sec":6,"x":"1 / 검색 / '한글날'로 1,172개가 나왔어요. (10월 2일) / 2 / 필터 / 과목 · 학년 · 학기 · 교과서 출판사 / 3 / 문제 수 · 플레이 · 복사 / 많이 쓰인 퀴즈를 고를 때 참고해요. / TIP / 위쪽 '초등'을 눌러 학교급을 바꿀 수 있어요.","no":"퀴즈 자료실에는 다른 선생님들이 공개한 퀴즈가 많습니다. 한글날로 검색하니 1,172개가 나왔습니다. 카드 아래 숫자는 차례로 문제 수, 플레이 수, 복사 수입니다. 직접 만들 시간이 없을 때는 여기서 찾아 쓰는 것도 방법입니다. 화면 속 만든 사람 이름은 흐리게 처리했습니다.","alt":["퀴즈 자료실에서 한글날로 검색한 결과"]},{"n":35,"t":"자료실 퀴즈 가져오기 전에","sec":6,"x":"1 / 프리미엄 맵 퀴즈 / 썸네일에 번개 표시가 있어요. / 2 / 내 퀴즈로 복사 / 내 퀴즈로 가져와 고쳐 써요. / 3 / 퀴즈 체험하기 / 학생처럼 먼저 풀어 봐요. / 주의 / 상위 플랜 맵으로 만든 퀴즈는 하위 플랜에서 고칠 수 없다고 안내돼요. Free는 번개 없는 퀴즈부터!","no":"자료실에서 인기 있는 한글날 퀴즈를 열어 보니 '프리미엄 맵으로 제작된 퀴즈'라는 안내가 붙어 있었습니다. 젭 퀴즈 자주 묻는 질문에는 상위 플랜 맵으로 만든 퀴즈를 하위 플랜 사용자가 수정할 수 없다고 적혀 있습니다. Free 계정에서는 썸네일에 번개 표시가 없는 퀴즈를 골라 복사하시는 편이 안전합니다.","alt":["프리미엄 맵으로 제작된 자료실 퀴즈 페이지와 내 퀴즈로 복사 버튼"]},{"n":36,"t":"내 퀴즈에서 다시 쓰기","sec":6,"x":"1 / 내 퀴즈 / 왼쪽 메뉴에서 열어요. / 2 / 내가 만든 퀴즈 / 문제 수와 플레이 수가 보여요. / 3 / 더보기 메뉴 / 입장 · 공유 · 복사 · 수정 · 학습 리포트 · 삭제 / TIP / 반마다 결과를 따로 보고 싶으면 '복사'해서 반 이름을 붙여 쓰세요.","no":"만든 퀴즈는 내 퀴즈에 쌓입니다. 점 세 개 메뉴에서 바로 입장하거나 공유, 복사, 수정, 학습 리포트, 삭제를 할 수 있습니다. 한 퀴즈를 여러 반에서 쓰면 결과가 한 리포트에 모이니, 반별로 따로 보고 싶을 때는 복사해서 반 이름을 붙여 쓰시면 됩니다. 화면 속 계정 주소는 흐리게 처리했습니다.","alt":["내 퀴즈 목록과 퀴즈 더보기 메뉴"]},{"n":37,"t":"꼭 알아 둘 점","sec":6,"x":"자료실에 공개돼요 / Free 계정 퀴즈는 숨길 수 없어요. 학생 이름 · 사진은 넣지 마세요. / 번개 표시는 유료 / 초록은 Basic, 파랑은 Pro. 표시 없는 맵과 기능으로 꾸려요. / AI 문제 검토 / 개수 · 유형이 요청과 다르기도 해요. 정답과 문장을 꼭 확인해요. / 선택형 정답 체크 / 정답이 여러 개 체크돼요. 처음 켜진 1번을 확인해요. / 닉네임 정리 / 처음엔 무작위 이름이에요. 변경 요청 뒤 변경 잠금! / 기기와 인원 / PC · 모바일 모두 되고 크롬을 권장해요. 한 맵 최대 200명. / 동시 접속 · 기기 · 플랜 관련 안내: 젭 퀴즈 자주 묻는 질문 기준","no":"가장 중요한 것은 공개 범위입니다. 배움터 계정은 Free 플랜이라 만든 퀴즈가 모두 자료실에 공개되니, 학생 개인정보는 넣지 않도록 해 주세요. 동시 접속 인원, 기기, 크롬 권장은 젭 퀴즈 자주 묻는 질문의 안내를 옮긴 것입니다. 나머지는 연수를 준비하며 직접 해 보면서 확인한 내용입니다.","alt":[]},{"n":38,"t":"수업에 이렇게 써 보세요","sec":6,"x":"계기교육 10분 퀴즈 / 자료실에서 찾은 퀴즈를 복사해 그날 바로 / 단원 복습 자유 풀이 / 운동장 맵에 핵심 문제 7~10개를 숨겨 두기 / 차근차근 순서 풀이 / 쉬운 문제부터 순서대로 풀게 하고 싶을 때 / 플래시카드로 예습 / 맵에 들어가기 전 혼자 카드를 넘겨 보기 / 처음에는 이렇게 시작해 보세요 / 운동장 맵 + OX · 선택형 5문제 + '틀렸을 때만 정답 보여주기'. 학습 리포트로 틀린 문제만 다시 짚으면 돼요.","no":"오늘 해 본 기능만으로도 계기교육, 단원 복습, 예습까지 할 수 있습니다. 운동장과 마녀의 마법 맵은 아이들이 각자 속도로 푸는 방식이라 개인 활동으로 쓰기 좋습니다. 처음에는 다섯 문제 정도로 가볍게 시작해 보시기를 권해 드립니다.","alt":[]},{"n":39,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 퀴즈 같이 만들기 / 단원에 맞는 문제를 함께 만들어 드려요. / 첫 수업 함께 진행 / 교실 TV에 맵을 띄울 때 옆에서 도와드려요. / 결과 정리 도움 / 학생별 통계를 함께 확인해요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 퀴즈를 만들거나 처음 수업에 쓰실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,46136],[46136,46464],[92600,61192],[153792,59950],[213742,91136],[304878,62032],[366910,105802],[472712,63648],[536360,61228],[597588,42832],[640420,65670],[706090,77656],[783746,80206],[863952,66306],[930258,72530],[1002788,58646],[1061434,52396],[1113830,68132],[1181962,80346],[1262308,96802],[1359110,81598],[1440708,70238],[1510946,72520],[1583466,75378],[1658844,66280],[1725124,78002],[1803126,79292],[1882418,60090],[1942508,74170],[2016678,72434],[2089112,60814],[2149926,70434],[2220360,49760],[2270120,80274],[2350394,71790],[2422184,48692],[2470876,59432],[2530308,54692],[2585000,37658]],"toffs":[[0,3592],[3592,3786],[7378,4982],[12360,4734],[17094,6312],[23406,4536],[27942,8312],[36254,4774],[41028,5034],[46062,3516],[49578,5296],[54874,5930],[60804,5556],[66360,5496],[71856,5292],[77148,4564],[81712,4660],[86372,5748],[92120,5966],[98086,7360],[105446,5878],[111324,6972],[118296,5846],[124142,6498],[130640,5452],[136092,6024],[142116,5842],[147958,4702],[152660,5920],[158580,5060],[163640,5062],[168702,5152],[173854,3994],[177848,5774],[183622,5418],[189040,4092],[193132,4214],[197346,4542],[201888,3752]],"packSize":2622658,"thumbSize":205640},{"key":"tkbell","name":"띵커벨","title":"띵커벨 사용 안내서","group":"quiz","sub":"경북AI배움터로 접속해 퀴즈·보드·토론 수업 만들기","fee":"공모 선정자 유료 · 배틀 게임은 모두","feeKind":"part","feeNote":"유료 이용권은 배움터 공모로 선정된 선생님께 나가요. 배움터를 거쳐 들어가면 무료 교사도 퀴즈 배틀의 유료 게임을 쓸 수 있어요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 띵커벨로 할 수 있는 일"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 띵커벨에 접속하고 배움터 혜택과 유료 기능을 살펴봐요"},{"start":9,"num":"2","label":"퀴즈 만들기","desc":"퀴즈를 직접 만들고 선택형·OX·단답형·순서형 문제를 넣어요"},{"start":20,"num":"3","label":"AI로 만들기","desc":"AI로 문제를 만들고 검토해서 가져와요"},{"start":25,"num":"4","label":"수업 모드","desc":"수업 모드로 학생 입장부터 최종 순위까지 진행해요"},{"start":35,"num":"5","label":"과제 모드","desc":"과제 모드로 기간을 정해 과제로 내요"},{"start":37,"num":"6","label":"보드","desc":"보드를 만들어 설정하고 공유한 뒤 결과를 내려받아요"},{"start":44,"num":"7","label":"토의·토론","desc":"토의·토론 투표로 학생 의견과 까닭을 모아요"},{"start":48,"num":"8","label":"결과와 활용","desc":"리포트와 라이브러리, 유의사항과 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"띵커벨","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 퀴즈·보드·토론 수업 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 띵커벨을 함께 써 보겠습니다. 띵커벨은 퀴즈, 토의·토론, 보드 같은 참여 활동을 만들어 학생들과 함께 진행하고 결과까지 모아 볼 수 있는 도구입니다. 화면 속 퀴즈도 연수를 준비하면서 직접 만들어 진행해 본 것입니다.","alt":["띵커벨 수업 모드에서 선택형 문제를 진행하는 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 띵커벨, 혜택과 유료 기능 / 04–08쪽 / STEP 2 / 퀴즈 만들기 / 기본 설정, 문제 유형 4가지 / 09–19쪽 / STEP 3 / AI로 만들기 / 조건 넣기, AI 문제 검토 / 20–24쪽 / STEP 4 / 수업 모드 / 학생 입장부터 최종 순위까지 / 25–34쪽 / STEP 5 / 과제 모드 / 기간을 정해 과제로 내기 / 35–36쪽 / STEP 6 / 보드 / 협업 게시판 만들고 공유하기 / 37–43쪽 / STEP 7 / 토의·토론 / 투표하고 까닭 나누기 / 44–47쪽 / STEP 8 / 결과와 활용 / 리포트, 라이브러리, 유의사항 / 48–52쪽","no":"여덟 단계로 진행합니다. 시간이 부족하면 2단계 퀴즈 만들기와 4단계 수업 모드만 꼭 해 보세요. 4단계에서는 선생님들 휴대폰으로 직접 들어와 문제를 풀어 보시겠습니다.","alt":[]},{"n":3,"t":"띵커벨로 만들 수 있는 활동","sec":0,"x":"시작하기 전에 / 퀴즈 / 학생들이 실시간으로 문제를 풀고 결과를 함께 봐요. / 토의·토론 / 실시간으로 의견을 나누고 결과를 확인해요. / 보드 / 학생들과 함께 쓰는 온라인 협업 게시판이에요. / 워크시트 / 종이 학습지를 온라인 학습지로 만들어 과제로 내요. / 게임 / 학생들과 실시간으로 게임을 풀고 결과를 확인해요. / 리포트 / 진행한 활동의 결과가 모여요. 파일로 내려받을 수 있어요. / 오늘 직접 해 볼 활동 / 퀴즈 · 보드 토의·토론 / 직접 만들고, 수업 모드로 함께 풀고, 결과까지 확인해 볼게요. / 학생은 회원가입이나 앱 설치 없이 tkbell.kr에서 방번호로 들어와요.","no":"띵커벨에서 만들기 버튼을 누르면 퀴즈, 토의·토론, 보드, 워크시트, 게임 다섯 가지를 만들 수 있습니다. 활동 설명은 띵커벨 만들기 창에 나온 문구를 바탕으로 정리했습니다. 오늘은 이 가운데 퀴즈, 보드, 토의·토론을 직접 만들어 보고, 학생들은 tkbell.kr에서 방번호로 들어오는 흐름까지 함께 확인하겠습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 띵커벨 열기","sec":1,"x":"1 / 에듀테크 서비스 → 띵커벨 / 배움터에 교원으로 로그인한 뒤 메인 화면에서 찾아요. / 2 / 마우스를 올리면 설명 표시 / 퀴즈 · 토의 · 워크시트 등 할 수 있는 활동이 나와요. / 3 / 목록 2쪽에 있어요 / 첫 화면에 안 보이면 화살표로 넘겨 보세요. / TIP / 띵커벨 사이트로 바로 가지 말고 꼭 배움터를 거쳐 들어오세요. 그래야 배움터 혜택이 적용돼요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 에듀테크 서비스 목록을 한 번 넘기면 2쪽에 띵커벨이 있습니다. 누르면 새 탭에서 띵커벨이 열립니다. 띵커벨 사이트에 바로 들어가면 배움터 혜택이 적용되지 않으니 꼭 배움터를 거쳐 들어가 주세요.","alt":["경북AI배움터 에듀테크 서비스 목록에서 띵커벨에 마우스를 올린 화면"]},{"n":5,"t":"처음 한 번은 띵커벨 계정과 연동해요","sec":1,"x":"1 / 띵커벨 계정 입력 / 회원이면 쓰던 아이디로, 처음이면 회원가입 후 연동해요. / 2 / 개인정보 처리 동의 / 필수 항목이라 체크해야 넘어가요. / 3 / 로그인 및 연동하기 / 누르면 띵커벨 화면으로 넘어가요. / TIP / 연동은 처음 한 번만 하면 돼요. 그다음부터는 배움터에서 누르면 바로 들어가져요.","no":"띵커벨 이벤트 페이지에 안내된 연동 방법입니다. 연수용 계정은 이미 연동되어 있어서 이 화면을 직접 거치지는 않았습니다. 처음 들어가시는 선생님은 이 순서대로 한 번만 연동해 주시면 됩니다. 비밀번호는 각자 입력해 주세요.","alt":["띵커벨 안내 페이지의 AIEP와 띵커벨 연동 방법"]},{"n":6,"t":"접속하면 처음 보이는 화면 (홈)","sec":1,"x":"1 / 만들기 + / 새 활동을 만들어요. / 2 / 왼쪽 메뉴 / 홈 · 라이브러리 · 레슨 · 클래스 · 보관함 · 리포트 / 3 / 나의 수업 리포트 / 진행한 수업 결과가 쌓여요. / 4 / 나의 최신 띵커벨 / 최근에 만든 활동이 보여요. / TIP / 처음엔 '학생 정보 이용 동의' 창이 떠요. 클래스를 쓸 때 필요한 동의라 오늘은 닫아도 돼요.","no":"띵커벨에 들어오면 홈 화면이 열립니다. 왼쪽 메뉴의 보관함에는 내가 만든 자료가, 리포트에는 수업 결과가 모입니다. 처음 들어오면 클래스 이용을 위한 학생 정보 이용 동의 창이 뜨는데, 오늘은 클래스를 만들지 않으니 닫고 진행하셔도 됩니다. 이름 부분은 개인정보라 흐리게 처리했습니다.","alt":["띵커벨 홈 화면"]},{"n":7,"t":"배움터로 들어오면 퀴즈 배틀 혜택이 있어요","sec":1,"x":"기본 제공 / 출발! 우주 경주 · 우주 정거장 · 땅따먹기(최대 2팀) / 배움터로 들어오면 더해지는 혜택 / 사막의 경쟁자 · 정글 탐험 · 땅따먹기(최대 6팀) / 대상 / AIEP와 연동한 초·중·고 띵커벨 무료 교사 / 꼭 확인하세요 / 띵커벨에 바로 들어가면 혜택이 없어요. 퀴즈 배틀 말고 다른 유료 기능은 이 혜택에 들어가지 않아요.","no":"띵커벨 이벤트 페이지에 안내된 내용입니다. AIEP, 우리 도에서는 경북AI배움터를 거쳐 띵커벨에 들어오면 무료 교사도 퀴즈 배틀의 유료 게임까지 쓸 수 있습니다. 다만 배틀 외의 유료 기능은 적용되지 않는다고 안내되어 있습니다. 배틀 모드는 수업 모드와 같은 플레이 모드 선택 창에서 고릅니다.","alt":["AIEP에서 온 선생님을 위한 특별 혜택 안내: 기본 제공과 유료 혜택 게임","이벤트 대상과 혜택 받는 방법 안내"]},{"n":8,"t":"왕관 표시가 붙은 기능은 유료예요","sec":1,"x":"왕관 표시 기능 / 문제 유형 가운데 투표 · 설명형, 배틀 가운데 사막의 경쟁자 · 정글 탐험 / 배틀 게임은 배움터로 들어오면 무료 교사도 쓸 수 있어요. / AI로 만들기 · PDF 인쇄 / AI로 만들기에는 '유료 · Beta' 표시가 붙어 있어요. 이용권 계정 기준 한 달에 10회까지 쓸 수 있어요. / 보드 결과를 PDF로 인쇄하는 기능도 유료 회원만 쓸 수 있어요. / 리포트 보관 기간 / 무료 회원은 1개월, 유료 회원은 다음 해 2월 말까지 보관돼요. / 필요한 리포트는 미리 내려받아 두세요. / 연수 화면은 이용권이 등록된 계정이에요 / 띵커벨 이용권(2026. 3. 1. ~ 2027. 2. 28.)이 등록된 계정으로 찍은 화면이라, 무료 계정에서는 왕관 표시 기능이 잠겨 보일 수 있어요.","no":"띵커벨은 기본 기능을 무료로 쓸 수 있고, 메뉴에 왕관 표시가 붙은 기능은 유료입니다. 오늘 보여 드리는 화면은 이용권이 등록된 계정이라 유료 기능까지 보입니다. 선생님 계정 상황에 따라 화면이 조금 다를 수 있다는 점 참고해 주세요. 리포트 보관 기간 안내는 리포트 화면 아래에 적힌 문구를 그대로 옮겼습니다.","alt":[]},{"n":9,"t":"만들기 + → 퀴즈 고르기","sec":2,"x":"1 / 만들 수 있는 활동 5가지 / 퀴즈 · 토의·토론 · 보드 · 워크시트 · 게임 가운데 골라요. / 2 / 설명 보고 확인 / 고른 활동의 설명이 오른쪽에 떠요. 오늘은 퀴즈부터 만들어요. / TIP / 홈 화면 오른쪽 위에도, 내 이름 아래에도 만들기 버튼이 있어요. 어느 쪽을 눌러도 같은 창이 열려요.","no":"만들기 버튼을 누르면 이 창이 뜹니다. 왼쪽에서 활동을 고르면 오른쪽에 설명이 나옵니다. 오늘은 퀴즈, 보드, 토의·토론을 차례로 만들어 보겠습니다.","alt":["띵커벨 만들기 창에서 퀴즈를 고른 화면"]},{"n":10,"t":"문제 만드는 방법 고르기","sec":2,"x":"1 / AI로 만들기 / 조건을 넣으면 AI가 문제를 만들어 줘요. 유료 · Beta 기능이에요. / 2 / 직접 만들기 / 문제를 하나씩 입력해요. 오늘은 여기서 시작해요. / 3 / 아래 안내 문구 / AI 결과는 꼭 검토하고, 개인정보가 들어가지 않게 해 달라는 안내예요. / TIP / AI로 만들기는 STEP 3에서 따로 해 볼게요.","no":"퀴즈를 고르면 문제를 만드는 방법을 묻습니다. AI로 만들기는 유료이면서 아직 시험 단계인 기능이라 STEP 3에서 따로 다루고, 지금은 직접 만들기로 문제를 하나씩 넣어 보겠습니다.","alt":["AI로 만들기와 직접 만들기 중 고르는 화면"]},{"n":11,"t":"기본 정보 넣기","sec":2,"x":"1 / 제목 / 학생 화면에도 보이니 알아보기 쉽게 써요. / 2 / 공개 범위 / 전체공개(모든 사용자)나 비공개(나만 보기)로 정해요. / 3 / 학교급 · 필터 / 꼭 골라야 하는 항목이에요. 학년과 과목을 정해요. / 4 / 만들기 완료 / 문제를 다 넣은 뒤 눌러 저장해요. / TIP / 학생 정보가 들어가는 퀴즈는 비공개로 해 두세요.","no":"제목과 공개 범위, 학교급과 필터를 먼저 정합니다. 공개범위 옆 물음표에 마우스를 올리면 공개 범위마다 누가 볼 수 있는지 설명이 나옵니다. 실습에서는 제목을 '[연수 실습] 가을 상식 퀴즈'로 하고 비공개로 만들었습니다.","alt":["퀴즈 기본 정보 입력 화면과 공개 범위 설명"]},{"n":12,"t":"퀴즈 문제 유형 9가지","sec":2,"x":"오늘 실습 / OX / O, X로 답하는 문제 / 오늘 실습 / 선택형 / 보기 가운데 정답 고르기 / 오늘 실습 / 단답형 / 짧은 낱말로 답 쓰기 / 빈칸형 / 문장 속 빈칸 채우기 / 서술형 / 생각을 글로 길게 쓰기 / 오늘 실습 / 순서형 / 보기를 차례대로 고르기 / 선잇기형 / 알맞은 것끼리 잇기 / 유료 / 투표 / 정답 없이 생각 고르기 / 유료 / 설명형 / 문제 사이에 설명 넣기 / 오늘 만들 퀴즈 / 4문제 / 선택형 · OX · 단답형 · 순서형 한 문제씩 / 유형 이름은 띵커벨 화면 그대로, 설명은 이름을 바탕으로 짧게 정리했어요. '유료'는 화면에 왕관 표시가 붙은 유형이에요.","no":"문제 편집 화면 위쪽에서 고르는 유형입니다. 오늘은 선택형, OX, 단답형, 순서형을 한 문제씩 만들어 네 문제짜리 퀴즈를 완성하겠습니다. 투표와 설명형에는 왕관 표시가 붙어 있어 유료 이용권이 있어야 쓸 수 있습니다.","alt":[]},{"n":13,"t":"선택형 문제 만들기","sec":2,"x":"1 / 문제 유형 / 첫 문제는 선택형으로 골라요. / 2 / 질문 / 120byte까지 쓸 수 있어요. / 3 / 미디어 추가 / 네이버 이미지 · 유튜브 · 내 이미지 · 음성 파일 / 4 / 선택지 · 정답 / 보기를 쓰고 오른쪽 동그라미로 정답을 표시해요. / 5 / 문제 추가하기 / 다음 문제를 만들어요.","no":"첫 문제는 '추석은 음력 몇 월 며칠일까요?'라는 선택형 문제로 만들었습니다. 보기는 1월 1일, 5월 5일, 8월 15일, 9월 9일 네 개이고 정답은 8월 15일입니다. 왼쪽 아래 문제 추가하기를 누르면 다음 문제 칸이 생깁니다.","alt":["선택형 문제 편집 화면"]},{"n":14,"t":"정답 · 제한시간 · 해설 정하기","sec":2,"x":"1 / 정답 체크 / 정답 보기 오른쪽 동그라미를 누르면 초록색 체크가 돼요. / 2 / 제한시간 / 없음, 10초부터 120초까지 골라요. 실습에서는 20초로 했어요. / 3 / 해설 / 결과를 볼 때 학생들에게 보여 줄 설명을 써요. / TIP / 보기는 5개까지 넣을 수 있어요. 비워 둔 보기는 학생 화면에 나오지 않아요.","no":"같은 문제 화면을 아래로 내리면 정답, 제한시간, 해설을 정하는 칸이 있습니다. 해설은 '추석은 음력 8월 15일로, 한가위라고도 불려요.'라고 적었습니다. 다섯 번째 보기 칸은 비워 두었는데 학생 화면에는 보기 네 개만 나왔습니다.","alt":["선택지, 정답, 제한시간, 해설을 입력한 화면"]},{"n":15,"t":"OX 문제 만들기","sec":2,"x":"1 / OX 유형 / OX를 누르면 선택지가 O, X 두 개로 바뀌어요. / 2 / 정답 고르기 / 송편은 추석 음식이라 이 문제는 X가 정답이에요. / 3 / 제한시간 / 문제마다 따로 정할 수 있어요. / TIP / 수업을 시작할 때 지난 시간 내용을 OX 몇 문제로 짧게 확인하기 좋아요.","no":"두 번째 문제는 '송편은 설날에 먹는 대표 음식이다.'라는 OX 문제입니다. 유형에서 OX를 누르면 선택지가 O와 X로 바뀌고, 정답 X 옆 동그라미를 눌러 표시했습니다.","alt":["OX 문제 편집 화면"]},{"n":16,"t":"단답형 문제 만들기","sec":2,"x":"1 / 정답 / 답을 쓰고 엔터를 치면 칸이 생겨요. 한 칸에 넣은 답은 하나만 맞혀도 정답이에요. / 2 / 정답 2 · 3 / 답을 여러 개 모두 써야 할 때만 채워요. / 3 / 단답형 출제 방법 / 누르면 채점 기준을 예시로 보여 줘요. / TIP / 비슷한 말까지 생각해서 정답을 넉넉하게 넣어 두세요.","no":"세 번째 문제는 '가을에 다 익은 곡식이나 열매를 거두어들이는 일을 무엇이라고 할까요?'라는 단답형입니다. 정답 칸에 '수확'을 쓰고 엔터, '추수'를 쓰고 엔터를 쳐서 둘 다 넣었습니다. 한 칸에는 엔터로 정답을 다섯 개까지 넣을 수 있다고 화면에 안내되어 있습니다.","alt":["단답형 정답 칸에 수확과 추수를 넣은 화면"]},{"n":17,"t":"단답형은 이렇게 채점돼요","sec":2,"x":"1 / 정답 기준 / 정답 1과 정답 2를 모두 써야 정답이에요. 쓰는 순서는 상관없어요. / 한 칸 안의 여러 답 / '세종'과 '세종대왕'처럼 같은 칸에 넣은 답은 둘 중 하나만 써도 돼요. / 칸을 나누는 경우 / '조선 시대 왕을 모두 쓰기'처럼 답이 여러 개 필요할 때 정답 2, 3을 써요. / TIP / 실습 문제는 '수확', '추수'를 정답 1 한 칸에 넣었어요. 둘 중 하나만 써도 정답이에요.","no":"단답형 출제 방법을 누르면 이 안내 창이 뜹니다. 예시 문제에서는 정답 1 칸에 세종과 세종대왕을, 정답 2 칸에 정조를 넣었습니다. 이렇게 하면 세종 또는 세종대왕 가운데 하나와 정조를 함께 써야 정답이 되고, 쓰는 순서는 상관없습니다. 실습 문제에서 '추수'를 정답 2 칸에 넣으면 수확과 추수를 둘 다 써야 정답이 되기 때문에, 두 낱말을 정답 1 한 칸에 함께 넣었습니다.","alt":["단답형 출제 방법 안내 창"]},{"n":18,"t":"순서형 문제 만들기","sec":2,"x":"1 / 안내 문구 / 보기를 먼저 다 쓰고, 정답 순서대로 오른쪽 칸을 눌러요. / 2 / 순서 번호 / 누른 순서대로 번호가 붙어요. 봄 1, 여름 2, 가을 3, 겨울 4. / TIP / 보기를 일부러 뒤섞어 써 두세요. 학생 화면에는 쓴 순서대로 보기가 나와요.","no":"네 번째 문제는 '봄부터 시작해 계절이 바뀌는 순서대로 고르세요.'라는 순서형입니다. 보기를 겨울, 가을, 봄, 여름 순으로 섞어 쓴 다음, 봄, 여름, 가을, 겨울 순서로 오른쪽 칸을 눌렀습니다. 해설에는 '봄 → 여름 → 가을 → 겨울 순서로 계절이 바뀌어요.'라고 적었습니다.","alt":["순서형 문제에 계절 순서를 정답으로 지정한 화면"]},{"n":19,"t":"다 만든 퀴즈 확인하기","sec":2,"x":"1 / 플레이 모드 / 배틀 · 수업 · 과제 · 도전 모드 등으로 바로 시작해요. / 2 / 복사 · 수정 / 다른 반용으로 복사하거나 다시 고쳐요. / 3 / 정답 ON/OFF / 정답 표시를 켜고 꺼요. TV에 띄울 때는 꺼 두세요. / TIP / 만든 퀴즈는 보관함에 저장되고, 홈의 '나의 최신 띵커벨'에도 보여요.","no":"만들기 완료를 누르면 이 상세 화면이 열립니다. 위쪽 버튼으로 바로 플레이를 시작할 수 있고, 오른쪽 위에서 복사하거나 수정할 수 있습니다. 문제 목록의 정답 표시는 교실 TV에 띄울 때 꺼 두시면 학생들에게 정답이 미리 보이지 않습니다. 이름 부분은 흐리게 처리했습니다.","alt":["완성한 퀴즈의 상세 화면"]},{"n":20,"t":"AI로 만들기는 동의부터 해요","sec":3,"x":"1 / 내용 확인 후 동의 체크 / AI로 만들기는 외부 AI 서비스(gemini)를 거쳐요. 그래서 개인정보나 민감한 내용은 넣지 않아야 해요. / 2 / 확인 / 체크해야 확인 버튼이 눌려요. / TIP / AI가 만든 문제의 저작권 책임은 만든 사람에게 있다고 안내돼요. 그대로 쓰지 말고 꼭 다듬어서 쓰세요.","no":"문제 만드는 방법에서 AI로 만들기를 누르면 AI 서비스 사용 동의 창이 뜹니다. 띵커벨의 AI 기능은 외부 서비스인 gemini를 거쳐 문제를 만들기 때문에 민감한 개인정보를 넣지 말라고 안내합니다. 생성된 문제의 저작권 관련 책임은 작성자에게 있다는 내용도 함께 적혀 있으니 한 번 읽어 보고 동의해 주세요.","alt":["AI 서비스 사용 동의 창"]},{"n":21,"t":"조건을 넣고 AI에게 맡기기","sec":3,"x":"1 / AI 활용 횟수 / 한 달에 10회까지 쓸 수 있어요. / 2 / 학교급 · 필터 / 5학년 > 2학기 > 사회처럼 범위를 골라요. / 3 / 문제 수 · 유형 / 5 · 10 · 20 · 30문제, OX · 선택형 · 단답형 · 서술형 / 4 / 프롬프트 (선택) / 원하는 주제와 수준을 문장으로 써요. / 5 / 확인 / 누르면 문제가 만들어져요.","no":"실습에서는 초등학교 5학년 2학기 사회로 범위를 정하고, OX와 선택형으로 5문제를 요청했습니다. 프롬프트에는 '고려 시대의 문화유산(팔만대장경, 고려청자, 금속활자)을 주제로 초등학교 5학년 수준의 문제를 만들어 주세요.'라고 적었습니다. 한 번 만들 때마다 오른쪽 위 AI 활용 횟수가 1회씩 올라갑니다.","alt":["AI로 만들기 조건 입력 화면"]},{"n":22,"t":"AI가 만든 문제 고르기","sec":3,"x":"1 / 안내 문구 / 문제 수정은 다음 단계에서 할 수 있어요. / 2 / 선택 · 생성 문제 수 / 몇 문제 가운데 몇 개를 골랐는지 보여요. / 3 / 문제 선택 / 가져갈 문제에만 체크해요. / 4 / 정답 / AI가 고른 정답이 초록색으로 표시돼요. / 5 / 선택 완료 / 고른 문제만 편집 화면으로 가져가요.","no":"확인을 누르고 잠시 기다리면 AI가 만든 문제가 나옵니다. 처음에는 다섯 문제가 모두 선택되어 있고, 체크를 풀면 그 문제는 가져가지 않습니다. 첫 문제는 고려청자를 묻는 선택형이었고 정답도 고려청자로 맞게 표시되어 있었습니다.","alt":["AI가 만든 문제 목록과 선택 화면"]},{"n":23,"t":"AI 문제는 한 문제씩 꼭 읽어 봐요","sec":3,"x":"1 / 체크 해제 / 애매한 문제는 체크를 풀어 빼요. / 2 / 문제 / 금속활자로 인쇄한 기술만의 특징을 묻고 있어요. / 3 / AI가 고른 정답 / '여러 번 찍어낼 수 있었다'는 목판 인쇄에도 맞는 말이라 정답으로 애매해요. / TIP / 선택 완료를 누르면 '반드시 검토 후 사용해 주세요' 안내가 한 번 더 떠요.","no":"AI가 만든 다섯 문제 가운데 4번은 빼고 가져왔습니다. 고려 금속활자 인쇄의 특징을 묻는 문제인데, AI가 정답으로 고른 '여러 번 찍어낼 수 있었다'는 목판 인쇄에도 해당하는 설명이라 금속활자만의 특징이라고 하기 어렵습니다. 이처럼 AI 문제는 그럴듯해 보여도 정답이 애매한 경우가 있으니, 수업에 쓰기 전에 꼭 한 문제씩 읽어 봐 주세요.","alt":["AI가 만든 4번 문제의 체크를 해제한 화면"]},{"n":24,"t":"가져온 문제 다듬고 저장하기","sec":3,"x":"1 / 문제 목록 / AI로 가져온 문제에는 AI 표시가 붙어요. / 2 / 제목 / 알아보기 쉽게 고쳐요. / 3 / 해시태그 / 내용에 맞는 해시태그가 저절로 들어가요. / 4 / 만들기 완료 / 다 고친 뒤 눌러 저장해요. / TIP / 직접 만들기와 같은 편집 화면이라 문제 · 보기 · 해설을 자유롭게 고칠 수 있어요.","no":"선택 완료를 누르면 고른 문제가 편집 화면으로 들어옵니다. 제목은 '[연수 실습] 고려 문화유산 AI 퀴즈'로 바꾸고 비공개로 저장했습니다. 해시태그는 AI가 내용을 보고 자동으로 넣어 주었습니다.","alt":["AI로 가져온 문제를 편집하는 화면"]},{"n":25,"t":"퀴즈를 시작하는 플레이 모드","sec":4,"x":"배틀 모드 / 게임처럼 겨루며 풀기 / 게임 / 방식 / 출발! 우주 경주 / 레이싱 / 우주 정거장 / 아이템 / 사막의 경쟁자 / 레이싱 · 유료 / 정글 탐험 / 아이템 · 유료 / 땅따먹기 / 팀플레이 / 유료 게임은 배움터로 들어오면 무료 교사도 쓸 수 있어요. / 기본 모드 · 오늘 실습 / 수업 모드 / 선생님 진행 속도에 맞춰 학생들이 각자 기기로 함께 풀어요. / 기본 모드 · 오늘 실습 / 과제 모드 / 기간을 정해 보내면 학생들이 그 안에 자유롭게 풀어요. / 기본 모드 · 그 밖에 / 도전 모드 · 플래시 카드 · 슬라이드","no":"만든 퀴즈에서 플레이하기를 누르면 플레이 모드 선택 창이 뜹니다. 위쪽은 게임처럼 겨루는 배틀 모드, 아래쪽은 수업 모드와 과제 모드 같은 기본 모드입니다. 왕관 표시가 붙은 사막의 경쟁자와 정글 탐험은 유료 게임인데, 배움터를 거쳐 들어오면 무료 교사도 쓸 수 있습니다. 오늘은 기본 모드의 수업 모드와 과제 모드를 해 보겠습니다.","alt":[]},{"n":26,"t":"수업 모드로 시작하기","sec":4,"x":"1 / 공유 대상 / '누구나'는 방번호만 알면 들어와요. '클래스'는 만들어 둔 클래스를 골라 진행해요. / 2 / 수업 모드 / 기본 모드에서 골라요. 오른쪽에 설명이 나와요. / 3 / 시작하기 / 누르면 학생들이 들어오는 대기실이 열려요. / TIP / 오늘은 클래스를 만들지 않고 '누구나'로 진행했어요.","no":"공유 대상은 누구나로 두고, 기본 모드에서 수업 모드를 골라 시작하기를 누릅니다. 수업 모드는 선생님이 진행하는 속도에 맞춰 학생들이 각자 기기로 참여하고, 끝나면 결과 리포트가 남는 방식입니다. 클래스 기능을 쓰면 학생 명단으로 관리할 수 있지만 학생 정보 동의가 필요해서 오늘은 다루지 않았습니다.","alt":["플레이 모드 선택 창에서 수업 모드를 고른 화면"]},{"n":27,"t":"대기실: 방번호를 화면에 띄워요","sec":4,"x":"1 / 방번호 · QR / 학생은 tkbell.kr에서 방번호를 넣거나 QR을 찍어요. / 2 / 접속 현황 / 들어온 학생 닉네임이 여기에 보여요. / 3 / 진행 옵션 / 정오답 피드백 · 타이머 · 문제 섞기 · 선택지 섞기 · 보너스 점수 / 4 / 시작하기 / 학생들이 다 들어오면 눌러요. / TIP / 교실 TV에 이 화면을 띄워 두면 학생들이 보고 따라 들어와요.","no":"시작하기를 누르면 대기실 화면이 열립니다. 실습 때 방번호는 114823이었습니다. 아래쪽 옵션은 정오답 피드백, 타이머, 보너스 점수는 켜고 문제 섞기와 선택지 섞기는 끈 채로 진행했습니다. 지금 선생님들 휴대폰으로 tkbell.kr에 들어와 화면의 방번호를 넣어 보시겠습니다.","alt":["방번호와 QR 코드가 보이는 수업 모드 대기실"]},{"n":28,"t":"학생은 방번호와 닉네임으로 들어와요","sec":4,"x":"1 / 방번호 · 닉네임 / tkbell.kr의 '퀴즈·토론·게임' 탭에 방번호와 닉네임을 넣어요. / 2 / 동의하고 입장하기 / 회원가입 없이 바로 들어가요. / 3 / 대기 화면 / '입장하였습니다'가 뜨면 선생님이 시작할 때까지 기다려요. / TIP / 닉네임은 한글 · 영어 · 숫자만 돼요. '1번 학생'처럼 띄어 쓰면 오류가 나니 '1번학생'처럼 붙여 쓰게 하고, 실명 대신 번호를 쓰게 해 주세요.","no":"학생은 휴대폰이나 태블릿 브라우저에서 tkbell.kr에 들어갑니다. 퀴즈·토론·게임 탭에 방번호와 닉네임을 넣고 동의하고 입장하기를 누르면 됩니다. 실습할 때 닉네임에 '1번 학생'처럼 띄어쓰기를 넣었더니 '한글, 영어, 숫자만 입력 가능합니다'라는 오류가 났습니다. 입력 화면에도 실명을 쓰지 말라는 안내가 있으니 번호로 정해 주시면 좋겠습니다.","alt":["학생 기기의 띵커벨 참여하기 화면에 방번호와 닉네임을 넣은 모습","입장 후 학생 대기 화면"]},{"n":29,"t":"TV 화면: 문제를 함께 풀어요","sec":4,"x":"1 / 방번호 / 진행하는 동안 왼쪽 위에 계속 보여요. / 2 / 타이머 / 남은 시간이 막대로 줄어들어요. / 3 / 제출 인원 / 몇 명이 답을 냈는지 보여요. / 4 / 결과 확인 / 시간이 끝나기 전에 눌러 바로 결과를 볼 수 있어요. / TIP / 시간이 다 되면 결과 화면으로 저절로 넘어가요.","no":"시작하기를 누르면 TV 화면에 문제와 보기가 나옵니다. 위쪽 막대가 남은 시간이고, 오른쪽 위에 몇 명이 제출했는지 나옵니다. 모두 제출했으면 결과 확인을 눌러 바로 넘어가도 됩니다. 실습 때 첫 문제는 제한시간이 끝나 결과 화면으로 저절로 넘어갔습니다.","alt":["선생님 화면에 문제와 보기가 나온 모습"]},{"n":30,"t":"학생 화면: 보기를 누르면 제출돼요","sec":4,"x":"1 / 학생 선택지 / 학생 기기에도 문제와 보기가 나와요. 답을 눌러 고르면 돼요. / 2 / 제출되었습니다 / 친구들이 다 낼 때까지 기다려요. / TIP / 정오답 피드백을 켜 두면 결과가 나올 때 학생 기기에도 맞았는지 틀렸는지 바로 보여요.","no":"학생 화면입니다. 선택형은 보기를 누르면 바로 제출되고, 단답형은 글자를 써서 냅니다. 제출하고 나면 친구들을 기다리는 화면이 나옵니다.","alt":["학생 기기에 문제와 보기가 나온 화면","답을 제출한 뒤 학생 화면"]},{"n":31,"t":"문제마다 결과를 함께 봐요","sec":4,"x":"1 / 정답 · 인원 / 정답에 체크가 되고, 보기마다 고른 인원이 나와요. / 2 / 미참여 / 답을 내지 않은 학생 수예요. / 3 / 참여자 보기 · 해설 · 순위 / 누가 무엇을 골랐는지, 해설과 지금 순위를 볼 수 있어요. / 4 / 다음 / 다음 문제로 넘어가요. / TIP / 틀린 학생이 많은 문제는 해설을 띄워 짚고 넘어가세요.","no":"OX 문제의 결과 화면입니다. 정답 X에 체크 표시가 되고, O와 X를 고른 인원이 나옵니다. 오른쪽 아래 버튼으로 참여자 답, 해설, 현재 순위를 차례로 띄워 볼 수 있습니다. 확인이 끝나면 오른쪽 위 다음을 누릅니다.","alt":["OX 문제 결과 화면"]},{"n":32,"t":"참여자 보기와 랜덤발표","sec":4,"x":"1 / 정답 · 오답 · 미참여 / 탭을 눌러 학생 답을 나눠 봐요. / 2 / 랜덤발표 / 한 명을 무작위로 뽑아 발표를 시켜요. / 3 / 학생 답 카드 / 닉네임과 낸 답이 함께 보여요. / TIP / 닉네임이 TV 화면에 그대로 나오니 번호 닉네임을 쓰면 마음이 편해요.","no":"결과 화면에서 참여자 보기를 누르면 정답, 오답, 미참여로 나눠 학생 답을 볼 수 있습니다. 화면은 순서형 문제 결과로, 학생이 정한 순서가 번호로 나와 있습니다. 랜덤발표를 누르면 한 명을 뽑아 주니 발표 순서를 정할 때 쓰기 좋습니다.","alt":["참여자 보기 화면에서 정답 탭과 랜덤발표 버튼"]},{"n":33,"t":"종합 결과로 마무리해요","sec":4,"x":"1 / 문항별 정답자 · 오답자 / 문제마다 맞힌 학생과 틀린 학생 수가 막대로 나와요. / 2 / 해설 · 문제 / 다시 짚을 문제를 바로 열어 봐요. / 3 / 최종 순위 / 시상대 화면으로 넘어가요. / 4 / 완료 / 수업을 끝내요. 결과는 리포트에 남아요. / TIP / 틀린 학생이 많은 문제를 골라 수업 마무리에서 한 번 더 다뤄 보세요.","no":"마지막 문제가 끝나면 종합 결과가 나옵니다. 문제마다 정답자와 오답자 수가 막대로 나와서 어느 문제를 어려워했는지 한눈에 볼 수 있습니다. 오른쪽 위 최종 순위를 누르면 시상대 화면으로, 완료를 누르면 수업이 끝나고 리포트에 결과가 저장됩니다.","alt":["문항별 정답자와 오답자를 보여 주는 종합 결과 화면"]},{"n":34,"t":"최종 순위와 학생 결과","sec":4,"x":"1 / 최종 순위 / 점수가 높은 학생이 시상대에 올라가요. / 2 / 학생 결과 / 학생 기기에는 내 점수와 정답 · 오답 수가 나와요. / TIP / 순위 경쟁이 부담스러운 반이라면 시상대는 건너뛰고 종합 결과만 함께 봐도 돼요.","no":"최종 순위를 누르면 시상대 화면이 나옵니다. 실습에서는 1번학생이라는 닉네임으로 들어가 네 문제를 풀어 보았습니다. 학생 기기에는 자기 점수와 맞힌 문제, 틀린 문제 수가 나옵니다.","alt":["최종 순위 시상대 화면","학생 기기의 풀이 결과 화면"]},{"n":35,"t":"과제 모드: 기간을 정해 보내기","sec":5,"x":"1 / 과제 종료일 / 날짜와 시각을 정해요. 과제 기간은 최대 4주까지 정할 수 있어요. / 2 / 플레이 옵션 / 정오답 피드백 · 타이머 · 문제 섞기 · 선택지 섞기를 켜고 꺼요. / 3 / 닉네임 안내 문구 / 학생이 닉네임을 쓸 때 보이는 안내예요. 예: '번호만 쓰세요' / 4 / 과제 생성 / 누르면 방번호와 공유 방법이 나와요. / TIP / 과제 모드는 플레이 모드 선택 창의 기본 모드에서 골라요. 학생들은 기간 안에 각자 편한 때 풀어요.","no":"같은 퀴즈를 과제로도 내 보겠습니다. 플레이 모드 선택 창에서 과제 모드를 고르면 이 설정 창이 뜹니다. 과제 종료일 옆 물음표에 마우스를 올리면 과제 기간은 최대 4주까지 정할 수 있다는 안내가 나옵니다. 결과는 학생들이 푸는 대로 리포트에서 확인할 수 있습니다.","alt":["과제 모드 설정 창과 과제 기간 안내"]},{"n":36,"t":"과제 공유하기","sec":5,"x":"1 / 과제 종료일 / 실습 과제는 2026. 10. 30. 오전 10시까지 풀 수 있어요. / 2 / QR · 방번호 / 학생은 tkbell.kr에서 방번호를 넣거나 QR로 들어와요. / 3 / 공유 / 카카오톡 · 페이스북 · 네이버밴드 · HiClass로 보내거나 링크를 복사해요. / TIP / 하이클래스 알림장에 링크를 붙여 두면 학생들이 집에서도 바로 들어와 풀 수 있어요.","no":"과제 생성을 누르면 공유 창이 열립니다. 실습 과제의 방번호는 768625이고 종료일은 10월 30일 오전 10시로 정했습니다. 학생에게는 방번호를 알려 주거나, 링크를 복사해 하이클래스 같은 학급 소통 도구에 올려 주시면 됩니다.","alt":["과제 공유 창의 방번호와 공유 버튼"]},{"n":37,"t":"보드 유형 11가지","sec":6,"x":"지도형 / 세계지도 위에 위치를 표시하고 글을 올려요. / 문제출제형 / 글 쓰듯 문제를 만들어 띵커벨 퀴즈로 이어요. / 격자형 · 오늘 실습 / 같은 높이로 순서대로 놓여요. / 그룹형 / 모둠별로 나누어 놓아요. / 출석부형 / 참여자마다 정해진 자리에 써요. / 타일형 / 빈 공간에 맞춰 저절로 채워져요. / 스트림 / 세로로 한 줄로 놓여요. / 타임라인 / 가로선을 따라 순서대로 놓여요. / 롤링페이퍼 / 시즌 테마에 맞춰 짧은 글과 사진을 남겨요. / 헥사곤 / 원하는 자리에 육각형 게시물을 써요. / 만다라트 / 주제를 하위 주제로 넓히고 구체화해요. / 보드란? / 학생들과 함께 쓰는 온라인 협업 게시판이에요. / 유형 설명: 띵커벨 보드 만들기 화면의 안내 문구를 줄여 옮겼어요.","no":"만들기에서 보드를 고르면 유형을 먼저 정합니다. 오늘은 가장 기본인 격자형으로 '가을 하면 떠오르는 것'을 모아 보겠습니다. 출석부형은 학생마다 자리가 정해져 있어 한 사람씩 빠짐없이 쓰게 할 때, 만다라트는 주제를 넓혀 가는 활동에 쓰기 좋습니다.","alt":[]},{"n":38,"t":"보드 만들기: 제목과 유형","sec":6,"x":"1 / 보드 제목 / 학생들이 보는 화면 맨 위에 나와요. / 2 / 보드 유형 / 11가지 가운데 골라요. 오늘은 격자형이에요. / 3 / 만들기 완료 / 누르면 보드가 만들어지고 설정 창이 열려요. / TIP / 제목은 학생에게 하는 질문처럼 써 두면 무엇을 올릴지 바로 알아요.","no":"보드 제목은 '[연수 실습] 가을 하면 떠오르는 것'으로 넣고 격자형을 골랐습니다. 오른쪽 위 만들기 완료를 누르면 보드가 만들어집니다.","alt":["보드 제목을 넣고 격자형을 고른 화면"]},{"n":39,"t":"보드 설정하기","sec":6,"x":"1 / 제목 · 설명 / 할 일을 알려 줘요. 예: 낱말, 그림, 사진 무엇이든 좋아요. 한 사람이 한 장씩 올려요. / 2 / 배경 / 보드 배경을 바꿔요. / 3 / 게시물 승인 / 켜 두면 선생님이 승인한 게시물만 보드에 보여요. / 4 / 닉네임 · 댓글 · 반응 / 작성자 닉네임과 댓글을 보일지, 어떤 반응을 남기게 할지 정해요. / 5 / 새 게시물 위치 / 새 글을 맨 처음에 둘지, 마지막에 둘지 골라요. / TIP / 학생 글이 바로 올라가는 것이 걱정된다면 게시물 승인을 켜 두세요.","no":"보드를 만들면 오른쪽에 개별 보드 설정 창이 열립니다. 설명에는 '낱말, 그림, 사진 무엇이든 좋아요. 한 사람이 한 장씩 올려요.'라고 적었습니다. 실습에서는 게시물 승인, 닉네임 표시, 댓글 표시를 켜고 반응은 좋아요로 두었습니다.","alt":["개별 보드 설정 창"]},{"n":40,"t":"보드 공유 설정","sec":6,"x":"1 / 공유 설정 / 공개 대상 · 방문자 권한 · 복사 권한을 정해요. 실습은 전체 공개 · 작성 가능 · 복사 불가로 했어요. / 2 / 공유 방식 / URL 복사 · QR 코드 · 방번호 · 카카오톡 등으로 보내요. / 3 / 공개 대상 / 비공개 · 공개 제한 · 전체 공개 · 클래스 공개. 공개 제한은 비밀번호 4자리를 정해요. / TIP / 방번호로 공유하려면 '공개 제한'으로 바꾸고 비밀번호를 정해야 해요. 전체 공개일 때는 링크나 QR로 보내 주세요.","no":"보드 위쪽 공유 버튼을 누르면 공유하기 창이 열립니다. 처음에는 공개 대상이 비공개로 되어 있어 학생이 들어올 수 없습니다. 방번호를 누르면 공개 범위를 공개 제한으로 바꾸고 비밀번호를 정하라는 안내가 뜹니다. 실습에서는 전체 공개로 바꾸고 링크로 공유했습니다. 공개 제한을 쓰실 때는 비밀번호를 선생님이 직접 정해 주세요.","alt":["보드 공유하기 창의 공유 설정과 공유 방식","보드 공개 대상 선택 화면"]},{"n":41,"t":"게시물 올리기","sec":6,"x":"1 / + 버튼 / 오른쪽 아래 +를 눌러 새 게시물을 써요. / 2 / 제목 · 내용 / 짧게 써요. 예: 단풍, 빨갛고 노랗게 물든 나뭇잎 / 3 / 첨부 / 파일 · 링크 · 이미지와 영상 · 그리기 · 투표를 넣어요. / 4 / 확인 / 누르면 보드에 올라가요. / TIP / 선생님이 예시 게시물을 먼저 올려 두면 학생들이 따라 쓰기 쉬워요.","no":"보드 오른쪽 아래 더하기 버튼을 누르면 게시물 쓰기 창이 열립니다. 실습에서는 '단풍'이라는 제목으로 '빨갛고 노랗게 물든 나뭇잎이 떠올라요.'라는 예시 게시물을 올렸습니다. 그림을 직접 그리거나 투표를 붙일 수도 있습니다.","alt":["보드에 게시물을 쓰는 창"]},{"n":42,"t":"올라온 게시물 보기","sec":6,"x":"1 / 게시물 카드 / 올라온 순서대로 격자에 놓여요. / 2 / 선택 승인 · 타이머 / 게시물을 골라 승인하고, 타이머로 활동 시간을 정해요. / 3 / 위쪽 버튼 / 보기 · 설정 · 공유 · 더보기 / 4 / + 버튼 / 게시물을 더 올려요. / TIP / 더보기 → 옵션 → 결과 다운로드로 보드 내용을 내려받을 수 있어요.","no":"게시물이 올라오면 이렇게 격자 모양으로 놓입니다. 게시물 승인을 켜 두었다면 선택 승인으로 공개할 게시물을 고를 수 있습니다. 타이머를 띄워 활동 시간을 함께 보는 것도 좋습니다.","alt":["게시물이 올라온 격자형 보드 화면"]},{"n":43,"t":"보드 결과 내려받기","sec":6,"x":"1 / 엑셀로 저장 / 게시물 내용을 표로 모아 둬요. / 2 / 이미지로 저장 / 보드 참여 결과를 그림 파일로 저장해요. / 3 / PDF로 인쇄 / 유료 회원만 쓸 수 있어요. / 4 / AI 내용 정리 (Beta) / 게시물 내용을 AI가 정리해 줘요. chatGPT API를 쓰니 민감한 개인정보가 담긴 보드에는 쓰지 않는 게 좋아요. / TIP / 활동이 끝날 때마다 엑셀로 저장해 두면 학기 말 기록 정리가 편해요.","no":"보드 오른쪽 위 더보기를 누르면 옵션 창이 열리고, 여기서 결과 다운로드를 누르면 이 창이 뜹니다. 옵션 창에는 게시물 지우기, 복사, 전체 삭제 같은 메뉴도 함께 있습니다. 엑셀과 이미지 저장은 바로 쓸 수 있고, PDF 인쇄는 유료 회원 기능이라고 안내되어 있습니다. AI 내용 정리는 chatGPT API를 쓰기 때문에 민감한 개인정보가 담긴 게시글은 피해 달라는 안내가 함께 있습니다.","alt":["보드 결과 다운로드 창"]},{"n":44,"t":"토의·토론 유형 7가지","sec":7,"x":"1 / 유형 / 찬성반대 · 신호등 · 가치수직선 · 투표 · 띵킹보드 · 워드클라우드 · 설명형(유료) / 2 / 선택지 / 찬성반대를 고르면 '찬성한다', '반대한다'가 미리 들어가 있어요. / 3 / 의견 받기 / 켜 두면 고른 까닭을 글로 함께 받아요. / TIP / 토의·토론에는 정답이 없어요. 오늘은 '투표'로 현장체험학습 장소를 골라 봤어요.","no":"만들기에서 토의·토론을 고르면 퀴즈와 비슷한 편집 화면이 열리고, 위쪽에서 유형을 고릅니다. 처음에는 찬성반대가 선택되어 있고 선택지도 찬성한다, 반대한다로 채워져 있습니다. 의견 받기를 켜면 학생이 고른 까닭을 글로 함께 받을 수 있습니다.","alt":["토의·토론 편집 화면의 유형 목록과 찬성반대 선택지"]},{"n":45,"t":"투표 질문 만들기","sec":7,"x":"1 / 질문 / 까닭까지 쓰도록 질문에 함께 적어 두면 좋아요. / 2 / 선택지 / 과학관 · 수목원 · 박물관처럼 고를 것을 써요. 5개까지 넣을 수 있어요. / 3 / 의견 받기 / ON으로 두면 학생이 고른 다음 까닭을 써요. / TIP / 제한시간은 '없음'으로 두어 충분히 생각하고 쓰게 했어요.","no":"질문은 '가을 현장체험학습으로 가장 가고 싶은 곳은 어디인가요? 고른 까닭도 적어 주세요.'로 했습니다. 선택지는 과학관, 수목원, 박물관 세 곳이고, 의견 받기를 켜서 까닭을 함께 받았습니다. 만든 뒤에는 퀴즈와 똑같이 수업 모드로 시작하면 됩니다.","alt":["투표 유형에 질문과 선택지를 넣은 화면"]},{"n":46,"t":"학생 화면: 고르고 까닭 쓰기","sec":7,"x":"1 / 고르기 / 가고 싶은 곳을 눌러요. / 2 / 까닭 쓰기 / 고른 까닭을 글로 써서 제출해요. / TIP / 들어오는 방법은 퀴즈와 같아요. tkbell.kr에서 방번호와 닉네임을 넣어요.","no":"학생 화면입니다. 수목원을 고르면 아래에 까닭을 쓰는 칸이 나옵니다. 실습에서는 '단풍이 든 나무를 가까이에서 보고, 여러 가지 열매도 관찰하고 싶어요.'라고 써서 냈습니다.","alt":["학생이 투표에서 수목원을 고른 화면","학생이 고른 까닭을 쓰는 화면"]},{"n":47,"t":"투표 결과와 의견 함께 보기","sec":7,"x":"1 / 선택지별 인원 / 어느 곳을 몇 명이 골랐는지 보여요. / 2 / 참여자 보기 / 학생 의견을 선택지별로 모아 봐요. / 3 / 의견 카드 / 닉네임과 쓴 까닭이 카드로 나와요. / 4 / 랜덤발표 / 한 명을 뽑아 의견을 말해 보게 해요. / TIP / 같은 곳을 고른 까닭이 서로 어떻게 다른지 견주어 보면 토의가 풍성해져요.","no":"투표가 끝나면 선택지마다 고른 인원이 막대로 나옵니다. 오른쪽 아래 참여자 보기를 누르면 선택지별로 학생 의견 카드가 모여 있습니다. 랜덤발표로 한 명을 뽑아 까닭을 말하게 하면 자연스럽게 토의로 이어 갈 수 있습니다.","alt":["선택지별 인원이 나온 투표 결과 화면","학생 의견 카드와 랜덤발표 버튼"]},{"n":48,"t":"리포트로 결과 확인하기","sec":8,"x":"1 / 참여 결과 요약 / 평균 정답률 · 참여 인원 · 문제 수를 한눈에 봐요. / 2 / 다운로드 / 결과를 파일로 내려받아요. / 3 / 참여인원 · 문제 탭 / 학생별로, 문제별로 나눠 볼 수 있어요. / TIP / 리포트는 무료 회원 1개월, 유료 회원은 다음 해 2월 말까지 보관돼요. 필요한 것은 미리 내려받아 두세요.","no":"왼쪽 메뉴의 리포트를 누르면 진행한 수업 목록이 나오고, 하나를 누르면 이 상세 화면이 열립니다. 실습한 가을 상식 퀴즈는 참여 인원 2명, 문제 4개, 평균 정답률 38%로 나왔습니다. 참여인원 탭에서는 학생별 점수와 순위를, 문제 탭에서는 문항별 정답률을 볼 수 있습니다.","alt":["수업 리포트 상세 화면"]},{"n":49,"t":"라이브러리에서 공개 자료 찾기","sec":8,"x":"1 / 검색 / '한글날'처럼 수업 주제로 찾아요. / 2 / 필터 · 유형 / 학교급과 퀴즈 · 토의토론 · 워크시트 · 게임으로 좁혀요. / 3 / 결과 카드 / 누르면 문제를 미리 볼 수 있어요. / TIP / 주제가 같다면 처음부터 만들기보다 찾아서 고쳐 쓰는 편이 빨라요.","no":"왼쪽 메뉴의 라이브러리에서는 다른 선생님들이 전체 공개로 올린 자료를 찾을 수 있습니다. 초등학교 필터를 두고 한글날을 검색했더니 313개 자료가 나왔습니다. 만든 선생님 이름은 흐리게 처리했습니다.","alt":["라이브러리에서 한글날을 검색한 결과"]},{"n":50,"t":"찾은 자료 바로 쓰거나 복사하기","sec":8,"x":"4 / 바로 플레이 / 배틀 · 수업 · 과제 모드 등으로 바로 시작해요. / 5 / 복사 / 내 보관함으로 가져와 우리 반에 맞게 고쳐 써요. / TIP / 다른 선생님 자료도 문제와 정답을 한 번씩 확인하고 쓰세요.","no":"검색 결과에서 자료를 누르면 상세보기가 열립니다. 문제를 미리 보고 마음에 들면 바로 플레이 모드로 시작하거나, 복사해서 내 보관함으로 가져와 고쳐 쓸 수 있습니다. 공개 자료도 정답이 틀린 경우가 있을 수 있으니 수업 전에 한 번 훑어봐 주세요.","alt":["라이브러리 자료의 상세보기 화면"]},{"n":51,"t":"꼭 알아 둘 점","sec":8,"x":"배움터로 접속 / 띵커벨에 바로 들어가면 퀴즈 배틀 혜택이 적용되지 않아요. / 학생 닉네임 / 한글 · 영어 · 숫자만 되고 띄어쓰기는 안 돼요. 실명 대신 번호로 정해 주세요. / 공개 설정 / 학생 정보가 들어간 퀴즈와 보드는 비공개나 공개 제한으로 두세요. / AI 결과 검토 / AI 문제와 AI 내용 정리는 꼭 검토하고, 개인정보는 넣지 않아요. / 리포트 보관 기간 / 무료 1개월, 유료는 다음 해 2월 말까지예요. 미리 내려받아 두세요. / 클래스 삭제 주의 / 클래스를 지우면 리포트와 보드의 학생 이름도 함께 지워지고 되돌릴 수 없어요.","no":"여섯 가지만 기억해 주세요. 특히 학생 닉네임은 띄어쓰기가 들어가면 입장이 안 되니 수업 전에 규칙을 미리 알려 주시면 좋습니다. 클래스 기능을 쓰시는 경우, 클래스를 지우면 리포트와 보드에 남은 학생 이름도 함께 지워지고 복구가 안 된다고 안내되어 있으니 주의해 주세요.","alt":[]},{"n":52,"t":"수업에 이렇게 써 보세요","sec":8,"x":"수업 도입 OX / 지난 차시 내용을 OX 다섯 문제로 수업 모드에서 짧게 / 단원 정리 배틀 / 단원 끝에 우주 경주나 땅따먹기 팀 대결로 / 생각 모으기 / 보드로 낱말과 사진을 모으고, 투표로 까닭 나누기 / 과제 모드 복습 / 기간을 정해 집에서 풀고 리포트로 확인 / 한 번 만든 자료는 계속 다시 쓸 수 있어요 / 같은 퀴즈를 다른 반에서 다시 플레이하거나 과제 모드로 바꿔 낼 수 있어요. 라이브러리에서 찾은 자료도 복사해서 우리 반에 맞게 고쳐 쓰세요.","no":"오늘 해 본 기능만으로도 수업 도입 복습, 단원 정리 대결, 생각 모으기, 과제까지 할 수 있습니다. 처음에는 OX 다섯 문제 정도로 가볍게 시작해 보시고, 아이들이 익숙해지면 배틀 모드나 보드로 넓혀 가시기를 권해 드립니다.","alt":[]},{"n":53,"t":"궁금한 점이 생기면 교실로 찾아가겠습니다","sec":8,"x":"연수가 끝난 뒤에도 / 첫 퀴즈 같이 만들기 / 단원에 맞는 문제를 함께 만들어 드려요. / 첫 수업 모드 함께 진행 / 교실 TV로 처음 진행할 때 옆에서 도와드려요. / 보드 · 결과 정리 도움 / 보드 설정과 리포트 내려받기를 함께 확인해요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 퀴즈를 만들거나 처음 수업 모드를 진행하실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,34266],[34266,55414],[89680,63672],[153352,66920],[220272,92414],[312686,70906],[383592,91072],[474664,71862],[546526,51824],[598350,57344],[655694,56160],[711854,62586],[774440,57484],[831924,64364],[896288,54618],[950906,63882],[1014788,70218],[1085006,55082],[1140088,52916],[1193004,70588],[1263592,62606],[1326198,62340],[1388538,63192],[1451730,68774],[1520504,58540],[1579044,59838],[1638882,72134],[1711016,67188],[1778204,55542],[1833746,47298],[1881044,53790],[1934834,44772],[1979606,63364],[2042970,58942],[2101912,73178],[2175090,61082],[2236172,68384],[2304556,62392],[2366948,65250],[2432198,76054],[2508252,50542],[2558794,53208],[2612002,65312],[2677314,58538],[2735852,59662],[2795514,49978],[2845492,64952],[2910444,56344],[2966788,56326],[3023114,50458],[3073572,58504],[3132076,56444],[3188520,38218]],"toffs":[[0,3190],[3190,4424],[7614,5096],[12710,5192],[17902,7430],[25332,5652],[30984,7488],[38472,5314],[43786,4764],[48550,4826],[53376,4112],[57488,4786],[62274,4664],[66938,5042],[71980,4370],[76350,4882],[81232,5136],[86368,4304],[90672,4166],[94838,5100],[99938,5230],[105168,4818],[109986,5152],[115138,5042],[120180,4562],[124742,5026],[129768,5740],[135508,5334],[140842,4994],[145836,4200],[150036,4760],[154796,3710],[158506,5188],[163694,5330],[169024,6332],[175356,5364],[180720,4898],[185618,4860],[190478,5296],[195774,5554],[201328,4184],[205512,4072],[209584,5416],[215000,4644],[219644,4658],[224302,4022],[228324,5238],[233562,4390],[237952,4980],[242932,4158],[247090,4144],[251234,4564],[255798,3852]],"packSize":3226738,"thumbSize":259650},{"key":"classgame","name":"클래스게임","title":"클래스게임 사용 안내서","group":"quiz","sub":"경북AI배움터로 접속해 실시간 쌍방향 게임 수업하기","fee":"무료 · Y클라우드 연동","feeKind":"free","feeNote":"YBM Y클라우드의 서비스예요. Y클라우드 이용약관에 콘텐츠와 서비스를 무료로 제공한다고 되어 있고, 배움터에서 처음 한 번 계정을 연동하면 써요(Y클라우드 공지 2026. 8. 26.).","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 클래스게임 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 클래스게임에 접속하고 처음 한 번 계정을 연동해요"},{"start":7,"num":"2","label":"게임 설정","desc":"게임을 고르고 교과서·단어·시간을 정해 게임방을 만들어요"},{"start":14,"num":"3","label":"참여와 진행","desc":"학생이 접속 코드로 들어와 사전 단어 학습과 게임을 진행해요"},{"start":24,"num":"4","label":"결과 확인","desc":"학생별·단어별 결과를 보고 다시하기와 종료를 익혀요"},{"start":28,"num":"5","label":"다른 과목","desc":"사회 OX 서바이벌, 수학, 음악 게임을 살펴봐요"},{"start":36,"num":"6","label":"유의사항과 활용","desc":"유의사항과 수업 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"클래스게임","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 실시간 쌍방향 게임 수업하기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 클래스게임을 함께 써 보겠습니다. 클래스게임은 YBM의 Y클라우드에서 제공하는 서비스로, 선생님이 게임방을 열면 아이들이 접속 코드로 들어와 교과 내용을 게임으로 익힙니다. 화면 속 문제도 연수를 준비하면서 직접 게임방을 열고 학생 화면으로 들어가 풀어 본 것입니다.","alt":["클래스게임 사회 OX 서바이벌 게임 학생 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 클래스게임, 계정 연동 / 04–06쪽 / STEP 2 / 게임 설정 / 게임 고르기, 단어, 시간, 게임방 / 07–13쪽 / STEP 3 / 참여와 진행 / 접속 코드, 사전 학습, 게임 화면 / 14–23쪽 / STEP 4 / 결과 확인 / 학생별 · 단어별 결과, 다시하기 / 24–27쪽 / STEP 5 / 다른 과목 / 사회 OX 서바이벌, 수학, 음악 / 28–35쪽 / STEP 6 / 유의사항과 활용 / 꼭 알아 둘 점, 수업 아이디어 / 36–37쪽","no":"여섯 단계로 진행하겠습니다. 시간이 부족하면 2단계 게임 설정과 3단계 참여와 진행만 꼭 해 보세요. 3단계에서는 선생님들 휴대폰으로 직접 게임방에 들어와 보시도록 하겠습니다.","alt":[]},{"n":3,"t":"클래스게임으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 게임 29가지 / 영어 16 · 사회 3 음악 4 · 수학 6 / 교과서 단원 연계 / 단원 단어 · 개념어로 바로 출제 / 회원가입 없이 참여 / 학생은 접속 코드와 닉네임만 / 결과 보기 / 학생별 점수, 단어별 정답률 / Y클라우드(YBM) 서비스 / 처음 한 번만 계정 연동 / 배움터를 거쳐 들어가면 배움터 계정과 Y클라우드 계정을 연결하라는 안내가 나와요. 한 번 연결하면 그다음부터 바로 써요. / 게임 수: 2026. 10. 클래스게임 화면 기준","no":"클래스게임은 게임을 고르고, 교과서 단원이나 단어를 정해 게임방을 열고, 아이들이 접속 코드로 들어와 함께 게임을 하는 흐름으로 씁니다. 영어 게임이 가장 많고, 사회·음악·수학 게임도 있습니다. 배움터를 거쳐 처음 들어가면 Y클라우드 계정과 연결하라는 안내가 나오는데, 한 번만 해 두면 됩니다.","alt":[]},{"n":4,"t":"배움터에서 클래스게임 찾기","sec":1,"x":"1 / 에듀테크 서비스 3쪽 / 목록 아래 › 를 눌러 3/4쪽으로 넘겨요. / 2 / 클래스게임 / 카드를 누르면 새 창으로 열려요. / 3 / 서비스 설명 / 카드에 마우스를 올리면 소개가 나와요. / TIP / 꼭 배움터를 거쳐 들어가 주세요. 그래야 계정 연동 안내가 나와요.","no":"배움터 첫 화면의 에듀테크 서비스 목록에서 클래스게임은 3쪽에 있습니다. 아래쪽 화살표로 3/4쪽까지 넘기면 Y클라우드 옆에 클래스게임 카드가 보입니다. 카드에 마우스를 올리면 오른쪽에 짧은 소개가 나오고, 누르면 새 창으로 클래스게임이 열립니다.","alt":["경북AI배움터 에듀테크 서비스 목록의 클래스게임 카드"]},{"n":5,"t":"클래스게임 첫 화면","sec":1,"x":"1 / 학교급 / 초등이 골라져 있어요. / 2 / 과목 탭 / 영어 · 사회 · 음악 · 수학 / 3 / 게임 카드 / 카드를 누르면 게임 설정 창이 새로 열려요. / TIP / 게임 설정은 새 탭에서 열려요. 첫 화면 탭은 그대로 두셔도 돼요.","no":"클래스게임 첫 화면입니다. 오른쪽 위에서 학교급을 고를 수 있는데 초등이 기본으로 골라져 있습니다. 가운데 과목 탭에서 영어, 사회, 음악, 수학을 고르면 아래에 게임 카드가 나옵니다. 게임 카드를 누르면 설정 화면이 새 탭으로 열립니다.","alt":["클래스게임 첫 화면"]},{"n":6,"t":"처음 한 번, 계정 연동하기","sec":1,"x":"1 / 기존 회원 로그인 / Y클라우드 아이디가 있으면 로그인만 하면 연동돼요. / 2 / AIEP 계정 연동 회원가입 / 아이디가 없으면 가입하면서 연동돼요. / 3 / AIEP 계정 아니에요 / 내 배움터 계정이 아니면 로그아웃해요. / 주의 / 함께 쓰는 컴퓨터라면 배움터에 누구 이름으로 로그인돼 있는지 먼저 확인해 주세요.","no":"배움터에서 처음 들어와 게임 카드를 누르면 AIEP 회원 연동 안내 창이 뜹니다. Y클라우드 아이디가 이미 있으면 기존 회원 로그인을, 없으면 AIEP 계정 연동 회원가입을 누르시면 됩니다. 연수를 준비할 때 컴퓨터 하나에 여러 계정이 섞여 있었는데, 그대로 로그인하면 다른 사람의 배움터 계정과 연결될 수 있어서 이름을 먼저 확인하도록 했습니다. 로그인과 회원가입은 선생님이 직접 해 주셔야 합니다.","alt":["AIEP 회원 연동 안내 창"]},{"n":7,"t":"게임 목록 살펴보기","sec":2,"x":"1 / 과목 탭 / N 표시는 새로 들어온 게임이 있다는 뜻이에요. / 2 / 개인 · 모둠 / 게임 형태예요. 대부분 개인전이에요. / 3 / 게임 설명 / 어떤 게임인지 한 줄로 알려 줘요. / 오늘 실습 / 영어 Matching Block Game으로 처음부터 끝까지 진행해 볼게요.","no":"영어 탭을 누른 화면입니다. 카드마다 게임 이름 옆에 개인, 모둠 표시가 있고 아래에 한 줄 설명이 있습니다. 오늘은 첫 번째 카드인 Matching Block Game으로 게임방을 열고 결과까지 보겠습니다. 단어 블록과 그림 블록을 짝짓는 게임이라 처음 보는 아이들도 금방 이해합니다.","alt":["영어 게임 목록"]},{"n":8,"t":"과목별 게임 한눈에","sec":2,"x":"영어 / 16가지 / Matching Block / Build The Word / Word Typing / Infinite Stairs / Bombing / Word Search / Speed / Spell it / Matching / Cross words / Bingo / Drawing / Halli Galli / Snake / Mole / OX Survival / 교과서 필수 단어 또는 주제별 단어 / 사회 / 3가지 / 개념 어휘 완성 / 빙고 / OX 서바이벌 / 사회 3-1 ~ 4-2 단원 개념어 / 음악 / 4가지 / 붐웨커 게임 / 나만의 노래 만들기 / 스마트 악기 연주 / 서바이벌 퀴즈왕 / 수학 / 6가지 / 두더지 게임 / 스피드 연산 / 빙고 게임 / 수학 사천성 / 폭탄 날리기 / 서바이벌 연산왕 / 수학 3-1 ~ 6-2 연산 단원 / 모둠으로도 되는 게임 / Word Search, Drawing Game(모둠 전용), 개념 어휘 완성, 붐웨커 게임","no":"과목별로 어떤 게임이 있는지 정리했습니다. 영어가 16가지로 가장 많고, 사회 3가지, 음악 4가지, 수학 6가지입니다. 대부분 개인전이고, 모둠으로 할 수 있는 게임은 아래에 따로 적었습니다. 게임 이름은 2026년 10월 클래스게임 화면을 그대로 옮겼습니다.","alt":[]},{"n":9,"t":"단어를 고르는 두 가지 방법","sec":2,"x":"1 / 교과서 필수 단어 / YBM 교과서 단원 단어로 내요. / 2 / 주제별 단어 / 학년별 주제(가족, 감정 등)로 내요. / 3 / 교과서 선택 / 3~6학년 YBM 영어 교과서 / 4 / 더 보기 / › 를 누르면 교과서가 더 나와요. / TIP / 우리 반 영어 교과서가 YBM이 아니면 ② 주제별 단어를 쓰면 돼요.","no":"게임 카드를 누르면 이 화면이 새 탭으로 열립니다. 위쪽 탭에서 교과서 필수 단어와 주제별 단어 가운데 하나를 고릅니다. 교과서 필수 단어에는 YBM 영어 교과서만 나오기 때문에, 다른 출판사 교과서를 쓰는 반이라면 주제별 단어를 쓰시는 편이 맞습니다. 실습에서는 초등 영어 6(김혜리) 교과서를 골랐습니다.","alt":["교과서 필수 단어와 주제별 단어 탭, 교과서 선택 화면"]},{"n":10,"t":"주제별 단어로 내기","sec":2,"x":"1 / 학년 / 초3 ~ 초6 가운데 골라요. / 2 / 주제 / 가족, 감정, 날씨, 음식 등 28가지 / 3 / 단어 목록 / 고른 주제의 단어가 바로 보여요. 5단어보다 적으면 주제를 더 골라요. / 4 / 다음 / 게임 단어를 정하는 단계로 가요. / TIP / 교과서와 상관없이 쓸 수 있어요.","no":"주제별 단어 탭을 누르면 학년을 먼저 고르고, 주제를 고릅니다. 초6을 골랐을 때 가족, 감정, 과목, 날씨, 음식, 직업 같은 주제가 28가지 나왔습니다. 화면은 감정 주제를 고른 모습인데 sorry, happy, angry 같은 11개 단어가 바로 보였습니다. 우리 학교처럼 YBM이 아닌 교과서를 쓰는 반에서는 이 방법이 편합니다.","alt":["주제별 단어 선택 화면"]},{"n":11,"t":"교과서 단원 고르기","sec":2,"x":"1 / 단원 체크 / 여러 단원을 함께 골라도 돼요. / 2 / 단어 목록 / 고른 단원의 단어가 모두 보여요. / 3 / 최소 단어 수 / 5단어보다 적으면 단원을 더 골라요. / 4 / 다음 / 실습 / 초등 영어 6(김혜리) Lesson 1 What Grade Are You In? (15단어)","no":"교과서를 고르면 단원 목록이 나옵니다. 단원 왼쪽 동그라미를 누르면 오른쪽에 그 단원 단어가 모두 나옵니다. 실습에서는 Lesson 1을 골랐고 club, first, second 같은 15개 단어가 나왔습니다. 게임에는 5단어 이상이 필요해서 단어가 적은 단원은 두 단원을 같이 고르시면 됩니다.","alt":["단원 선택과 단어 목록 화면"]},{"n":12,"t":"게임에 낼 단어 정하기","sec":2,"x":"1 / 게임 단어 수 / Matching Block은 5개 또는 6개 / 2 / 단어 선택 / 지정은 직접 고르기, 랜덤은 자동 고르기 / 3 / 고른 단어 / 지정이면 단어를 눌러 골라요. 주황색이 고른 단어예요. / 4 / 다음 / TIP / 단어 수 범위는 게임마다 달라요. 사회 OX 서바이벌은 10단어부터예요.","no":"단원 단어 가운데 실제 게임에 나올 단어를 정하는 단계입니다. Matching Block Game은 5개나 6개를 고를 수 있었습니다. 단어 선택을 지정으로 바꾸고 first부터 sixth까지 서수 여섯 개를 직접 눌러 골랐습니다. 랜덤으로 두면 단어가 자동으로 정해집니다.","alt":["게임 단어 수와 단어 선택 화면"]},{"n":13,"t":"게임 설정과 게임방 만들기","sec":2,"x":"1 / 게임 시간 / 3분 ~ 10분 / 2 / 참여 인원 / 처음에는 25명으로 돼 있어요. / 3 / 사전 단어 학습 / 켜 두면 게임 전에 단어를 함께 익혀요. / 4 / 게임 형태 / 이 게임은 개인전만 있어요. / 5 / 게임방 생성하기 / 누르면 바로 학습 대기 화면이 열려요.","no":"마지막 설정입니다. 게임 시간은 3분부터 10분까지 고를 수 있고 실습에서는 3분으로 했습니다. 참여 인원은 25명으로 들어가 있었고, 사전 단어 학습을 켜 두면 게임 전에 단어 카드를 함께 볼 수 있습니다. 게임방 생성하기를 누르면 바로 학생을 받을 수 있는 대기 화면이 열립니다.","alt":["게임 시간, 참여 인원, 사전 단어 학습 설정 화면"]},{"n":14,"t":"학습 대기 화면","sec":3,"x":"1 / QR 코드 / 돋보기를 누르면 크게 보여요. / 2 / 접속 URL / 복사해서 학급 게시판에 올려요. / 3 / 접속 코드 / 6자리 숫자예요. / 4 / 접속자 / 들어온 학생 닉네임이 바로 떠요. / 5 / 사전 단어 학습하기 / 게임 전에 단어를 함께 봐요. / 6 / 게임 시작하기 / 모두 들어오면 눌러요.","no":"게임방을 만들면 이 화면이 나옵니다. 왼쪽에 QR 코드, 접속 URL, 접속 코드가 있고, 오른쪽에 들어온 학생 닉네임이 하나씩 뜹니다. 실습 때 학생 두 명으로 들어가 보니 가을토끼, 초록개구리가 바로 떴습니다. 모두 들어오면 사전 단어 학습을 하거나 곧바로 게임을 시작합니다.","alt":["QR 코드, 접속 URL, 접속 코드와 접속자 목록이 있는 학습 대기 화면"]},{"n":15,"t":"학생이 들어오는 방법","sec":3,"x":"1 / QR 코드 찍기 / 태블릿 카메라로 찍으면 바로 들어와요. / 2 / ybmcloud.com/game1 / 이 주소로 들어와 접속 코드를 넣어요. (i)를 누르면 안내가 나와요. / 3 / 접속 코드 / 칠판에 6자리 숫자를 크게 적어 주세요. / TIP / game1 주소는 과목과 상관없이 같아요. 사회 게임도 이 주소로 들어갔어요.","no":"학생이 들어오는 방법은 세 가지입니다. QR 코드를 찍거나, ybmcloud.com/game1 주소에 들어가 접속 코드를 넣거나, 선생님이 복사해 준 접속 URL을 누르면 됩니다. 접속 코드 옆 (i)를 누르면 화면처럼 주소 안내가 나옵니다. 사회 OX 서바이벌을 할 때도 같은 game1 주소로 들어갔으니, 아이들에게는 이 주소 하나만 알려 주시면 됩니다.","alt":["접속 코드 안내 말풍선이 열린 학습 대기 화면"]},{"n":16,"t":"학생 접속 화면","sec":3,"x":"1 / 캐릭터 / 다섯 가지 가운데 골라요. / 2 / 접속 코드 / 선생님이 알려 준 6자리 숫자 / 3 / 닉네임 / 결과 화면에 이 이름이 나와요. / 4 / 게임 참여 번호 / 결과에 '1번 가을토끼'처럼 붙어요. / 5 / 접속하기 / TIP / 참여 번호는 출석 번호로 정하면 결과 정리가 편해요.","no":"학생 화면입니다. 회원가입 없이 캐릭터를 고르고 접속 코드, 닉네임, 게임 참여 번호를 넣은 뒤 접속하기를 누르면 됩니다. 참여 번호는 결과 화면에서 닉네임 앞에 붙어 '1번 가을토끼'처럼 나왔습니다. 닉네임은 실명 대신 정해 둔 규칙으로 쓰게 하고, 참여 번호를 출석 번호로 맞추면 누가 누구인지 헷갈리지 않습니다.","alt":["캐릭터, 접속 코드, 닉네임, 게임 참여 번호를 넣는 학생 접속 화면"]},{"n":17,"t":"학생 대기 화면","sec":3,"x":"1 / 게임 정보 / 개인전 · 게임 시간 · 문항 수 / 2 / 게임 방법 / 그림과 한 줄 설명으로 규칙을 보여 줘요. / 3 / 대기 안내 / 선생님이 시작할 때까지 기다려요. / TIP / 기다리는 동안 규칙 그림을 TV로 함께 보며 설명해 주세요.","no":"접속한 학생은 이 화면에서 기다립니다. 위에 개인전, 3분, 6문항 같은 게임 정보가 나오고, 왼쪽 그림으로 게임 방법을 보여 줍니다. Matching Block Game은 두 번 이내로 꺾어서 이을 수 있는 블록 가운데 같은 뜻의 블록을 연달아 누르는 게임입니다. 처음 하는 반이라면 이 그림을 보며 한 번 설명해 주시면 좋습니다.","alt":["게임 방법이 그림으로 나오는 학생 대기 화면"]},{"n":18,"t":"사전 단어 학습","sec":3,"x":"1 / 예문 보기 · 단어 음원 / 켜고 끌 수 있어요. / 2 / 전체 단어 자동 재생 / 단어를 차례로 넘겨 줘요. / 3 / 단어 목록 / 단원 단어 15개가 모두 나와요. / 4 / 단어 카드 / 그림 · 뜻 · 예문 / 5 / 게임 시작하기 / TIP / 선생님이 단어를 누르면 학생 화면에도 같은 카드가 떠요.","no":"대기 화면에서 사전 단어 학습하기를 누르면 이 화면이 열립니다. 왼쪽 단어를 누르면 오른쪽에 그림, 우리말 뜻, 예문이 크게 나옵니다. 실습 때 first를 누르자 학생 화면에도 똑같이 first 카드가 떴습니다. 게임에 들어가기 전에 단어를 함께 읽어 보고 나서 게임 시작하기를 누르시면 됩니다.","alt":["사전 단어 학습 화면"]},{"n":19,"t":"게임 시작 — 규칙 안내","sec":3,"x":"1 / 카운트다운 / 몇 초 동안 규칙을 보여 준 뒤 시작해요. / 2 / 게임 규칙 / 짝을 잘못 지으면 생명력이 깎여요. 생명력이 다 떨어지면 처음부터 다시 해요. / 규칙 한 줄 정리 / 힌트 블록과 재배치 블록끼리도 이어져요. / 힌트를 누르면 이을 수 있는 블록이 보여요. / 남은 힌트·재배치는 클리어 보너스가 돼요.","no":"선생님이 게임 시작하기를 누르면 학생 화면에 규칙 안내가 숫자를 세며 잠깐 나온 뒤 게임이 시작됩니다. 블록을 잘못 이으면 생명력이 깎이고, 생명력이 다 떨어지면 게임이 처음부터 다시 시작됩니다. 힌트 블록과 재배치 블록끼리 이으면 힌트와 재배치를 하나씩 얻는데, 쓰지 않고 남기면 끝날 때 보너스가 됩니다.","alt":["게임 시작 전 학생 화면에 뜬 규칙 안내"]},{"n":20,"t":"학생 게임 화면","sec":3,"x":"1 / 스테이지 / 3단계까지 있어요. / 2 / 10초 카운트 / 10초 안에 못 찾으면 생명력이 줄어요. / 3 / 점수 / 4 / 가능 블록 / 지금 이을 수 있는 쌍의 수 / 5 / 힌트 · 재배치 / 블록으로 얻어서 써요. / 6 / 생명력 / 5개. 다 잃으면 처음부터 다시","no":"학생이 실제로 게임하는 화면입니다. 1단계에서는 그림 블록과 영어 단어 블록을 짝지었습니다. 왼쪽 원 안 숫자가 10초부터 줄어드는데, 실습 때 그 안에 짝을 찾지 못하면 오른쪽 위 하트가 하나씩 꺼졌습니다. 하트를 다 잃으면 점수가 0으로 돌아가고 1단계부터 다시 시작했습니다. 가능 블록 숫자를 보면 지금 이을 수 있는 쌍이 몇 개인지 알 수 있습니다.","alt":["Matching Block Game 학생 게임 화면"]},{"n":21,"t":"스테이지가 올라가면","sec":3,"x":"1 / 스테이지 표시 / 1단계를 마치면 2단계로 넘어가요. / 2 / 우리말 뜻 블록 / '다섯 번째'처럼 뜻이 적혀 있어요. / 3 / 영어 단어 블록 / fifth 와 다섯 번째를 이어요. / 4 / 힌트 · 재배치 / 1단계에서 얻은 것이 남아 있어요. / 정리 / 1단계는 그림 ↔ 단어, 2단계는 단어 ↔ 우리말 뜻이었어요.","no":"1단계를 끝내면 '첫 번째 스테이지를 완료했어요' 안내와 함께 2단계로 넘어갑니다. 2단계에서는 블록이 더 많아지고, 영어 단어와 우리말 뜻을 짝짓습니다. 실습은 3분 안에 2단계까지 해 보았고, 3단계는 시간 안에 가 보지 못했습니다. 아이들에게는 시간을 조금 넉넉히 주시는 편이 좋겠다고 보았습니다.","alt":["2단계 게임 화면, 영어 단어와 우리말 뜻 블록"]},{"n":22,"t":"선생님 화면 — 게임 현황","sec":3,"x":"1 / 참여 인원 / 2 / 남은 시간 / 3 / 시간 늘리기 / 다음 쪽에서 자세히 볼게요. / 4 / 게임 결과 보기 / 시간이 끝나면 눌러요. / 5 / 순위 / 게임을 끝낸 학생으로 1~5위를 채워요. / 6 / 로켓 / 학생이 맞힐수록 위로 올라가요.","no":"게임이 시작되면 선생님 화면은 게임 현황으로 바뀝니다. 위쪽에 참여 인원과 남은 시간이 있고, 아래에는 학생마다 로켓이 하나씩 있어서 블록을 맞힐수록 로켓이 올라갑니다. 실습 때 가을토끼가 블록을 맞히자 로켓이 위로 올라갔습니다. 교실 TV에는 이 화면을 띄워 두고 진행하시면 됩니다.","alt":["선생님 게임 현황 화면, 순위 메달과 로켓"]},{"n":23,"t":"시간 늘리기와 순위 기준","sec":3,"x":"1 / 늘릴 시간 / 10 · 20 · 30 · 40 · 50초 / 2 / 증가 / 누르면 남은 시간이 그만큼 늘어요. / 순위는 이렇게 정해요 (? 버튼 안내) / 게임을 끝까지 마친 학생만 순위에 들어요. / 보너스를 더한 총점 → 본 문항 점수 → 문제 푼 시간 순으로 비교해요.","no":"게임 중에 시간이 모자라 보이면 시간을 늘릴 수 있습니다. 목록에서 10초부터 50초까지 고르고 증가를 누르면 됩니다. 실습 때 50초를 고르고 눌렀더니 남은 시간이 43초에서 1분 31초로 늘었습니다. 오른쪽의 물음표 버튼을 누르면 순위 기준이 나오는데, 게임을 끝까지 마친 학생만 순위에 들어가고 총점, 본 문항 점수, 문제 푼 시간 순서로 비교한다고 안내하고 있습니다.","alt":["게임 시간 증가 목록이 열린 게임 현황 화면"]},{"n":24,"t":"게임 결과 — 학생별","sec":4,"x":"1 / 평균 완료 시간 / 2 / 완료율 / 끝까지 마친 학생 수 / 3 / 평균 점수 / 4 / 학생별 결과 / 번호 · 닉네임, 걸린 시간, 점수, 맞힌 단어(초록) / 5 / 게임 다시하기 / 6 / 학습 종료하기 / 실습에서 겪은 일 / 생명력을 다 잃고 처음부터 다시 하다 시간이 끝나 0점이 나왔어요.","no":"시간이 끝나면 '게임 시간이 종료되었습니다' 안내가 뜨고, 게임 결과 보기를 누르면 이 화면이 나옵니다. 위쪽에 평균 완료 시간, 완료율, 평균 점수가 있고 아래에 학생별 결과가 나옵니다. 실습 때 가을토끼는 2단계까지 갔지만, 10초 제한에 자꾸 걸려 하트를 다 잃는 바람에 처음부터 다시 하다 시간이 끝났고 결과는 0점이었습니다. 저학년이나 처음 하는 반은 게임 시간을 넉넉히 주시는 편이 좋겠습니다.","alt":["학생별 게임 결과 화면"]},{"n":25,"t":"단어별 결과와 설명하기","sec":4,"x":"1 / 설명하기 / 단어별 탭에서 정답률 옆 버튼을 눌러요. / 2 / 단어 카드 / 그림 · 뜻 · 예문이 크게 떠요. / 3 / 발음 듣기 / TIP / 학생 화면에도 같은 카드가 떠요. 정답률이 낮은 단어부터 짚어 주세요.","no":"결과 화면의 단어별 탭을 누르면 단어마다 정답률 막대가 나옵니다. 실습에서는 fifth가 0%로 가장 낮았습니다. 옆의 설명하기를 누르면 그림과 뜻, 예문이 담긴 카드가 뜨고 스피커 버튼으로 발음도 들려줄 수 있습니다. 이때 학생 화면에도 같은 카드가 떠서, 게임이 끝난 뒤 바로 복습하기에 좋습니다.","alt":["단어별 결과에서 설명하기를 눌러 단어 카드가 뜬 화면"]},{"n":26,"t":"학생 결과 화면","sec":4,"x":"1 / 내 점수 / Bonus, Time Bonus가 따로 나와요. / 2 / 우리 반 평균 · 최고점 / 3 / 게임 시간 / 나, 반 평균, 가장 빠른 시간을 비교해요. / 4 / 단어별 결과 보기","no":"게임이 끝나면 학생 화면도 결과 화면으로 바뀝니다. 내 점수와 보너스, 우리 반 평균과 최고점, 게임 시간이 함께 나옵니다. 실습 결과가 0점이라 캐릭터 아래에 'You Can Do It!'이 나왔고, 뒤에 나오는 사회 게임에서 끝까지 맞혔을 때는 'Excellent'가 나왔습니다.","alt":["학생 결과 화면, 점수와 우리 반 평균, 게임 시간"]},{"n":27,"t":"한 판 더 할 때, 끝낼 때","sec":4,"x":"게임 다시하기 / 같은 접속 코드로 대기 화면에 돌아가요. / 들어와 있던 학생도 그대로 남아 있어서 바로 한 판 더 할 수 있어요. / 학습 종료하기 / 클래스게임 첫 화면으로 돌아가요. / 학생 화면에는 '선생님이 퇴장하셨습니다'가 떠요.","no":"결과 화면 위쪽의 두 버튼입니다. 게임 다시하기를 누르자 같은 접속 코드의 대기 화면으로 돌아갔고, 학생 두 명도 그대로 남아 있어 바로 다시 시작할 수 있었습니다. 학습 종료하기를 누르면 클래스게임 첫 화면으로 돌아가고, 학생 화면에는 '선생님이 퇴장하셨습니다' 안내가 떴습니다.","alt":[]},{"n":28,"t":"사회 — OX 서바이벌 설정","sec":5,"x":"1 / 교과서 / 사회 3-1 ~ 4-2 (YBM) / 2 / 단원 / 단원 단위로 골라요. / 3 / 개념어 / 단원 개념어로 OX 문제가 나와요. / 4 / 최소 단어 수 / 10단어 이상 / TIP / 순서는 영어와 같아요. 교과서 → 단원 → 게임 단어 → 게임 설정","no":"영어 말고 다른 과목도 해 보았습니다. 사회 탭의 OX 서바이벌 게임을 누르면 사회 3-1부터 4-2까지 교과서가 나옵니다. 실습에서는 4-2 1단원을 골랐고 공동체, 다수결의 원칙, 민주주의, 주민 자치 같은 개념어 15개가 나왔습니다. 문제는 이 개념어의 뜻을 설명한 문장이 맞는지 틀린지를 고르는 방식이었습니다.","alt":["사회 4-2 1단원 개념어 목록"]},{"n":29,"t":"문제별 시간 정하기","sec":5,"x":"1 / 문제별 시간 / 10초 ~ 20초 / 2 / 참여 인원 / 3 / 사전 단어 학습 / 4 / 게임방 생성하기 / 영어 게임과 다른 점 / Matching Block은 전체 시간을, OX 서바이벌은 한 문제당 시간을 정해요.","no":"게임 단어는 10개, 랜덤으로 두고 다음으로 넘어갔습니다. OX 서바이벌은 전체 게임 시간이 아니라 한 문제에 줄 시간을 10초에서 20초 사이로 정합니다. 문장을 읽어야 하는 문제라 실습에서는 가장 긴 20초로 했습니다. 나머지는 영어와 같아서 게임방 생성하기를 누르면 대기 화면이 열립니다.","alt":["OX 서바이벌 게임 설정 화면"]},{"n":30,"t":"학생 화면 — O, X 고르기","sec":5,"x":"1 / 풍선 / 문제 10개의 진행 정도 / 2 / 문제 / 개념어 뜻을 설명한 문장 / 3 / 남은 시간 / 4 / O 버튼 / 5 / X 버튼 / 누르면 원숭이가 그쪽 섬으로 건너가요. / 이 문제의 답 / O — 서명 운동의 뜻을 바르게 설명했어요.","no":"학생 화면입니다. 비행기가 문제 현수막을 끌고 들어오면 문장을 읽고 O나 X를 누릅니다. 위쪽 풍선 열 개가 문제 진행 정도를 보여 주고, 문제를 지날 때마다 색이 바뀝니다. 첫 문제는 서명 운동의 뜻을 바르게 설명한 문장이라 O를 눌렀습니다. 다른 문제 가운데는 학교 자치의 뜻에 캠페인 설명을 붙여 놓은 것처럼, 개념어끼리 헷갈리게 섞어 둔 X 문제도 있었습니다.","alt":["OX 서바이벌 학생 화면, 문제와 O X 버튼"]},{"n":31,"t":"선생님 화면 — 정답 확인과 다음 문제","sec":5,"x":"1 / 문제 번호 / 2 / 정답 확인 / 누르면 그 문제를 마감해요. / 3 / 다음 문제 / 선생님이 눌러야 넘어가요. / 4 / 학생 위치 / 고른 쪽(O, X)에 캐릭터가 서요. / 5 / 탈락자 / 틀리거나 고르지 않으면 아래로 내려가요. / TIP / 한 문제씩 넘기는 방식이라 정답 확인 뒤 한마디 설명을 덧붙이기 좋아요.","no":"선생님 화면에는 문제와 함께 학생 캐릭터가 O 쪽, X 쪽에 서는 모습이 보입니다. 정답 확인을 누르면 시간이 남아 있어도 그 문제가 마감되고, 다음 문제를 눌러야 다음 문제로 넘어갑니다. 실습 때 초록개구리는 답을 고르지 않아 첫 문제에서 바로 탈락자 칸으로 내려갔습니다. Matching Block과 달리 선생님이 속도를 조절할 수 있어서, 문제마다 짧게 설명하며 진행하기 좋다고 보았습니다.","alt":["OX 서바이벌 선생님 진행 화면"]},{"n":32,"t":"OX 서바이벌 결과","sec":5,"x":"1 / 맞힌 문제 수 분포 / 0~10 위의 숫자가 학생 수예요. / 2 / 우승 / 10문제를 모두 맞히면 Perfect! / 3 / 실패 / 탈락 전까지 맞힌 문제 수가 나와요. / 4 / 다시하기 · 학습 종료 / TIP / 단어별 탭에서 개념어별 정답률과 설명하기도 쓸 수 있어요.","no":"열 문제를 모두 진행하면 '게임이 종료되었습니다' 안내가 뜨고 결과 화면으로 갑니다. 가을토끼는 열 문제를 다 맞혀 우승과 Perfect가 표시됐고, 초록개구리는 첫 문제에서 탈락해 실패, 0문제로 나왔습니다. 위쪽 막대는 맞힌 문제 수별로 학생이 몇 명인지 보여 줍니다. 영어 게임처럼 단어별 탭에서 개념어별 정답률을 보고 설명하기로 다시 짚을 수 있습니다.","alt":["OX 서바이벌 학생별 결과, 우승 Perfect와 실패"]},{"n":33,"t":"학생 결과 화면 (사회)","sec":5,"x":"1 / 칭찬 문구 / 결과에 따라 Excellent 같은 문구가 떠요. / 2 / 우리 반 평균 / 계단 위에 반 평균 자리가 표시돼요. / 3 / 내 자리 / 내 캐릭터가 맞힌 문제 수만큼 올라가요.","no":"사회 OX 서바이벌에서 열 문제를 다 맞힌 학생 화면입니다. Excellent 문구와 함께 계단 맨 위에 캐릭터가 서 있고 우승 표시가 붙었습니다. 우리 반 평균도 계단 위에 함께 표시돼서, 아이가 반 전체 가운데 어디쯤인지 한눈에 볼 수 있습니다.","alt":["Excellent와 계단 그래프가 나온 학생 결과 화면"]},{"n":34,"t":"수학 — 연산 게임 설정","sec":5,"x":"1 / 교과서 / 수학 3-1 ~ 6-2 / 2 / 연산 단원만 / 계산 단원만 들어 있어요. / 3 / 학습 개념 / 예: 6-1 분수의 나눗셈 / 4 / 학습 유형 / (진분수)÷(자연수)처럼 계산 유형을 골라요. / 5 / 다음 / 참고 / 수학은 실습 때 이 설정 화면까지 살펴봤어요.","no":"수학 탭의 스피드 연산 게임을 열어 보았습니다. 교과서는 3-1부터 6-2까지 있고, 단어 대신 학습 개념과 학습 유형을 고릅니다. 화면에 '연산 단원만 제공됩니다'라고 적혀 있어서 6-1을 고르면 분수의 나눗셈과 소수의 나눗셈만 나왔습니다. 분수의 나눗셈을 고르면 (진분수)÷(자연수), (가분수)÷(자연수) 같은 계산 유형을 다시 고를 수 있습니다. 수학은 설정 화면까지만 확인했습니다.","alt":["수학 스피드 연산 게임 학습 개념과 유형 선택 화면"]},{"n":35,"t":"음악 게임 4가지","sec":5,"x":"1 / 붐웨커 게임 / 붐웨커를 연주하며 정확도를 겨뤄요. 개인 · 모둠 / 2 / 나만의 노래 만들기 / 노래를 만들어 친구들과 함께 들어 봐요. / 3 / 스마트 악기 연주 / 스마트 악기로 연주하고 함께 들어 봐요. / 4 / 서바이벌 퀴즈왕 / 퀴즈를 풀며 가장 오래 살아남아요. / 참고 / 설명은 게임 카드 문구 기준이에요. 수업 전에 한 번 열어 보세요.","no":"음악 탭에는 게임이 네 가지 있습니다. 붐웨커 게임은 개인전과 모둠전이 모두 되고, 나만의 노래 만들기와 스마트 악기 연주는 만든 노래나 연주를 친구들과 함께 들어 보는 활동입니다. 서바이벌 퀴즈왕은 카드 그림으로 보아 사회 OX 서바이벌과 비슷하게 두 섬 가운데 하나를 고르는 방식으로 보였습니다. 음악 게임은 카드 설명만 확인했으니 수업에 쓰시기 전에 한 번 열어 보시길 권해 드립니다.","alt":["음악 게임 목록"]},{"n":36,"t":"꼭 알아 둘 점","sec":6,"x":"처음 한 번 계정 연동 / 배움터와 Y클라우드 계정이 연결돼요. 로그인한 이름부터 확인해 주세요. / 만 14세 미만 동의 / 학생 참여에는 법정대리인 동의가 필요해요. 대기 화면 안내에 가정통신문 서식이 있어요. / YBM 교과서 기준 / 영어는 주제별 단어로 대신할 수 있어요. 사회는 3~4학년, 수학은 연산 단원만 있어요. / 10초 · 생명력 규칙 / Matching Block은 생명력을 다 잃으면 처음부터 다시 해요. 시간을 넉넉히 주세요. / 닉네임 규칙 / 로그인 없이 닉네임으로 들어와요. 실명 대신 정한 규칙으로 안내해 주세요. / 앱 설치 없이 / 학생은 브라우저에서 ybmcloud.com/game1 로 들어와요.","no":"대기 화면에 '서비스 이용 시 만 14세 미만 법정대리인 동의 안내'가 있어 눌러 보니 Y클라우드 공지로 연결되었습니다. 학생이 QR 코드나 URL로 들어와 쓰는 서비스라서 개인정보 보호법에 따라 법정대리인 동의가 필요하고, 학교 사정에 맞게 사전 동의나 사후 동의를 받으라고 안내하고 있습니다. 공지 안에 가정통신문 서식도 있으니 처음 쓰시기 전에 확인해 주세요. 교과서는 YBM 기준이라 다른 출판사를 쓰는 반은 영어 주제별 단어나 OX형 게임부터 써 보시면 좋겠습니다.","alt":[]},{"n":37,"t":"수업에서 이렇게 써 보세요","sec":6,"x":"단원 도입 / 사전 단어 학습 → 게임 / 새 단원 단어를 카드로 함께 읽고, 바로 Matching Block으로 짝지어 봐요. / 차시 마무리 / OX 서바이벌로 개념 확인 / 정답 확인을 누를 때마다 한 문장씩 짚어 주면 개념 정리가 돼요. / 다음 차시 복습 / 정답률 낮은 단어부터 / 단어별 결과에서 정답률이 낮은 단어를 골라 설명하기로 다시 보여 줘요. / 반복 연습 / 수학 연산 게임 / 계산 유형을 좁혀 골라 짧게 여러 번 해요. 게임 다시하기로 같은 코드를 그대로 써요.","no":"직접 써 보면서 떠올린 활용 방법입니다. 영어는 사전 단어 학습과 Matching Block을 이어서 단원 도입에, 사회는 OX 서바이벌을 차시 마무리에 쓰면 좋겠다고 생각했습니다. 결과 화면의 단어별 정답률을 보고 다음 시간에 낮은 단어부터 설명하기로 다시 짚어 주는 것도 방법입니다. 수학은 계산 유형을 좁혀서 짧게 여러 번 반복하는 데 맞아 보였습니다.","alt":[]},{"n":38,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 처음 계정 연동 / 배움터에서 들어가 연동하는 과정을 함께해요. / 첫 게임방 함께 열기 / 교실 TV로 처음 진행할 때 옆에서 도와드려요. / 단원에 맞는 게임 고르기 / 과목과 단원에 맞는 게임과 단어를 함께 골라요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 처음 계정을 연동하거나 첫 게임방을 여실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,58994],[58994,49420],[108414,57858],[166272,57092],[223364,77240],[300604,75696],[376300,96460],[472760,65090],[537850,87502],[625352,72954],[698306,75970],[774276,66880],[841156,64024],[905180,80614],[985794,81244],[1067038,73252],[1140290,78812],[1219102,71988],[1291090,82496],[1373586,73316],[1446902,81278],[1528180,71980],[1600160,67868],[1668028,64702],[1732730,65228],[1797958,60608],[1858566,39430],[1897996,60496],[1958492,54790],[2013282,79802],[2093084,69262],[2162346,53584],[2215930,58150],[2274080,59242],[2333322,85126],[2418448,66018],[2484466,58352],[2542818,39888]],"toffs":[[0,5258],[5258,3908],[9166,4904],[14070,4506],[18576,6426],[25002,6240],[31242,8162],[39404,4618],[44022,6738],[50760,6404],[57164,5818],[62982,5536],[68518,5478],[73996,6102],[80098,6012],[86110,6770],[92880,6126],[99006,6088],[105094,5836],[110930,6034],[116964,7112],[124076,6570],[130646,6052],[136698,5312],[142010,5714],[147724,5672],[153396,3336],[156732,4918],[161650,4544],[166194,7096],[173290,6080],[179370,4496],[183866,5260],[189126,4852],[193978,7364],[201342,4616],[205958,4456],[210414,3914]],"packSize":2582706,"thumbSize":214328},{"key":"readingn","name":"리딩앤","title":"리딩앤 사용 안내서","group":"subject","sub":"경북AI배움터로 접속해 영어 독서 수업 준비하기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"배움터로 들어가면 이용권이 적용돼요. LMS 대시보드의 이용권 만료 예정일은 2027. 6. 1.이에요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 리딩앤 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 리딩앤에 접속하고 두 화면을 구분해요"},{"start":6,"num":"2","label":"학습 화면 시작","desc":"학습 화면에 처음 들어가 학습자 정보를 입력해요"},{"start":7,"num":"3","label":"LMS 반 세팅","desc":"LMS에서 수업을 만들고 학생을 배정하고 이용권을 써요"},{"start":14,"num":"4","label":"수업에 쓰기","desc":"숙제, 리딩러너, 월간 리포트로 수업에 활용해요"},{"start":17,"num":"5","label":"자료 챙기기","desc":"학습지, 교과 연계 도서, 이용권 현황을 챙겨요"},{"start":20,"num":"6","label":"유의사항과 활용","desc":"유의사항과 수업 활용 아이디어"}],"slides":[{"n":1,"t":"리딩앤","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 영어 독서 수업 준비하기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 리딩앤을 같이 살펴보겠습니다. 리딩앤은 레벨별 영어 그림책을 읽는 서비스이고, 선생님은 LMS라는 관리 화면에서 반을 만들고 숙제를 낼 수 있습니다. 연수 준비하면서 실제 계정으로 수업을 하나 만들어 보았고, 그때 찍은 화면으로 안내드리겠습니다.","alt":["리딩앤 접속 화면: 학습하러 가기와 LMS 바로가기"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 리딩앤, 두 갈래 화면 / 04–05쪽 / STEP 2 / 학습 화면 시작 / 학습자 정보 입력(최초 1회) / 06쪽 / STEP 3 / LMS 반 세팅 / 수업 추가, 학생 배정, 이용권 / 07–13쪽 / STEP 4 / 수업에 쓰기 / 숙제, 리딩러너, 월간 리포트 / 14–16쪽 / STEP 5 / 자료 챙기기 / 학습지, 교과 연계 도서, 이용권 현황 / 17–19쪽 / STEP 6 / 유의사항과 활용 / 로그아웃·학생 확인, 활용 아이디어 / 20–21쪽","no":"여섯 단계로 진행하겠습니다. 핵심은 3단계 LMS 반 세팅입니다. 수업을 만들고, 학생을 배정하고, 이용권을 쓰는 데까지 해 두셔야 학생들 화면에 책이 보입니다. 시간이 부족하면 3단계와 4단계의 숙제 만들기만이라도 꼭 같이 해 보셨으면 합니다.","alt":[]},{"n":3,"t":"리딩앤으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 레벨별 영어책 / 리딩앤 레벨·시리즈·주제로 골라 읽어요 / 읽고 녹음하기 / 책 속 문장 녹음과 단계별 활동 기록이 남아요 / LMS로 반 관리 / 수업 만들기, 학생 배정, 숙제, 리딩러너 / 기록과 리포트 / 월간 리포트, 학습 기록 엑셀 다운로드 / 들어가는 문은 두 개 / 학습하러 가기 LMS 바로가기 / 책은 학습 화면에서 읽고, 반과 숙제는 선생님 전용 LMS에서 관리해요. / 이용권 만료 예정일: 2027년 6월 1일 (LMS 대시보드 표시 기준)","no":"리딩앤은 크게 두 화면으로 나뉩니다. 학생과 선생님이 같이 쓰는 학습 화면에서는 책을 읽고, 선생님만 쓰는 LMS에서는 반을 만들고 숙제를 냅니다. 이 둘을 구분해 두시면 덜 헤매실 것 같습니다. 이용권 만료 예정일은 연수 준비 때 LMS 대시보드에 2027년 6월 1일로 표시돼 있었습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 리딩앤 열기","sec":1,"x":"1 / 에듀테크 서비스 → 리딩앤 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 소개 문구 / 영어 레벨별 디지털 도서로 단계적으로 읽기 실력을 키우는 서비스라고 나와요. / TIP / 누르면 새 탭에서 리딩앤이 열리고 배움터 계정으로 바로 들어가요. 따로 가입하지 않아도 돼요.","no":"배움터 메인 화면의 에듀테크 서비스 첫 줄에 리딩앤이 있습니다. 미리캔버스 때와 마찬가지로 누르기만 하면 배움터 계정으로 자동 로그인됩니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록과 리딩앤 소개 문구"]},{"n":5,"t":"두 갈래 중 하나를 고르는 화면","sec":1,"x":"1 / 학습하러 가기 / 책을 읽는 학습 사이트예요. 학생과 선생님이 함께 써요. / 2 / LMS 바로가기 / 선생님용 학습 관리 화면이에요. 반·학생·숙제를 여기서 관리해요. / TIP / 태블릿은 '리딩앤' 앱이 설치돼 있어야 하고, LMS는 PC 접속을 권장한다고 화면에 안내돼 있어요.","no":"리딩앤을 누르면 먼저 이 선택 화면이 나옵니다. 책을 읽을 때는 왼쪽, 반을 관리할 때는 오른쪽입니다. 학생들은 왼쪽만 쓰면 되고, 선생님은 두 곳을 오가게 됩니다.","alt":["리딩앤 서비스 선택 화면"]},{"n":6,"t":"처음 한 번, 학습자 정보 입력하기","sec":2,"x":"1 / 이름 · 생년월일 / 학습하러 가기를 처음 누르면 이 창이 뜨고 닫히지 않아요. 최초 1회만 입력해요. / 2 / 저장하기 / 저장하면 내 서재가 열려요. 리딩앤 레벨·시리즈·주제별로 책을 찾을 수 있어요. / TIP / 학생들도 실명으로 입력하도록 안내해 주세요. LMS 학생 현황에서 우리 반 학생을 찾기가 쉬워져요.","no":"학습 화면에 처음 들어가면 학습자 정보 창이 뜹니다. 배움터 공식 안내에도 최초 1회 입력 후 이용이라고 나와 있습니다. 리딩앤 쪽 세팅 가이드에서도 학생 이름을 알아보기 쉽게 정해 두면 나중에 배정하기 편하다고 안내하고 있어서, 학생들에게 실명으로 넣도록 지도해 주시면 좋겠습니다.","alt":["학습자 정보 추가하기 창"]},{"n":7,"t":"LMS 대시보드 둘러보기","sec":3,"x":"1 / 왼쪽 메뉴 / 수업 관리, 학생 관리, 학습 자료실, 사용 가이드, 학교 교육 연계 / 2 / 요약 통계 / 총 수업 수, 총 학생 수, 배정을 기다리는 대기 학생 수 / 3 / 교육기관 코드 / 학교마다 정해진 코드예요. 배움터로 처음 들어온 학생은 대기 학생으로 잡혀요. / TIP / 아래로 내리면 성취 현황(레벨별 학생 수, 많이 읽은 시리즈, 녹음 문장, 완독 메달)과 이용권 현황이 이어져요.","no":"LMS 바로가기를 누르면 대시보드가 먼저 열립니다. 연수 준비 때는 수업이 0개, 배정을 기다리는 학생이 2명으로 나와 있었습니다. 학생이 배움터를 거쳐 리딩앤에 한 번 들어오면 이 대기 학생 숫자에 잡힌다고 이해하시면 됩니다.","alt":["리딩앤 LMS 대시보드"]},{"n":8,"t":"반 세팅은 네 단계면 끝나요","sec":3,"x":"1 / 학생 첫 접속 / 학생이 학습하러 가기로 들어와 학습자 정보를 저장하면 LMS에 '배정 대기중'으로 들어와요. / 2 / 수업 추가 / 수업 관리 → 수업 현황 → 수업 추가하기에서 우리 반을 만들어요. / 3 / 학생 배정 / 학생 관리 → 학생 현황에서 학생을 체크하고 배정하기를 눌러요. / 4 / 이용권 사용 / 수업 상세에서 이용권을 쓰면 학생 화면에 책이 보이기 시작해요. / 순서가 중요해요 / 학생이 먼저 한 번 접속해야 LMS에서 배정할 수 있어요. 첫 시간에 학생들과 같이 1단계를 해 두면 편해요.","no":"리딩앤 공식 LMS 세팅 가이드의 순서를 배움터 화면에 맞춰 네 단계로 정리했습니다. 배움터 Q&A 답변에서도 학생이 최초 접속한 뒤에 선생님 LMS에 학생 정보가 생긴다고 안내하고 있었습니다. 그래서 첫 수업 시간에 학생들과 함께 학습하러 가기까지 들어가 보는 것을 추천드립니다.","alt":[]},{"n":9,"t":"수업 현황에서 수업 추가하기","sec":3,"x":"1 / 수업 추가하기 / 반(수업)을 새로 만드는 버튼이에요. / 2 / 학습 기록 다운로드 / 시작일과 종료일을 정하고 엑셀로 학습 기록을 내려받아요. / TIP / 만든 수업은 아래 목록에 수업명·콜렉션·선생님·학생 수로 쌓여요.","no":"왼쪽 메뉴에서 수업 관리, 수업 현황으로 들어오시면 됩니다. 처음에는 목록이 비어 있고, 오른쪽 위 초록 버튼으로 수업을 만듭니다.","alt":["LMS 수업 현황 화면"]},{"n":10,"t":"수업 정보 입력하기","sec":3,"x":"1 / 수업명 / 예: 6학년 1반 영어. 학년과 반이 드러나게 지어 주세요. / 2 / 콜렉션 / '[교육청] 리딩앤스쿨'이 자동으로 들어가 있어요. / 3 / 선생님 / 목록에서 담당 선생님(본인)을 골라요. / 4 / 추가 / 누르면 '수업 추가 완료' 창이 뜨고 상세보기로 이어져요. / 주의 / 수업명에 대괄호 [ ]를 넣었더니 추가를 눌러도 수업이 만들어지지 않았어요. 괄호 없이 써 주세요.","no":"수업명, 콜렉션, 선생님 세 칸만 채우면 됩니다. 콜렉션은 교육청 리딩앤스쿨이 이미 들어가 있습니다. 연수 준비 때 수업명 앞에 대괄호를 붙였더니 아무 반응 없이 만들어지지 않았고, 괄호를 빼니 바로 만들어졌습니다. 수업명에는 기호를 넣지 않는 편이 안전하다고 생각합니다.","alt":["수업 추가하기 입력 창"]},{"n":11,"t":"수업 상세 화면","sec":3,"x":"1 / 상세 정보 / 수업명, 콜렉션, 선생님, 이번 달 목표 권수, 리딩앤 레벨 / 2 / 수정하기 · 삭제하기 / 수업명이나 목표 권수를 바꿀 때 써요. / 3 / 수업 상세 · 리딩러너 관리 / 두 탭으로 나뉘어요. 숙제와 학생은 수업 상세 탭에 있어요. / TIP / 수업 목록에서 수업명을 누르면 언제든 이 화면으로 다시 들어올 수 있어요.","no":"상세보기를 누르면 이 화면이 열립니다. 위쪽은 수업 정보, 아래쪽은 숙제와 학생 관리입니다. 이번 달 목표 권수는 수정하기에서 바꿀 수 있습니다.","alt":["수업 상세 화면 위쪽"]},{"n":12,"t":"배정 대기 학생을 수업에 넣기","sec":3,"x":"1 / 배정 대기중 / 배움터로 처음 들어온 학생이 이렇게 표시돼요. / 2 / 체크 → 배정하기 / 우리 반 학생을 체크하면 아래에 배정하기 버튼이 나타나요. 수업을 골라 넣어요. / TIP / 수업 상세 화면의 '학생 배정하기' 버튼으로도 같은 일을 할 수 있어요.","no":"학생 관리, 학생 현황으로 들어오면 대기 중인 학생 목록이 나옵니다. 화면 속 학생 이름과 아이디는 흐리게 처리했습니다. 체크한 뒤 배정하기를 누르고 수업을 고르면 됩니다.","alt":["학생 현황 화면(학생 이름 흐림 처리)"]},{"n":13,"t":"수업 상세 아래쪽: 숙제와 학생 관리","sec":3,"x":"1 / 숙제 만들기 / 책과 기한을 정해 숙제를 내요(14쪽). / 2 / 학생 배정하기 / 대기 학생을 이 수업으로 불러와요. / 3 / 이용권 사용 · 자동 사용 / 학생을 체크해 이용권을 쓰면 학생 화면에 책이 보여요. / 4 / 리딩앤 레벨 조회 / 학생별 레벨 테스트 결과를 확인해요. / TIP / 이용권 자동 사용을 켜 두면 매월 1일 기준으로 이용권이 자동으로 쓰여요.","no":"수업 상세 화면을 내리면 숙제 관리와 학생 관리가 나옵니다. 리딩앤 세팅 가이드에 따르면 학생에게 이용권을 부여해야 학습 사이트에서 책이 보입니다. 배정까지만 하고 이용권을 빠뜨리면 학생 화면이 비어 있을 수 있으니 꼭 확인해 주세요.","alt":["수업 상세 화면 아래쪽의 숙제 관리와 학생 관리"]},{"n":14,"t":"숙제 만들기","sec":4,"x":"1 / 숙제 기한 / 시작일과 마감일을 달력에서 골라요. / 2 / 책 리스트 / 레벨·시리즈로 거르거나 제목으로 검색해요. / 3 / 추가하기 / 숙제로 낼 책을 담아요. '추가한 책' 탭에서 확인해요. / 4 / 누르면 수업 학생들에게 숙제가 나가요. / TIP / '이어서 신규 숙제 만들기'에 체크하면 창을 닫지 않고 다음 숙제를 바로 만들 수 있어요.","no":"수업 상세에서 숙제 만들기를 누르면 이 창이 뜹니다. 기한을 정하고, 책을 골라 담고, 숙제 만들기를 누르면 됩니다. 교과서 단원과 연결된 책은 18쪽의 교과 연계 콘텐츠에서 찾을 수 있습니다.","alt":["숙제 만들기 창"]},{"n":15,"t":"리딩러너로 3주 읽기 일정 잡기","sec":4,"x":"1 / 시작일 고르기 / 수업 상세의 리딩러너 관리 탭 → 새 리딩러너 일정 생성 / 2 / 종료일은 자동 / 시작일로부터 21일 뒤로 자동으로 정해져요. / TIP / 진행 중인 일정과 예정된 일정이 따로 보이고, 지난 일정은 리딩러너 내역에 쌓여요.","no":"리딩러너는 수업 상세의 두 번째 탭에 있습니다. 시작일만 고르면 종료일이 21일 뒤로 자동으로 잡힙니다. 학생 화면 위쪽 메뉴에도 리딩러너가 있어서, 정해 둔 3주 동안 반 전체가 함께 읽어 나가는 일정으로 쓰시면 될 것 같습니다.","alt":["새 리딩러너 일정 생성 창"]},{"n":16,"t":"월간 리포트 보기","sec":4,"x":"1 / 조회 기간 / 달 단위로 골라요. / 2 / 수업 선택 / 전체 수업 또는 특정 수업을 골라요. / 3 / 조회 / 선생님이나 학생 이름으로도 찾을 수 있어요. / 4 / 안내 문구 / 학습 이력이 없는 학생은 리포트를 볼 수 없어요. / TIP / 학부모 상담이나 학기말 기록 전에 한 번씩 열어 보시면 좋아요.","no":"수업 관리 아래 월간 리포트 메뉴입니다. 달을 고르고 조회하면 수업별로 리포트를 볼 수 있습니다. 학생이 책을 한 권도 읽지 않았다면 리포트가 나오지 않는다는 점만 기억해 주세요.","alt":["월간 리포트 검색 화면"]},{"n":17,"t":"학습 자료실: 책별 학습지","sec":5,"x":"1 / 도서 검색 / 책 제목으로 찾아요. / 2 / 자료 표시 / 레벨차트, General·Specific Question, 프리미엄 자료를 아이콘으로 구분해요. / 3 / 다운로드 / 단어 학습, 내용 이해, 등장인물 분석, Writing sheet 학습지를 받아요. / TIP / 책을 읽은 뒤 바로 쓸 수 있는 활동지라, 인쇄해서 개인 활동으로 쓰기 좋아요.","no":"학습 자료실의 기타 학습 자료에는 책마다 활동지가 붙어 있습니다. 단어 학습, 내용 이해, 등장인물 분석처럼 읽은 뒤 바로 해 볼 수 있는 활동이라 개인 활동지로 쓰기 좋다고 생각합니다.","alt":["기타 학습 자료 목록"]},{"n":18,"t":"교과서 단원과 연결된 책 찾기","sec":5,"x":"1 / 출판사 10종 / LMS 메뉴 학교 교육 연계 → 초등 교과 연계 콘텐츠. 출판사를 누르면 학년·단원별 연계 도서가 나와요. / 2 / 전체 도서 목록 / 리딩앤스쿨에 있는 책 전체를 볼 수 있어요. / 3 / 가정통신문 / 개인정보 동의서와 리딩앤스쿨 사용법이 담긴 한글 파일이에요. / TIP / 학생 개인정보가 들어간 LMS 계정을 만들 때는 이 동의서를 꼭 받으라고 안내돼 있어요.","no":"LMS 왼쪽 메뉴의 학교 교육 연계를 누르면 초등 교과 연계 콘텐츠 페이지가 열립니다. 우리 학교 교과서 출판사를 누르면 단원마다 어울리는 책이 정리돼 있어서, 숙제를 고를 때 이 페이지부터 보시면 시간이 많이 줄어들 것 같습니다.","alt":["초등 교과 연계 콘텐츠 페이지"]},{"n":19,"t":"이용권 현황과 안내 자료","sec":5,"x":"1 / 이용권 현황 / 콜렉션별 사용 중 인원, 잔여 이용권, 만료 예정일을 보여 줘요. / 2 / 안내 자료 / 사용 가이드, 리딩&레벨 차트, 프로그램 소개자료, 교과연계 커리큘럼 / TIP / 잔여 이용권 수는 계정마다 다를 수 있어요. 학생을 배정하기 전에 한 번 확인해 주세요.","no":"대시보드를 맨 아래까지 내리면 이용권 현황과 안내 자료 버튼이 있습니다. 레벨 차트와 교과연계 커리큘럼은 내려받아 두시면 책 고를 때 참고하기 좋습니다.","alt":["대시보드 아래쪽의 이용권 현황과 안내 자료"]},{"n":20,"t":"알아 두면 덜 헤매요","sec":6,"x":"1 / 30분 동안 안 쓰면 로그아웃 / '로그인이 필요해요'가 뜨면 배움터에서 리딩앤을 다시 눌러 주세요. / · / 학생이 LMS에 안 보일 때 / 학생이 학습하러 가기로 한 번 들어와 학습자 정보를 저장했는지 먼저 확인해요. / · / 수업명은 기호 없이 / 대괄호 [ ]가 들어가면 수업이 만들어지지 않았어요. / TIP / 같은 사례가 배움터 Q&A에도 올라와 있어서, 막히면 검색해 보시면 도움이 돼요.","no":"리딩앤은 30분 넘게 쓰지 않으면 세션이 끝납니다. 이때는 리딩앤 주소로 바로 들어가지 마시고 배움터에서 다시 눌러 주셔야 합니다. 학생이 LMS에 보이지 않는 경우는 대부분 학생이 아직 학습 화면에 한 번도 들어오지 않은 경우였습니다.","alt":["세션 만료 안내 화면"]},{"n":21,"t":"수업에 이렇게 써 보세요","sec":6,"x":"단원 연계 읽기 / 교과 연계 콘텐츠에서 단원 도서 고르기 → 숙제로 내기 / 3주 읽기 일정 / 리딩러너 21일 일정으로 반 전체 읽기 습관 만들기 / 읽고 나서 학습지 / 기타 학습 자료의 단어·내용 이해 활동지로 개인 활동 / 기록으로 피드백 / 월간 리포트로 개별 칭찬과 상담 자료 준비 / 학생과 함께 쓰려면 / 배움터에서 학생 배정이 먼저 필요하고, 에듀테크 활용 개인정보 동의서(가정통신문)를 받아야 해요.","no":"교과서 단원과 연결된 책을 숙제로 내고, 리딩러너로 3주 동안 함께 읽고, 읽은 뒤에는 학습지로 정리하는 흐름을 추천드립니다. 학생과 함께 쓰시려면 배움터 학생 배정과 개인정보 동의서가 먼저 필요하니 말씀해 주세요.","alt":[]},{"n":22,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 반 세팅 함께하기 / 수업 만들기부터 학생 배정, 이용권 사용까지 같이 해 드려요. / 책 · 숙제 고르기 / 교과서 단원에 맞는 책과 숙제 내는 법을 알려 드려요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 반 세팅은 교실로 찾아가 함께 처리해 드리겠습니다.","alt":[]}],"offs":[[0,41150],[41150,50752],[91902,56282],[148184,60602],[208786,58564],[267350,69614],[336964,60790],[397754,64096],[461850,50832],[512682,55728],[568410,58916],[627326,50238],[677564,70248],[747812,61544],[809356,56682],[866038,59570],[925608,85516],[1011124,83790],[1094914,52752],[1147666,55154],[1202820,54568],[1257388,40624]],"toffs":[[0,3464],[3464,4032],[7496,4742],[12238,4668],[16906,4662],[21568,5064],[26632,4596],[31228,5178],[36406,3894],[40300,4474],[44774,4302],[49076,3678],[52754,5268],[58022,4894],[62916,4598],[67514,4396],[71910,5608],[77518,5990],[83508,3864],[87372,3952],[91324,4374],[95698,3964]],"packSize":1298012,"thumbSize":99662},{"key":"vocatrain","name":"보카트레인","title":"보카트레인 사용 안내서","group":"subject","sub":"단어장 만들기부터 배포 · 테스트까지 영단어 학습을 한곳에서","fee":"유료 기능 적용","feeKind":"paid","feeNote":"월 이용료가 있는 유료 서비스(무료 체험 7일)예요. 배움터로 들어가면 결제 없이 학교 관리자 화면을 쓰고, 체험 기간이 지나도 그대로 써져요. 설정 화면에 이용 기간 표시는 없어요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 보카트레인 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 보카트레인 관리자 화면에 접속하고 둘러봐요"},{"start":7,"num":"2","label":"반 · 학생 준비","desc":"반을 만들고 학생을 확인해 반에 배정해요"},{"start":11,"num":"3","label":"단어장 만들기","desc":"교과서 단어장을 가져오거나 우리 반 단어장을 직접 만들어요"},{"start":18,"num":"4","label":"배포와 학습","desc":"단어장을 학생에게 배포하고 학습 단계를 이해해요"},{"start":22,"num":"5","label":"온라인 테스트","desc":"온라인 단어 테스트를 만들고 결과를 확인해요"},{"start":31,"num":"6","label":"종이 시험지","desc":"종이 단어 시험지와 답안지를 출력해요"},{"start":35,"num":"7","label":"더 알아 두기","desc":"퀴즈, 성적, 설정, 유의사항과 수업 활용"}],"slides":[{"n":1,"t":"보카트레인","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 단어장 만들기부터 배포 · 테스트까지 영단어 학습을 한곳에서 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 보카트레인을 함께 써 보겠습니다. 보카트레인은 영단어 학습 서비스로, 선생님은 관리자 화면에서 단어장을 만들어 보내고 테스트와 성적을 관리하고, 학생은 받은 단어장으로 단계별 암기 학습을 합니다. 화면 속 그림은 연수 준비하면서 실제로 테스트를 만들어 보다가 찍은 출제 방식 선택 창입니다.","alt":["보카트레인 테스트 출제 방식 선택 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 보카트레인, 첫 화면 / 04–06쪽 / STEP 2 / 반 · 학생 준비 / 반 만들기, 학생 확인, 반배정 / 07–10쪽 / STEP 3 / 단어장 만들기 / 교과서 단어장, 우리 반 단어장 / 11–17쪽 / STEP 4 / 배포와 학습 / 단어장 보내기, 학습 단계 / 18–21쪽 / STEP 5 / 온라인 테스트 / 출제, 제출 현황, 결과 조회 / 22–30쪽 / STEP 6 / 종이 시험지 / 시험지 · 답안지 출력 / 31–34쪽 / STEP 7 / 더 알아 두기 / 퀴즈, 성적, 설정, 유의사항 / 35–39쪽","no":"오늘은 일곱 단계로 진행합니다. 접속해서 반과 학생을 확인하고, 단어장을 만들어 학생에게 보낸 다음, 온라인 테스트와 종이 시험지까지 한 번씩 만들어 보겠습니다. 시간이 부족하면 3단계 단어장 만들기와 6단계 종이 시험지만 꼭 해 보세요. 학생 계정이 없어도 바로 해 볼 수 있는 부분입니다.","alt":[]},{"n":3,"t":"보카트레인으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 교과서 단어장 / 출판사별 3~6학년 교과서 빈출 단어(2022 개정) / 우리 반 단어장 / 직접 입력 · 붙여넣기 · 엑셀로 만들기 / 단계별 암기 학습 / 보고 · 듣고 · 써 보며 단어 익히기 / 테스트와 시험지 / 자동 채점 온라인 테스트, 종이 시험지 출력 / 배움터와 연결 / 배움터 로그인 한 번이면 끝 / 선생님은 관리자 화면에서 단어장 · 배포 · 테스트 · 성적을 관리하고, 학생은 받은 단어장으로 공부해요. / 같은 학교 선생님들이 관리자 화면 하나를 함께 써요.","no":"배움터에서 보카트레인 위에 마우스를 올리면 \"학생은 보고 듣고 써 보며 단어를 익히고, 교사는 단어장 배포와 자동 채점, 통계로 학습을 관리하는 영단어 학습 서비스\"라고 소개되어 있습니다. 출판사별 초등 교과서 단어장이 이미 들어 있어서 우리 학교 교과서에 맞춰 바로 쓸 수 있다는 점이 가장 편하다고 느꼈습니다. 다만 관리자 화면은 학교 단위로 함께 쓰는 구조라서, 다른 선생님 반 학생도 목록에 같이 보인다는 점은 기억해 두시면 좋겠습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 보카트레인 열기","sec":1,"x":"1 / 에듀테크 서비스 → 보카트레인 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 보카트레인 관리자 화면이 바로 열려요. / TIP / 따로 회원가입하거나 비밀번호를 넣지 않아도 돼요. 처음 들어가면 선생님 계정이 자동으로 등록돼요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 메인 화면의 에듀테크 서비스 첫 페이지 여덟 번째 칸에 보카트레인이 있습니다. 누르면 새 탭으로 관리자 화면이 열리고 배움터 계정으로 바로 로그인됩니다. 처음 들어간 선생님은 선생님 관리 목록에 자동으로 추가되는 것을 확인했습니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록과 보카트레인 설명"]},{"n":5,"t":"관리자 화면 첫 모습","sec":1,"x":"1 / 왼쪽 메뉴 / 반 · 학생 · 교재 · 테스트 · 퀴즈 · 성적 · 설정이 모여 있어요. / 2 / 재원생(전체반) / 반마다 학생 수가 보여요. 미배정은 아직 반이 없는 학생이에요. / 3 / 나의 교재 목록 / 내가 만든 단어장이 폴더별로 보여요. / 4 / 학습완료 · 미학습 / 달력에서 고른 날짜에 공부한 학생과 안 한 학생을 나눠 봐요. / 5 / 메뉴얼 보기 / 업체가 만든 선생님 매뉴얼(PDF)이 열려요.","no":"들어가면 바로 이 초기화면이 나옵니다. 가운데 공지사항에는 업데이트 소식이 올라오고, 오른쪽에는 반별 학생 수와 내 교재가 보입니다. 아래 달력에서 날짜를 고르면 그날 학습을 마친 학생과 아직 안 한 학생을 나눠서 볼 수 있습니다. 왼쪽 아래 메뉴얼 보기를 누르면 업체에서 만든 선생님 매뉴얼 PDF가 열리니, 연수 뒤에 참고하셔도 좋습니다.","alt":["보카트레인 관리자 초기화면"]},{"n":6,"t":"같은 학교 선생님과 함께 쓰는 화면","sec":1,"x":"1 / 선생님 관리 / 우리 학교에서 보카트레인에 들어온 선생님이 모두 보여요. / · / 반 · 학생 · 교재도 함께 보여요 / 다른 선생님 반에 단어장이나 테스트를 보내지 않도록 반 이름을 꼭 확인해요. / · / 설정은 상의 후에 / 보카트레인 설정은 다른 반에도 영향을 줄 수 있어, 바꾸기 전에 함께 이야기해 주세요. / TIP / 반 이름은 '6-3'처럼 학년-반으로 지으면 목록에서 찾기 쉬워요.","no":"연수를 준비하면서 가장 먼저 눈에 띈 점입니다. 보카트레인 관리자 화면은 선생님마다 따로 있는 게 아니라 학교 단위로 하나를 함께 씁니다. 그래서 클래스 관리나 학생 관리에 다른 선생님 반과 학생도 같이 보입니다. 화면 속 아이디와 이름은 개인정보라서 흐리게 가렸습니다.","alt":["선생님 관리 화면(아이디와 이름은 흐리게 처리)"]},{"n":7,"t":"우리 반 만들기","sec":2,"x":"1 / 반이름 / '6-3'처럼 학년-반으로 적어요. / 2 / 담임 / 목록에서 내 이름을 골라요. / 3 / 반별 학습 설정 / 랭킹 표기 · 학습모듈 스킵 · All Books 사용 여부 / 4 / 전송 / 누르면 반이 만들어져요.","no":"클래스 관리 화면 왼쪽 아래 아이콘 줄에서 맨 앞 보라색 사람 아이콘이 반 생성입니다. 누르면 이 창이 뜹니다. 반이름을 적고 담임을 내 이름으로 고른 뒤 전송을 누르면 됩니다. 연수 때는 다른 선생님 반과 헷갈리지 않도록 반이름과 담임을 꼭 확인해 주세요. 저는 화면만 확인하고 실제로 반을 만들지는 않았습니다.","alt":["반 생성 창(담임 이름은 흐리게 처리)"]},{"n":8,"t":"반 목록 살펴보기","sec":2,"x":"1 / 수정 · 삭제 / 연필로 반 정보를 고치고, 휴지통으로 지워요. / 2 / 반별 학습 설정 / 랭킹 표기, 학습모듈 스킵, All Books 사용 여부를 반마다 다르게 둘 수 있어요. / 3 / 아래 아이콘 줄 / 반 생성 · 반 정보 수정 · 조회 · 삭제 · 검색 / TIP / 학습모듈 스킵은 '미사용'을 권해요. 단계를 건너뛰면 학습 능률이 떨어져 권장하지 않는다고 안내돼 있어요.","no":"반 목록에서 각 반의 학습 설정이 한눈에 보입니다. 랭킹 표기는 학생 학습 결과로 순위를 보여 줄지, 학습모듈 스킵은 학습 단계를 건너뛸 수 있게 할지, All Books는 기본 교재를 학생에게 보여 줄지를 정합니다. 보카트레인 설정 화면 설명에도 학습모듈 스킵은 학습 능률 때문에 권장하지 않는다고 나와 있습니다.","alt":["클래스 관리 화면(담임 이름은 흐리게 처리)"]},{"n":9,"t":"학생 목록 확인하기","sec":2,"x":"1 / 반목록으로 거르기 / 반을 고르고 조회를 눌러요. / 2 / STUDY · TEST / 학생 한 명의 학습 기록과 테스트 결과를 바로 봐요. / 3 / 아래 아이콘 / 반배정 · 학년 일괄등록 · 엑셀로 내보내기 / · / 학생은 언제 보이나요? / 학생이 배움터에서 보카트레인에 처음 들어오면 이 목록에 생겨요.","no":"학생 관리에서는 학생을 직접 만들지 않습니다. 배움터에서 학생을 배정해 두면, 학생이 배움터로 보카트레인에 처음 들어온 순간 이 목록에 자동으로 생깁니다. 매뉴얼에도 학생이 최초 접속한 뒤 학생관리에 보인다고 되어 있습니다. 화면 속 학생은 다른 반 학생이라 이름과 아이디를 흐리게 처리했습니다.","alt":["학생 관리 화면(아이디와 이름은 흐리게 처리)"]},{"n":10,"t":"처음 들어온 학생을 우리 반에 넣기","sec":2,"x":"1 / 학생 체크 / 반을 정할 학생 앞 네모를 체크해요. 여러 명도 돼요. / 2 / 반목록에서 반 고르기 / 아래 반배정 아이콘을 누르면 이 창이 떠요. / 3 / Yes / 체크한 학생이 고른 반으로 들어가요. / · / 미배정 학생 / 반이 없는 학생은 반목록 '미배정'에서 찾아요.","no":"학생이 처음 들어오면 반이 정해지지 않은 미배정 상태일 수 있습니다. 학생 관리에서 우리 반 학생을 체크하고, 아래 아이콘 줄의 반배정을 누르면 '선택된 학생들을 배정할 반을 선택하세요'라는 창이 뜹니다. 반을 고르고 Yes를 누르면 됩니다. 연수 준비 때는 창만 열어 보고 No를 눌러 아무것도 바꾸지 않았습니다.","alt":["반배정 창(학생 정보는 흐리게 처리)"]},{"n":11,"t":"단어장을 만드는 두 가지 길","sec":3,"x":"1 / My Book 생성하기 / 직접 입력하거나 붙여넣기 · 엑셀로 우리 반 단어장을 만들어요. / 2 / All Books 가져오기 / 교과서 · 모의고사 · 수능 단어장을 내 교재로 가져와요. / 3 / 단계별 탭 / 파닉스 · 초등 · 중등 · 고등 · 모의고사 · 수능 / 4 / 내용보기 · 가져오기 / 단어 목록을 미리 보고, 마음에 들면 가져와요. / TIP / All Books는 학생 앱에 이미 들어 있어요. 가져오기는 한 번에 외울 단어 수를 바꾸고 싶을 때 써요.","no":"교재 관리 → My Book 생성 메뉴입니다. 위 초록 버튼은 직접 단어장을 만드는 곳이고, 아래 파란 버튼 영역은 업체가 미리 넣어 둔 All Books 목록입니다. 화면 안내에 따르면 All Books는 학생 앱에 이미 탑재되어 있고, 지정된 학습량을 바꾸고 싶을 때 가져오기를 해서 쓰면 됩니다.","alt":["My Book 생성 화면"]},{"n":12,"t":"초등 교과서 단어장 미리 보기","sec":3,"x":"1 / 초등 탭 / 3~6학년 출판사별 교과서 빈출 단어장(2022 개정)이 있어요. / 2 / 내용보기 결과 / 오른쪽에 번호 · 단어 · 뜻이 나와요. 예: 6학년 천재(함) 203개 / · / 그 밖의 초등 자료 / 학년별 빈출 단어, 기본 1200, 필수 800, 필수 800 유의어 / TIP / 우리 학교 교과서 출판사와 학년을 먼저 확인한 뒤 골라 주세요.","no":"초등 탭을 누르면 2022 개정 교과서 기준으로 3학년부터 6학년까지 출판사별 단어장이 나옵니다. 천재(김, 이, 함), YBM(김, 최), 동아, 미래엔, 비상, 아이스크림 교과서가 있었습니다. 내용보기를 누르면 오른쪽에 단어와 뜻이 바로 보여서, 우리 교과서 단어와 맞는지 확인하고 가져올 수 있습니다.","alt":["초등 탭에서 6학년 천재(함) 단어장 내용을 본 화면"]},{"n":13,"t":"교과서 단어장 가져오기","sec":3,"x":"1 / Unit별 단어수 / 한 유닛에 넣을 단어 수를 정해요. 기본은 15개예요. / 2 / 가져오기 / 누르면 내 교재(My Books)로 옮겨져요. / TIP / 15개보다 많게 나눌 수도 있지만, 워드빙고 학습에는 한 유닛에 최대 15개까지만 적용돼요.","no":"가져오기를 누르면 이 창이 뜹니다. 총 단어 수가 보이고, 유닛별 단어 수만 정하면 됩니다. 화면 안내에 따르면 15개 제한은 워드빙고 학습에만 적용되고, 15개보다 큰 유닛도 만들 수는 있습니다. 6학년 단어 203개를 15개씩 나누면 14개 유닛이 생깁니다. 연수 준비 때는 창만 확인하고 취소했습니다.","alt":["단어장 가져오기 창"]},{"n":14,"t":"우리 반 단어장 직접 만들기","sec":3,"x":"1 / 교재명 / 학생 앱에 보일 이름이에요. / 2 / 생성방식 / 붙여넣기(한글 파일) · 엑셀자료 · 중복제거 / 3 / 철자 / 영어 단어를 한 줄에 하나씩, Enter로 줄을 바꿔요. / 4 / 단어 뜻 / 철자와 같은 순서로 한 줄에 하나씩 적어요. / TIP / 단어 하나는 40자 이내로 적는 게 좋아요.","no":"My Book 생성하기를 누르면 이 창이 뜹니다. 연수 실습용으로 '[연수 실습] 6학년 1단원 단어'라는 이름을 붙이고 club, drum, grade 같은 여덟 단어를 넣어 봤습니다. 철자 칸과 뜻 칸은 줄 순서가 서로 맞아야 합니다. 한글 파일로 정리한 단어는 붙여넣기, 엑셀로 정리한 단어는 엑셀자료로 한꺼번에 넣을 수 있고, 중복제거를 누르면 같은 단어가 자동으로 빠집니다.","alt":["My Book 생성하기 입력 창"]},{"n":15,"t":"유닛 나누고 저장하기","sec":3,"x":"1 / Unit 탭 / 나눈 결과가 Unit 1, Unit 2처럼 탭으로 보여요. / 2 / Unit별 단어수 → Unit 나누기 / 예: 8단어를 4개씩 나누면 2개 유닛 / 3 / 총 단어수 · 총 Unit수 / 자동으로 계산돼요. / 4 / 전송 / 누르면 단어장이 만들어지고 My Book 관리로 넘어가요. / TIP / 등록한 뒤에도 My Book 관리에서 단어를 고칠 수 있어요.","no":"창 아래쪽에서 유닛별 단어 수를 적고 Unit 나누기를 누르면, 위쪽 입력 칸이 Unit 1, Unit 2 탭으로 나뉩니다. 실습에서는 여덟 단어를 네 개씩 나눠 두 개 유닛을 만들었습니다. 전송을 누르니 바로 My Book 관리 화면으로 넘어가면서 단어장이 목록에 생겼습니다.","alt":["Unit 나누기 결과와 전송 버튼"]},{"n":16,"t":"만든 단어장 관리하기","sec":3,"x":"1 / 새로 만든 단어장 / Unit 개수와 단어 수, 등록일이 함께 보여요. / 2 / 수정 · 삭제 / 연필로 단어를 고치고, 휴지통으로 지워요. / 3 / 폴더 이동 / 학년 · 단원별 폴더를 만들어 정리해요. / 4 / 아래 아이콘 / 정보 수정 · 교재 삭제 · 검색 · 폴더 이동 · 교재 복사 / TIP / 교재 복사를 쓰면 같은 단어장을 유닛 크기만 바꿔 하나 더 만들 수 있어요.","no":"방금 만든 실습 단어장이 Unit 2개, 단어 8개로 목록 맨 위에 생겼습니다. 오른쪽 폴더 목록에서 폴더를 만들고 폴더이동 버튼으로 단어장을 정리할 수 있습니다. 매뉴얼에 따르면 교재 복사 기능으로 유닛별 단어 개수를 바꾼 사본을 만들 수 있습니다.","alt":["My Book 관리 화면"]},{"n":17,"t":"다른 이용자가 공유한 단어장 쓰기","sec":3,"x":"1 / 교재명 검색 / '초등'처럼 검색하면 공유 단어장을 찾을 수 있어요. / 2 / A 아이콘 / 단어를 확인하고 유닛별 단어 수를 정해 배포하면 내 교재로 쓸 수 있어요. / 3 / 제작자 / 학원 · 학교 등 다른 이용자가 만들어 공유한 자료예요. / 4 / 교재 배포 / 여러 개를 체크한 뒤 아래 아이콘으로 한꺼번에 가져와요. / TIP / 쓰기 전에 철자와 뜻을 훑어보세요. 철자가 틀린 단어가 섞인 자료도 있었어요.","no":"교재 관리 → My Book 공유 메뉴입니다. 다른 이용자가 공유한 단어장이 2,400개가 넘게 올라와 있고, '초등'으로 검색하니 111개가 나왔습니다. 줄 앞의 A 아이콘을 누르면 '단어 갯수별로 배포합니다'라는 창이 뜨고, 단어 목록을 보면서 유닛별 단어 수를 정해 배포할 수 있습니다. 업체 교재가 아니라 이용자가 올린 자료라서, 쓰기 전에 꼭 한 번 확인해 주세요.","alt":["My Book 공유 화면에서 '초등'으로 검색한 결과"]},{"n":18,"t":"학생에게 단어장 보내기","sec":4,"x":"1 / 반목록 → 조회 / 단어장을 보낼 반을 골라요. / 2 / 추가 / 학생 이름 옆 추가를 누르면 교재 고르기 창이 떠요. / 3 / + 아이콘 / 여러 학생을 체크하고 누르면 한꺼번에 보낼 수 있어요. / 4 / 배포교재목록 / 보낸 단어장과 단계가 쌓이고, 교재삭제도 여기서 해요.","no":"교재 관리 → My Book 배포 메뉴입니다. 단어장을 만들기만 해서는 학생에게 보이지 않고, 여기서 배포해야 학생 앱에 들어갑니다. 반을 고르고 학생 옆 추가를 누르거나, 여러 명을 체크한 뒤 왼쪽 아래 더하기 아이콘을 누르면 한 번에 보낼 수 있습니다.","alt":["My Book 배포 화면(학생 이름은 흐리게 처리)"]},{"n":19,"t":"단어장과 학습 단계 고르기","sec":4,"x":"1 / 단어장 체크 / 보낼 단어장을 골라요. 폴더별로 볼 수도 있어요. / 2 / 학습 단계 / 3단계 · 5단계 · 9단계 중에서 골라요. 처음엔 5단계로 되어 있어요. / 3 / Image / 학습 화면에 그림을 함께 띄울지 켜고 끄는 스위치예요. / 4 / 배포 / 누르면 학생 앱에 단어장이 들어가요. / TIP / 처음에는 5단계로 시작해 보고, 학생 반응에 따라 3단계나 9단계로 바꿔 보세요.","no":"추가를 누르면 이 창이 뜹니다. 실습 단어장을 체크하고 아래에서 학습 단계를 고른 뒤 배포를 누르면 됩니다. 연수 준비 때 보인 학생은 다른 선생님 반 학생이어서 실제 배포는 하지 않고 취소했습니다.","alt":["배포할 교재를 고르는 창"]},{"n":20,"t":"학생은 이런 단계로 외워요","sec":4,"x":"1 / Flash Card / 단어 카드를 보고 소리를 들으며 익혀요 / 2 / Word Bingo / 제한 시간 안에 알맞은 단어 카드를 맞춰요 / 3 / Dictation / 소리를 듣고 철자를 받아써요 / 4 / Speed Quiz / 제한 시간 안에 객관식 문제를 풀어요 / 5 / Writing / 뜻을 보고 철자를 써요 / 9단계 / 쉬운 단계(Easy) 뒤에 Hard Word Bingo · Hard Speed Quiz 같은 어려운 단계가 이어져요. / 선생님이 바꿀 수 있는 것 / 배포할 때 3 · 5 · 9단계를 고르고, 보카트레인 설정에서 단계별 제한 시간을 정해요.","no":"학생 화면은 학생 계정이 있어야 볼 수 있어서 직접 찍지 못했습니다. 대신 관리자 설정 화면에 나오는 학습 이름과 앱 소개를 바탕으로 정리했습니다. 설정 화면에 플래시 카드, Word Bingo, Speed Quiz가 있고, 딕테이션과 라이팅은 실시간 OX 채점 설명에 나옵니다. 9단계에는 Easy Word Bingo, Hard Word Bingo처럼 쉬운 단계와 어려운 단계가 나뉘어 있습니다. 학생 화면에 보이는 이름은 조금 다를 수 있으니, 학생 배정이 되면 한 번 함께 확인해 보겠습니다.","alt":[]},{"n":21,"t":"학생별 학습 기록 보기","sec":4,"x":"1 / STUDY · TEST 탭 / 학생 관리에서 STUDY 버튼을 누르면 열려요. / 2 / 달력 / 날짜별로 공부한 기록을 확인해요. / 3 / 학습 기록 표 / 교재명 · 유닛 · 학습 시간 · 학습 기록 · 학습 상태 / TIP / 매뉴얼 기준으로 STUDY는 단계별 암기 학습 현황, TEST는 선생님이 낸 테스트 결과를 보여 줘요.","no":"학생 관리에서 학생 줄의 STUDY 버튼을 누르면 이 창이 뜹니다. 아직 이 학생은 학습 기록이 없어서 표가 비어 있지만, 학습을 하면 날짜별로 교재와 유닛, 학습 시간, 학습 상태가 쌓입니다. 위쪽 TEST 탭으로 바꾸면 테스트 결과를 볼 수 있습니다.","alt":["학생 STUDY 기록 창(이름은 흐리게 처리)"]},{"n":22,"t":"① 테스트 볼 학생 고르기","sec":5,"x":"1 / 반 · 학생 체크 / 삼각형을 눌러 펼치고 반 전체나 학생 몇 명을 체크해요. / 2 / 추가 / 오른쪽에 대상 학생 이름이 쌓여요. / 3 / Next / 교재 선택 단계로 넘어가요. / TIP / 테스트 만들기는 학생선택 → 교재선택 → 문제구성, 세 단계예요.","no":"테스트 관리 → 테스트 생성 메뉴입니다. 맨 위 진행 표시처럼 세 단계로 만듭니다. 먼저 반을 펼쳐 학생을 체크하고 추가를 누르면 오른쪽에 이름이 쌓입니다. 확인한 뒤 Next를 누릅니다.","alt":["테스트 생성 1단계 학생선택 화면(이름은 흐리게 처리)"]},{"n":23,"t":"② 출제 방식 고르기","sec":5,"x":"1 / 통합 출제 / 고른 범위 전체에서 테스트 1개를 만들어요. 단원 평가처럼 써요. / 2 / 개별 출제 / 유닛마다 테스트를 하나씩, 한 번에 여러 개 만들어요. / TIP / 교재선택 화면의 '출제 방식' 버튼을 누르면 이 창이 떠요.","no":"교재선택 단계에서 출제 방식 버튼을 누르면 이 창이 뜹니다. 통합 출제는 여러 유닛을 한데 모아 시험 하나를 만들고, 개별 출제는 유닛 수만큼 시험을 한 번에 만듭니다. 실습에서는 Unit 1과 Unit 2를 묶어 통합 출제로 만들어 봤습니다.","alt":["테스트 출제 방식 선택 창"]},{"n":24,"t":"③ 시험 범위 고르기","sec":5,"x":"1 / 교재 탭 / My Books · 기출 단어장 · 단원별 자료 · 배포된 교재 / 2 / 유닛 체크 / 단어장을 펼쳐 시험 볼 유닛을 체크해요. / 3 / 추가 / 오른쪽 목록에 범위가 들어가요. / 4 / 출제 방식 / 고른 방식(통합 출제 · 개별 출제)이 버튼에 표시돼요. / 5 / Next / 문제 구성으로 넘어가요.","no":"교재 탭에서 My Books는 내가 만든 단어장, 기출 단어장은 교과서 빈출 단어장, 단원별 자료는 교과서 단원별로 정리된 단어장입니다. 실습 단어장을 펼쳐 두 유닛을 체크하고 추가를 누르니 오른쪽에 범위가 들어갔습니다.","alt":["테스트 생성 2단계 교재선택 화면"]},{"n":25,"t":"④ 시험 이름과 합격 기준 정하기","sec":5,"x":"1 / 시험명 / 학생 화면에 보일 이름이에요. / 2 / 미리보기 / 학생에게 어떻게 보일지 먼저 확인해요. / 3 / 합격 기준점수 / 예: 80점 / 4 / 실시간 채점여부 / 문제를 풀 때 바로 채점해 보여 줄지 정해요. / 5 / 불합격 재시험 / 자동 출제를 고르면 재시험 기회와 방식(전체 / 틀린 단어만)을 정해요.","no":"실습에서는 시험명을 '[연수 실습] 1단원 단어 시험'으로 적고 합격 기준을 80점으로 했습니다. 불합격 재시험을 자동 출제로 고르면 재시험 기회 칸이 새로 생기고, 틀린 단어만 다시 보게 할 수도 있습니다. 단어 시험을 통과할 때까지 연습시키고 싶을 때 쓰기 좋다고 생각합니다.","alt":["테스트 생성 3단계 문제구성 위쪽"]},{"n":26,"t":"⑤ 문제 유형과 시간 정하기","sec":5,"x":"1 / 문제유형 / 듣기(뜻 찾기 · 철자 적기)와 쓰기(단어→뜻 · 뜻→단어)를 개수로 나눠요. / 2 / 제한 시간 / 문항마다(예: 10초) 또는 테스트 전체 시간을 정해요. / 3 / 주관식 첫글자 힌트 / 철자 쓰는 문제에 첫 글자를 보여 줄지 정해요. / 4 / 배포 방법 / 즉시 배포 또는 날짜를 정한 예약 배포 / TIP / 남은 문항 수가 0개가 되도록 맞춘 뒤, 맨 위 Finish를 누르면 학생에게 배포돼요.","no":"문제 유형에서 듣기 테스트와 쓰기 테스트를 체크하고 개수를 적습니다. 실습에서는 여덟 단어로 뜻 찾기 2, 철자 적기 2, 단어→뜻 객관식 2, 뜻→단어 객관식 1, 주관식 1을 넣어 남은 문항 수를 0으로 맞췄습니다. 이 단계에서 Finish를 누르면 학생에게 바로 나가기 때문에, 연수 준비 때는 Finish를 누르지 않았습니다.","alt":["테스트 생성 3단계 문제구성 아래쪽"]},{"n":27,"t":"학생에게는 이렇게 보여요","sec":5,"x":"1 / Test List / 정규시험과 재시험이 나뉘어 보이고, 제출 여부가 표시돼요. / TIP / 시험명은 학생이 알아보기 쉽게 '1단원 단어 시험'처럼 지어 주세요.","no":"시험명 옆 미리보기를 누르면 학생 화면의 테스트 목록이 이렇게 보입니다. 배포하기 전에도 볼 수 있어서, 이름이 어떻게 보이는지 확인하기 좋습니다.","alt":["테스트 미리보기(학생 Test List 화면)"]},{"n":28,"t":"보낸 테스트 확인하기","sec":5,"x":"1 / 학생별 / 켜면 학생 기준으로 테스트를 모아 봐요. / 2 / 제출 현황 / 제출한 학생 수 / 대상 학생 수 / 3 / 확인 / 누가 냈는지, 점수와 합격 여부를 봐요. / 4 / 재배포 / 같은 테스트를 다시 보낼 때 써요. / TIP / 오른쪽 위 '예약대기'에 체크하면 예약 배포해 둔 테스트를 볼 수 있어요.","no":"테스트 관리 → 테스트 목록입니다. 화면에 보이는 'test'는 다른 선생님이 9월에 만든 테스트입니다. 제출 현황이 0/1이면 한 명에게 보냈고 아직 아무도 내지 않았다는 뜻입니다. 확인을 누르면 자세한 현황이 뜹니다.","alt":["테스트 목록 화면"]},{"n":29,"t":"제출 현황 자세히 보기","sec":5,"x":"1 / 시험 정보 / 출제 범위와 문제 유형을 다시 확인해요. / 2 / 제출현황 / 학생별 제출 여부 · 점수 · 합격 여부 / · / '1차 재시험중' / 불합격해서 자동 재시험을 보고 있다는 뜻이에요.","no":"확인 창 아래쪽에서 학생별로 제출 여부, 점수, 합격 여부를 볼 수 있습니다. 이 학생은 20점으로 불합격해서 자동 재시험이 나갔고, 그래서 합격여부에 1차 재시험중이라고 나옵니다.","alt":["테스트 확인 창(학생 이름은 흐리게 처리)"]},{"n":30,"t":"테스트 결과 조회와 오답노트","sec":5,"x":"1 / 일자별 · 기간 평균 / 날짜마다 보거나 기간 평균을 봐요. / 2 / 반 · 학생 · 기간 → 조회 / 기간은 최대 1년까지 정할 수 있어요. / 3 / 결과 출력 · 오답노트 / 결과를 출력 · 저장하거나 틀린 단어만 뽑아 출력해요. / TIP / 결과가 안 보이면? 자동 재시험을 골랐다면 불합격 학생은 재시험이 자동으로 나가서 결과가 남지 않아요.","no":"테스트 관리 → 테스트 결과 조회입니다. 반과 기간을 정하고 조회를 누르면 결과가 나옵니다. 아래 아이콘으로 결과 출력, 결과 저장, 오답노트를 쓸 수 있습니다. 화면 안내에 결과가 안 보일 때의 이유가 적혀 있는데, 자동 재시험을 고르면 불합격 시 재시험이 자동 출제되어 결과가 남지 않는다고 합니다.","alt":["테스트 결과 조회 화면"]},{"n":31,"t":"① 시험지에 넣을 단어 고르기","sec":6,"x":"1 / 교재 탭 / 기출 단어장 · 단원별 자료 · My Books / 2 / 유닛 체크 / 단어장을 펼쳐 유닛을 골라요. / 3 / 추가 / 고른 범위를 시험지에 넣어요. / 4 / 범위 확인 / 오른쪽 목록을 보고 Next를 눌러요. / TIP / 테스트 관리 → 시험지 출력 메뉴예요. 학생을 고르지 않아도 돼서 학생 계정이 없어도 바로 써 볼 수 있어요.","no":"종이 단어 시험지는 테스트 관리 안의 시험지 출력 메뉴에서 만듭니다. 온라인 테스트와 달리 학생 선택 단계가 없습니다. 실습에서는 My Books 탭에서 실습 단어장의 두 유닛을 골랐습니다.","alt":["시험지 출력 1단계 교재선택 화면"]},{"n":32,"t":"② 문제 유형과 개수 정하기","sec":6,"x":"1 / 문제유형 / 단어→뜻, 뜻→단어를 객관식 · 주관식 개수로 나눠요. / 2 / Next / 시험명을 적는 단계로 넘어가요. / TIP / 매뉴얼에서는 문항 수 합계를 고른 단어 수보다 적게 정하라고 안내해요. 예: 8단어 → 7문항","no":"선택한 단어 수가 위에 나오고, 아래에서 문제 유형별 개수를 정합니다. 실습에서는 단어→뜻 객관식 2, 주관식 2, 뜻→단어 객관식 1, 주관식 2로 모두 7문항을 만들었습니다.","alt":["시험지 출력 2단계 출력설정 화면"]},{"n":33,"t":"③ 시험지 · 답안지 고르기","sec":6,"x":"· / 시험명 → Finish / 시험명을 적고 Finish를 누르면 이 창이 떠요. / 1 / 시험지 / 학생에게 나눠 줄 시험지가 새 탭에서 열려요. / 2 / 답안지 / 정답이 표시된 답안지가 열려요. / TIP / 새 탭이 열리면서 인쇄 창이 바로 떠요. 프린터로 인쇄하거나 PDF로 저장하면 돼요. 시험지 출력 관리에서 다시 출력할 수도 있어요.","no":"시험명을 '[연수 실습] 1단원 단어 시험지'로 적고 Finish를 누르니 출력 유형을 고르는 창이 떴습니다. 시험지를 누르면 새 탭에서 시험지가 열리고 곧바로 인쇄 창이 뜹니다. 인쇄하지 않으실 때는 인쇄 창에서 취소를 누르시면 됩니다.","alt":["출력할 유형을 고르는 창"]},{"n":34,"t":"이렇게 출력돼요","sec":6,"x":"시험지 ① 시험명과 학교 · 반 · 이름 칸 ② 객관식 ③ 주관식 / 답안지 ① 객관식 정답 번호 ② 주관식 정답","no":"실습 단어장으로 실제로 뽑아 본 시험지와 답안지입니다. 시험지에는 학교, 학년, 반, 이름 칸이 들어가고, 객관식은 보기 네 개, 주관식은 밑줄로 나옵니다. 답안지에는 객관식 정답 번호와 주관식 정답이 함께 적혀 있어서 바로 채점할 수 있습니다. 같은 범위로 다시 만들면 문제 순서와 보기가 바뀔 수 있습니다.","alt":["출력된 시험지","출력된 답안지"]},{"n":35,"t":"퀴즈 관리: 유의어 · 반의어 · 예문 퀴즈","sec":7,"x":"1 / 초등학교 퀴즈 / 초등 필수 유의어 · 반의어 퀴즈, 초등 교과서 예문 퀴즈 / 2 / 출제 방식 / 테스트처럼 통합 출제 · 개별 출제를 골라요. / · / 만드는 순서 / 학생선택 → 퀴즈선택 → 퀴즈구성. 테스트와 같아요. / TIP / 퀴즈도 '퀴즈시험 출력' 메뉴에서 종이로 뽑을 수 있어요.","no":"퀴즈 관리는 업체가 만든 퀴즈 전용 자료로 문제를 냅니다. 스타터, 챌린지, 초등학교, 중학교, 고등학교 폴더가 있고, 초등학교 폴더에는 필수 유의어, 필수 반의어, 교과서 예문 퀴즈가 있습니다. 만드는 순서와 설정은 테스트와 거의 같습니다.","alt":["퀴즈 생성 2단계 퀴즈선택 화면"]},{"n":36,"t":"성적 관리: 학생들의 STUDY 결과","sec":7,"x":"1 / 일자별 · 기간 평균 / 성적표를 날짜별 또는 기간 평균으로 봐요. / 2 / 반 · 학생 · 기간 → 조회 / 기간은 최대 1년까지예요. / 3 / 오답학습 · 학습이력 / 학생이 틀린 단어와 학습 흐름을 확인해요. / 4 / 성적표 출력 · 저장 / 아래 아이콘으로 성적표를 출력하거나 저장해요. / · / 같은 메뉴의 다른 기능 / 개인별 종합 분석 · 상담 일지 · 랭킹 조회","no":"성적 관리 → 성적표 조회는 학생들의 STUDY 학습 결과를 보는 곳입니다. 테스트 결과 조회와 화면 구성이 비슷합니다. 같은 메뉴 안에 학생별 종합 분석, 상담 내용을 적어 두는 상담 일지, 반별 우수 학생 순위를 보는 랭킹 조회도 있습니다.","alt":["성적표 조회 화면"]},{"n":37,"t":"보카트레인 설정 살펴보기","sec":7,"x":"1 / 음성 설정 / 일부 콘텐츠의 원어민 음성(TTS)을 남자(John) · 여자(Sally) 중 골라요. / 2 / STUDY 공통 / OX 채점, 학습모듈 스킵, 중복 로그인, 플래시 카드 제어 / 3 / 학습 순서 · 예문 · Enter키 / 랜덤 / 순차 학습, 예문 사용, Enter로 다음 문제 / 4 / 단계별 제한 시간 / Word Bingo · Speed Quiz 문항별 시간 / TIP / TEST 설정의 '테스트 강제 종료'를 불합격 처리로 두면 시험 중 창을 닫는 부정행위를 막을 수 있어요.","no":"기본 설정 → 보카트레인 설정입니다. 학생 학습 방식을 세세하게 정할 수 있습니다. 화면 아래 설명에 따르면 테스트 강제 종료는 컨닝 방지용이고, 테스트 중간 저장은 강제 종료를 쓰면 적용되지 않습니다. 함께 쓰는 관리자 화면이라 다른 반에도 영향을 줄 수 있으니, 바꾸기 전에 동학년과 이야기해 주세요.","alt":["보카트레인 설정 화면"]},{"n":38,"t":"쓰기 전에 꼭 알아 둘 점","sec":7,"x":"함께 쓰는 관리자 화면 / 같은 학교 선생님의 반 · 학생 · 교재가 함께 보여요. 배포 · 테스트 전에 반 이름을 확인해요. / 학생 배정과 동의서 / 학생은 배움터에서 배정을 받아야 들어올 수 있고, 에듀테크 활용 개인정보 동의서가 필요해요. / 바로 뜨는 인쇄 창 / 시험지 · 답안지를 누르면 새 탭에서 인쇄 창이 바로 떠요. 인쇄하지 않을 땐 취소를 눌러요. / 자동 재시험과 결과 / 자동 재시험을 고르면 불합격 학생의 결과가 바로 남지 않아요. 테스트 목록의 확인에서 진행 상황을 봐요.","no":"연수를 준비하며 직접 써 보면서 걸렸던 부분만 모았습니다. 특히 시험지 출력에서 시험지나 답안지를 누르면 인쇄 창이 곧바로 뜨는데, 이 창을 닫기 전까지는 다른 화면이 멈춘 것처럼 보일 수 있습니다. 당황하지 마시고 인쇄 창에서 취소를 누르시면 됩니다.","alt":[]},{"n":39,"t":"수업에 이렇게 써 보세요","sec":7,"x":"단원 단어 예습 / 교과서 단어장을 단원 단위로 가져와 배포 → 수업 전 5단계 학습 / 단원 마무리 테스트 / 통합 출제 + 틀린 단어만 자동 재시험 → 통과할 때까지 연습 / 종이 단어 시험 / 기기 없이도 시험지 출력 → 답안지로 바로 채점 / 어휘 넓히기 / 초등 필수 유의어 · 반의어 퀴즈로 심화 학습 / 학생과 함께 쓰려면 / 배움터에서 학생 배정과 개인정보 동의서(가정통신문)가 먼저 필요해요. 학생이 처음 들어오면 학생 관리에서 우리 반으로 반배정해 주세요.","no":"오늘 해 본 기능만으로도 단원 단어 예습, 단원 마무리 테스트, 종이 단어 시험, 어휘 심화 퀴즈까지 할 수 있습니다. 학생과 함께 쓰실 분은 배움터 학생 배정과 개인정보 동의서가 먼저 필요하니 말씀해 주세요. 동의서 가정통신문은 배움터 공지의 공식 양식을 인쇄해서 가져다 드리겠습니다.","alt":[]},{"n":40,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":7,"x":"연수가 끝난 뒤에도 / 반 만들기 · 반배정 / 우리 반을 만들고 학생을 반에 넣는 것까지 함께 해 드려요. / 단어장 만들기 / 교과서 단어장 가져오기, 엑셀로 단어장 만들기를 도와드려요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 반 만들기와 반배정, 단어장 만들기는 교실로 찾아가 함께 처리해 드리겠습니다.","alt":[]}],"offs":[[0,40094],[40094,53648],[93742,59086],[152828,59890],[212718,72040],[284758,58018],[342776,42312],[385088,56654],[441742,52234],[493976,53742],[547718,79840],[627558,97066],[724624,49378],[774002,55432],[829434,57520],[886954,61634],[948588,84184],[1032772,48548],[1081320,62688],[1144008,64442],[1208450,54388],[1262838,43154],[1305992,55014],[1361006,55864],[1416870,62036],[1478906,65030],[1543936,36672],[1580608,54932],[1635540,46714],[1682254,64412],[1746666,57956],[1804622,43946],[1848568,47368],[1895936,52808],[1948744,50108],[1998852,68874],[2067726,74132],[2141858,60824],[2202682,58908],[2261590,41042]],"toffs":[[0,3704],[3704,4524],[8228,5230],[13458,4756],[18214,5516],[23730,4468],[28198,3498],[31696,4060],[35756,4406],[40162,4380],[44542,5428],[49970,6100],[56070,4076],[60146,4250],[64396,4476],[68872,4694],[73566,5876],[79442,4046],[83488,5094],[88582,5320],[93902,4776],[98678,3508],[102186,4486],[106672,4322],[110994,4870],[115864,4828],[120692,2958],[123650,4224],[127874,3450],[131324,4444],[135768,4582],[140350,3328],[143678,3786],[147464,3768],[151232,4194],[155426,5188],[160614,5328],[165942,4460],[170402,4668],[175070,4002]],"packSize":2302632,"thumbSize":179072},{"key":"matamath","name":"마타수학","title":"마타수학 사용 안내서","group":"subject","sub":"경북AI배움터로 접속해 반 만들기부터 출제·결과 확인까지","fee":"유료 기능 적용","feeKind":"paid","feeNote":"학교가 가입 신청해 구입하는 유료 서비스예요. 배움터로 들어가면 결제나 회원가입 없이 우리 학교 계정으로 모든 기능을 썼어요. 화면에 이용 기간 표시는 없어요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 마타수학 소개와 커리큘럼 4가지"},{"start":5,"num":"1","label":"접속하기","desc":"경북AI배움터에서 마타수학에 접속하고 홈 화면을 살펴봐요"},{"start":7,"num":"2","label":"반 만들기","desc":"우리 학교 관리에서 반을 만들고 학생을 넣어요"},{"start":11,"num":"3","label":"학습지 출제","desc":"간편출제 네 단계로 학습지를 출제해요"},{"start":16,"num":"4","label":"수업 관리","desc":"수업 목록과 상세에서 PDF 인쇄와 수업 공지를 다뤄요"},{"start":20,"num":"5","label":"결과 확인","desc":"실시간 현황, 학습 보고서, 학생 목록으로 결과를 확인해요"},{"start":24,"num":"6","label":"꼭 알아 둘 점","desc":"유의사항과 수업 활용 아이디어"}],"slides":[{"n":1,"t":"마타수학","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 반 만들기부터 출제·결과 확인까지 / 2026. 10. / 작성자: 이정현, 황영수","no":"이번에는 경북AI배움터 에듀테크 가운데 AI마타수학을 함께 살펴보겠습니다. 마타수학은 학습지를 골라 우리 반에 내 주면, 학생이 푸는 모습을 실시간으로 보고 결과를 보고서로 받아 볼 수 있는 수학 학습 서비스입니다. 안내서에 들어간 화면은 모두 연수를 준비하면서 실제로 들어가 찍은 것이고, 선생님과 학생 이름은 가렸습니다.","alt":["마타수학 선생님 홈 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 마타수학, 홈 화면 / 05–06쪽 / STEP 2 / 반 만들기 / 우리 학교 관리, 반 추가, 학생 넣기 / 07–10쪽 / STEP 3 / 학습지 출제 / 간편출제 4단계, AI 맞춤 학습지 / 11–15쪽 / STEP 4 / 수업 관리 / 수업 목록, PDF 인쇄, 수업 공지 / 16–19쪽 / STEP 5 / 결과 확인 / 실시간 현황, 학습 보고서, 학생 목록 / 20–23쪽 / STEP 6 / 유의사항과 활용 / 미리 알아 둘 점, 수업 활용 아이디어 / 24–26쪽","no":"오늘은 여섯 단계로 진행하겠습니다. 마타수학은 반이 있어야 학습지를 낼 수 있어서, 2단계 반 만들기를 꼭 먼저 해 주셔야 합니다. 시간이 부족하면 2단계와 3단계만 따라 해 보셔도 바로 수업에 쓰실 수 있습니다.","alt":[]},{"n":3,"t":"마타수학으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 간편출제 / 학년·학기와 학습지만 고르면 우리 반에 바로 출제 / AI 맞춤 학습지 / 진단 학습지에서 틀린 개념으로 맞춤 학습지 생성 / 실시간 현황 / 학생별·문항별 정오답과 풀이 과정을 바로 확인 / 학습 보고서 / 평균 성적, 성적 분포, 학생별·문항별 분석 / 배움터 소개 문구 / 취약 개념을 AI로 분석하는 수학 학습 / 학생의 취약 개념을 분석해 맞춤형 문제와 학습 경로를 주고, 개인 수준에 맞는 수학 학습을 돕는 서비스예요. / 권장 환경: PC·태블릿, 크롬 브라우저, 화면 비율 100%","no":"배움터에서 마타수학 위에 마우스를 올리면 학생의 취약 개념을 AI로 분석해 맞춤형 문제와 학습 경로를 제공한다는 설명이 나옵니다. 직접 써 보니 핵심은 네 가지라고 생각합니다. 간편출제로 학습지를 내고, AI 맞춤 학습지로 틀린 개념을 다시 풀게 하고, 실시간 현황과 학습 보고서로 결과를 확인하는 흐름입니다. 권장 환경은 마타수학 자주 묻는 질문의 안내를 옮겼습니다.","alt":[]},{"n":4,"t":"홈 화면의 커리큘럼 4가지","sec":0,"x":"시작하기 전에 / 마타와 연산학습 / 계산을 반복 연습 / · 강마다 16문항 안팎 / · 1점 복합형 문항 / · 문제 유형명은 표시되지 않음 / 마타와 개념학습 / 개념을 하나씩 확인 / · 강마다 5문항 / · 2~3점 주관식 문항 / · AI 맞춤 학습지 최대 3회 / 마타와 기본 다지기 / 단원 기본 문제 / · 단원마다 12문항 / · 단원 정리용 / · AI 맞춤 학습지 최대 3회 / 마타와 실력 다지기 / 단원 심화 문제 / · 단원마다 3문항 / · 4점 고난도 문항 / · 3문항이라 AI 맞춤 학습지 없음 / 교육과정 고르기 / 출제할 때 2015 개정과 2022 개정 가운데 하나를 골라요. 2026학년도 초등학교는 모든 학년이 2022 개정 교육과정이에요.","no":"홈 화면에는 네 가지 커리큘럼이 카드로 나옵니다. 문항 수는 2022 개정 초5-2를 기준으로 직접 열어 보고 옮겼습니다. 새 개념을 배운 날은 개념학습, 계산 연습은 연산학습, 단원을 마무리할 때는 기본 다지기, 잘하는 학생의 도전 과제로는 실력 다지기가 어울린다고 생각합니다. 실력 다지기는 단원마다 3문항이라 AI 맞춤 학습지를 고르는 칸이 없습니다.","alt":[]},{"n":5,"t":"경북AI배움터에서 마타수학 열기","sec":1,"x":"1 / 에듀테크 서비스 → 마타수학 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 클릭하면 새 탭에서 마타수학이 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 마타수학 회원가입이나 비밀번호 입력은 필요 없어요. 배움터 로그인 한 번이면 돼요.","no":"미리캔버스와 같은 자리, 에듀테크 서비스 첫 페이지 둘째 줄에 마타수학이 있습니다. 누르면 새 탭에서 선생님 화면으로 바로 들어갑니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록"]},{"n":6,"t":"처음 보이는 선생님 홈 화면","sec":1,"x":"1 / 커리큘럼 4가지 · 간편출제 / 카드를 누르면 학습지 출제가 시작돼요. / 2 / 왼쪽 메뉴 / 수업 목록, 질문 & 답변, 학습 보고서, 학생 목록 / 3 / 실시간 학습지 / 내가 낸 학습지와 제출 현황이 보여요. / 4 / 답변을 기다리는 질문 / 학생이 남긴 질문이 여기 모여요. / 5 / 우리 학교 관리 / 반을 만들고 학생을 넣는 곳이에요(STEP 2).","no":"홈 화면은 다섯 곳만 기억하시면 됩니다. 위쪽 네 가지 색깔 카드가 출제 버튼이고, 오른쪽에는 내가 낸 학습지가 실시간으로 쌓입니다. 왼쪽 아래 '우리 학교 관리'에서 반을 먼저 만들어야 출제할 수 있습니다. 오른쪽 위 '선생님 매뉴얼 바로가기'를 누르면 기능별 공식 사용 가이드도 볼 수 있습니다.","alt":["마타수학 선생님 홈 화면"]},{"n":7,"t":"우리 학교 관리 화면","sec":2,"x":"1 / 01 반 관리 / 반을 만들고 학생을 넣는 메뉴예요. / 2 / 챗봇 사용하기 / AI 챗봇 마토를 학생 학습지에 넣을지 정해요. '학생 입력'을 켜면 수학과 관련 없는 답변이 나올 수 있어요. / 3 / AI마타수학 돌아가기 / 출제하는 선생님 화면으로 돌아가요. / TIP / 출제할 때 챗봇을 켜도, 여기서 챗봇이 꺼져 있으면 학생에게 나오지 않아요.","no":"홈 화면 왼쪽 아래 '우리 학교 관리'를 누르면 이 화면이 나옵니다. 우리 학교 정보를 설정하는 곳이라 챗봇 설정은 학교 전체에 적용됩니다. 우리학교 코드와 주소는 화면에서 가렸습니다.","alt":["우리 학교 관리 화면"]},{"n":8,"t":"반 관리 목록","sec":2,"x":"1 / 반 추가 / 새 반을 만들어요. / 2 / 학생 관리 / 반 이름을 고치거나 학생을 넣고 빼요. / 3 / 삭제 / 반을 지워요. / TIP / 생성자 칸에 반을 만든 선생님 이름이 나와요. 다른 선생님 반은 건드리지 않도록 확인해 주세요.","no":"학교에는 이미 5학년 4반이 하나 있고, 연수 준비하면서 학생이 없는 '연수 실습반'을 하나 만들어 두었습니다. 선생님마다 맡은 반을 직접 만들어 쓰시면 됩니다. 생성자 이름은 가렸습니다.","alt":["반 관리 목록 화면"]},{"n":9,"t":"반 추가하기","sec":2,"x":"1 / 교육과정 / 처음에는 2015 개정이 골라져 있어요. 2022 개정으로 바꿔요. / 2 / 반 이름 / 숫자·한글·영문과 특수문자 -_/*! 만 쓸 수 있어요. / 3 / 학생선택 / 반에 넣을 학생을 골라요(다음 쪽). / 4 / 추가하기 / 줄을 늘려 여러 반을 한 번에 만들어요. / 5 / 생성하기 / 누르면 반이 만들어져요.","no":"반 이름은 화면처럼 '6학년 1반'으로 지으면 됩니다. 다만 출제 화면과 학생 목록에서는 반 이름 뒤에 '반'이 한 번 더 붙어 '6학년 1반반'처럼 보입니다. 신경 쓰이시면 '6학년 1'까지만 적으셔도 됩니다. 이 화면은 예시만 입력해 보고 생성하지 않았습니다.","alt":["교과반 추가 화면"]},{"n":10,"t":"반에 학생 넣기","sec":2,"x":"1 / 추가 ( + ) / 왼쪽 목록에서 반에 넣을 학생을 눌러요. / 2 / 선택한 학생 목록 / 들어갈 학생이 여기 모여요. 빼려면 '−'를 눌러요. / 3 / 저장하기 / 저장해야 반에 들어가요. / TIP / 왼쪽에는 우리 학교로 등록된 학생이 보여요. 학생이 보이지 않으면 배움터 학생 배정부터 확인해 주세요.","no":"학생 이름과 아이디는 가렸습니다. 학교에 등록된 학생 가운데 우리 반 학생을 골라 넣는 방식입니다.","alt":["교과반 학생 선택 창"]},{"n":11,"t":"① 학습 범위 고르기","sec":3,"x":"1 / 개정 교육과정 / 2022 개정 교육과정을 골라요. / 2 / 학년-학기 / 하나만 골라요. 예: 초5-2 / 3 / 다음 / 학습지 고르기로 넘어가요. / TIP / 홈 화면 커리큘럼 카드의 '간편출제'를 누르면 이 화면부터 시작해요. 처음에는 2015 개정이 골라져 있으니 꼭 바꿔 주세요.","no":"간편출제는 네 단계입니다. 지금 보시는 화면은 마타와 개념학습의 첫 단계입니다. 연산학습, 기본 다지기, 실력 다지기도 순서는 똑같습니다.","alt":["간편출제 1단계 학습 범위 선택 화면"]},{"n":12,"t":"② 학습지 고르기","sec":3,"x":"1 / 강(학습지) 목록 / 강 이름과 문항 수를 보고 하나를 골라요. / 2 / 문제 미리보기 / 배점, 문제, 정답과 풀이까지 미리 볼 수 있어요. / 3 / 다음 / 출제 대상 고르기로 넘어가요. / TIP / 학습지는 한 번에 하나씩 출제돼요. 여러 강을 내려면 출제를 한 번 더 해요.","no":"왼쪽에서 강을 누르면 오른쪽에 문제가 정답, 풀이와 함께 나옵니다. 출제하기 전에 우리 반 수준에 맞는지 미리 훑어보시면 좋겠습니다.","alt":["간편출제 2단계 학습지 선택과 문제 미리보기"]},{"n":13,"t":"③ 출제 대상 고르기","sec":3,"x":"TIP / 다른 선생님 반도 목록에 함께 보여요. 내 반만 골랐는지 꼭 확인해 주세요. / 1 / 학년/교과반 / '교과반'을 고르면 반 목록이 나와요. / 2 / 반 고르기 / 출제할 반을 눌러요. 여러 반도 고를 수 있어요. / 3 / 고른 반 확인 / 아래에 표시돼요. ×로 뺄 수 있어요. / 4 / 다음 / 마지막 확인으로 넘어가요.","no":"학교에 만들어진 반이 모두 보이기 때문에, 다른 선생님 반을 잘못 누르면 그 반 학생에게 학습지가 나갑니다. 연수 준비 때도 이 부분이 가장 조심스러웠습니다.","alt":["간편출제 3단계 출제 대상 반 선택 화면"]},{"n":14,"t":"④ 확인하고 완료","sec":3,"x":"1 / 차시명 / 자동으로 붙어요. 예: [마타와 개념학습] 초5-2 01차시 / 2 / AI 맞춤 학습지 / 없음, 1회, 2회, 3회 가운데 골라요. / 3 / 출제 세부 설정 / 챗봇, 지식 발전소, 문제 유형명을 켜고 꺼요. / 4 / 출제 대상 / 고른 반이 맞는지 한 번 더 봐요. / 5 / 완료 / 누르는 순간 학생에게 학습지가 나가요.","no":"완료를 누르면 '수업을 생성 중입니다' 화면이 잠깐 나온 뒤 바로 출제됩니다. 연수 준비 때는 학생이 없는 연수 실습반에만 출제해 보았습니다. AI 맞춤 학습지와 세부 설정은 다음 쪽에서 자세히 보겠습니다.","alt":["간편출제 4단계 설정 확인 화면"]},{"n":15,"t":"AI 맞춤 학습지와 출제 세부 설정","sec":3,"x":"AI 맞춤 학습지 / · / 학생마다 다르게 만들어져요 / 진단 학습지에서 드러난 취약 개념으로 학습지가 생겨요. / · / 차례대로 열려요 / 진단 학습지를 마치면 1차가, 1차를 마치면 2차가 열려요. / · / 3문항 이하면 없어요 / 진단 학습지가 3문항 이하면 만들어지지 않아요. / 출제 세부 설정 / · / 챗봇 / 문제의 개념과 힌트를 알려 줘요. 우리 학교 관리에서도 켜져 있어야 해요. / · / 지식 발전소 / 문제에 해당하는 개념을 설명하는 페이지예요. / · / 문제 유형명 / 어떤 유형의 문제인지 보여 줘요. 연산학습에는 없어요.","no":"4단계 화면에서 동그라미 i 표시를 누르면 이 설명이 나옵니다. 세부 설정은 AI 맞춤 학습지에도 똑같이 적용됩니다. 처음에는 셋 다 켜진 상태로 출제해 보시고, 시험처럼 풀게 하고 싶은 날만 챗봇을 끄시면 된다고 생각합니다.","alt":["AI 맞춤 학습지 안내 말풍선","출제 세부 설정 안내 말풍선"]},{"n":16,"t":"수업 목록에서 출제한 학습지 보기","sec":4,"x":"1 / 찾기 / 유형·학년도·반·검색어로 찾아요. / 2 / 수업 카드 / 누르면 수업 상세로 가요. / 3 / 수업공지 · 질문답변 / 카드에서 바로 들어가요. / TIP / 출제를 마치면 이 화면이 떠요. '나의 수업 보기'를 누르면 수업 목록으로 와요.","no":"출제한 학습지는 수업 단위로 모입니다. 같은 커리큘럼과 학기로 여러 번 출제하면 한 카드 안에 차시가 쌓이는 구조입니다.","alt":["수업 목록 화면","출제 완료 화면"]},{"n":17,"t":"수업 상세 화면","sec":4,"x":"1 / 수업 공지 / 이 수업을 받은 학생에게 공지를 올려요. / 2 / 질문 & 답변 / 학생 질문에 답해요. 숫자는 질문 수예요. / 3 / PDF / 학습지를 인쇄용으로 미리 봐요. / 4 / 보고서 · 실시간 / 학생이 없으면 회색으로 눌리지 않아요. / 5 / AI 맞춤 1차 / AI 맞춤 학습지 제출 현황이 따로 보여요.","no":"수업 카드를 누르면 나오는 화면입니다. 진단 학습지 아래에 AI 맞춤 1차 줄이 따로 생긴 것은 출제할 때 AI 맞춤 학습지를 1회로 골랐기 때문입니다. 연수 실습반에는 학생이 없어서 보고서와 실시간 버튼이 회색입니다.","alt":["수업 상세 화면"]},{"n":18,"t":"학습지를 PDF로 인쇄하기","sec":4,"x":"1 / 해설 / 해설 안보이기 / 해설 보이기 / 2 / 분할 / 한 쪽을 4칸 또는 2칸으로 나눠요. / 3 / 로고 / 마타수학 로고를 보일지 정해요. / 4 / PDF / 인쇄 / PDF로 저장하거나 바로 인쇄해요. / TIP / 태블릿이 모자란 날에는 종이로 풀게 할 수 있어요. 다만 종이로 푼 결과는 보고서에 남지 않아요.","no":"수업 상세에서 학습지 이름 옆 PDF를 누르면 이 미리보기가 열립니다. 해설 보이기로 한 부 더 뽑으면 채점용 답지로 쓸 수 있습니다.","alt":["학습지 PDF 미리보기 화면"]},{"n":19,"t":"수업 공지 쓰기","sec":4,"x":"1 / 제목 / 공지 제목을 적어요. / 2 / 내용 / 풀이 기한이나 안내 사항을 적어요. / 3 / 첨부파일 / hwp·pdf·ppt·이미지 등 최대 5개 / 4 / 등록 / 누르면 공지가 올라가요. / TIP / 수업 공지는 학습지마다 따로 있어요. 수업 상세의 '수업 공지'에서 들어가요.","no":"연수 준비 때는 예시 문구만 입력해 보고 등록은 하지 않았습니다. 학습지를 낸 뒤 언제까지 풀면 좋을지 같은 안내를 적어 두시면 좋겠습니다.","alt":["수업 공지 작성 화면"]},{"n":20,"t":"실시간 현황판","sec":5,"x":"TIP / 홈 화면 '실시간 학습지'의 [실시간] 버튼으로도 바로 들어올 수 있어요. / 1 / 반 탭 / 출제한 반마다 따로 봐요. / 2 / 제출 현황 / 미제출 / 제출완료 학생 수 / 3 / 배점별 색 / 1점~4점 문항을 색으로 구분해요. / 4 / 정오답 표시 숨기기 / O/X 표시를 가려요. / 5 / 미제출한 학생만 보기 / 아직 안 낸 학생만 골라 봐요.","no":"연수 실습반에는 학생이 없어서 빈 화면입니다. 학생들이 풀기 시작하면 다음 쪽처럼 바뀝니다. 정오답 표시 숨기기는 화면을 TV에 함께 띄워 볼 때 쓰기 좋다고 생각합니다.","alt":["실시간 현황판 화면"]},{"n":21,"t":"학생이 풀기 시작하면 이렇게 보여요","sec":5,"x":"실시간 O/X 대시보드 / 새로고침하지 않아도 학생별·문항별 정답 여부가 바로 바뀌어요. / 학생 상태 표시 / 진단 · 진단 학습지 푸는 중 AI 맞춤 1차 · 맞춤 학습지 푸는 중 이탈 · 학습지를 벗어남 / 연습장 첨삭 / 문항을 누르면 학생의 풀이 과정과 연습장이 보여요. 그 위에 선생님이 파란 펜으로 바로 첨삭해요. / 알려 드릴 점 / 학생이 푸는 화면은 연수 준비 때 직접 확인하지 못해서, AI마타수학 선생님 사용 가이드의 '실시간 현황' 안내를 옮겼어요.","no":"공식 가이드에 따르면 실시간 현황은 새로고침 없이 정보가 계속 바뀌고, 학생 이름 옆 표시로 지금 어떤 학습지를 푸는지 알 수 있습니다. 문항 칸을 누르면 학생이 연습장에 쓴 풀이가 그대로 보이고, 선생님이 그 위에 파란 펜으로 직접 고쳐 줄 수 있다고 합니다. 실제 반에서 써 보시면 순회 지도할 학생을 고르는 데 도움이 될 것 같습니다.","alt":[]},{"n":22,"t":"학습 보고서","sec":5,"x":"1 / 전체 · 반별 탭 / 반을 여러 개 냈다면 반마다 따로 봐요. / 2 / 진단 학습지 결과 분석 / 학습지, 출제일, 제출 수, 문항 수 / 3 / 평균 성적 / 제출한 학생들의 평균 점수 / 4 / 성적 분포도 / 점수대별 학생 분포 / TIP / 아래로 내리면 학생별 분석과 문항별 분석도 나와요. 지난 학습지는 왼쪽 메뉴 '학습 보고서'에서 다시 찾아요.","no":"제출한 학생이 없어서 그래프는 비어 있습니다. 학생들이 제출하면 평균 성적과 분포도, 학생별 분석, 문항별 분석이 채워집니다.","alt":["종합 보고서 화면"]},{"n":23,"t":"학생 목록","sec":5,"x":"1 / 학년도 · 반 / 반을 고르면 소속 학생이 보여요. / 2 / 보고서 · 누적 / 학생 한 명의 누적 보고서를 열어요. / 3 / 제출한 학습지 / 제출한 수 / 받은 학습지 수 / TIP / 학생 이름과 아이디가 그대로 나오니 TV에 띄울 때는 조심해 주세요.","no":"학생 이름과 아이디는 가렸습니다. 학생 한 명의 흐름을 보고 싶을 때는 이 화면의 누적 보고서를 열어 보시면 됩니다.","alt":["학생 목록 화면"]},{"n":24,"t":"쓰기 전에 알아 둘 점","sec":6,"x":"학생과 함께 쓰려면 / 배움터 학생 배정과 에듀테크 개인정보 동의서(가정통신문)가 먼저 필요해요. / 출제 대상 확인 / 다른 선생님 반도 목록에 보여요. 완료 전에 반을 꼭 확인해요. / 풀이 기한 / 지금은 기한 없이 풀 수 있어요(FAQ 기준). / 챗봇 학생 입력 / 켜 두면 수학과 관련 없는 답변이 나올 수 있어요. / 자기주도학습 / 학생이 즐겨찾기한 문제로 만든 학습지는 선생님이 볼 수 없어요. / 권장 환경 / PC·태블릿, 크롬 브라우저, 화면 비율 100%","no":"풀이 기한, 권장 환경, 자기주도학습 내용은 마타수학 공식 가이드와 자주 묻는 질문을 근거로 했습니다. 학생과 함께 쓰실 분은 배움터 학생 배정과 개인정보 동의서가 먼저 필요하니 말씀해 주세요. 동의서 가정통신문은 배움터 공지의 공식 양식을 인쇄해서 가져다 드리겠습니다.","alt":[]},{"n":25,"t":"수업에 이렇게 써 보세요","sec":6,"x":"새 개념을 배운 날 / 개념학습 + AI 맞춤 1회 → 틀린 개념만 다시 풀기 / 계산 연습 / 연산학습 출제 → 실시간 현황으로 막힌 학생부터 순회 / 단원 마무리 / 기본 다지기 → 학습 보고서로 많이 틀린 문항 짚기 / 도전 과제 / 실력 다지기를 일찍 끝낸 학생에게, 또는 PDF로 인쇄해 과제로 / 학생 화면에서는 / 풀다가 막히면 챗봇 마토에게 힌트를 묻고, 지식 발전소에서 개념을 다시 봐요. 다시 풀고 싶은 문제는 즐겨찾기해 두었다가 자기주도학습에서 모아 풀어요.","no":"네 가지 커리큘럼을 수업 흐름에 맞춰 이렇게 나눠 쓰면 좋겠다고 생각했습니다. 학생 화면 설명은 공식 가이드와 출제 화면의 안내 문구를 옮긴 것입니다. 연수 중에 직접 출제를 연습해 보실 때는 학생이 없는 연수 실습반을 대상으로 고르시면 실제 학생에게는 나가지 않습니다.","alt":[]},{"n":26,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 반 만들기 · 학생 넣기 / 우리 반을 만들고 학생을 넣는 일부터 함께 해 드려요. / 출제 · 결과 보기 안내 / 첫 출제와 실시간 현황 보기를 교실에서 같이 해 봐요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 반 만들기와 첫 출제는 교실로 찾아가 함께 해 드리겠습니다.","alt":[]}],"offs":[[0,45840],[45840,49994],[95834,63242],[159076,69348],[228424,59688],[288112,79014],[367126,71370],[438496,44566],[483062,51292],[534354,47194],[581548,48290],[629838,67776],[697614,49340],[746954,57418],[804372,97324],[901696,62000],[963696,66424],[1030120,53596],[1083716,58506],[1142222,52898],[1195120,58642],[1253762,65104],[1318866,49808],[1368674,59940],[1428614,56754],[1485368,41456]],"toffs":[[0,3846],[3846,3948],[7794,5214],[13008,5800],[18808,4634],[23442,6300],[29742,5216],[34958,3396],[38354,3902],[42256,3552],[45808,3490],[49298,4676],[53974,3812],[57786,4188],[61974,6416],[68390,5096],[73486,4946],[78432,4162],[82594,4474],[87068,3898],[90966,4444],[95410,5040],[100450,3804],[104254,4272],[108526,4306],[112832,3994]],"packSize":1526824,"thumbSize":116826},{"key":"jajak","name":"자작자작","title":"자작자작 사용 안내서","group":"subject","sub":"글감 제시부터 AI 피드백, 디지털 문집까지","fee":"유료 기능 적용","feeKind":"paid","feeNote":"원래 유료 서비스인데 경북교육청 멤버십이 적용돼요. 마이 페이지 멤버십 정보: 경북 교육청 2025. 12. 17. ~ 2027. 2. 28.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 자작자작 소개와 전체 흐름"},{"start":5,"num":"1","label":"접속하기","desc":"경북AI배움터에서 자작자작에 접속하고 대시보드를 살펴봐요"},{"start":8,"num":"2","label":"그룹과 학생","desc":"그룹을 만들고 학생을 초대하거나 계정을 만들어요"},{"start":13,"num":"3","label":"활동과 글감","desc":"활동과 글감을 만들고 평가 기준과 작성 조건을 정해요"},{"start":22,"num":"4","label":"글쓰기와 AI 도움","desc":"글쓰기 화면에서 맞춤법 검사와 AI 도움을 써 봐요"},{"start":27,"num":"5","label":"피드백과 통계","desc":"AI 피드백을 확인하고 글 분석 통계를 봐요"},{"start":32,"num":"6","label":"디지털 책","desc":"모은 글로 디지털 책을 만들고 나눠요"},{"start":38,"num":"","label":"마무리","desc":"Insight 소개, 유의사항, 수업 활용, 마무리"}],"slides":[{"n":1,"t":"자작자작","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 글감 제시부터 AI 피드백, 디지털 문집까지 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 두 번째로 자작자작을 함께 써 보겠습니다. 자작자작은 선생님이 글감을 내면 학생이 AI 도움과 피드백을 받으며 글을 쓰고, 그 글을 디지털 문집으로 엮는 글쓰기 서비스입니다. 화면 속 글쓰기 장면도 연수 준비하면서 실습 그룹을 만들어 직접 써 본 것입니다.","alt":["자작자작 글쓰기 화면과 AI 도움 패널"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 자작자작, 대시보드 / 05–07쪽 / STEP 2 / 그룹과 학생 / 그룹 개설, 학생 초대·계정 생성 / 08–12쪽 / STEP 3 / 활동과 글감 / 글감 만들기, 평가 기준, 추천 글감 / 13–21쪽 / STEP 4 / 글쓰기와 AI 도움 / 작성 조건, 맞춤법, AI 도움 / 22–26쪽 / STEP 5 / 피드백과 통계 / AI 피드백 확인, 어휘 분석 / 27–31쪽 / STEP 6 / 디지털 책 / 문집 만들기, 공유·PDF·인쇄 / 32–37쪽 / 마무리 / 더 알아보기 · 유의사항 · 활용 / JAJAK Insight(베타), 꼭 알아 둘 점, 수업 활용 아이디어 / 38–41쪽","no":"여섯 단계로 진행하고, 마지막에 유의사항과 수업 활용을 짧게 나누겠습니다. 시간이 부족하면 STEP 3 글감 만들기와 STEP 5 피드백 확인만 꼭 해 보세요. 이 두 가지가 자작자작의 핵심입니다.","alt":[]},{"n":3,"t":"자작자작으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 글감 만들기 · 가져오기 / 갈래와 평가 기준을 정하고, 추천 글감도 골라 써요 / AI 글쓰기 도움 / 쓰는 도중 맞춤법 검사와 AI 제안을 받아요 / AI 피드백 · 통계 / 기준별 평가와 점수, 우리 반 어휘 분석 / 디지털 문집 / 모은 글을 책으로 엮어 링크·PDF·인쇄 / 배움터 소개 한 줄 / 글감 → AI 피드백 → 디지털 문집 / 선생님이 낸 글감으로 학생이 AI 피드백을 받으며 글을 쓰고, 그 결과물을 디지털 문집으로 완성하도록 돕는 글쓰기 서비스예요. / 경북AI배움터 에듀테크 서비스 소개 문구를 바탕으로 정리","no":"자작자작은 글감 제시, 글쓰기, AI 피드백, 문집 만들기가 한 흐름으로 이어지는 도구입니다. 배움터에서 자작자작 칸에 마우스를 올리면 나오는 소개 문구를 그대로 정리했습니다. 오늘은 이 흐름을 처음부터 끝까지 한 번씩 따라가 보겠습니다.","alt":[]},{"n":4,"t":"자작자작은 이 순서로 흘러가요","sec":0,"x":"한눈에 보기 / 1 / 그룹 만들기 / 우리 반 그룹 개설 / 2 / 학생 모으기 / 초대 · 계정 생성 / 3 / 활동 · 글감 / 과제 내기 / 4 / 글쓰기 / AI 도움 · 맞춤법 / 5 / 피드백 · 통계 / AI 평가 확인 / 6 / 디지털 책 / 문집으로 엮기 / 대시보드의 빠른 작업도 같은 순서예요 / Step1 그룹 개설하기 → Step2 학생 추가하기 → Step3 활동 및 글감 만들기. 처음에는 이 세 단추만 차례로 누르면 준비가 끝나요.","no":"전체 흐름을 먼저 보고 시작하겠습니다. 그룹을 만들고 학생을 모은 다음, 활동과 글감을 내면 학생이 글을 쓰고, 선생님은 피드백과 통계를 확인한 뒤 마지막에 책으로 엮습니다. 대시보드의 빠른 작업 세 단추가 앞의 세 단계와 같습니다.","alt":[]},{"n":5,"t":"경북AI배움터에서 자작자작 열기","sec":1,"x":"1 / 에듀테크 서비스 → 자작자작 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 소개 문구 / 글감 · AI 피드백 · 디지털 문집을 돕는 서비스라고 나와요. / TIP / 누르면 새 탭에서 자작자작 교사 화면이 열려요. 배움터 로그인 상태 그대로 들어가요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 에듀테크 서비스에서 자작자작을 누르면 새 탭이 열리면서 교사 화면으로 들어갑니다. 미리캔버스 바로 옆 칸에 있습니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록"]},{"n":6,"t":"처음 보이는 화면, 대시보드","sec":1,"x":"1 / 관리 중인 그룹 · 학생 수 / 카드를 누르면 관리 화면으로 바로 가요. / 2 / 빠른 작업 Step1~3 / 그룹 개설 → 학생 추가 → 활동·글감 만들기 / 3 / 왼쪽 메뉴 / 글쓰기 활동 · 디지털 책장 · 그룹/학생 관리 / TIP / 처음 들어가면 '서비스를 둘러볼까요?' 창이 떠요. 둘러보기 시작을 누르면 화면별 안내를 짧게 보여 줘요.","no":"대시보드에는 관리 중인 그룹과 학생 수, 빠른 작업, 최근 제출된 글이 나옵니다. 화면은 제 계정이라 이름 부분을 가렸습니다. 처음 들어가시면 둘러보기 안내가 뜨는데 한 번 따라가 보시면 메뉴 위치를 익히기 좋습니다.","alt":["자작자작 교사 대시보드"]},{"n":7,"t":"최근 업데이트로 생긴 기능 두 가지","sec":1,"x":"1 / 손글씨도 OK, OCR / 공책에 쓴 글을 사진으로 올리면 글자를 읽어 바로 평가해요. / 2 / 고쳐쓴 글 AI 피드백 / 고쳐서 다시 낸 글도 회차별로 평가·피드백을 이어 받아요. / 3 / 다시 보지 않기 / 체크하고 확인을 누르면 이 안내가 다시 뜨지 않아요. / TIP / 손글씨 방식은 STEP 3에서 글감의 '작성 방식'을 고를 때 정해요.","no":"접속하면 업데이트 안내 창이 먼저 뜰 수 있습니다. 손글씨 OCR과 고쳐쓴 글 AI 피드백이 새로 들어왔다는 안내입니다. 손글씨 기능은 기기가 부족한 교실에서 특히 쓸모가 있어서 STEP 3에서 다시 보겠습니다.","alt":["자작자작 업데이트 안내 창"]},{"n":8,"t":"그룹 개설하기 — 우리 반 만들기","sec":2,"x":"1 / 그룹명 / 예: 6학년 ○반, 동아리 이름 / 2 / 그룹 소개 / 필수 항목이에요. 한 줄이면 충분해요. / 3 / 공개 여부 → 비공개 / 그룹 광장에 노출되지 않아요. / 4 / 소속 / 학교를 고르고 학교 이름을 두 글자 이상 검색 / 5 / 학년 / 일반, 초등1~6, 중등, 고등 등 / 6 / 그룹 만들기 / 누르면 그룹 관리 목록에 바로 생겨요.","no":"대시보드에서 Step1 그룹 개설하기를 누르면 이 화면이 나옵니다. 그룹 이미지는 비워 두면 기본 이미지가 들어갑니다. 실습에서는 [연수 실습] 자작자작 맛보기라는 비공개 그룹을 만들었습니다. 공개로 두면 다른 학교 선생님들도 그룹 광장에서 활동 내용을 볼 수 있으니, 학급 그룹은 비공개를 권해 드립니다.","alt":["그룹 개설하기 입력 화면"]},{"n":9,"t":"그룹 코드 · 링크 · QR로 학생 부르기","sec":2,"x":"1 / 그룹 코드 / 학생이 코드를 넣어 참여 요청을 보내요. / 2 / 그룹 참여 링크 / 복사해서 알림장이나 클래스룸에 붙여 넣어요. / 3 / QR · 초대 안내문 / 안내문 PDF를 내려받아 인쇄하거나 화면에 띄워요. / 4 / 그룹 설정 / 그룹 정보를 고칠 때 눌러요. / TIP / 학생이 참여 요청을 보내면 학생 관리의 '참여 요청' 칸에 숫자가 올라가요.","no":"그룹을 만들면 그룹마다 코드와 참여 링크, QR이 생깁니다. 이미 자작자작 계정이 있는 학생이라면 이 코드나 QR로 참여 요청을 보내게 하면 됩니다. 개설자 이름은 가렸습니다.","alt":["그룹 상세 화면의 참여 코드와 QR"]},{"n":10,"t":"학생 일괄 추가 ① 기존 학생 초대","sec":2,"x":"1 / 기존 학생 초대 / 계정 생성 / 계정이 있으면 초대, 없으면 계정 생성 / 2 / 아이디 입력 / 학생 아이디를 넣고 + 로 한 명씩 더해요. / 3 / 엑셀로 한꺼번에 / 템플릿을 내려받아 아이디를 적고 끌어다 놓아요. / TIP / 초대한 학생이 수락해야 그룹에 들어와요. 기다리는 학생은 '초대 수락 대기'에 보여요.","no":"학생 관리에서 그룹을 고른 뒤 학생 일괄 추가를 누르면 이 화면이 나옵니다. 이미 자작자작에 가입한 학생은 아이디로 초대하고, 학생이 많으면 엑셀 템플릿으로 한꺼번에 초대할 수 있습니다.","alt":["학생 일괄 추가의 기존 학생 초대 탭"]},{"n":11,"t":"학생 일괄 추가 ② 계정 생성","sec":2,"x":"1 / 계정 생성 / 자작자작 계정이 없는 학생의 계정을 만들어요. 만든 계정은 그룹에 바로 들어가요. / 2 / 개인정보 수집·이용 동의 / 만 14세 미만은 법정대리인(보호자) 서명이 필요해요. / 3 / 동의서 2종 내려받기 / 14세 미만 보호자용 · 14세 이상 본인용 / 4 / 동의 확인 체크 / 동의를 받은 뒤 체크하고 계정을 만들어요. / 주의 / 초등학생은 모두 만 14세 미만이에요. 보호자 서명 동의서를 먼저 받아 주세요.","no":"계정이 없는 학생은 선생님이 계정을 만들어 줄 수 있습니다. 다만 계정을 만들기 전에 개인정보 수집 이용 동의를 받아야 하고, 초등학생은 보호자 서명이 필요합니다. 동의서 양식은 이 화면에서 바로 내려받을 수 있습니다.","alt":["계정 생성 탭의 개인정보 동의 안내"]},{"n":12,"t":"학생 관리 — 명단 확인과 비밀번호 초기화","sec":2,"x":"1 / 등록 학생 · 참여 요청 · 초대 수락 대기 / 카드를 누르면 그 목록으로 바뀌어요. 등록 한도(300명)도 여기서 보여요. / 2 / 검색 / 닉네임이나 아이디로 찾아요. / 3 / 비밀번호 초기화 · 내보내기 / 열쇠는 비밀번호 초기화, 빨간 아이콘은 모든 그룹에서 내보내기 / TIP / 비밀번호를 잊은 학생은 열쇠 아이콘으로 바로 초기화해 주면 돼요.","no":"학생 관리에서는 등록된 학생과 참여 요청, 초대 수락 대기를 나눠서 봅니다. 화면은 실제 학급 명단이라 닉네임과 아이디를 가렸습니다. 수업 중에 비밀번호를 잊은 학생이 생기면 열쇠 아이콘으로 바로 초기화할 수 있습니다.","alt":["학생 관리 목록"]},{"n":13,"t":"활동 만들기 — 글감을 담는 묶음","sec":3,"x":"1 / 활동명 / 예: 독서 감상문 쓰기 (64자까지) / 2 / 활동 공개 / 끄면 학생에게 보이지 않아요. / 3 / 활동 만들기 / 목록에 활동이 생기면 그 안에 글감을 넣어요. / TIP / 활동은 폴더, 글감은 그 안의 과제라고 생각하면 쉬워요. 한 활동에 글감을 여러 개 담을 수 있어요.","no":"활동 글감 설정 메뉴에서 그룹을 고르고 새 활동 만들기를 누릅니다. 실습에서는 가을, 나의 하루 쓰기라는 활동을 만들었습니다. 활동은 묶음이고 실제 과제는 그 안에 넣는 글감입니다.","alt":["새 활동 만들기 창"]},{"n":14,"t":"새 글감 만들기 ① 작성 방식 고르기","sec":3,"x":"1 / 온라인 / 학생이 글쓰기 화면에서 직접 써요. / 2 / 손글씨 / 선생님이 손글씨 사진을 올리면 OCR로 글자를 읽어 제출돼요. / 3 / 미리 알아 둘 점 / 손글씨 사진은 글감을 만든 뒤 선생님이 올려요. 작성 방식은 나중에 바꿀 수 없어요. / TIP / 기기가 부족한 날은 공책에 쓰고 손글씨 방식으로 모아도 AI 평가를 받을 수 있어요.","no":"활동 옆의 새 글감 만들기를 누르면 먼저 작성 방식을 고릅니다. 오늘 실습은 온라인으로 하겠습니다. 손글씨는 학생이 직접 올리는 것이 아니라 선생님이 사진을 등록하는 방식이라는 점을 기억해 주세요.","alt":["새 글감 만들기의 작성 방식 선택 창"]},{"n":15,"t":"새 글감 만들기 ② 글감 내용","sec":3,"x":"1 / 제목 / 학생 목록에 보일 글감 이름 / 2 / 글감 내용 · 글 작성 안내 / 무엇을 쓸지 구체적으로, 아래 칸에는 순서·유의점을 적어요. / 3 / 참고 자료 / 웹 URL · YouTube · 이미지를 최대 5개까지 / 4 / 제출 편수 / 한 편만(감상문·보고서) / 여러 편(일기·관찰 기록) / 5 / 진행 단계 / 필수는 1·2단계뿐이에요. 3·4단계는 기본값이 있어요.","no":"글감은 네 단계로 만듭니다. 필수는 글감 내용과 AI와 평가 두 단계이고, 나머지는 기본값이 있어서 필요할 때만 바꾸면 됩니다. 실습에서는 가을 하면 떠오르는 장면이라는 글감을 만들었습니다.","alt":["글감 내용 입력 화면과 진행 단계"]},{"n":16,"t":"새 글감 만들기 ③ AI와 평가 — 갈래","sec":3,"x":"1 / 갈래 4가지 / 표현적 · 설득하는 · 정보 전달의 · 보고하는 글쓰기 / 2 / 평가 기준 / 기본으로 4개가 골라져 있어요. 다음 쪽에서 더 볼게요. / 3 / 오른쪽 요약 / 고른 내용이 단계별로 정리돼요. / TIP / 실습에서는 '표현적 글쓰기'를 골랐어요. 경험·감정·생각을 쓰는 생활문이나 일기에 어울려요.","no":"2단계는 AI 피드백과 평가에 쓰일 설정입니다. 먼저 갈래를 고르는데, 설득하는 글이나 정보를 전달하는 글처럼 국어 교육과정의 글 종류와 맞춰 고르시면 됩니다.","alt":["갈래 선택 화면"]},{"n":17,"t":"새 글감 만들기 ④ 평가 기준 직접 추가","sec":3,"x":"1 / 기본 평가 기준 / 주제의 충실성 · 어휘의 적절성 · 문법의 정확성 · 시각과 태도 / 2 / 평가 기준 직접 추가 / 기준 이름(50자)과 AI가 살펴볼 내용(300자)을 적어요. / 3 / 추가된 기준 / 체크해서 쓰고, 휴지통으로 지워요. 모두 7개까지 골라요. / TIP / 실습 예시: '감각적 표현 — 흉내 내는 말·꾸며 주는 말로 생생하게 표현했는지 평가합니다.'","no":"기본 기준 네 가지에 더해 선생님이 기준을 직접 만들 수 있습니다. 우리 반 성취기준이나 이번 차시 학습 목표를 그대로 기준으로 넣으면 AI 피드백이 그 기준에 맞춰 나옵니다. 화면 위쪽에 5/7개 선택이라고 보이듯 7개까지 고를 수 있습니다.","alt":["평가 기준 목록과 직접 추가 창"]},{"n":18,"t":"새 글감 만들기 ⑤ 대상 학년과 AI 글쓰기 도움","sec":3,"x":"1 / 대상 학년 / AI가 학년에 맞춰 피드백 수준을 조절해요. / 2 / 학생 AI 글쓰기 도움 / 켜 두면 쓰는 중에 AI 도움을 받아요. 5분에 한 번씩 / 3 / 단계 완료 표시 / 필수 단계를 채우면 오른쪽에 체크가 붙어요. / TIP / 초등은 '초등 저학년' 또는 '초등 고학년' 중에서 골라 주세요.","no":"대상 학년을 고르면 AI가 그 수준에 맞는 말로 피드백을 줍니다. 학생 AI 글쓰기 도움은 켜 두면 학생이 쓰는 도중에 도움을 받을 수 있고, 5분 간격으로 쓸 수 있습니다.","alt":["대상 학년과 학생 AI 글쓰기 도움 설정"]},{"n":19,"t":"새 글감 만들기 ⑥ 글 작성 조건 (선택)","sec":3,"x":"1 / 글자 수 제한 / 최소·최대 글자 수 (실습: 150자 이상) / 2 / 문단 수 제한 / 문단 개수를 정할 때 켜요. / 3 / 필수 표현 / 꼭 들어갈 낱말을 쉼표로 (실습: 가을) / 4 / 붙여넣기 허용 / 꺼 두면 복사한 문장을 붙여 넣을 수 없어요. / TIP / 붙여넣기는 기본으로 꺼져 있어요. 학생이 직접 쓰게 하려면 그대로 두세요.","no":"3단계부터는 선택 설정입니다. 글자 수와 필수 표현을 정하면 학생 글쓰기 화면 위쪽에 조건 체크 목록이 나타나서, 학생이 스스로 조건을 채웠는지 확인할 수 있습니다.","alt":["글 작성 조건 설정 화면"]},{"n":20,"t":"새 글감 만들기 ⑦ 공개 및 일정 (선택)","sec":3,"x":"1 / 학생에게 글감 공개 / 켜 두면 학생 글감 목록에 바로 보여요. / 2 / 학생 글 공개 여부 / 공개 선택 허용 / 비공개로 고정(작성자와 선생님만) / 3 / 마감일 / 비워 두면 기한 없이 쓸 수 있어요. / 4 / 글감 만들기 / 작성 방식·제출 편수는 바꿀 수 없다는 확인 창이 떠요. / TIP / 만든 직후 목록에 '문제 분석 중' 표시가 잠시 떠요. 끝나면 학생이 쓸 수 있어요.","no":"마지막 단계에서는 공개 여부와 마감일을 정합니다. 학생끼리 글을 돌려 읽게 하려면 공개 선택 허용, 개인적인 글이라면 비공개로 고정을 고르시면 됩니다. 글감 만들기를 누르면 작성 방식과 제출 편수는 바꿀 수 없다는 확인 창이 한 번 더 나옵니다.","alt":["공개 및 일정 설정 화면"]},{"n":21,"t":"글감 가져오기 — 추천 글감 1,277개","sec":3,"x":"1 / 내 글감 / 추천 글감 / 내가 만든 글감과 자작자작이 제공하는 글감 / 2 / 검색 / 낱말로 찾아요 (예: 가을 → 11개) / 3 / 상세 보기 / 글감 내용과 설정을 미리 봐요. / 4 / 선택한 글감 추가 / 체크한 글감을 지금 활동에 넣어요. / TIP / 원본 글감은 바뀌지 않고, 작성 방식과 제출 편수는 그대로 가져와요.","no":"새로 만들기 부담스러우시면 활동 옆의 글감 가져오기를 눌러 보세요. 추천 글감이 1,277개 있고 낱말로 검색할 수 있습니다. 작년에 만든 내 글감을 새 학급에서 다시 쓸 때도 이 메뉴를 씁니다.","alt":["글감 가져오기 화면"]},{"n":22,"t":"글쓰기 홈 — 글감별로 글 모아 보기","sec":4,"x":"1 / 그룹 · 활동 · 글감 고르기 / 고른 글감의 정보와 글 목록이 아래에 나와요. / 2 / 새 글 작성 / 선생님도 직접 써 볼 수 있어요. / 3 / 작성된 글 / 전체 글 / 내 글, 다운로드 / 4 / 피드백 작성하기 / 피드백 관리 화면으로 바로 가요. / TIP / 학생에게 보여 줄 예시 글을 선생님이 먼저 써 두면 수업 안내가 쉬워져요.","no":"글쓰기 홈은 글감별로 제출된 글을 모아 보는 곳입니다. 새 글 작성을 누르면 선생님도 글을 써 볼 수 있어서, 오늘처럼 학생 화면을 미리 경험해 보기 좋습니다.","alt":["글쓰기 홈 화면"]},{"n":23,"t":"글쓰기 화면 살펴보기","sec":4,"x":"1 / 작성 조건 / 제목·본문·글자 수·필수 표현을 채우면 하나씩 체크돼요. / 2 / AI 도움 / 쓴 글을 바탕으로 이어 쓸 내용을 제안해요. / 3 / 맞춤법 검사 / 맞춤법과 띄어쓰기를 확인해요. / 4 / 임시 저장 · 글 등록 / 조건을 다 채우면 글 등록이 켜져요. / 5 / 글감 정보 / 글감 내용과 평가 기준을 옆에서 다시 봐요.","no":"실습 글로 바스락, 은행잎 길을 써 보았습니다. 위쪽 작성 조건이 5/5 충족으로 바뀌는 것이 보이실 겁니다. 일부러 띄어쓰기 실수를 두 군데 넣어 두었는데, 다음 쪽에서 맞춤법 검사로 확인해 보겠습니다.","alt":["글쓰기 화면"]},{"n":24,"t":"맞춤법 검사 — 고칠 곳과 이유를 함께","sec":4,"x":"1 / 맞춤법 검사 / 누르면 오른쪽에 결과가 떠요. / 2 / 교정 제안 + 이유 / 발 밑에서 → 발밑에서 (표준국어대사전: 합성어라 붙여 씀) / 3 / 하나씩 적용 / 필요한 것만 골라 본문에 반영해요. / 4 / 모두 적용 / 제안을 한꺼번에 반영해요. / TIP / 실습 글에 넣어 둔 띄어쓰기 실수 두 곳을 정확히 찾아냈어요. 다시 검사는 잠시 뒤에 할 수 있어요.","no":"맞춤법 검사는 고칠 곳만 알려 주는 것이 아니라 교정 이유도 보여 줍니다. 학생에게 이유를 읽고 스스로 적용 여부를 정하게 하면 맞춤법 지도에도 쓸 수 있습니다.","alt":["맞춤법 검사 결과 패널"]},{"n":25,"t":"AI 도움 — 대신 써 주지 않고 방향을 짚어 줘요","sec":4,"x":"1 / AI 제안 / 복사 · 새로 요청 / 2 / 참 잘 쓴 부분 / 글 속 문장을 그대로 짚어 칭찬해요. / 3 / 다듬어 볼 방향 / 더 써 볼 내용을 구체적으로 제안해요. / 4 / 5분 간격 / 새 AI 도움은 5분 뒤에 다시 요청할 수 있어요. / TIP / AI 제안이 글의 맥락에 맞는지는 학생이 스스로 판단하도록 지도해 주세요.","no":"AI 도움은 글을 대신 써 주지 않습니다. 잘 쓴 문장을 짚어 주고, 그날 아침의 공기나 친구와의 대화를 더 떠올려 보라는 식으로 방향만 제안합니다. 화면 아래에도 AI가 생성한 제안이니 맥락에 맞는지 확인하라는 안내가 있습니다.","alt":["AI 도움 제안 내용"]},{"n":26,"t":"등록한 글 확인과 내려받기","sec":4,"x":"1 / 전체 글 / 내 글 / 글감에 제출된 글을 카드로 봐요. / 2 / 다운로드 / PDF · Word로 내려받아요. / 3 / 피드백 작성하기 / 이 글감의 피드백 관리로 가요. / TIP / 글 카드 오른쪽 위에 공개 · 비공개 표시가 붙어요.","no":"글을 등록하면 글쓰기 홈의 작성된 글에 카드로 나타납니다. 다운로드를 누르면 PDF와 Word 가운데 골라 내려받을 수 있어서, 학급 게시나 포트폴리오 정리에 쓸 수 있습니다.","alt":["작성된 글 목록과 다운로드 메뉴"]},{"n":27,"t":"피드백 관리 ① 공개 설정과 AI 일괄 작성","sec":5,"x":"1 / 그룹 · 활동 · 글감 고르기 / 피드백을 볼 글감을 정해요. / 2 / 학생 공개 설정 / 피드백 글과 점수를 학생에게 보일지 따로 정해요. / 3 / AI 일괄 작성 / 제출된 글의 AI 피드백을 한꺼번에 만들어요. / 4 / AI 피드백 작업 현황 / 생성 중 · 대기 · 처리 오류 · AI 검토 중단 건수 / TIP / 점수는 숨기고 피드백 글만 학생에게 보여 줄 수도 있어요.","no":"피드백 관리에서는 먼저 학생에게 무엇을 보여 줄지 정합니다. 피드백 글과 점수가 따로 켜고 끄는 스위치로 나뉘어 있어서, 점수 공개가 부담스러우면 글만 보여 주면 됩니다.","alt":["피드백 관리 상단"]},{"n":28,"t":"피드백 관리 ② 글별 · 학생별 보기","sec":5,"x":"1 / 글별 보기 / 학생별 보기 / 제출 상태 필터로 골라 봐요. / 2 / 피드백 상태 · 점수 / 피드백 완료 여부와 최근 점수 / 3 / 피드백 수정 / 글마다 AI 피드백을 열어 고쳐요. / 4 / 피드백 일괄 다운로드 / 피드백을 한꺼번에 내려받아요. / TIP / 이 화면은 실제 학급의 글이라 글 제목과 닉네임을 가렸어요.","no":"아래쪽 목록에서 학생 글마다 피드백 상태와 점수를 한눈에 봅니다. 미제출 학생도 함께 표시되어 누가 아직 내지 않았는지 확인하기 좋습니다. 피드백 수정을 누르면 다음 쪽 화면으로 넘어갑니다.","alt":["피드백 목록"]},{"n":29,"t":"피드백 관리 ③ AI 피드백 확인하고 고치기","sec":5,"x":"1 / 이력 보기 · 글감 정보 · 피드백 수정 / 고쳐쓴 회차와 글감을 옆에서 봐요. / 2 / 저장된 종합 점수 / 기준별 점수를 모은 점수예요. / 3 / 기준별 점수 구간 / 예: 주제의 충실성 81~100점 / 4 / 평가 · 개선 제안 / 기준마다 AI가 쓴 평가와 다음에 해 볼 점 / 5 / 수정하기 / 문장을 고쳐 저장하면 점수가 다시 계산돼요.","no":"왼쪽은 학생 글, 오른쪽은 기준별 AI 평가입니다. 실제 학생 글이라 내용은 흐리게 처리했습니다. AI가 쓴 평가가 우리 반 기준과 다르면 수정하기로 고친 뒤 학생에게 공개하시면 됩니다.","alt":["피드백 수정 화면"]},{"n":30,"t":"글 분석 통계 ① 우리 반 어휘 한눈에","sec":5,"x":"1 / 그룹 · 활동 · 글감 / 통계를 볼 글감을 골라요. / 2 / 참여 학생 수 · 제출 글 수 / 3 / 어휘 다양성 TTR · MATTR / 서로 다른 낱말을 얼마나 고르게 썼는지 / 4 / 어휘 수준 분포 / 국립국어원 '국어 기초 어휘 목록' 기준 1~5등급 / TIP / TTR은 쓴 낱말 가운데 서로 다른 낱말의 비율이에요. MATTR은 글 길이의 영향을 줄인 값이에요.","no":"글 분석 통계는 학생들이 쓴 글의 어휘를 숫자로 보여 줍니다. 어휘 다양성 지표와 어휘 수준 분포가 나오고, 수준 분류는 국립국어원 국어 기초 어휘 목록을 따른다고 화면에 안내되어 있습니다.","alt":["글 분석 통계 요약 카드와 어휘 수준 분포"]},{"n":31,"t":"글 분석 통계 ② 단어 연결망과 학생별 결과","sec":5,"x":"1 / 단어 연결 네트워크 / 함께 쓰인 낱말끼리 선으로 이어져요. / 2 / 필터 / 연결이 몇 번 이상인 낱말만 볼지 정해요. / 3 / 학생별 글 분석 결과 / 학생마다 어휘 다양성과 어휘 수준 분포 / TIP / 우리 반이 어떤 낱말을 자주 썼는지 보고 다음 글감의 어휘 지도를 계획해 볼 수 있어요.","no":"아래로 내리면 단어 연결 네트워크와 학생별 결과가 나옵니다. 학생 이름은 가렸습니다. 학생별 어휘 다양성 수치는 개별 지도 자료로 참고하실 수 있습니다.","alt":["단어 연결 네트워크와 학생별 글 분석 결과"]},{"n":32,"t":"디지털 책 만들기 ① 크기 고르기","sec":6,"x":"1 / 3단계 / 크기 선택 → 콘텐츠 선택 → 미리보기 / 2 / 시집형 (148×210mm) / A5와 비슷해요. 문집 만들 때 가장 많이 골라요. / · / 신국판 (152×225mm) / 시집형보다 조금 커요. / TIP / 디지털 책 만들기는 크롬에 맞춰져 있어요.","no":"디지털 책장의 디지털 책 만들기는 세 단계입니다. 먼저 책 크기를 고르는데, 학급 문집은 화면 안내대로 시집형을 가장 많이 고른다고 합니다.","alt":["디지털 책 크기 선택 화면"]},{"n":33,"t":"디지털 책 만들기 ② 책에 넣을 글 고르기","sec":6,"x":"1 / 그룹 선택 / 글을 가져올 그룹을 골라요. / 2 / 활동 · 글감 · 글 체크 / 활동째, 글감째, 글 하나씩 고를 수 있어요. / 3 / 선택된 콘텐츠 / 고른 순서대로 쌓이고, 손잡이로 순서를 옮겨요. / 4 / 저자 선택 / 학생을 골라 그 학생 글만 담을 때 / 5 / 선택 완료 / 다음 단계에서 표지와 내용을 다듬어요.","no":"콘텐츠 선택하기를 누르면 이 창이 뜹니다. 그룹을 고른 뒤 활동이나 글감 전체를 체크하면 그 안의 글이 한꺼번에 들어갑니다. 실습에서는 제가 쓴 글 한 편을 넣었습니다.","alt":["콘텐츠 선택 창"]},{"n":34,"t":"디지털 책 만들기 ③ 표지 꾸미기","sec":6,"x":"1 / 표지 고르기 / 왼쪽 목록에서 표지를 누르면 표지 설정이 나와요. / 2 / 표지 제목 · 그룹 이름 / 실습: 우리들의 가을 / 3 / 서체 · 제목 크기 / 4 / 표지 이미지 / 권장 크기 584×818 / 5 / 표지 전체를 이미지로 / 켜면 이미지가 표지 전체를 채워요. / 주의 / 표지 제목과 이미지가 없으면 다음 단계로 넘어가지 않아요.","no":"표지 제목과 표지 이미지는 필수입니다. 실습 중에 이미지를 넣지 않고 다음을 눌렀더니 책의 표지제목과 이미지는 필수입니다라는 안내가 떴습니다. 학생 그림을 스캔해 표지로 쓰면 학급 문집 느낌이 잘 납니다.","alt":["표지 설정 화면"]},{"n":35,"t":"디지털 책 만들기 ④ 글 페이지와 내지 확인","sec":6,"x":"1 / 지금 단계 / 콘텐츠 선택 단계에서 편집해요. / 2 / 글 고르기 / 목록에서 글을 누르면 그 페이지가 보여요. / 3 / 페이지 미리보기 / 날짜 · 그룹 이름 · 작성자가 자동으로 들어가요. / · / 내지 설정 / 본문 서체 · 글자 크기 · 정렬 · 메인 색상을 바꿔요. / TIP / 목차와 활동 · 글감 간지도 자동으로 만들어져요.","no":"목록에서 글을 누르면 실제 책 페이지가 어떻게 나오는지 보입니다. 글을 고르면 아래에 내지 설정이 나와서 서체와 글자 크기, 정렬, 색상을 바꿀 수 있습니다. 작성자 이름은 가렸습니다.","alt":["책 속 글 페이지 미리보기"]},{"n":36,"t":"디지털 책 만들기 ⑤ 임시 저장하고 미리보기","sec":6,"x":"1 / 임시 저장 확인 / 저장한 뒤에는 콘텐츠를 다시 고를 수 없어요. 편집은 돼요. / 2 / 페이지 넘기기 / 키보드 ← → 로 넘겨요. / 3 / 삭제 · 이전 / 4 / 최종 발행 / 책을 완성해 내 책장에 올려요. / TIP / 실습 책 '우리들의 가을'은 임시 저장까지만 해 두었어요.","no":"임시 저장 및 다음을 누르면 확인 창이 뜹니다. 임시 저장하고 나면 넣을 글을 다시 고를 수 없으니, 글을 다 모은 다음에 저장하세요. 미리보기에서 페이지를 넘겨 보고 이상이 없으면 최종 발행을 누릅니다.","alt":["책 미리보기와 임시 저장 확인 창"]},{"n":37,"t":"디지털 책 만들기 ⑥ 발행한 책 나누기","sec":6,"x":"1 / 두쪽 보기 · 삭제 / 펼친 책처럼 두 쪽씩 봐요. / 2 / 인쇄 제작 / 종이책 인쇄를 맡겨요. 주문 내역은 내 책장에서 / 3 / 뷰어 링크 복사 / 링크로 가정이나 다른 반과 나눠요. / 4 / PDF 다운로드 / 파일로 받아 보관하거나 인쇄해요. / 주의 / 인쇄 제작은 주문 전에 비용과 절차를 꼭 확인해 주세요.","no":"발행한 책은 내 책장의 발행 탭에 모이고, 열면 이 화면이 나옵니다. 뷰어 링크를 복사해 가정에 보내거나 PDF로 내려받을 수 있고, 종이책 인쇄도 맡길 수 있습니다. 화면은 제가 작년에 만든 책이라 이름을 가렸습니다.","alt":["발행한 디지털 책 보기 화면"]},{"n":38,"t":"더 알아보기 — JAJAK Insight (베타)","sec":7,"x":"마무리 / · / 서술형 평가 전문 AI 엔진 / 학생 답안을 분석해 일관된 기준과 근거 있는 채점을 돕는다고 소개해요. / · / 들어가는 길 / 자작자작 왼쪽 아래 Insight 배너로 들어가요. / · / 메뉴 / 내 문항 · 내 문항 풀어보기 · 자료실 · 학생 관리 / · / 이용 기간 / 2026년 12월까지 (베타) / 주의 / 베타 기간에 만든 데이터는 서비스가 끝나면 남지 않고 정식 서비스로 옮겨지지 않아요.","no":"JAJAK Insight는 서술형 평가 문항을 만들고 AI 채점을 돕는 별도 서비스입니다. 주소로 바로 가면 로그인 창이 뜨니 자작자작 왼쪽 아래 배너로 들어가셔야 합니다. 베타 기간 데이터는 남지 않는다는 안내가 있어 오늘은 소개만 드립니다.","alt":["JAJAK Insight 로그인 화면"]},{"n":39,"t":"쓰기 전에 기억해 둘 여섯 가지","sec":7,"x":"마무리 · 꼭 알아 둘 점 / 개인정보 동의 먼저 / 학생 계정을 만들기 전에 동의서를 받아요. 만 14세 미만은 보호자 서명 / 바꿀 수 없는 설정 / 작성 방식(온라인·손글씨)과 제출 편수는 글감을 만든 뒤 못 바꿔요. / AI 도움은 5분 간격 / 학생 AI 글쓰기 도움은 5분마다 한 번 받을 수 있어요. / AI 피드백은 선생님이 확인 / 공개 전에 기준별 평가와 점수를 보고 필요하면 고쳐요. / 책은 글을 다 모은 뒤 저장 / 임시 저장 뒤에는 넣을 글을 다시 고를 수 없어요. / 크롬 권장 / 디지털 책 만들기는 크롬에 맞춰져 있어요.","no":"오늘 실습하면서 화면에 직접 뜬 안내들만 모았습니다. 특히 개인정보 동의서와, 글감을 만든 뒤 작성 방식과 제출 편수를 바꿀 수 없다는 점은 처음 쓰실 때 가장 많이 놓치는 부분이라 한 번 더 말씀드립니다.","alt":[]},{"n":40,"t":"수업에 이렇게 써 보세요","sec":7,"x":"마무리 · 수업 활용 / 아침 글쓰기 루틴 / 주제별 활동에 글감을 미리 넣어 두고 하루 하나씩. 일기·관찰 기록은 '여러 편 제출' / 교과 서술형 평가 / 설득·정보 전달 갈래를 고르고 성취기준을 평가 기준으로 직접 추가 / 공책 글도 그대로 / 손글씨 글감으로 만들고 학생 공책 사진을 올려 OCR로 평가 / 학년말 학급 문집 / 한 해 동안 쓴 글을 골라 디지털 책으로 엮고 링크·PDF·인쇄로 나눠요 / 학생과 함께 처음 시작할 때 / 비공개 그룹 만들기 → 개인정보 동의서 받기 → 계정 생성 또는 초대 → 추천 글감 하나로 첫 글쓰기","no":"아침 글쓰기처럼 매일 하는 활동은 활동 하나에 글감을 여러 개 미리 넣어 두면 편합니다. 서술형 평가로 쓰실 때는 성취기준을 평가 기준으로 직접 넣는 것을 추천드립니다. 처음 시작하실 때는 추천 글감 하나로 가볍게 시작해 보세요.","alt":[]},{"n":41,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":7,"x":"연수가 끝난 뒤에도 / 그룹 · 학생 계정 설정 / 그룹 개설부터 학생 초대, 계정 생성까지 함께 해 드려요. / 글감 · 평가 기준 만들기 / 우리 반 수업에 맞는 글감과 평가 기준을 같이 만들어요. / 개인정보 동의서 / 학생 계정 생성에 필요한 동의서를 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 직접 써 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 그룹과 학생 계정 설정, 글감과 평가 기준 만들기는 교실로 찾아가 함께 해 드리겠습니다.","alt":[]}],"offs":[[0,52884],[52884,57772],[110656,61510],[172166,52514],[224680,58228],[282908,59184],[342092,67520],[409612,61372],[470984,68400],[539384,63924],[603308,78430],[681738,58932],[740670,55252],[795922,67714],[863636,79882],[943518,64720],[1008238,74430],[1082668,60120],[1142788,64748],[1207536,74486],[1282022,79568],[1361590,61536],[1423126,70012],[1493138,78518],[1571656,111594],[1683250,50774],[1734024,69902],[1803926,71066],[1874992,63040],[1938032,65560],[2003592,57360],[2060952,56834],[2117786,58084],[2175870,59932],[2235802,74526],[2310328,57922],[2368250,82070],[2450320,61228],[2511548,62736],[2574284,60392],[2634676,42498]],"toffs":[[0,3654],[3654,4580],[8234,5330],[13564,4508],[18072,4654],[22726,4860],[27586,5836],[33422,5142],[38564,5208],[43772,4620],[48392,5306],[53698,5186],[58884,4220],[63104,5428],[68532,6082],[74614,4882],[79496,5698],[85194,4972],[90166,5298],[95464,5930],[101394,5554],[106948,5112],[112060,5414],[117474,5934],[123408,7936],[131344,3868],[135212,5668],[140880,5652],[146532,5604],[152136,5574],[157710,4778],[162488,4540],[167028,4914],[171942,5032],[176974,5794],[182768,5112],[187880,4776],[192656,4808],[197464,5182],[202646,4858],[207504,4032]],"packSize":2677174,"thumbSize":211536},{"key":"doopedia","name":"두피디아","title":"두피디아 사용 안내서","group":"etc","sub":"경북AI배움터로 접속해 수업 자료 찾기","fee":"무료 범위","feeKind":"free","feeNote":"무료로 쓰는 대신 광고가 함께 나와요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 두피디아로 할 수 있는 일"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 두피디아에 접속하고 첫 화면을 살펴봐요"},{"start":6,"num":"2","label":"검색하고 읽기","desc":"검색하고 항목을 읽고 관련 항목으로 이어 가며 공유해요"},{"start":11,"num":"3","label":"쉬운 백과","desc":"쉬운 백과로 아이들 눈높이 글을 읽고 원문과 비교해요"},{"start":14,"num":"4","label":"사진과 영상","desc":"항목 사진, 슬라이드 쇼, 동영상을 수업 자료로 찾아요"},{"start":20,"num":"5","label":"둘러보기","desc":"분야 메뉴, 포토 커뮤니티, 지구촌 여행기를 둘러봐요"},{"start":26,"num":"6","label":"요령과 활용","desc":"검색 요령, 광고와 저작권 유의사항, 수업 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"두피디아","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 수업 자료 찾기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 두피디아를 함께 살펴보겠습니다. 두피디아는 두산이 운영하는 온라인 백과사전으로, 수업 자료를 찾거나 아이들이 조사 학습을 할 때 쓰기 좋습니다. 화면은 연수를 준비하면서 직접 검색해 보며 찍은 것입니다.","alt":["두피디아 첫 화면의 똑똑한 콘텐츠, 최신 지식 콘텐츠, 오늘의 역사"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 두피디아, 첫 화면 / 04–05쪽 / STEP 2 / 검색하고 읽기 / 검색 결과, 항목 읽기, 공유 / 06–10쪽 / STEP 3 / 쉬운 백과 / 아이들 눈높이 글로 읽기 / 11–13쪽 / STEP 4 / 사진과 영상 / 이미지, 슬라이드 쇼, 동영상 / 14–19쪽 / STEP 5 / 둘러보기 / 분야, 포토 커뮤니티, 여행기 / 20–25쪽 / STEP 6 / 요령과 활용 / 검색 요령, 유의사항, 수업 활용 / 26–29쪽","no":"여섯 단계로 진행하겠습니다. 시간이 부족하면 2단계 검색하고 읽기와 3단계 쉬운 백과만 꼭 해 보세요. 두피디아는 로그인 없이 쓰는 도구라서 처음 써 보셔도 어렵지 않을 거라고 생각합니다.","alt":[]},{"n":3,"t":"두피디아로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 백과사전 / 769,703개 항목 분류 태그·참조항목으로 이어 읽기 / 쉬운 백과 / 일부 항목은 해요체로 쉽게 풀어 쓴 글이 있어요 / 사진과 영상 / 항목 사진, 슬라이드 쇼, 짧은 지식 영상 / 포토 커뮤니티·여행기 / 사진 8,465,190장 여행기 17,692건 / 배움터로 접속하면 / 회원가입 없이 바로 검색 / 배움터에서 두피디아를 누르면 첫 화면이 바로 열려요. 읽고 보는 기능은 로그인 없이 쓸 수 있어요. / 지식나누기 글쓰기 같은 참여 기능만 로그인이 필요해요. (항목 수: 2026. 10. 2. 첫 화면 기준)","no":"두피디아는 백과사전, 포토 커뮤니티, 지구촌 여행기 세 가지로 이루어져 있습니다. 미리캔버스나 퀴즈앤과 달리 따로 로그인하지 않아도 대부분의 기능을 쓸 수 있어서, 아이들에게 안내하기도 편하다고 보았습니다. 항목 수와 사진 수는 연수를 준비한 날 첫 화면에 나온 숫자입니다.","alt":[]},{"n":4,"t":"배움터에서 두피디아 열기","sec":1,"x":"1 / 에듀테크 서비스 / 배움터 첫 화면에서 조금 내리면 보여요. / 2 / 두피디아 카드 / 누르면 새 탭에서 두피디아가 열려요. / 3 / 서비스 설명 / 카드에 마우스를 올리면 짧은 소개가 나와요. / TIP / 카드가 안 보이면 목록 아래 화살표(1/4)로 다음 쪽을 넘겨 보세요.","no":"배움터에 로그인한 뒤 첫 화면을 조금 내리면 에듀테크 서비스 목록이 나옵니다. 두피디아 카드를 누르면 새 탭에서 두피디아 첫 화면이 열립니다. 목록은 네 쪽으로 나뉘어 있어서, 두피디아가 안 보이면 아래 화살표로 넘겨 보시면 됩니다.","alt":["경북AI배움터 에듀테크 서비스 목록의 두피디아 카드"]},{"n":5,"t":"두피디아 첫 화면","sec":1,"x":"1 / 검색창 / 궁금한 낱말을 넣어 찾아요. / 2 / 세 가지 서비스 / 백과사전 · 포토 커뮤니티 · 지구촌 여행기 / 3 / 분야 메뉴 / 줄 세 개 아이콘(전체 분야), 문화예술~VIDEO / 4 / 오늘의 역사 / 오늘 날짜에 있었던 일을 보여 줘요. / 5 / 로그인 · 회원가입 / 검색하고 읽는 데는 필요 없어요.","no":"두피디아 첫 화면입니다. 맨 위 검색창이 가장 많이 쓰는 곳이고, 오른쪽 위 버튼 세 개로 백과사전, 포토 커뮤니티, 지구촌 여행기를 오갈 수 있습니다. 오른쪽의 오늘의 역사는 달력에서 날짜를 바꿀 수 있어서 아침 활동 이야깃거리로 쓰기 좋습니다. 오른쪽 위 로그인은 오늘 쓰지 않습니다.","alt":["두피디아 첫 화면의 검색창, 서비스 버튼, 분야 메뉴, 오늘의 역사"]},{"n":6,"t":"검색어 넣기","sec":2,"x":"1 / 검색창 / 한글날을 앞두고 '훈민정음'을 넣어 봤어요. / 2 / 추천 검색어 / 글자를 넣는 동안 관련 낱말이 아래에 떠요. 골라 누를 수 있어요. / TIP / 돋보기를 누르면 백과사전·이미지·동영상을 한꺼번에 찾는 통합검색 결과가 나와요.","no":"다음 주가 한글날이라 '훈민정음'으로 검색해 보겠습니다. 검색창에 글자를 넣는 동안 아래에 추천 검색어가 나오는데, 한자 표기나 관련 낱말도 함께 보여 줍니다. 돋보기를 누르면 통합검색 결과로 넘어갑니다.","alt":["검색창에 훈민정음을 입력하자 추천 검색어가 나온 화면"]},{"n":7,"t":"검색 결과 살펴보기","sec":2,"x":"1 / 결과 종류 / 백과사전·이미지·동영상·오디오·포토커뮤니티별 개수 / 2 / 첫 결과가 워드프로세서? / 분류 태그가 'IT'예요. 이름만 같은 다른 항목이에요. / 3 / 찾던 항목 / 역사·문화유적 태그와 사진을 보고 골라요. / TIP / 제목 옆 회색 분류 태그를 먼저 보면 엉뚱한 항목에 들어가지 않아요.","no":"재미있게도 '훈민정음'의 첫 결과는 예전 삼성의 한글 워드프로세서였습니다. 제목 옆 분류 태그가 IT로 붙어 있어서 구별할 수 있습니다. 아이들과 쓸 때도 분류 태그를 먼저 보는 습관을 들이면 좋겠다고 생각했습니다. 우리가 찾던 항목은 두 번째, 역사와 문화유적 태그가 붙은 항목입니다.","alt":["훈민정음 통합검색 결과. 첫 결과는 IT 분류의 워드프로세서"]},{"n":8,"t":"항목 첫 화면","sec":2,"x":"1 / 분류 태그 / 이 항목이 어느 분야인지 / 2 / 쉬운 백과 보기 / 아이들 눈높이 글로 (STEP 3) / 3 / 이미지(11) / 이 항목 사진만 모아 보기 (STEP 4) / 4 / 인쇄 · 공유 / 종이로 뽑거나 링크 보내기 / 5 / 요약 / 굵은 글씨 두 줄로 핵심 먼저 / 6 / 참조항목 / 관련 항목으로 이어 읽기","no":"항목에 들어가면 맨 위에 분류 태그와 제목이 나오고, 오른쪽 위에 쉬운 백과 보기와 이미지 버튼이 있습니다. 본문 첫머리의 굵은 글씨 두 줄이 요약이라 아이들에게는 이 부분만 먼저 읽혀도 충분할 때가 많습니다. 오른쪽 참조항목에는 세종실록, 월인석보처럼 함께 읽으면 좋은 항목이 모여 있습니다.","alt":["훈민정음 항목 첫 화면의 분류 태그, 쉬운 백과 보기, 이미지, 인쇄와 공유, 요약, 참조항목"]},{"n":9,"t":"본문 읽기","sec":2,"x":"1 / 사진 / 화살표나 아래 작은 사진으로 넘겨요. / 2 / 기본 정보 표 / 지정일, 소장처, 시대 등을 한눈에 / 3 / 지도보기 / 있는 곳을 지도로 확인해요. / 4 / 파란 글자 / 따로 항목이 있는 낱말이에요. / 5 / 포토 커뮤니티 / 사용자들이 올린 관련 사진","no":"조금 내리면 사진과 기본 정보 표가 나란히 나옵니다. 문화유산 항목은 지정일, 소장처, 소재지가 표로 정리되어 있고 지도보기 버튼도 있습니다. 본문의 파란 글자는 따로 항목이 있는 낱말이라 이어서 찾아 읽을 수 있습니다. 오른쪽 아래에는 광고가 나오는데, 화면에서는 흐리게 처리했습니다.","alt":["훈민정음 항목 본문의 사진, 기본 정보 표, 지도보기, 파란 글자, 포토 커뮤니티"]},{"n":10,"t":"이어 읽고 공유하기","sec":2,"x":"1 / 공유하기 / 페이스북 · 카카오톡 · 링크 복사 / 2 / '학습' 태그 / 두피디아의 학습(학년·과목) 분류에 묶인 항목이에요. / 3 / 참조항목 / 훈민정음에서 '세종실록'을 눌러 넘어온 화면이에요. / TIP / 링크를 복사해 학급 게시판에 올려 두면 아이들이 같은 항목으로 바로 들어와요.","no":"훈민정음 항목의 참조항목에서 세종실록을 누르면 이렇게 바로 넘어갑니다. 공유 버튼을 누르면 페이스북, 카카오톡, 링크 복사가 나옵니다. 아이들에게 같은 항목을 보여 주고 싶을 때는 링크를 복사해서 학급 게시판이나 클래스룸에 올려 두시면 편합니다.","alt":["참조항목에서 넘어간 세종실록 항목과 공유하기 창"]},{"n":11,"t":"쉬운 백과로 바꿔 보기","sec":3,"x":"1 / 쉬운 백과 표시 / 지금 쉬운 글을 보고 있다는 뜻 / 2 / 원문 보기 / 원래 백과사전 글로 돌아가요. / 3 / 해요체 요약 / 말하듯 풀어 쓴 두 줄 요약 / 4 / 사진 · 기본 정보 / 원문과 같은 자료가 그대로 나와요. / TIP / 모든 항목에 있지는 않아요. 오른쪽 위에 '쉬운 백과 보기'가 보일 때만 쓸 수 있어요.","no":"초등 교실에서 가장 쓸모 있다고 느낀 기능이 쉬운 백과입니다. 항목 오른쪽 위의 쉬운 백과 보기를 누르면 같은 항목이 해요체로 바뀌고, 제목 옆에 쉬운 백과 표시가 붙습니다. 다만 모든 항목에 있지는 않습니다. 예를 들어 '화산 폭발 원리' 항목에는 이 버튼이 없었습니다.","alt":["쉬운 백과로 바뀐 훈민정음 항목. 쉬운 백과 표시와 원문 보기 버튼"]},{"n":12,"t":"쉬운 백과 본문","sec":3,"x":"1 / 소제목 / 창제와 국보 지정, 해례본의 발견, 보존 이야기로 나눠 보여 줘요. / 2 / 이야기하듯 쓴 문장 / 한자어를 줄이고 짧은 문장으로 풀어 써요. / TIP / 조사 학습 때 쉬운 백과로 먼저 읽고, 더 궁금한 부분은 원문 보기로 넓혀 가면 좋아요.","no":"쉬운 백과 본문은 소제목 세 개로 나뉘어 있어서 아이들이 어디까지 읽었는지 알기 쉽습니다. 원문의 긴 문단이 짧은 문장으로 풀려 있어서 아이들이 혼자 읽기에도 부담이 덜하다고 보았습니다. 오른쪽 광고 자리는 흐리게 처리했습니다.","alt":["쉬운 백과 본문. 소제목 세 개로 나뉜 해요체 글"]},{"n":13,"t":"같은 항목, 두 가지 글","sec":3,"x":"원문 (백과사전) / 쉬운 백과 / 문체 / '~이다'로 끝나는 백과사전 문체 / '~예요, ~어요' 해요체 / 구성 / 긴 문단이 이어짐 / 소제목 세 개로 나눔 / 낱말 / 한자어·전문 용어를 그대로 씀 / 쉬운 말로 풀어 씀 / 어울리는 때 / 수업 준비, 사실 확인 / 아이들의 첫 읽기, 조사 학습 / 쉬운 백과는 줄여 쓴 글이라 세부 내용이 묶이기도 해요 / 원문은 책의 예의는 세종이, 해례는 집현전 학사들이 썼다고 나누어 적었는데, 쉬운 백과는 '세종대왕과 집현전 학자들이 만든' 글자로 묶어 적었어요. 이름·연도·숫자는 원문 보기로 한 번 더 확인해요.","no":"원문과 쉬운 백과를 나란히 읽어 보니 차이가 분명했습니다. 쉬운 백과는 아이들이 읽기 좋은 대신, 원문을 줄이는 과정에서 내용이 묶이는 부분이 있었습니다. 예를 들어 원문은 책의 어느 부분을 누가 썼는지 나누어 적었는데, 쉬운 백과는 한 문장으로 묶었습니다. 아이들이 조사 결과를 정리할 때는 이름이나 연도만큼은 원문으로 확인하도록 안내하시면 좋겠습니다.","alt":[]},{"n":14,"t":"항목 사진 모아 보기","sec":4,"x":"1 / 이미지 목록 / 항목 위 '이미지(11)'를 누르면 열려요. / 2 / 사진 / 누르면 크게 볼 수 있어요. / TIP / 검색 결과의 이미지 탭보다 항목 안의 이미지가 더 정확해요. (26쪽)","no":"항목 오른쪽 위의 이미지 버튼을 누르면 그 항목에 쓰인 사진만 모아서 보여 줍니다. 훈민정음은 책을 여러 방향에서 찍은 사진 열한 장이 있었습니다. 사진을 누르면 크게 볼 수 있습니다.","alt":["훈민정음에 대한 이미지 11장 목록"]},{"n":15,"t":"사진 크게 보기","sec":4,"x":"1 / 사진정보 / 저작권 표시 © doopedia.co.kr / 2 / 관련항목 / 이 사진이 쓰인 항목, 쉬운 백과로도 가요. / 3 / Slide Show / 사진을 큰 창에 띄워 넘겨 봐요. / 4 / 사진 목록 / 아래 작은 사진으로 바로 이동","no":"사진을 누르면 큰 사진과 함께 아래에 사진 정보가 나옵니다. 사진정보 칸에 저작권 표시가 있고, 관련항목에서 원래 항목이나 쉬운 백과로 돌아갈 수 있습니다. 오른쪽 아래 Slide Show 버튼이 수업에서 특히 쓸모 있습니다.","alt":["사진 아래의 사진정보, 관련항목, Slide Show 버튼, 사진 목록"]},{"n":16,"t":"슬라이드 쇼로 띄우기","sec":4,"x":"1 / 슬라이드 쇼 창 / 화면 가운데에 사진이 크게 떠요. / 2 / 넘기기 / 양옆 화살표로 앞뒤 사진 / 3 / 닫기 / X를 누르면 원래 화면으로 / TIP / 교실 TV에 띄워 놓고 한 장씩 넘기며 \"무엇이 보이나요?\" 하고 묻기 좋아요.","no":"Slide Show를 누르면 이렇게 큰 창이 뜹니다. 훈민정음 책 사진에 ㅂ, ㅁ, ㄷ, ㅋ 같은 자음이 크게 보이는데, 아이들에게 무엇이 보이는지 먼저 묻고 시작하면 한글날 도입으로 좋겠다고 생각했습니다. 오른쪽 위 X를 누르면 원래 화면으로 돌아갑니다.","alt":["훈민정음 책 사진을 띄운 슬라이드 쇼 창"]},{"n":17,"t":"동영상 찾기","sec":4,"x":"1 / 동영상 탭 / '화산'을 검색하니 영상이 22개 나왔어요. / 2 / 영상 목록 / 성산일출봉, 화산쇄설층, 흑요석처럼 우리나라 지형 영상이 많아요. / TIP / '훈민정음'처럼 영상이 0개인 낱말도 있어요. 탭의 숫자를 먼저 확인해요.","no":"이번에는 과학 화산 단원을 떠올리며 '화산'으로 검색해 보았습니다. 검색 결과 위쪽의 동영상 탭을 누르면 영상만 모아서 볼 수 있습니다. 제주 지형 영상이 많아서 단원 도입에 쓸 만했습니다. 반대로 훈민정음은 영상이 하나도 없었으니, 탭 옆 숫자를 먼저 보시면 됩니다.","alt":["화산 검색 결과의 동영상 탭. 성산일출봉, 흑요석 등 영상 목록"]},{"n":18,"t":"영상 보기","sec":4,"x":"1 / 영상 제목 / 화산이 빚어낸 거대한 성곽, 성산일출봉 / 2 / 재생수 · 좋아요 / 얼마나 봤는지 보여 줘요. / 3 / 목록 · 좋아요 · 공유 / 영상 목록으로 돌아가거나 공유해요. / 4 / 세로형 짧은 영상 / 휴대폰 화면처럼 세로로 된 숏폼이에요. / TIP / 설명란에 'AI 보이스 사용' 안내가 붙은 영상도 있어요.","no":"성산일출봉 영상을 눌러 보았습니다. 휴대폰 화면처럼 세로로 된 짧은 영상이라 TV에 띄우면 가운데에 길쭉하게 나옵니다. 영상 아래 설명란에는 AI 보이스를 썼다는 안내가 있었습니다. 소리가 나오니 교실 스피커를 미리 확인해 주세요.","alt":["성산일출봉 세로형 영상 화면과 재생수, 목록, 좋아요, 공유 버튼"]},{"n":19,"t":"VIDEO 메뉴에서 둘러보기","sec":4,"x":"1 / VIDEO / 위 메뉴에서 바로 들어가요. / 2 / 인기 토픽 추천 영상 / 요즘 기념일에 맞춘 영상이 올라와요. (이날은 국군의 날) / 아래로 내리면 / 조회수 Top3 · 최신 트렌드 영상 · 최신 트렌드 숏폼 / TIP / 최신 영상에 김천 청암사 수도암 동·서 삼층석탑, 고령 지산동 고분군처럼 경북 영상도 있었어요.","no":"검색하지 않고 영상을 둘러보고 싶을 때는 위 메뉴의 VIDEO를 누르면 됩니다. 맨 위에는 기념일에 맞춘 추천 영상이 나오고, 아래로 내리면 조회수 순위와 최신 영상, 짧은 숏폼이 이어집니다. 최신 영상 가운데 김천과 고령 문화유산 영상이 있어서 우리 지역 공부에도 쓸 수 있겠다고 보았습니다.","alt":["두피디아 VIDEO 메뉴 첫 화면의 인기 토픽 추천 영상"]},{"n":20,"t":"분야별로 둘러보기","sec":5,"x":"1 / 전체 카테고리 / 왼쪽 위 줄 세 개 아이콘을 누르면 23개 분야가 열려요. / 철학 / 종교 / 사회과학 / 경제·경영 / 여행 / 스포츠 / 생활 / 교통·통신 / 순수과학 / 기술과학 / 동물 / 식물 / 의학 / IT / 문화예술 / 지리학 / 역사 / 문화유적 / 세계지명 / 인물 / 기관·단체 / 지역 / 학습 / TIP / '학습' 분야 안에는 학년·과목 분류가 있어요. 목록이 길어서, 수업 자료는 검색으로 찾는 편이 빨라요.","no":"왼쪽 위의 줄 세 개 아이콘을 누르면 철학부터 학습까지 23개 분야가 열립니다. 맨 끝의 학습 분야에는 학년과 과목 분류가 있는데, 항목이 만 개가 넘게 한꺼번에 나와서 원하는 자료를 고르기는 쉽지 않았습니다. 수업 자료는 검색으로 찾고, 분야 메뉴는 아이들이 자유롭게 둘러볼 때 쓰시면 좋겠습니다.","alt":["왼쪽 위 메뉴 아이콘을 누르면 열리는 전체 카테고리 목록"]},{"n":21,"t":"분야 첫 화면 (과학기술)","sec":5,"x":"1 / 큰 분야 메뉴 / 문화예술 · 사회역사 · 과학기술 · 동식물 / 2 / 인기 토픽 추천 콘텐츠 / 사진과 함께 읽을거리를 골라 줘요. / 3 / 조회수 Top3 / 그 분야에서 많이 본 항목 / TIP / 아래로 내리면 #소프트웨어, #항공우주공학 같은 컬렉션과 숏폼이 이어져요.","no":"위 메뉴의 큰 분야를 누르면 이런 첫 화면이 나옵니다. 과학기술에서는 티라노사우루스가 추천 콘텐츠로, 24절기 같은 항목이 조회수 순위에 올라 있었습니다. 아래로 내리면 주제별 컬렉션이 있어서 아이들이 관심 분야를 골라 읽기 좋습니다.","alt":["과학기술 분야 첫 화면의 인기 토픽 추천 콘텐츠와 조회수 Top3"]},{"n":22,"t":"포토 커뮤니티","sec":5,"x":"1 / 사진 검색 / 장소나 문화유산 이름으로 찾아요. / 2 / 그룹별 · 전체 리스트 보기 / 사진을 묶음이나 목록으로 봐요. / 3 / 사진등록 / 회원이 사진을 올리는 곳 (오늘은 쓰지 않아요) / 4 / 서비스 이동 / 백과사전 · 포토 커뮤니티 · 지구촌 여행기","no":"포토 커뮤니티는 사용자들이 직접 찍어 올린 사진을 모아 둔 곳입니다. 첫 화면 오른쪽 위 버튼으로 들어오면 화면 색이 어둡게 바뀝니다. 여행지와 문화유산 사진이 많아서 사회 수업 자료를 찾을 때 쓸 만합니다.","alt":["두피디아 포토 커뮤니티 첫 화면의 사진 목록"]},{"n":23,"t":"사진 검색 (경주 첨성대)","sec":5,"x":"1 / 지역 분류 / 경상북도 > 경주시 > 인왕동처럼 장소로 정리돼요. / 2 / 사진 미리보기 / 낮, 밤, 계절이 다른 사진이 함께 나와요. / 3 / 검색 결과 수 / 게시물 21건, 사진 287컷 / TIP / 경북 문화유산 사진을 찾을 때 좋아요. 화면 속 올린 사람 이름은 흐리게 처리했어요.","no":"포토 커뮤니티에서 첨성대를 검색해 보았습니다. 게시물 21건, 사진 287컷이 나왔고, 낮 사진뿐 아니라 조명을 켠 밤 사진도 있었습니다. 경주처럼 우리 지역 문화유산을 다룰 때 여러 각도의 사진을 보여 주기 좋습니다. 사진을 올린 분들의 이름은 개인정보라 흐리게 처리했습니다.","alt":["포토 커뮤니티에서 첨성대를 검색한 결과. 지역 분류와 사진 미리보기"]},{"n":24,"t":"사진 게시물 보기","sec":5,"x":"1 / 지역 / 찍은 곳의 주소까지 나와요. / 2 / 사진 모음 / 한 게시물에 여러 각도의 사진 / 3 / 목록 · 스크랩 · 프린트 · 링크 / 게시물을 모아 두거나 주소를 보내요. / 4 / 키워드 · 백과사전 항목보기 / 사진에서 백과 항목으로 넘어가요. / TIP / 사진 사이에 광고가 섞여 나와요. (화면에서는 흐리게 처리)","no":"게시물을 하나 열면 찍은 곳의 주소와 사진 여러 장이 나옵니다. 아래쪽 백과사전 항목보기를 누르면 첨성대 백과 항목으로 이어집니다. 사진 사이에 광고 칸이 하나 섞여 있었는데, 화면에서는 흐리게 처리했습니다. 올린 사람 이름도 흐리게 했습니다.","alt":["경주 첨성대 사진 게시물. 지역 정보, 사진 모음, 스크랩과 링크 버튼, 키워드"]},{"n":25,"t":"지구촌 여행기","sec":5,"x":"1 / 여행기 검색 / 나라나 도시 이름으로 찾아요. / 2 / 여행 메뉴 / 해외여행 · 국내여행 · 테마여행 · 여행작가 · 이벤트 / 3 / 새 여행기 작성 / 회원이 글을 쓰는 곳 (오늘은 쓰지 않아요) / TIP / 해외여행 여행기만 11,264편이에요. 세계 여러 나라를 조사할 때 사진 자료로 볼 만해요.","no":"지구촌 여행기는 여행 작가와 사용자들이 쓴 여행 글 모음입니다. 해외여행 메뉴에만 만 천 편이 넘는 여행기가 있었습니다. 글은 어른 눈높이라 아이들에게 그대로 읽히기보다는, 세계 여러 나라 수업에서 사진 자료로 함께 보시는 쪽을 권해 드립니다.","alt":["지구촌 여행기 첫 화면의 검색창, 여행 메뉴, 새 여행기 작성 버튼"]},{"n":26,"t":"검색어는 구체적으로","sec":6,"x":"'화산' → 이미지 탭 / 중국의 산 화산(華山) 사진만 줄줄이 나와요. / '화산 폭발' / '화산 폭발 원리' 항목이 맨 위에 나와요. / 이렇게 찾아요 / 낱말 하나 더 붙이기 / 화산 → 화산 폭발 / 항목 안의 이미지 보기 / 찾던 항목에 들어가서 '이미지'를 누르면 그 항목 사진만 나와요. / 분류 태그 확인 / 세계지명 · 지리학 · 학습 등","no":"연수를 준비하면서 가장 의외였던 장면입니다. '화산'으로 검색한 뒤 이미지 탭을 누르니 중국의 산 이름인 화산 사진만 나왔습니다. '화산 폭발'로 낱말을 하나 더 붙이니 화산 폭발 원리 항목이 맨 위에 나왔습니다. 아이들에게도 검색어를 구체적으로 쓰는 연습을 함께 시키면 좋겠다고 생각했습니다.","alt":["화산으로 검색한 이미지 탭. 중국의 산 화산 사진이 나옴","화산 폭발로 검색한 결과. 화산 폭발 원리 항목이 맨 위"]},{"n":27,"t":"광고가 함께 나와요","sec":6,"x":"1 / 닫기 / 오른쪽 위 작은 글자예요. 잘 안 눌리면 브라우저 뒤로 가기로 닫혀요. / 2 / 열기 / 누르면 광고 사이트로 넘어가요. 누르지 않도록 미리 알려 주세요. / 본문 아래와 옆에도 배너 광고가 붙어요.","no":"두피디아는 무료로 쓰는 대신 광고가 함께 나옵니다. 화면을 넘기다가 이렇게 화면 전체를 덮는 광고가 한 번 떴습니다. 오른쪽 위 닫기 글자가 작아서 잘 눌리지 않았고, 브라우저 뒤로 가기를 누르니 닫혔습니다. 아이들이 직접 쓸 때는 광고의 열기 버튼을 누르지 않도록 미리 이야기해 주시면 좋겠습니다.","alt":["두피디아 화면 위로 뜬 전면 광고 창과 닫기, 열기 버튼","본문 아래의 저작권 표시와 배너 광고"]},{"n":28,"t":"꼭 알아 둘 점","sec":6,"x":"로그인 없이 / 읽고 보는 기능은 회원가입 없이 써요. 글쓰기·사진 올리기 같은 참여 기능만 로그인이 필요해요. / 광고 / 옆·아래 배너와 전면 광고가 떠요. 아이들에게 누르지 않도록 미리 안내해요. / 본문 저작권 / 본문 아래에 무단 전재·재배포와 AI 학습 이용을 금지한다고 적혀 있어요. 옮겨 쓸 때는 출처를 밝혀요. / 사진 저작권 / 포토 커뮤니티 사진은 올린 사람의 것이에요. 화면으로 함께 보고, 내려받아 배포하지 않아요. / 같은 이름 항목 / 훈민정음(워드프로세서), 화산(중국의 산)처럼 이름만 같은 항목이 있어요. 분류 태그를 봐요. / 쉬운 백과 확인 / 줄여 쓴 글이라 세부 내용이 묶이기도 해요. 이름·연도는 원문 보기로 확인해요.","no":"정리하면 여섯 가지입니다. 로그인 없이 쓸 수 있어 편하지만, 그만큼 광고가 함께 나옵니다. 백과 본문과 사진 모두 저작권 안내가 붙어 있어서, 수업 화면으로 보여 주는 것과 자료로 옮겨 싣는 것은 구분해 주시면 좋겠습니다. 아이들 조사 학습에서는 출처 쓰기 연습과 함께 쓰시기를 권해 드립니다.","alt":[]},{"n":29,"t":"수업에 이렇게 써 보세요","sec":6,"x":"한글날 계기 교육 / '훈민정음' 쉬운 백과를 함께 읽고, 책 사진을 슬라이드 쇼로 넘겨 보기 / 과학 단원 도입 / 화산 단원을 성산일출봉 같은 짧은 영상으로 시작하기 / 우리 지역 문화유산 / 포토 커뮤니티에서 첨성대처럼 경북 문화유산 사진을 여러 각도로 보기 / 조사 학습과 출처 쓰기 / 쉬운 백과로 읽고, 원문에서 확인한 뒤 '두피디아, 항목 이름'으로 출처 적기 / 아침 활동으로 '오늘의 역사' / 첫 화면의 오늘의 역사에서 그날 있었던 일을 하나 골라 아침 이야깃거리로 써 보세요. 10월 2일에는 소설가 김동인이 태어난 날이 있었어요.","no":"오늘 살펴본 기능으로 해 볼 만한 수업을 네 가지로 모아 보았습니다. 다음 주가 한글날이니 훈민정음 쉬운 백과와 책 사진 슬라이드 쇼로 계기 교육을 해 보시면 좋겠습니다. 조사 학습을 할 때는 쉬운 백과로 읽고, 원문으로 확인하고, 출처를 적는 순서를 함께 연습하면 정보 활용 교육으로도 이어진다고 생각합니다.","alt":[]},{"n":30,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 단원 자료 같이 찾기 / 다음 단원에 쓸 항목·사진·영상을 함께 찾아 드려요. / 조사 학습 준비 / 쉬운 백과가 있는 항목을 골라 학습지와 연결해요. / 교실 TV로 띄우기 / 슬라이드 쇼와 영상 띄우기를 옆에서 도와드려요.","no":"오늘 연수는 여기까지입니다. 두피디아는 로그인 없이 바로 쓸 수 있어서 내일 수업에도 바로 써 보실 수 있습니다. 단원 자료를 찾거나 교실 TV로 띄우다가 막히시면 언제든 불러 주세요. 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,68830],[68830,47330],[116160,61558],[177718,64668],[242386,95142],[337528,62542],[400070,93960],[494030,104738],[598768,114082],[712850,85216],[798066,99996],[898062,104716],[1002778,62056],[1064834,85876],[1150710,73228],[1223938,78808],[1302746,102956],[1405702,61142],[1466844,67048],[1533892,101088],[1634980,76844],[1711824,134286],[1846110,97970],[1944080,100000],[2044080,147286],[2191366,107684],[2299050,55632],[2354682,66580],[2421262,66018],[2487280,40096]],"toffs":[[0,4662],[4662,3802],[8464,5042],[13506,5430],[18936,6396],[25332,4396],[29728,6230],[35958,7588],[43546,7256],[50802,5830],[56632,7374],[64006,6002],[70008,4172],[74180,5870],[80050,4966],[85016,6210],[91226,6072],[97298,4958],[102256,5054],[107310,6494],[113804,5798],[119602,7316],[126918,6010],[132928,6806],[139734,6462],[146196,7392],[153588,4670],[158258,4710],[162968,5162],[168130,3910]],"packSize":2527376,"thumbSize":172040},{"key":"notion","name":"노션","title":"노션 사용 안내서","group":"etc","sub":"페이지와 데이터베이스로 학급 운영 노트 만들기","fee":"공모 선정자만 유료","feeKind":"part","feeNote":"유료 라이선스는 배움터 공모로 선정된 선생님께만 나갔어요. 무료 사용자는 배움터와 연동되지 않으니 개인 무료 계정으로 실습해요(배움터 공지 2026. 4. 6.).","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 노션과 배움터 이용 조건 소개"},{"start":4,"num":"1","label":"접속하기","desc":"배움터 연동 조건을 확인하고 개인 계정으로 들어가 첫 화면을 살펴봐요"},{"start":10,"num":"2","label":"페이지 만들기","desc":"페이지를 만들고 꾸민 뒤 블록으로 내용을 채워요"},{"start":19,"num":"3","label":"데이터베이스","desc":"데이터베이스로 학급 행사 일정을 만들고 캘린더로 봐요"},{"start":28,"num":"4","label":"템플릿","desc":"템플릿을 찾아 내 워크스페이스에 추가해요"},{"start":32,"num":"5","label":"AI로 초안","desc":"AI로 초안을 만들고 검토해 넣어요"},{"start":34,"num":"6","label":"공유와 활용","desc":"공유, 게시, 내보내기와 유의사항, 활용 아이디어를 정리해요"}],"slides":[{"n":1,"t":"노션","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 페이지와 데이터베이스로 학급 운영 노트 만들기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 노션을 함께 써 보겠습니다. 노션은 메모, 문서, 일정, 과제를 한 공간에 정리하는 도구입니다. 화면 속 페이지는 연수를 준비하면서 직접 만들어 본 학급 운영 노트입니다.","alt":["노션으로 만든 학급 운영 노트 실습 페이지"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 연동 조건, 개인 계정, 첫 화면 / 04–09쪽 / STEP 2 / 페이지 만들기 / 꾸미기, '/' 블록, 하위 페이지 / 10–18쪽 / STEP 3 / 데이터베이스 / 속성, 표, 캘린더 보기 / 19–27쪽 / STEP 4 / 템플릿 / 찾기, 무료 템플릿 추가 / 28–31쪽 / STEP 5 / AI로 초안 / 부탁하기, 검토하고 넣기 / 32–33쪽 / STEP 6 / 공유와 활용 / 공유, 게시, 내보내기, 유의사항 / 34–39쪽","no":"여섯 단계로 진행합니다. 시간이 부족하면 2단계 페이지 만들기와 3단계 데이터베이스만 꼭 해 보세요. 이 두 가지가 노션의 기본입니다.","alt":[]},{"n":3,"t":"노션으로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 페이지와 블록 / 글, 할 일, 토글, 표를 블록처럼 쌓아 문서 만들기 / 데이터베이스 / 일정과 과제를 표, 보드, 캘린더로 관리하기 / 템플릿 / 수업 계획처럼 만들어진 틀을 가져와 쓰기 / 공유와 게시 / 동료 초대, 웹 링크로 누구나 보게 하기 / 경북 교원 이용 안내 / 배움터 연동은 공모 선정 교원만 / 노션은 라이선스 수가 정해져 있어 공모로 선정된 선생님께만 유료 라이선스가 배포됐어요. / 선정되지 않았다면 개인 계정(무료)으로 오늘 기능을 그대로 써 볼 수 있어요. (배움터 공지 2026. 4. 6. · Q&A 2026. 8. 18.)","no":"노션은 블록을 쌓아 페이지를 만들고, 데이터베이스로 일정과 과제를 관리하는 도구입니다. 다만 배움터 연동은 공모로 라이선스를 받은 선생님만 됩니다. 선정되지 않으신 분도 개인 무료 계정으로 오늘 실습을 그대로 따라 하실 수 있습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 노션 찾기","sec":1,"x":"1 / 에듀테크 서비스 2쪽 / 메인 화면 에듀테크 서비스에서 > 를 눌러 2쪽으로 넘기면 노션이 있어요. / 2 / 마우스를 올리면 설명 / 메모, 문서, 일정, 과제를 한 공간에서 정리하는 생산성 서비스라고 안내돼요. / TIP / 이용 안내 → 안내 자료실의 노션 '매뉴얼 보기'는 지금 젭 퀴즈 안내로 연결돼 있어요. 이 안내서를 참고해 주세요.","no":"배움터 주소는 aischool.gbe.kr입니다. 교원으로 로그인한 뒤 에듀테크 서비스 두 번째 쪽 마지막 칸에 노션이 있습니다. 안내 자료실의 노션 매뉴얼 링크는 연수 준비 시점에 젭 퀴즈 안내로 연결되어 있었습니다.","alt":["배움터 에듀테크 서비스 2쪽의 노션 카드와 설명"]},{"n":5,"t":"배움터 연동은 라이선스를 받은 선생님만","sec":1,"x":"1 / 무료 사용자는 연동 불가 / 노션 정책으로 무료 사용자는 배움터와 연결되지 않아요. (공지 2026. 4. 6.) / 2 / 공모 선정자에게 유료 라이선스 / 선정되셨다면 창의인재과-11332 공문을 확인해 주세요. / 3 / 인증코드는 네이버웍스 메일함 / 이메일 인증코드는 배움터 네이버웍스 → 오른쪽 위 메일에서 볼 수 있어요.","no":"위쪽은 배움터 공지사항, 아래쪽은 Q&A 관리자 답변입니다. 노션은 라이선스 수가 정해져 있어서 공모로 선정된 선생님께만 유료 라이선스가 나갔습니다. 선정되신 분은 처음 접속할 때 이메일 인증코드를 받게 되는데, 이 코드는 배움터 네이버웍스 메일함에서 확인하실 수 있습니다.","alt":["배움터 공지사항과 Q&A 답변 중 노션 라이선스 안내"]},{"n":6,"t":"이 문구가 보이면 개인 계정으로","sec":1,"x":"1 / Please contact your administrator… / 배움터에서 노션을 눌렀는데 빨간 문구가 뜨면, 라이선스가 없는 계정이라는 뜻이에요. / 2 / 개인 계정으로 로그인 / 같은 화면에서 이메일, 구글 등으로 로그인해요. 처음이면 바로 가입되고 온보딩 화면이 이어져요. / TIP / 개인 무료 요금제로도 오늘 실습하는 페이지, 데이터베이스, 템플릿, 공유 기능은 모두 써요. AI는 체험 정도로만 쓸 수 있어요.","no":"연수를 준비하면서 라이선스가 없는 계정으로 배움터의 노션을 눌러 보니 이 화면이 나왔습니다. 이럴 때는 같은 로그인 화면에서 개인 계정으로 들어가시면 됩니다. 오늘 실습도 개인 무료 계정으로 진행했습니다.","alt":["노션 로그인 화면과 관리자 문의 안내 오류 문구"]},{"n":7,"t":"처음 로그인하면 내 워크스페이스 만들기","sec":1,"x":"1 / 다른 선생님 워크스페이스 / 같은 메일 도메인을 쓰는 사람들의 공간이 보일 수 있어요. '참여하기'는 누르지 않아요. / 2 / 새로운 워크스페이스 생성하기 / 목록 맨 아래 파란 버튼으로 내 공간을 만들어요. / 3 / 마케팅 메시지 수신 / 처음부터 체크되어 있어요. 원하지 않으면 해제하고 버튼을 눌러요.","no":"배움터 메일 주소처럼 여러 선생님이 같은 도메인을 쓰는 메일로 가입하면, 다른 분들이 만든 워크스페이스가 참여하기 목록으로 길게 보입니다. 화면 속 이름은 흐리게 가렸습니다. 남의 공간에 들어가지 않도록 맨 아래 새로운 워크스페이스 생성하기를 눌러 주세요.","alt":["온보딩의 워크스페이스 목록과 새로운 워크스페이스 생성하기 버튼"]},{"n":8,"t":"사용 목적을 고르고 나머지는 건너뛰기","sec":1,"x":"1 / 개인용 → 계속하기 / 어떤 것을 골라도 쓰는 데 차이는 없어요. 오늘은 개인용으로 했어요. / 2 / 데스크톱 앱 → 건너뛰기 / 브라우저에서 바로 쓸 거라면 설치하지 않아도 돼요. / 3 / 설정 세션 → 건너뛰기 / 노션 전문가와의 1:1 세션 예약 화면이에요.","no":"사용 목적은 업무, 개인용, 학교용 가운데 하나를 고르면 됩니다. 첫 화면 아래쪽의 워크스페이스 AI 개선 체크박스는 체크하지 않아도 됩니다. 그다음 나오는 데스크톱 앱 안내와 무료 설정 세션 예약은 건너뛰기를 누르시면 바로 노션 첫 화면으로 들어갑니다.","alt":["온보딩의 사용 목적 선택, 데스크톱 앱 안내, 설정 세션 예약 화면"]},{"n":9,"t":"첫 화면 살펴보기","sec":1,"x":"1 / 홈 · 검색 / 돋보기로 페이지를 찾아요. / 2 / 개인 페이지 / 내가 만든 페이지가 쌓여요. 연습용 3개가 미리 있어요. / 3 / 도움말 · 휴지통 / 지운 페이지는 휴지통에서 되살려요. / 4 / 새 페이지 / 연필 모양 버튼이에요. (STEP 2) / 5 / 공유 / 열린 페이지를 나눠요. (STEP 6)","no":"왼쪽이 사이드바, 오른쪽이 페이지입니다. 처음 들어오면 환영 페이지, 월별 가계부, 주간 할 일 목록 같은 연습용 페이지가 들어 있습니다. 화면 맨 위 워크스페이스 이름에는 가입한 사람의 이름이 들어가서 흐리게 가렸습니다.","alt":["노션 첫 화면의 사이드바와 환영 페이지"]},{"n":10,"t":"새 페이지 만들기","sec":2,"x":"1 / 연필 버튼 / 사이드바 왼쪽 아래, '새 채팅' 옆에 있어요. / 2 / 페이지 / 빈 문서를 만들어요. 오늘 실습은 여기서 시작해요. / 3 / 데이터베이스 / 표로 된 데이터베이스를 따로 만들 수도 있어요. 오늘은 페이지 안에 넣어 볼게요. (STEP 3) / TIP / 채팅과 AI 노트는 노션 AI 기능이에요. 무료 요금제에서는 체험 정도로만 쓸 수 있어요.","no":"연필 모양 버튼을 누르면 페이지, 채팅, AI 노트, 데이터베이스 메뉴가 나옵니다. 페이지를 눌러 빈 문서를 하나 만들어 보겠습니다.","alt":["사이드바 아래 새 페이지 버튼과 펼쳐진 메뉴"]},{"n":11,"t":"제목 쓰고 꾸미기","sec":2,"x":"1 / 아이콘 추가 · 커버 추가 · 댓글 추가 / 제목 위에 마우스를 올리면 나타나요. / 2 / 제목 / '새 페이지' 자리에 바로 입력해요. 사이드바 이름도 같이 바뀌어요. 예: [연수 실습] 우리 반 학급 운영 노트 / 3 / 시작하기 / 빈 페이지 아래쪽에서 AI, 데이터베이스, 폼, 템플릿으로 바로 시작할 수도 있어요.","no":"제목부터 적어 보겠습니다. 오늘은 우리 반 학급 운영 노트를 만들어 볼 거예요. 제목 위에 마우스를 올리면 아이콘 추가와 커버 추가 버튼이 보입니다.","alt":["새 페이지 제목과 아이콘 추가, 커버 추가 버튼, 시작하기 메뉴"]},{"n":12,"t":"아이콘 고르기","sec":2,"x":"1 / 이모지 · 아이콘 · 업로드 / 이모지 말고 노션 아이콘이나 직접 만든 그림을 올릴 수도 있어요. / 2 / 필터로 찾기 / school처럼 영어 단어로 검색해 찾았어요. / 3 / 눌러서 적용 / 페이지 아이콘이 바로 바뀌고, 사이드바에도 같이 보여요. / TIP / '아이콘 추가'를 누르면 무작위 이모지가 먼저 들어가요. 마음에 들지 않으면 그 아이콘을 다시 눌러 바꿔요.","no":"아이콘 추가를 누르니 처음에는 넥타이 이모지가 무작위로 들어갔습니다. 그 아이콘을 다시 누르면 선택 창이 열리고, school로 검색해서 학교 이모지를 골랐습니다.","alt":["아이콘 선택 창에서 school로 검색한 결과"]},{"n":13,"t":"커버 이미지 바꾸기","sec":2,"x":"1 / 변경하기 / 커버 추가를 누르면 무작위 그림이 들어가요. 커버에 마우스를 올려 변경하기를 눌러요. / 2 / 갤러리 · 업로드 · 링크 · Unsplash / 사진을 올리거나 무료 사진 사이트(Unsplash)에서 찾아요. / 3 / 색과 그라데이션 / 단색이나 그라데이션이 깔끔하고 무난해요.","no":"커버도 처음에는 무작위 그림이 들어갑니다. 커버 위에 마우스를 올리면 변경하기와 위치 변경 버튼이 보입니다. 학생 얼굴이 나온 사진은 커버로 쓰지 않는 것이 좋겠습니다.","alt":["커버 변경하기 버튼과 갤러리의 색과 그라데이션 목록"]},{"n":14,"t":"'/'를 쳐서 블록 넣기","sec":2,"x":"1 / 빈 줄에서 / 입력 / 넣을 수 있는 블록 목록이 열려요. 뒤에 글자를 이어 치면 바로 찾아져요. 예: /콜아웃, /페이지 / 2 / 블록 목록 / 텍스트, 제목, 목록, 할 일, 토글, 콜아웃, 표, 이미지, 동영상, 파일, 데이터베이스까지 있어요. / TIP / 빈 줄에서 스페이스를 누르면 AI 입력창이 열려요. 글을 쓸 때는 바로 글자부터 입력해요.","no":"노션의 모든 내용은 블록입니다. 빈 줄에서 슬래시를 치면 메뉴가 열리고, 이어서 콜아웃처럼 이름을 치면 바로 찾을 수 있습니다. 실습하다가 빈 줄에서 띄어쓰기를 먼저 누르면 AI 창이 열리니 당황하지 마시고 Esc를 누르세요.","alt":["빈 줄에서 /를 입력해 열린 블록 메뉴"]},{"n":15,"t":"자주 쓰는 블록은 바로 입력으로","sec":2,"x":"제목 / ## + 띄어쓰기 / # 제목1, ## 제목2, ### 제목3 / 할 일 / [] + 띄어쓰기 / 체크하면 줄이 그어져요 / 토글 / > + 띄어쓰기 / 눌러서 펼치고 접는 목록 / 글머리 목록 / - + 띄어쓰기 / • 점으로 시작하는 목록 / 번호 목록 / 1. + 띄어쓰기 / 번호가 저절로 이어져요 / 인용 / \" + 띄어쓰기 / 왼쪽 세로줄로 강조 / 구분선 / --- / 내용 사이에 가로선 / 콜아웃 / /콜아웃 / 아이콘이 붙은 강조 상자 / 블록 왼쪽의 + 와 ⋮⋮ / 블록에 마우스를 올리면 왼쪽에 + (바로 아래에 새 블록 넣기)와 ⋮⋮ (끌어서 옮기기, 누르면 블록 메뉴)가 나타나요.","no":"슬래시 메뉴 오른쪽에 적힌 단축 입력입니다. 줄 맨 앞에서 기호를 치고 띄어쓰기를 누르면 그 블록으로 바뀝니다. 구분선은 하이픈 세 개만 치면 됩니다. 자주 쓰는 제목, 할 일, 토글 세 가지만 기억하셔도 충분합니다.","alt":[]},{"n":16,"t":"블록으로 채운 학급 운영 노트","sec":2,"x":"1 / 콜아웃 / 이번 주 알림처럼 눈에 띄어야 할 내용 / 2 / 제목2 / 내용을 나누는 소제목 / 3 / 할 일 목록 / 요일별로 챙길 일, 체크하며 지워 나가요 / 4 / 토글 / 자주 묻는 질문을 접어 두기 좋아요 / 5 / 하위 페이지 / 페이지 안의 페이지 (다음 쪽) / TIP / 콜아웃 안에서 Enter를 치면 다음 줄도 콜아웃 안에 들어가요. 밖에 쓰려면 콜아웃 왼쪽 + 를 눌러요.","no":"지금까지 배운 블록으로 채운 모습입니다. 실습할 때 콜아웃 다음에 Enter를 쳤더니 제목이 콜아웃 안으로 들어가 버렸습니다. 콜아웃 밖에 새 블록을 만들려면 콜아웃에 마우스를 올리고 왼쪽 플러스를 누르시면 됩니다.","alt":["콜아웃, 제목, 할 일, 토글, 하위 페이지 블록으로 채운 페이지"]},{"n":17,"t":"하위 페이지 만들기","sec":2,"x":"1 / /페이지 / 하위 페이지를 넣을 빈 줄에서 입력해요. / 2 / 맨 위 '페이지' / 지금 페이지 안에 '새 페이지'가 생겨요. 눌러서 들어가 제목을 적어요. / TIP / '페이지 링크'는 이미 있는 다른 페이지로 가는 바로가기예요. 새로 만들 때는 맨 위 '페이지'를 골라요.","no":"수업 자료 제목 아래에 하위 페이지를 하나 만들어 보겠습니다. 슬래시 페이지를 치고 맨 위 페이지를 고르면 됩니다. 단원별로 하위 페이지를 만들어 두면 자료를 찾기 편합니다.","alt":["/페이지를 입력해 나온 블록 메뉴"]},{"n":18,"t":"하위 페이지에 자료 모으기","sec":2,"x":"1 / 위치 표시 / '상위 페이지 / 지금 페이지'가 보여요. 앞쪽을 누르면 돌아가요. / 2 / 글머리 기호 목록 / 차시별 활동지 이름을 목록으로 적어요. / 3 / 웹 북마크 / /북마크 → 주소 붙여 넣기 → 북마크 생성. 사이트가 카드로 들어가요.","no":"하위 페이지 제목은 수학 4단원 수업 자료로 정했습니다. 활동지 목록을 적고, 웹 북마크로 경북AI배움터 주소를 넣어 보았습니다. 자주 쓰는 사이트를 이렇게 카드로 모아 두면 수업 중에 바로 열 수 있습니다.","alt":["하위 페이지의 위치 표시, 글머리 기호 목록, 웹 북마크"]},{"n":19,"t":"페이지 안에 데이터베이스 넣기","sec":3,"x":"1 / /데이터베이스 / 데이터베이스를 넣을 빈 줄에서 입력해요. / 2 / 표 보기 / 엑셀처럼 줄과 칸으로 된 표가 페이지 안에 들어가요. / 데이터베이스란? / 줄 하나하나가 페이지인 표예요. 같은 내용을 표, 보드, 갤러리, 캘린더 등 여러 모양으로 볼 수 있어요.","no":"이번에는 학급 행사 일정을 데이터베이스로 만들어 보겠습니다. 슬래시 데이터베이스를 치면 인라인, 전체 페이지, 표, 보드, 갤러리, 캘린더 같은 종류가 나옵니다. 처음에는 표 보기로 시작하는 것이 가장 쉽습니다.","alt":["/데이터베이스를 입력해 나온 데이터베이스 종류 목록"]},{"n":20,"t":"새 데이터베이스 살펴보기","sec":3,"x":"1 / 데이터베이스 제목 / '새 데이터베이스'를 눌러 이름을 적어요. 예: 학급 행사 일정 / 2 / + 속성 추가 / 날짜, 선택, 체크박스 같은 칸을 늘려요. / 3 / + 새 페이지 / 한 줄을 추가해요. 행사 이름을 적고 Enter를 눌러요.","no":"표가 들어가면 처음에는 이름 칸 하나만 있습니다. 제목을 학급 행사 일정으로 바꾸고, 속성 추가로 칸을 늘려 보겠습니다.","alt":["방금 만든 빈 데이터베이스의 제목, 속성 추가, 새 페이지"]},{"n":21,"t":"속성(칸) 종류 고르기","sec":3,"x":"1 / 속성 이름 / 이름을 먼저 적고(예: 구분) 종류를 골라요. / 2 / 날짜 / 행사 날. 캘린더 보기에 쓰여요. / 3 / 선택 / 학교 행사 · 학급 행사처럼 정해 둔 꼬리표 중 하나 / 4 / 체크박스 / 준비 완료처럼 했는지 안 했는지","no":"속성은 표의 칸입니다. 오늘은 날짜, 구분이라는 이름의 선택, 준비 완료라는 이름의 체크박스 세 개를 추가했습니다. 숫자, 사람, 파일과 미디어, URL 같은 종류도 있어서 과제 제출 현황 같은 표도 만들 수 있습니다.","alt":["속성 이름 입력칸과 속성 유형 목록"]},{"n":22,"t":"날짜 넣기","sec":3,"x":"1 / 날짜 칸 누르기 / 달력이 열리고 오늘 날짜가 먼저 표시돼요. / 2 / 날짜 고르기 / 행사 날을 누르고 Esc로 닫아요. / 3 / 종료일 · 시간 포함 / 여러 날 이어지는 행사는 종료일을, 시각이 필요하면 시간 포함을 켜요.","no":"날짜 칸을 누르면 달력이 열립니다. 가을 체육대회는 10월 16일로 넣었습니다. 리마인더 기능도 있지만 오늘은 다루지 않겠습니다.","alt":["날짜 칸을 눌러 열린 달력"]},{"n":23,"t":"선택 꼬리표 만들기","sec":3,"x":"1 / 꼬리표 이름 입력 / 구분 칸을 누르고 '학교 행사'처럼 적어요. / 2 / 생성 / Enter를 누르면 색이 붙은 꼬리표가 생겨요. 다음 줄부터는 목록에서 골라요. / TIP / 꼬리표가 여러 개 붙어야 하면 속성을 '다중 선택'으로 만들어요.","no":"선택 속성은 처음 쓸 때 꼬리표를 만들고, 그다음부터는 만들어 둔 꼬리표 중에서 고릅니다. 학교 행사와 학급 행사 두 가지를 만들었습니다.","alt":["구분 칸에 학교 행사를 입력해 새 옵션을 만드는 화면"]},{"n":24,"t":"완성한 학급 행사 일정","sec":3,"x":"1 / 이름 / 행사 이름 (줄마다 페이지) / 2 / 날짜 / 2026년 10월 16일 형식 / 3 / 구분 (선택) / 색으로 행사 종류가 나뉘어요 / 4 / 준비 완료 (체크박스) / 누르면 바로 체크돼요","no":"가을 체육대회, 현장체험학습, 학급 회의, 독서 골든벨 네 가지를 넣어 보았습니다. 날짜는 연수용 예시입니다. 표 오른쪽 위의 필터와 정렬로 학급 행사만 보거나 날짜순으로 정렬할 수도 있습니다.","alt":["행사 4개를 입력한 학급 행사 일정 표"]},{"n":25,"t":"같은 데이터를 다른 모양으로 보기","sec":3,"x":"1 / + (보기 추가) / 데이터베이스 제목에 마우스를 올리면 오른쪽에 보여요. / 2 / 캘린더 / 날짜 속성을 기준으로 달력에 일정이 놓여요. / · / 다른 보기 / 보드, 갤러리, 리스트, 차트, 타임라인, 폼 등도 있어요.","no":"보기를 추가해도 데이터가 복사되는 것이 아니라 같은 데이터를 다른 모양으로 보여 주는 것입니다. 제목 옆 플러스를 누르고 캘린더를 골랐습니다. 보기 이름은 달력으로 정했습니다.","alt":["새 보기 추가 메뉴의 보기 종류"]},{"n":26,"t":"캘린더 보기로 한 달 일정 보기","sec":3,"x":"1 / 보기 탭 (표 · 달력) / 눌러서 오가요. 데이터는 하나라서 어느 쪽에서 고쳐도 함께 바뀌어요. / 2 / < 오늘 > / 지난달과 다음 달로 옮겨요. / 3 / 일정 카드 / 누르면 그 행사의 페이지가 열려요. / TIP / 날짜 칸에 마우스를 올리면 나오는 + 로 그날 일정을 바로 추가할 수 있어요.","no":"표에 넣은 날짜대로 행사가 달력에 놓였습니다. 학년 협의회 일정이나 과제 마감일도 이렇게 관리하면 한눈에 보입니다.","alt":["학급 행사 일정 캘린더 보기, 10월 달력에 행사 4개"]},{"n":27,"t":"한 줄이 곧 한 페이지","sec":3,"x":"1 / 제목 / 표의 이름 칸이 이 페이지의 제목이에요. / 2 / 속성 / 표에서 넣은 구분, 날짜, 준비 완료가 위쪽에 모여 있어요. 여기서 고쳐도 표에 반영돼요. / 3 / 본문 / Enter를 눌러 준비물, 역할 분담, 시간표를 적어요.","no":"캘린더에서 가을 체육대회를 누르면 이렇게 페이지가 열립니다. 표의 한 줄이 그대로 하나의 페이지라서, 행사마다 준비물이나 역할 분담을 따로 적어 둘 수 있습니다. 댓글 칸의 프로필 그림은 흐리게 가렸습니다.","alt":["가을 체육대회 일정 페이지의 속성과 본문 영역"]},{"n":28,"t":"템플릿 마켓플레이스 열기","sec":4,"x":"· / 들어가는 길 / 새 페이지 아래쪽 '시작하기'의 템플릿을 눌러요. / 1 / 템플릿 탭 / 처음엔 둘러보기 탭이 열려요. 템플릿을 눌러요. / 2 / 검색 / 필요한 것을 적어요. 예: 수업 계획 / 3 / 업무용 · 라이프 · 학업용 / 분류를 눌러 둘러봐도 돼요.","no":"처음부터 만들기 어렵다면 템플릿을 가져다 고쳐 쓰는 것이 빠릅니다. 새 페이지 아래쪽의 템플릿을 누르면 노션 마켓플레이스가 열립니다. 둘러보기 탭에는 유료 컨설팅 안내도 나오니 템플릿 탭으로 넘어가 주세요.","alt":["마켓플레이스의 템플릿 탭과 검색창, 분류"]},{"n":29,"t":"검색 결과에서 무료 템플릿 고르기","sec":4,"x":"1 / 템플릿 카드 / 그림으로 구성을 미리 볼 수 있어요. 별점도 참고해요. / 2 / 무료 / 이 표시가 있는 것만 골라요. / 3 / 유료 (US$) / 가격이 적힌 것은 결제가 필요해요.","no":"수업 계획으로 검색하니 50개 결과가 나왔습니다. 무료와 유료가 섞여 있어서 카드 오른쪽 아래 표시를 꼭 확인해 주세요. 오늘은 노션이 직접 만든 무료 템플릿인 수업 계획을 골랐습니다.","alt":["수업 계획 검색 결과의 템플릿 카드와 무료, 유료 표시"]},{"n":30,"t":"템플릿 살펴보고 추가하기","sec":4,"x":"1 / + 추가 / 내 워크스페이스에 복사돼요. 사이드바에 바로 생겨요. / 2 / 미리보기 / 추가하기 전에 실제 페이지를 열어 봐요. / 3 / 구성 그림 / 수업 제목, 수업일, 상태, 유형으로 수업을 관리하는 데이터베이스예요.","no":"노션이 만든 수업 계획 템플릿입니다. 아래쪽 미리보기 그림을 넘기면 수업별 페이지 구성도 볼 수 있습니다. 추가를 누르면 잠시 뒤 사이드바에 수업 계획 페이지가 생깁니다.","alt":["노션 공식 수업 계획 템플릿 상세 화면과 추가 버튼"]},{"n":31,"t":"추가한 템플릿 고쳐 쓰기","sec":4,"x":"1 / 사이드바에 추가 / 개인 페이지 맨 위에 '수업 계획'이 생겼어요. / 2 / 모든 수업 · 상태별 / 표 보기와 보드 보기가 미리 만들어져 있어요. / 3 / 보드 / 카드를 끌어 작성 전 → 작성 중 → 완료로 옮겨요. / TIP / 들어 있는 예시(영어 수업)는 지우고 우리 학년 단원과 차시로 바꿔 써요.","no":"템플릿을 추가하면 예시 수업 네 개가 들어 있습니다. 상태별 보기를 누르면 작성 전, 작성 중, 완료로 나뉜 보드가 나옵니다. 예시는 지우고 우리 단원으로 바꿔 쓰시면 됩니다.","alt":["사이드바에 추가된 수업 계획과 상태별 보드 보기"]},{"n":32,"t":"AI에게 초안 부탁하기","sec":5,"x":"실습에 쓴 요청 / 초등 6학년 학급 회의에서 다룰 만한 안건 5가지를 제안 이유와 함께 표로 정리해 줘 / 1 / AI 입력창 / 빈 줄에서 스페이스를 누르면 'AI로 편집하기' 창이 열려요. / 2 / 보내기 / 대상, 개수, 형식(표·목록)을 넣어 부탁하고 Enter를 눌러요.","no":"새 페이지를 하나 만들고 빈 줄에서 스페이스를 눌러 AI 창을 열었습니다. 누구를 위한 것인지, 몇 개인지, 어떤 모양으로 받을지를 함께 적으면 원하는 결과에 가깝게 나옵니다.","alt":["빈 줄에서 스페이스로 연 AI 입력창에 요청을 적은 모습"]},{"n":33,"t":"AI 답을 검토하고 페이지에 넣기","sec":5,"x":"1 / 결과 / 안건 5개와 제안 이유를 표로 정리해 줬어요. 생활 규칙, 안전, 온라인 예절, 역할 분담, 학급 행사였어요. / 2 / 아래에 삽입 / 마음에 들면 눌러서 페이지에 넣어요. / 3 / 채팅 / 이어서 고쳐 달라고 말할 수 있어요. / 꼭 검토하세요 / 무료 요금제의 AI는 '제한된 체험판'이에요. 넣은 뒤에는 우리 반 상황에 맞게 고쳐 써요.","no":"10초 정도 지나 표가 완성되었습니다. 아래에 삽입을 누르면 표가 페이지에 그대로 들어갑니다. 다만 AI가 덧붙인 마지막 안내 문장까지 함께 들어가서 따로 지워야 했습니다. 무료 요금제에서는 AI를 체험 정도로만 쓸 수 있다는 점도 기억해 주세요.","alt":["AI가 만든 학급 회의 안건 표와 아래에 삽입, 채팅 버튼"]},{"n":34,"t":"공유: 동료 선생님과 함께 보기","sec":6,"x":"1 / 공유 / 페이지 오른쪽 위 '공유'를 눌러요. / 2 / 초대 / 이메일을 적어 초대하면 그 사람만 볼 수 있어요. / 3 / 일반 사용 권한 / '초대받은 사용자만'이 기본이에요. '링크가 있는 웹의 모든 사용자'로 바꾸면 링크를 아는 누구나 봐요. / 4 / 링크 복사 / 주소를 복사해 메신저로 보내요. / TIP / 학생 정보가 들어간 페이지는 '초대받은 사용자만'으로 두어요.","no":"공유 창에서 동료 선생님 이메일을 넣어 초대할 수 있습니다. 실습 때는 실제로 초대하지는 않았습니다. 화면 속 계정 이름과 이메일은 흐리게 가렸습니다.","alt":["공유 창의 초대 입력칸, 일반 사용 권한 선택, 링크 복사"]},{"n":35,"t":"게시: 웹 페이지로 보여 주기","sec":6,"x":"1 / 게시 탭 / 공유 창 위쪽에서 '게시'로 넘어가요. / 2 / 게시 / 누르면 이 페이지가 웹 사이트가 돼요. 노션 계정이 없는 학생·학부모도 링크로 볼 수 있어요. / 3 / 안내 문구 / 링크를 가진 모든 사용자가 내용과 기여자 이름을 볼 수 있다고 안내돼요. / TIP / 게시할 페이지에는 학생 이름, 사진, 연락처를 넣지 않아요. 알림 전용 페이지를 따로 만들면 안전해요.","no":"게시는 페이지를 공개 웹 페이지로 만드는 기능입니다. 연수 준비 때는 게시 버튼까지만 확인하고 실제로 게시하지는 않았습니다. 게시하면 내 이름이 기여자로 보일 수 있으니 이 점도 함께 기억해 주세요.","alt":["공유 창의 게시 탭, 웹에 게시 미리보기와 게시 버튼"]},{"n":36,"t":"내보내기와 버전 기록","sec":6,"x":"1 / ··· → 내보내기 / 페이지 오른쪽 위 ··· 메뉴에 있어요. / 2 / PDF · HTML · Markdown & CSV / 인쇄하거나 파일로 보관할 때는 PDF를 골라요. 하위 페이지 포함 여부도 정해요. / 3 / 버전 기록 / 잘못 고쳤을 때 이전 상태를 찾아봐요. 무료 요금제는 7일까지 남아요. / TIP / 같은 메뉴의 '복제'로 학기 초 페이지를 복사해 두면 다음 학기에 다시 쓰기 좋아요.","no":"더보기 메뉴에는 링크 복사, 복제, 옮기기, 휴지통으로 이동, 내보내기, 버전 기록이 모여 있습니다. 실습 때는 내보내기 형식만 확인하고 취소했습니다. 버전 기록 기간은 노션 요금제 안내 기준으로 무료가 7일입니다.","alt":["페이지 더보기 메뉴와 내보내기 형식 목록"]},{"n":37,"t":"오늘 만든 학급 운영 노트","sec":6,"x":"1 / 사이드바 구조 / 페이지 이름 왼쪽 > 를 누르면 안에 든 하위 페이지와 데이터베이스가 펼쳐져요. / 2 / 한 페이지에 모두 / 알림, 할 일, 자주 묻는 질문, 수업 자료, 행사 일정이 한곳에 있어요. / TIP / 학기 초에 이렇게 하나 만들어 두면, 매주 알림과 할 일만 고쳐 쓰면 돼요.","no":"오늘 실습한 결과를 한 화면에 모았습니다. 사이드바를 펼치면 학급 운영 노트 안에 수학 4단원 수업 자료와 학급 행사 일정이 들어 있는 것을 볼 수 있습니다.","alt":["사이드바에 하위 페이지와 데이터베이스가 펼쳐진 완성 페이지"]},{"n":38,"t":"꼭 알아 둘 점","sec":6,"x":"배움터 연동 / 공모로 라이선스를 받은 선생님만 돼요. 나머지는 개인 계정(무료)으로 써요. / 무료 요금제 한도 / 파일 업로드 최대 5MB 버전 기록 7일 · 게스트 10명 / 멤버와 게스트 / 워크스페이스 멤버가 2명 이상이면 블록 수 제한이 생겨요. 동료는 페이지 공유로 초대해요. / AI는 체험판 / 무료 요금제의 AI는 제한된 체험판이에요. 결과는 꼭 검토해요. / 게시 페이지 주의 / 웹에 게시하는 페이지에는 학생 이름, 사진, 연락처를 넣지 않아요. / 남의 공간 참여 X / 온보딩과 워크스페이스 메뉴에 보이는 다른 사람 공간의 '참여하기'는 누르지 않아요. / 요금제 한도: 노션 요금제 안내(notion.com/pricing) 기준, 2026. 10. 확인","no":"무료 요금제 한도는 노션 요금제 안내 페이지를 기준으로 정리했습니다. 혼자 쓰는 무료 워크스페이스는 블록 수 제한이 없지만, 멤버를 두 명 이상 넣으면 제한이 생깁니다. 그래서 동료 선생님과 함께 쓸 때는 워크스페이스 멤버로 넣기보다 페이지 공유로 초대하는 편이 좋습니다.","alt":[]},{"n":39,"t":"수업과 학급 운영에 이렇게 써 보세요","sec":6,"x":"학급 운영 노트 / 주간 알림, 할 일, 자주 묻는 질문을 한 페이지에 / 수업 자료 보관함 / 단원별 하위 페이지에 활동지와 링크 모으기 / 행사 · 과제 캘린더 / 데이터베이스에 날짜를 넣고 캘린더 보기로 / 동학년 협업 페이지 / 공유로 초대해 교육과정과 평가 계획을 함께 고치기 / 학생 · 학부모에게는 '보기'로 / 알림용 페이지를 따로 만들어 웹에 게시하고 링크만 나누면, 계정 없이도 볼 수 있어요. 개인정보는 넣지 않아요.","no":"처음에는 오늘 만든 학급 운영 노트 하나만 꾸준히 써 보시기를 권해 드립니다. 익숙해지면 단원별 자료 보관함이나 동학년 협업 페이지로 넓혀 가시면 됩니다.","alt":[]},{"n":40,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 첫 페이지 같이 만들기 / 학급 운영 노트를 함께 만들어 드려요. / 데이터베이스 설계 / 어떤 속성이 필요한지 함께 정해요. / 공유 설정 확인 / 게시 전에 공개 범위를 같이 살펴봐요.","no":"오늘 연수는 여기까지입니다. 직접 해 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 첫 페이지를 만들거나 공유 설정을 바꾸실 때 교실로 찾아가 함께하겠습니다.","alt":[]}],"offs":[[0,35160],[35160,45660],[80820,61676],[142496,60352],[202848,78886],[281734,60502],[342236,62720],[404956,78368],[483324,58086],[541410,54052],[595462,47990],[643452,50786],[694238,65488],[759726,52616],[812342,60548],[872890,71978],[944868,52364],[997232,45748],[1042980,56100],[1099080,54184],[1153264,51688],[1204952,61136],[1266088,46762],[1312850,48748],[1361598,50900],[1412498,50184],[1462682,42202],[1504884,57776],[1562660,76010],[1638670,68988],[1707658,66584],[1774242,51684],[1825926,87530],[1913456,65954],[1979410,60056],[2039466,61098],[2100564,67920],[2168484,65858],[2234342,58276],[2292618,37488]],"toffs":[[0,2796],[2796,3738],[6534,4980],[11514,4698],[16212,5498],[21710,4812],[26522,5316],[31838,6078],[37916,3904],[41820,3974],[45794,3962],[49756,4264],[54020,5430],[59450,4526],[63976,4774],[68750,5718],[74468,4040],[78508,3782],[82290,4544],[86834,4400],[91234,4230],[95464,4502],[99966,3784],[103750,4018],[107768,4686],[112454,4222],[116676,3342],[120018,4502],[124520,5308],[129828,4670],[134498,4778],[139276,4364],[143640,6176],[149816,5798],[155614,4948],[160562,4794],[165356,4778],[170134,4616],[174750,4876],[179626,3742]],"packSize":2330106,"thumbSize":183368},{"key":"aidiary","name":"AI 마음일기","title":"AI 마음일기 사용 안내서","group":"etc","sub":"일기 한 편으로 마음을 기록하고 AI 댓글과 마음 흐름까지 살펴보기","fee":"유료 기능 적용","feeKind":"paid","feeNote":"경북 교원은 배움터를 거쳐 들어가면 무료로 써요. 선생님 화면에 표시된 이용 기간은 2027. 2. 28.까지예요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, AI 마음일기 소개와 두 화면"},{"start":5,"num":"1","label":"접속하기","desc":"경북AI배움터에서 AI 마음일기에 접속하고 학생 계정을 살펴봐요"},{"start":9,"num":"2","label":"일기 쓰기","desc":"학생 화면에 로그인해 이야기를 써요"},{"start":14,"num":"3","label":"AI 분석 결과","desc":"AI 감정 분석 결과와 토닥토닥 채팅을 봐요"},{"start":18,"num":"4","label":"체크인과 더 보기","desc":"감정 체크인, 공유이야기, 감정사전, 우체통을 둘러봐요"},{"start":24,"num":"5","label":"선생님이 할 일","desc":"선생님이 주제, 이야기, 소식지, 보고서, 그룹옵션을 관리해요"},{"start":31,"num":"6","label":"꼭 알아 둘 점","desc":"유의사항과 수업 활용 아이디어"}],"slides":[{"n":1,"t":"AI 마음일기","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 일기 한 편으로 마음을 기록하고 AI 댓글과 마음 흐름까지 살펴보기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 AI 마음일기를 함께 살펴보겠습니다. 학생이 일기를 쓰면 AI가 글 속 감정을 찾아 주고, 선생님은 우리 반 마음 흐름을 한 화면에서 볼 수 있는 도구입니다. 오른쪽 화면은 연수 준비하면서 제가 직접 써 본 예시 일기와 분석 결과입니다.","alt":["AI 마음일기에 쓴 예시 일기와 AI 감정 분석 결과 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → AI 마음일기, 학생 계정 / 05–08쪽 / STEP 2 / 일기 쓰기 / 학생 로그인, 첫 화면, 이야기 쓰기 / 09–13쪽 / STEP 3 / AI 분석 결과 / 감정 친구, 마음 상태, 토닥 채팅 / 14–17쪽 / STEP 4 / 체크인과 더 보기 / 체크인, 공유이야기, 감정사전 / 18–23쪽 / STEP 5 / 선생님이 할 일 / 주제, 이야기관리, 소식지, 보고서 / 24–30쪽 / STEP 6 / 유의사항과 활용 / AI 결과 읽는 법, 수업 활용 / 31–32쪽","no":"여섯 단계로 진행합니다. 학생 화면은 제가 선생님 계정으로 직접 일기를 쓰고 체크인해 보면서 찍었습니다. 시간이 부족하면 2단계 일기 쓰기와 3단계 AI 분석 결과만 따라 해 보셔도 이 도구가 어떤 건지 충분히 감이 오실 거라고 생각합니다.","alt":[]},{"n":3,"t":"AI 마음일기로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 마음일기 쓰기 / 주제에 맞춰 하루를 글로 기록하고, 글이 어려운 날은 감정 체크인만 / AI 감정 분석 / 글 속 감정 세 가지, 생활유형, 마음 상태를 바로 보여 줘요 / 심스의 토닥토닥 / AI 캐릭터 심스가 공감 댓글을 달고 짧게 대화해요 / 선생님 대시보드 / 우리 반 감정 온도, 신호등, 월간 보고서 / 경북 교원 혜택 / 배움터로 접속하면 무료로 사용 / 심스페이스 안내에 따르면 경북교육청 소속 선생님은 AIEP(경북AI배움터)를 거쳐 들어가야 무료로 쓸 수 있어요. / 선생님 화면 표시 이용 기간: 2027년 2월 28일까지","no":"AI 마음일기는 심스페이스라는 서비스입니다. 학생은 일기를 쓰거나 감정 체크인을 하고, AI는 글 속 감정을 찾아 공감 댓글을 달아 줍니다. 선생님은 대시보드와 월간 보고서로 우리 반 마음 흐름을 볼 수 있습니다. 심스페이스 매뉴얼에는 서울, 경북, 인천, 전남 교육청 소속 선생님이 AIEP로 가입하면 무료로 쓸 수 있다고 안내되어 있었습니다.","alt":[]},{"n":4,"t":"선생님 화면과 학생 화면, 두 가지예요","sec":0,"x":"시작하기 전에 / 선생님 화면 · 그룹 관리 / group.seamspace.me — 배움터에서 AI 마음일기를 누르면 열려요. 우리 반 감정 흐름, 주제, 보고서를 관리해요. / 학생 화면 · 마음일기 / diary.seamspace.me — 학생이 일기를 쓰고 체크인해요.","no":"주소가 두 개라는 것만 기억해 주시면 됩니다. 선생님은 group 주소, 학생은 diary 주소입니다. 선생님 화면 왼쪽 메뉴의 마음이야기를 누르면 학생 화면이 선생님 계정으로 그대로 열려서, 연수 때처럼 직접 써 보실 수 있습니다.","alt":["왼쪽은 선생님 그룹 관리 화면, 오른쪽은 학생 마음일기 화면"]},{"n":5,"t":"경북AI배움터에서 AI 마음일기 열기","sec":1,"x":"1 / 에듀테크 서비스 → AI 마음일기 / 교원으로 로그인한 뒤 메인 화면을 조금 내리면 둘째 줄에 있어요. / 2 / 마우스를 올리면 설명 표시 / 누르면 새 탭에서 선생님용 관리 화면이 열려요. / TIP / 따로 회원가입하지 않아도 돼요. 배움터 로그인 한 번이면 바로 들어가요.","no":"배움터 메인의 에듀테크 서비스 첫 페이지 둘째 줄에 AI 마음일기가 있습니다. 누르면 심스페이스 선생님 화면이 새 탭으로 열립니다. 저도 따로 가입하지 않고 배움터 계정으로 바로 들어갈 수 있었습니다.","alt":["경북AI배움터 메인의 에듀테크 서비스 목록"]},{"n":6,"t":"처음 보이는 화면, 대시보드","sec":1,"x":"1 / 그룹 이름 / 우리 반 그룹이에요. / 2 / 왼쪽 메뉴 / 멤버현황부터 그룹옵션까지 오늘 차례로 살펴봐요. / 3 / 기간 · 주제 · 멤버 / 최근 1주일처럼 보고 싶은 범위를 골라요. / 4 / 한눈에 보는 카드 / 멘탈헬스 상태, 감정 온도 분포, 이야기 작성 여부를 보여 줘요. / 5 / 이용 기간 / 화면 표시 기준 2027. 2. 28.까지","no":"학생들이 글을 쓰기 시작하면 이 카드들이 채워집니다. 아직 우리 반 학생들이 쓰기 전이라 비어 있습니다. 아래로 내리면 감정 체크인 분포, 감정 워드클라우드, 키워드 워드클라우드, 날짜별 감정 분포도 이어집니다.","alt":["선생님 화면의 대시보드"]},{"n":7,"t":"멤버현황: 우리 반 학생 한눈에","sec":1,"x":"1 / 마음이야기 · 체크인 · 활동 / 학생별 기록을 종류에 따라 나눠 봐요. / 2 / 최근 글 · 감정 · 감정 온도 / 멘탈헬스 상태와 이야기 작성 횟수도 함께 보여요. / 3 / 내보내기 / 표를 파일로 내려받을 수 있어요. / TIP / 이름 칸에 실명 대신 별명을 넣어 두면 화면을 띄워도 부담이 적어요.","no":"학생마다 최근 글과 감정, 감정 온도, 멘탈헬스 상태가 한 줄로 정리됩니다. 화면 속 아이디는 흐리게 가렸습니다. 우리 반은 이름 칸을 별명으로 해 두었습니다.","alt":["멤버현황 표, 아이디는 흐림 처리"]},{"n":8,"t":"그룹설정: 학생 계정 만들고 관리하기","sec":1,"x":"1 / 멤버(학생) 등록 / 양식을 내려받아 채워 일괄 등록하거나, 한 명씩 개별 등록해요. / 2 / 아이디 및 데이터 삭제 / 학생 계정과 기록을 지워요. / 3 / 비밀번호 초기화 / 학생이 비밀번호를 잊었을 때 다시 정해 줘요. / 4 / 매니저(교사) 등록 / 함께 볼 선생님을 매니저로 넣어요. / TIP / 멤버현황에 우리 반 학생이 이미 보이면 따로 등록하지 않아도 돼요. 양식 일괄 등록은 관리자만 할 수 있어요.","no":"그룹설정 화면 아래쪽입니다. 학생 계정은 양식으로 한꺼번에 만들 수 있고, 도움말에 관리자만 등록할 수 있다고 나와 있었습니다. 심스페이스 매뉴얼을 보면 학생은 스스로 회원가입을 할 수 없고, 선생님이 만든 계정으로만 로그인합니다.","alt":["그룹설정 화면의 멤버 등록, 삭제, 비밀번호 초기화, 매니저 등록"]},{"n":9,"t":"학생 로그인 화면","sec":2,"x":"1 / 아이디 · 비밀번호 / 선생님이 만들어 준 계정으로 로그인해요. / 2 / AIEP 로그인 / 경북AI배움터 계정으로 들어갈 때 눌러요. / 3 / 앱 QR 코드 / 안드로이드 · iOS 앱으로도 쓸 수 있어요. / TIP / 학생 주소는 diary.seamspace.me 예요. 학생은 직접 회원가입하지 않아요.","no":"학생은 diary 주소로 들어옵니다. 화면 맨 아래 교사용 페이지로 가기를 누르면 선생님 화면으로 넘어갑니다. 태블릿을 쓰는 반은 오른쪽 QR로 앱을 깔아도 됩니다.","alt":["마음일기 로그인 화면"]},{"n":10,"t":"AIEP 로그인으로 들어가기","sec":2,"x":"1 / 경상북도교육청 고르기 / 소속 교육청을 고르는 화면이 먼저 나와요. / 2 / 배움터 아이디 · 비밀번호 / 아이디 칸 끝에 @aiep.gbe.kr 이 붙어 있어요. / 3 / 로그인 / 로그인하면 바로 마음일기 첫 화면으로 와요. / TIP / 선생님도 같은 방법으로 학생 화면에 들어와 직접 써 볼 수 있어요.","no":"AIEP 로그인을 누르면 교육청을 고르는 화면이 나오고, 경상북도교육청을 누르면 배움터 로그인 창이 열립니다. 저는 선생님 계정으로 이 과정을 거쳐 마음일기 첫 화면까지 들어가 볼 수 있었습니다.","alt":["교육청 선택 화면과 경상북도교육청 로그인 화면"]},{"n":11,"t":"마음일기 첫 화면","sec":2,"x":"1 / 연필 버튼 / 이야기(일기)를 써요. / 2 / 하트 버튼 / 감정 체크인을 해요. / 3 / 달력 / 기록한 날에는 그날의 감정 캐릭터가 떠요. / 4 / 아래 메뉴 / 마음이야기 · 공유이야기 · 감정사전 · 마음관리 · 마이페이지 / 5 / 우체통 / 편지와 알림을 확인해요. / TIP / 선생님 화면 왼쪽 마음이야기 메뉴를 누르면 이 화면을 선생님 계정으로 그대로 써 볼 수 있어요.","no":"학생이 처음 들어오면 보는 화면입니다. 달력 모양이 교실 창살 무늬처럼 되어 있고, 기록한 날에는 감정 캐릭터가 올라옵니다. 오른쪽 아래 두 버튼만 기억하시면 됩니다. 연필은 일기, 하트는 체크인입니다.","alt":["마음일기 첫 화면의 달력과 버튼"]},{"n":12,"t":"이야기 쓰기","sec":2,"x":"1 / 주제 / 선생님이 등록한 주제가 떠요. 없으면 기본 주제 '오늘하루를 정리해 봐요'. / 2 / 글쓰기 칸 / 1,000자까지 마음을 있는 그대로 써요. / 3 / 공개 설정 / 처음에는 '기본'이에요. 누르면 공유 모둠을 고를 수 있어요. / 4 / 임시저장 · 저장 / 저장하면 AI 분석이 바로 시작돼요. / TIP / 글쓰기 칸 안내처럼 논리적이지 않아도 되니 마음을 있는 그대로 쓰도록 이끌어 주세요.","no":"제가 연수 준비하면서 실제로 써 본 글입니다. 체육 시간 피구에서 진 날, 짝꿍이 위로해 준 이야기를 아이 입장에서 써 봤습니다. 주제는 선생님이 따로 등록하지 않으면 기본 주제로 들어갑니다.","alt":["이야기 작성 화면에 예시 일기를 쓴 모습"]},{"n":13,"t":"공개 설정: 누구와 나눌까","sec":2,"x":"1 / 공유 모둠 / 고르면 그 모둠의 공유이야기에 함께 올라가요. / 2 / 기본 / 공유하지 않고 내 마음이야기에만 남겨요. / 3 / 완료 / 고른 뒤 완료를 눌러요. / TIP / 학생이 글을 비밀로 설정할 수 있게 할지는 그룹옵션에서 정해요.","no":"글쓰기 화면 왼쪽 아래 기본이라는 글자를 누르면 이 창이 뜹니다. 연수 예시 글은 기본 그대로 두고 저장했습니다.","alt":["공개 설정 창"]},{"n":14,"t":"저장하면 AI가 감정을 찾아요","sec":3,"x":"1 / 분석 안내 창 / 감정 친구들을 찾는 동안 잔잔한 음악이 나와요. / 2 / 감정 친구 만나러 가기 / 누르면 분석 결과 화면이 열려요. / TIP / 분석 중 음악은 주제를 만들 때 '음악 활성화'로 켜고 끌 수 있어요.","no":"저장을 누르면 잠깐 눈을 감고 오늘 하루를 정리해 보라는 문구와 함께 분석이 진행됩니다. 제가 해 봤을 때는 몇 초 만에 끝났습니다.","alt":["감정 분석 완료 안내 창"]},{"n":15,"t":"분석 결과 ① 감정 친구와 토닥 댓글","sec":3,"x":"1 / 감정 친구 / 글에서 찾은 감정 세 가지를 캐릭터로 보여 줘요. / 2 / 오늘의 생활유형 / LBTI라는 생활유형 결과예요. / 3 / 심스의 공감 댓글 / AI 캐릭터 심스가 글을 읽고 다정한 댓글을 달아요. / 4 / 심스와 채팅 / 캐릭터를 누르면 토닥토닥 채팅으로 이어져요. / TIP / 학생에게 토닥토닥 댓글을 보여 줄지는 그룹옵션의 보기 옵션에서 정해요.","no":"예시 글에서는 슬픔, 고독, 행복 세 감정이 나왔습니다. 진 것에 대한 속상함과 짝꿍 덕분에 풀린 마음을 함께 읽어 낸 것 같았습니다. 심스 댓글은 칭찬과 격려 위주로 달렸습니다.","alt":["분석 결과 화면의 감정 캐릭터와 심스 댓글"]},{"n":16,"t":"분석 결과 ② 생활유형과 마음 상태","sec":3,"x":"1 / 오늘의 생활유형(LBTI) / Life Balance Type Indicator. 오늘 생활을 성격 유형처럼 풀어 줘요. / 2 / 마음 상태 / 스트레스 · 불안감 · 우울감 · 열등감을 0~10으로 보여 줘요. / 3 / 신호 하트 / 초록 · 노랑 · 빨강 신호로 전체 상태를 알려 줘요. / 4 / 안내 문구 / 일반 AI(LLM)가 만든 참고용 지수로, 의료적 평가나 진단에 쓸 수 없어요. / TIP / 학생에게 LBTI와 멘탈헬스를 보여 줄지는 그룹옵션에서 정해요.","no":"결과 화면을 아래로 내리면 생활유형과 마음 상태가 나옵니다. 화면에 이 지수는 참조용이고 의료적 평가나 진단에 쓸 수 없다는 안내가 함께 있습니다. 학생들에게도 이 점을 꼭 같이 알려 주시면 좋겠습니다.","alt":["오늘의 생활유형과 마음 상태 막대"]},{"n":17,"t":"토닥토닥 채팅","sec":3,"x":"1 / 안내 / 대화는 최대 5회, 내용은 저장되지 않아요. / 2 / 학생이 보낸 말 / 일기에 이어 하고 싶은 말을 써요. / 3 / 심스의 답 / 걱정을 다독이고 다음에 해 볼 일을 함께 생각해 줘요. / 4 / 남은 채팅 수 / 한 번 보낼 때마다 줄어들어요. / TIP / 채팅 사용 여부와 횟수는 그룹옵션에서 바꿀 수 있어요.","no":"다음에도 금방 맞으면 어떡하지 하고 물어봤더니, 걱정할 필요 없다며 공을 피하는 연습을 해 보자고 답했습니다. 대화 내용은 저장되지 않는다고 화면에 안내되어 있습니다.","alt":["심스와 나눈 토닥토닥 채팅"]},{"n":18,"t":"감정 체크인: 글 없이 기분만 기록","sec":4,"x":"1 / 오늘 기분 / 다섯 얼굴 가운데 지금 기분에 가까운 것을 골라요. / 2 / 감정 캐릭터 / 고른 기분에 맞는 감정 단어가 캐릭터로 나와요. / 3 / 저장 / '나는 지금 안심돼요'처럼 한 문장으로 남아요. / TIP / 글쓰기가 어려운 날에는 체크인만 해도 달력과 마음 흐름에 기록이 남아요.","no":"하트 버튼을 누르면 나오는 화면입니다. 저는 네 번째 얼굴을 고르고 안심을 골랐습니다. 우리 반 설정은 하루에 글쓰기와 체크인을 각각 5번까지 할 수 있게 되어 있었습니다.","alt":["감정 체크인 화면"]},{"n":19,"t":"배지와 하루 기록 모아 보기","sec":4,"x":"1 / 배지 / 기록하면 배지와 경험치를 받아요. / 2 / 대표 배지로 설정하기 / 받은 배지를 대표 배지로 걸어 둘 수 있어요. / 3 / 체크인 카드 / 달력에서 날짜를 누르면 그날의 체크인이 보여요. / 4 / 이야기 카드 / 같은 날 쓴 일기와 심스 댓글도 함께 모여요. / TIP / 배지와 경험치는 꾸준히 기록하는 작은 동기가 될 수 있어요.","no":"첫 체크인을 하자 감정 캐스터라는 배지를 받았습니다. 달력에서 날짜를 누르면 그날 남긴 체크인과 일기가 카드로 모여 보입니다.","alt":["배지 획득 창과 날짜별 기록 카드"]},{"n":20,"t":"공유이야기: 모둠 친구와 나누기","sec":4,"x":"1 / 공유 모둠 / 참여한 공유 모둠이 카드로 보여요. / 2 / 골라 보기 버튼 / 버튼을 눌러 보고 싶은 글만 모아 봐요. / 3 / 공유된 이야기 / 감정 캐릭터, 심스 댓글과 함께 올라오고 친구들이 좋아요 · 댓글을 달아요. / TIP / 공유이야기 사용 여부는 그룹옵션에서 정해요.","no":"공개 설정에서 모둠을 고르면 이렇게 공유이야기에 올라갑니다. 칭찬이나 고마움 나누기처럼 함께 읽어도 좋은 주제일 때 쓰시면 좋겠습니다.","alt":["공유 모둠 목록과 모둠 안의 이야기 카드"]},{"n":21,"t":"감정사전: 감정 이름과 온도 익히기","sec":4,"x":"1 / 분류 / 긍정 감정부터 차례로 정리돼 있어요. / 2 / 온도 / 감정마다 온도가 있어요. 예: 감사 7, 만족 6 / 3 / 감정 카드 / 감정을 누르면 캐릭터와 감정 온도가 나와요. / 4 / 설명 / 어린이 눈높이 예시로 그 감정을 풀어 줘요.","no":"아래 메뉴의 감정사전입니다. 감정 이름을 누르면 어떤 때 그 감정을 느끼는지 아이들 말투로 설명해 줍니다. 감정 어휘 수업 자료로 바로 쓸 수 있겠다고 생각했습니다.","alt":["감정사전 목록과 만족 감정 설명 창"]},{"n":22,"t":"마음관리 · 마이페이지: 내 기록 돌아보기","sec":4,"x":"1 / 내 마음의 흐름 / 한 달 동안 감정 온도와 체크인 온도를 그래프로 봐요. / 2 / 이달의 LBTI / 한 달 생활유형을 모아 보여 줘요. / 3 / 프로필 / 연속 기록 일수와 경험치가 쌓여요. / 4 / 티어 · 배지 / 모은 배지와 단계를 확인해요.","no":"학생이 자기 기록을 돌아보는 메뉴입니다. 마음관리 그래프에도 감정 온도는 참고용이라는 안내가 붙어 있습니다. 마이페이지에서는 테마도 바꿀 수 있었습니다.","alt":["내 마음의 흐름 그래프와 마이페이지"]},{"n":23,"t":"우체통: 편지와 알림","sec":4,"x":"1 / 받은 우체통 · 보낸 우체통 / 받은 편지와 보낸 편지를 나눠 봐요. / 2 / 편지 쓰기 버튼 / 오른쪽 아래 버튼에서 편지를 써요. / TIP / 학생이 선생님께 편지를 쓸 수 있게 할지는 그룹옵션에서 정해요. 주제에서 응급알림받기를 켜면 긴급한 상황 알림도 우체통으로 와요.","no":"첫 화면 오른쪽 위 편지 봉투를 누르면 우체통이 열립니다. 아직 받은 편지가 없어서 비어 있습니다.","alt":["우체통 화면"]},{"n":24,"t":"주제 등록: 이번 주 일기 주제 만들기","sec":5,"x":"1 / 주제 · 설명 / 학생 글쓰기 화면 맨 위에 보일 질문을 써요. / 2 / 소주제(Beta) / 주제 안에 작은 질문을 더 붙일 수 있어요. / 3 / 분석 AI · 보고서에서 제외 / 분석 방식을 고르고, 월간 보고서에 넣을지 정해요. / 4 / 기간 · 글자수 / 시작일 · 종료일과 최소 · 최대 글자수를 정해요. / 5 / 저장 / 저장하면 정한 기간 동안 학생 글쓰기 화면에 주제가 떠요.","no":"주제관리 메뉴의 주제 등록 버튼을 누르면 나오는 창입니다. 연수 화면에는 친구에게 고마웠던 순간이라는 예시를 넣어 봤고, 우리 반 학생 화면에 연습 주제가 뜨지 않도록 저장하지 않고 닫았습니다.","alt":["주제 등록 창에 예시 주제를 넣은 모습"]},{"n":25,"t":"주제 옵션: 나쁜말 감지와 응급알림","sec":5,"x":"1 / 나쁜말 감지 / 사용 안 함 · 보통(비속어 차단) · 강함(무례한 표현까지 차단) / 2 / 응급알림받기 / 긴급한 상황이 감지되면 우체통으로 알림을 받아요. / 3 / 음악 활성화 / 이야기를 분석하는 동안 음악을 틀어요. / 4 / 멤버 연령 / 학생 연령을 적어 두는 칸이에요. / TIP / 응급알림받기는 처음에 꺼져 있어요. 우리 반 주제를 만들 때 켜 두시길 권해요.","no":"주제 등록 창 오른쪽을 아래로 내리면 나오는 옵션입니다. 물음표를 누르면 설명이 뜨는데, 화면에 나온 설명을 그대로 옮겼습니다.","alt":["주제 등록 창 오른쪽 아래 옵션"]},{"n":26,"t":"이야기관리: 학생 글 모아 보기","sec":5,"x":"1 / 목록 / 생성일 · 이름 · 내용 · 상태와 최근 댓글이 한 줄씩 쌓여요. / 2 / 검색 / 이름으로 학생 글을 찾아봐요. / 3 / 열 설정 · 행 간격 / 보고 싶은 칸만 골라 표를 정리해요. / TIP / 학생 글에 선생님이 댓글을 달면 학생 마음일기에서도 볼 수 있어요.","no":"아직 우리 반 학생들이 글을 쓰기 전이라 표가 비어 있습니다. 선생님 계정으로 쓴 연수용 글은 이 표에 잡히지 않았습니다.","alt":["이야기관리 표"]},{"n":27,"t":"소식지: 보호자에게 마음 소식 보내기","sec":5,"x":"1 / 소식지 작성 / 학생을 고른 뒤 소식지를 써요. / 2 / 상태별 개수 / 전체 · 진행중 · 예정 · 종료로 나눠 봐요. / 3 / 무드 트래킹 / 빨간 · 노란 · 초록 신호등별로 학생을 모아 보여 줘요. / 4 / 소식지 목록 / 보호자가 열람했는지와 댓글을 확인해요.","no":"소식지는 아직 Beta 기능입니다. 선생님 코멘트와 학생 글을 담아 보호자에게 공유하는 기능입니다. 오른쪽 무드 트래킹에서 최근 빨간 신호등인 학생을 바로 볼 수 있습니다.","alt":["소식지 목록과 무드 트래킹"]},{"n":28,"t":"소식지 작성 3단계","sec":5,"x":"1 / STEP 1 이야기 선택 / 학생 글을 첨부해요. 건너뛸 수도 있어요. / 2 / STEP 2 소식지 작성 / 보낸 사람(담임선생님)과 제목 · 내용을 써요. / 3 / STEP 3 옵션 설정 / 받는 사람(학부모), 언어, 열람 기간, 답장 횟수, 암호를 정해요. / TIP / 암호는 학생 생년월일 8자리처럼 보호자만 아는 값으로 정할 수 있어요.","no":"학생을 한 명 고르면 이 3단계 화면이 나옵니다. 연수 준비 때는 화면만 열어 보고 저장하지 않았습니다.","alt":["소식지 작성 STEP 1~3 화면, 아이디는 흐림 처리"]},{"n":29,"t":"마음관리: 월간 보고서 만들기","sec":5,"x":"1 / STEP 1 멤버 선택 / 글을 쓴 학생만 목록에 나와요. / 2 / STEP 2 보고서 생성 / 기간과 주제를 고르고 보고서를 만들어요. / 3 / STEP 3 다운로드 / 월별 · 멤버별 · 개별 · 전체 합본으로 묶어 내려받아요. / 4 / 미리보기 모드로 전환 / 만든 보고서를 화면에서 넘겨 보고 인쇄해요. / TIP / AI 코멘트가 비어 있으면 다시 생성하라는 안내가 있어요.","no":"선생님 화면의 마음관리 메뉴입니다. 학생 화면의 마음관리와 이름은 같지만 다른 기능입니다. 학생별 한 달 기록을 보고서로 만들어 상담 자료로 쓸 수 있습니다.","alt":["월간 보고서 생성 STEP 1~3 화면"]},{"n":30,"t":"그룹옵션: 우리 반 규칙 정하기","sec":5,"x":"1 / 기록 방식 · 하루 횟수 / 글쓰기와 체크인을 쓸지, 하루 몇 번까지 할지 정해요. / 2 / 비밀글 · 지난 이야기 / 글을 비밀로 할 수 있는지, 지난 날짜 일기를 쓸 수 있는지 정해요. / 3 / 공유이야기 · 채팅 · 편지 / 쓸지 말지와 심스 채팅 횟수를 정해요. / 4 / 보기 옵션 / 토닥토닥 댓글 · LBTI · 멘탈헬스를 학생에게 보여 줄지 정해요. / TIP / 바꾼 뒤에는 맨 아래 저장을 눌러야 적용돼요.","no":"우리 반 설정은 글쓰기와 체크인 각각 하루 5번, 비밀글은 없음, 지난 이야기와 공유이야기는 있음, 심스 채팅 5번으로 되어 있었습니다. 학년 수준에 맞게 바꾸시면 됩니다.","alt":["그룹옵션의 활동 옵션과 보기 옵션"]},{"n":31,"t":"쓰기 전에 꼭 알아 둘 점","sec":6,"x":"AI 결과는 참고용 / 감정 온도와 마음 상태는 일반 AI가 만든 지수예요. 의료적 평가나 진단에 쓸 수 없다고 화면에 안내돼 있어요. / 학생 계정 / 학생은 스스로 가입할 수 없고, 선생님이 만든 계정으로만 로그인해요. / 학부모 동의 / 학교 에듀테크 일괄 동의로 갈음하거나, 심스페이스 매뉴얼의 동의서 샘플을 고쳐 써요. / 신호가 걱정될 때 / 빨간 신호가 보이면 AI 결과만 믿지 말고 학생과 직접 이야기를 나눠 주세요. / 경북 교원 무료 이용 / 경북AI배움터(AIEP)로 들어가면 무료로 쓸 수 있어요. 선생님 화면에 표시된 이용 기간은 2027년 2월 28일까지예요.","no":"AI가 보여 주는 지수는 어디까지나 참고용입니다. 화면에도 의료적 평가나 진단에 쓸 수 없다고 적혀 있습니다. 학부모 동의는 학교에서 받는 에듀테크 일괄 동의로 갈음하는 경우가 많다고 매뉴얼에 나와 있고, 따로 받으려면 심스페이스 매뉴얼의 동의서 샘플을 고쳐 쓰시면 됩니다.","alt":[]},{"n":32,"t":"수업에 이렇게 써 보세요","sec":6,"x":"아침 감정 체크인 / 등교 후 1분, 오늘 기분을 고르고 하루를 시작해요. / 주제 일기 / 행사나 체험학습 뒤에 같은 주제로 돌아보는 글을 써요. / 감정 어휘 수업 / 감정사전으로 감정 이름과 온도를 익혀요. / 고마움 나누기 / 공유이야기 모둠에 칭찬과 고마운 일을 올려요. / 상담을 앞두고 / 대시보드와 월간 보고서로 한 달 흐름을 먼저 살펴보면 학생 · 학부모 상담에서 이야기를 열기 쉬워요.","no":"매일 길게 쓰게 하기보다 아침 체크인처럼 짧게 시작해 보시길 권합니다. 주제 일기는 행사 뒤에 한 번씩, 공유이야기는 칭찬이나 고마움처럼 함께 읽어도 좋은 주제일 때 쓰시면 좋겠다고 생각했습니다.","alt":[]},{"n":33,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 그룹 · 학생 계정 설정 / 우리 반 그룹과 학생 계정 등록을 함께 처리해 드려요. / 첫 주제 함께 만들기 / 학급에 맞는 주제와 옵션을 같이 정해 드려요. / 학부모 동의서 / 매뉴얼의 동의서 샘플을 우리 학교에 맞게 고쳐 드려요.","no":"오늘 연수는 여기까지입니다. 직접 써 보시다가 막히는 부분이 있으면 언제든 불러 주세요. 그룹 설정과 첫 주제 만들기는 교실로 찾아가 함께 해 드리겠습니다.","alt":[]}],"offs":[[0,58190],[58190,50974],[109164,65208],[174372,76164],[250536,57428],[307964,69488],[377452,63504],[440956,73650],[514606,63236],[577842,60208],[638050,68528],[706578,64650],[771228,47976],[819204,58162],[877366,84842],[962208,84874],[1047082,93496],[1140578,61374],[1201952,65020],[1266972,61666],[1328638,82336],[1410974,65850],[1476824,48472],[1525296,75346],[1600642,74754],[1675396,56324],[1731720,67720],[1799440,74594],[1874034,78996],[1953030,75218],[2028248,65336],[2093584,51962],[2145546,40326]],"toffs":[[0,4748],[4748,4110],[8858,5548],[14406,5696],[20102,4650],[24752,5716],[30468,5184],[35652,6646],[42298,4764],[47062,4870],[51932,5570],[57502,4640],[62142,3788],[65930,4770],[70700,6512],[77212,6360],[83572,6434],[90006,5442],[95448,5450],[100898,5178],[106076,6586],[112662,5472],[118134,3858],[121992,6632],[128624,6376],[135000,4434],[139434,5494],[144928,5330],[150258,5988],[156246,5804],[162050,5134],[167184,4186],[171370,3928]],"packSize":2185872,"thumbSize":175298},{"key":"codle","name":"코들","title":"코들 사용 안내서","group":"etc","sub":"경북AI배움터로 접속해 코딩·AI 수업 운영하기","fee":"무료 범위","feeKind":"free","feeNote":"교사 인증만 하면 무료 Basic 번개를 받아요. 파이썬 오류 도우미와 실시간 모니터링(기상캐스터)만 Pro(유료)예요.","cover":"data:image/webp;base64,","sections":[{"start":1,"num":"","label":"시작하기","desc":"표지, 차례, 코들 소개"},{"start":4,"num":"1","label":"접속하기","desc":"경북AI배움터에서 코들에 접속하고 첫 화면을 살펴봐요"},{"start":7,"num":"2","label":"교사 인증","desc":"교사 인증을 신청하고 번개와 무료 Basic 범위를 이해해요"},{"start":12,"num":"3","label":"교실 만들기","desc":"교실을 만들고 학생을 초대 코드로 가입시켜요"},{"start":14,"num":"4","label":"수업자료 준비","desc":"수업자료를 가져오거나 만들어 교실에 배부해요"},{"start":18,"num":"5","label":"수업 중 살펴보기","desc":"수업 중 학습 상황을 확인하고 AI 도우미를 써요"},{"start":20,"num":"6","label":"꼭 알아 둘 점","desc":"유의사항, 도움말, 수업 활용 아이디어"}],"slides":[{"n":1,"t":"코들","sec":0,"x":"AIEP 석적초 교내 연수 · 에듀테크 사용 안내서 / 경북AI배움터로 접속해 코딩·AI 수업 운영하기 / 2026. 10. / 작성자: 이정현, 황영수","no":"오늘은 경북AI배움터 에듀테크 가운데 코들을 함께 살펴보겠습니다. 코들은 코딩 실습과 퀴즈·활동지, 학습 확인까지 한곳에서 할 수 있는 수업 플랫폼입니다. 배움터로 바로 들어갈 수 있지만, 처음 한 번은 교사 인증을 거쳐야 기능이 열린다는 점을 꼭 기억해 주세요.","alt":["경북AI배움터 에듀테크 서비스 목록에서 코들에 마우스를 올린 화면"]},{"n":2,"t":"오늘 함께 해 볼 순서","sec":0,"x":"차례 / 접속하기 / 배움터 → 코들, 첫 화면 / 04–06쪽 / STEP 2 / 교사 인증 / 인증 신청, 번개, 무료 Basic / 07–11쪽 / STEP 3 / 교실 만들기 / 새 교실, 학생 초대 코드 / 12–13쪽 / STEP 4 / 수업자료 준비 / 가져오기, 배부, 활동, 직접 만들기 / 14–17쪽 / STEP 5 / 수업 중 살펴보기 / 학습 확인, AI 도우미 / 18–19쪽 / STEP 6 / 유의사항과 활용 / 꼭 알아 둘 점, 도움말, 수업 아이디어 / 20–22쪽","no":"오늘은 여섯 단계로 진행하겠습니다. 가장 중요한 것은 2단계 교사 인증입니다. 인증이 끝나야 교실 만들기와 수업자료 메뉴가 열리기 때문에, 연수 전에 미리 신청해 두시면 3단계부터 바로 따라 하실 수 있습니다.","alt":[]},{"n":3,"t":"코들로 할 수 있는 일","sec":0,"x":"시작하기 전에 / 코딩 실습 / 파이썬·엔트리·스크래치를 설치 없이 웹에서 / 수업자료(코스) / 공개 자료를 담거나 직접 만들어 교실에 배부 / 퀴즈 · 활동지 · 보드 / 자동 채점 퀴즈, 서술형 활동지, 의견 보드 / 학습 확인 · AI 도우미 / 성취율 확인, AI 문항 생성과 채점 / 처음 한 번은 꼭 / '교사 인증'을 먼저 해 주세요 / 배움터로 들어가도 처음에는 교실 만들기와 콘텐츠 메뉴가 잠겨 있어요. / 인증하면 무료 Basic이 열려요. 승인까지 영업일 기준 하루쯤 걸려요.","no":"코들은 코딩 실습 도구이면서 교실을 만들고 자료를 나눠 주는 학습관리 도구이기도 합니다. 파이썬뿐 아니라 엔트리, 스크래치 같은 블록 코딩도 들어 있어서 초등 실과 수업에도 쓸 수 있습니다. 다만 배움터로 처음 들어간 계정은 교사 인증 전이라 주요 메뉴가 잠겨 있었습니다. 이 부분은 2단계에서 자세히 보겠습니다.","alt":[]},{"n":4,"t":"경북AI배움터에서 코들 열기","sec":1,"x":"1 / 에듀테크 서비스 → 코들 / 배움터에 교원으로 로그인한 뒤 메인 화면을 조금 내리면 보여요. / 2 / 마우스를 올리면 설명 표시 / 누르면 새 탭에서 코들이 열리고 배움터 계정으로 바로 로그인돼요. / TIP / 따로 회원가입하거나 비밀번호를 넣지 않아도 돼요.","no":"배움터 주소는 aischool.gbe.kr입니다. 에듀테크 서비스 목록 둘째 줄에 코들이 있습니다. 누르면 새 탭이 열리면서 배움터 계정으로 자동 로그인됩니다.","alt":["경북AI배움터 에듀테크 서비스 목록과 코들 설명"]},{"n":5,"t":"처음 들어가면 뜨는 안내 창","sec":1,"x":"1 / X 버튼으로 닫기 / 코들 Pro(유료) 홍보 창이에요. 닫고 시작하면 돼요. / 2 / 오늘 하루 안 보기 / 같은 날 다시 뜨지 않게 하려면 이 글자를 눌러요. / TIP / 위쪽 초록색 띠도 해커톤 상담 안내예요. 수업과는 상관없어요.","no":"처음 들어가면 유료 콘텐츠 홍보 창이 먼저 뜹니다. 연수에서는 무료 Basic 기준으로 진행하니 닫고 넘어가시면 됩니다.","alt":["코들 접속 직후 뜨는 유료 요금제 홍보 창"]},{"n":6,"t":"첫 화면 한눈에 보기","sec":1,"x":"1 / 교실 · 콘텐츠 · 계정 / 코들의 세 가지 메뉴예요. / 2 / 내 번개 내역 / 코들 이용권(번개)을 확인하는 곳 / 3 / 관리하는 교실 · 가입한 교실 / 내가 만든 교실과 가입한 교실 / 4 / 새 교실 만들기 · 교실 가입하기 / 교실을 만들거나 초대 코드로 들어가요.","no":"교실은 수업을 운영하는 곳, 콘텐츠는 수업자료를 찾고 보관하는 곳, 계정은 인증과 번개를 관리하는 곳입니다. 지금은 관리하는 교실이 없다는 안내가 보이는데, 교사 인증 전이라 새 교실 만들기 버튼도 흐리게 보입니다.","alt":["코들 교실 화면 구성"]},{"n":7,"t":"인증 전에는 잠겨 있어요","sec":2,"x":"1 / 새 교실 만들기 / '요금제 구입 또는 교사 인증 후에 새 교실을 만들 수 있습니다'라는 안내가 떠요. / 2 / 콘텐츠 메뉴 / 같은 안내가 뜨고 들어가지지 않아요. / 3 / 교사 인증하기 / 여기서 바로 인증 신청 양식으로 갈 수 있어요. / TIP / 배움터로 들어온 계정도 처음에는 '인증 필요' 상태였어요.","no":"연수 준비하면서 직접 들어가 보니 교실 만들기와 콘텐츠 메뉴가 모두 잠겨 있었습니다. 배움터 연동만으로는 교사 인증이 되지 않고, 따로 신청해야 한다는 것을 알 수 있었습니다.","alt":["새 교실 만들기에 마우스를 올리면 뜨는 요금제 등록 안내"]},{"n":8,"t":"계정 메뉴에서 인증 상태 확인하기","sec":2,"x":"1 / 계정 → 계정 정보 / 위쪽 계정 메뉴를 누르면 처음 보이는 화면이에요. / 2 / 선생님 회원 · 인증 필요 / 빨간 '인증 필요'가 붙어 있으면 아직 잠긴 상태예요. / 3 / 인증하기 / 구글 설문 양식이 새 탭으로 열려요. / TIP / 이메일 칸 주소(배움터 아이디@aiep.gbe.kr)를 메모해 두세요. 신청할 때 그대로 적어요.","no":"계정 정보의 이메일 칸에는 배움터 아이디 뒤에 aiep.gbe.kr이 붙은 주소가 보입니다. 인증 양식에는 코들에 가입한 이메일을 적게 되어 있으니 이 주소를 그대로 옮겨 적으시면 됩니다. 양식은 구글 설문이라 구글 계정 로그인이 필요했습니다.","alt":["계정 정보 화면의 선생님 회원 인증 필요 표시"]},{"n":9,"t":"교사 인증 신청 방법","sec":2,"x":"1 / 이메일 확인 / 계정 정보의 이메일(…@aiep.gbe.kr)을 확인해요. / 2 / 증빙 준비 / 재직증명서, 교원 자격증, 이름이 보이는 학교 메신저 화면 중 하나 / 3 / 양식 제출 / 인증하기 → 구글 양식에 이메일을 쓰고 증빙을 첨부해요. / 4 / 승인 기다리기 / 영업일 기준 하루 안에 반영되고, 내 번개 내역에 Basic 번개가 생겨요. / 연수 전에 미리 신청해 주세요 / 승인까지 하루쯤 걸려서, 연수 당일에 신청하면 실습을 못 해요. 연수 전에 미리 신청해 주세요. / TIP / 가장 간단한 증빙은 업무용 메신저에서 내 이름이 보이는 화면을 캡처하는 거예요.","no":"인증 방법은 코들 가이드의 선생님 등록 안내를 따랐습니다. 증빙은 재직증명서, 교원 자격증, 이름이 보이는 학교 메신저 화면 가운데 하나면 됩니다. 코들은 입력한 개인정보를 인증 완료 후 24시간 안에 폐기한다고 안내하고 있습니다. 참고로 가이드에는 웨일 스페이스로 가입한 계정은 따로 인증할 필요가 없다고 나와 있습니다.","alt":[]},{"n":10,"t":"번개 = 코들 이용권","sec":2,"x":"1 / 내 번개 내역 / 인증이 끝나면 여기에 Basic 번개가 생겨요. / 2 / 아직은 '내 번개 내역이 없어요' / 인증 전에는 이렇게 비어 있어요. / · / 교실을 만들 때 번개를 할당 / 학생이 1명 가입할 때마다 1개씩 차감되고, 내보내면 돌아와요. / TIP / 번개를 할당하지 않았거나 기간이 지난 교실은 '휴면 교실'이 되어 기능이 제한돼요.","no":"코들은 번개라는 이용권으로 교실을 운영합니다. 교사 인증을 하면 무료 Basic 번개를 받고, 교실을 만들 때 이 번개를 할당합니다. 교실 구성원 수만큼 번개가 차감되고, 학생을 내보내거나 교실을 지우면 다시 돌아온다고 안내되어 있습니다.","alt":["계정의 내 번개 내역 화면"]},{"n":11,"t":"무료 Basic으로 할 수 있는 것","sec":2,"x":"구분 / Basic (교사 인증 · 무료) / Pro (유료) / 학생 수 / 최대 400명 / 구입한 인원만큼 / 활동 종류 / 코딩·퀴즈·활동지 등 모든 활동 / 모든 활동 / 제공 콘텐츠 / 프로그래밍 기초, 교과서 연계 / ＋ 심화, 데이터 분석, AI 기초 / AI 도우미 / 엔트리·활동지 도우미, 복습 퀴즈 생성, 서술형 문제 생성·채점 / ＋ 파이썬 오류 도우미 / 수업 관리 / 활동별 대시보드, 콘텐츠 재구성, 인솔모드 / ＋ 실시간 탭, 교실 기상캐스터 / 우리 학교 수업은 Basic으로 충분해요. 파이썬 오류 도우미와 실시간 모니터링(기상캐스터)만 Pro 전용이에요.","no":"코들 요금제 페이지의 플랜 비교표를 정리했습니다. 교사 인증으로 받는 Basic만으로도 코딩, 퀴즈, 활동지 같은 활동은 모두 쓸 수 있습니다. 파이썬 오류 도우미, 실시간 탭, 교실 기상캐스터는 유료 Pro에서만 됩니다. 학생 수는 요금제 페이지에 400명까지 무료로 나와 있고, 예전 FAQ에는 학기당 300명으로 적혀 있어서 실제 승인 때 안내를 한 번 더 확인하면 좋겠습니다.","alt":[]},{"n":12,"t":"새 교실 만들고 초대 코드 받기","sec":3,"x":"교사 인증 후 열리는 기능 / 1 / 새 교실 만들기 / 교실 메뉴 왼쪽의 '새 교실 만들기'를 눌러요. / 2 / 이름 · 번개 고르기 / 교실 이름을 정하고 할당할 번개(Basic)를 골라요. / 3 / 프로필 이름 / 이 교실에서 쓸 선생님 이름을 정하면 교실이 생겨요. / 4 / 초대 코드 확인 / '초대 코드 확인'을 눌러 나온 코드를 학생에게 알려 줘요. / 초대 코드는 30분 / 초대 코드는 조회한 뒤 30분 동안만 쓸 수 있어요. 지나면 '초대 코드 확인'을 다시 누르면 돼요. / 교실 설정 / 교실 설정에서 교실 이름 바꾸기, 초대 코드 다시 보기, AI 기능 켜고 끄기를 할 수 있어요.","no":"교실 만들기는 코들 가이드 순서대로 정리했습니다. 이 장의 실제 화면은 교사 인증이 승인되면 직접 만들어 보고 스크린샷으로 바꿀 예정입니다. 번개가 없으면 교실을 만들 수 없다는 점, 초대 코드는 조회 후 30분 동안만 유효하다는 점을 같이 안내해 주시면 좋겠습니다.","alt":[]},{"n":13,"t":"학생은 초대 코드로 교실에 들어와요","sec":3,"x":"1 / 3단계로 가입 / 초대 코드 입력 → 프로필 이름 정하기 → 교실 가입 완료 / 2 / 4칸에 초대 코드 입력 / 선생님이 알려 준 코드를 넣어요. / 3 / 다음으로 / 교실에서 쓸 이름을 정하면 끝이에요. / TIP / 학생도 배움터에서 코들을 눌러 들어온 뒤, 교실 → '교실 가입하기'를 눌러요.","no":"교실 메뉴 왼쪽의 교실 가입하기를 누르면 이 창이 뜹니다. 학생들은 선생님이 화면에 띄워 준 초대 코드를 넣고, 교실에서 쓸 이름을 정하면 됩니다. 이름은 번호와 이름처럼 정해 주시면 결과를 보기 편합니다.","alt":["교실 가입하기 창의 초대 코드 입력 칸"]},{"n":14,"t":"공개 수업자료 가져오기","sec":4,"x":"교사 인증 후 열리는 기능 / 1 / 콘텐츠 라이브러리 / 콘텐츠 메뉴에서 검색·태그·학교급으로 자료를 찾아요. / 2 / 열기로 미리 보기 / 자료에 들어 있는 활동을 먼저 살펴봐요. / 3 / ＋ 담기 / 마음에 들면 내 보관함에 담아요. / 4 / 그대로 또는 고쳐서 / 내 보관함 → 열기 → 코스 편집으로 내용을 바꿀 수 있어요. / original 자료 / 'original' 표시가 붙은 자료는 코들이 만들고 자문단 검수를 거친 자료예요. / TIP / '기본 학교급 선택'에서 초등을 골라 두면 콘텐츠 메뉴에 들어갈 때마다 초등 자료만 보여요.","no":"콘텐츠 라이브러리에는 코들이 만든 오리지널 자료와 다른 선생님들이 공유한 자료가 있습니다. 처음에는 직접 만들기보다 공개 자료 하나를 담아서 그대로 써 보시는 것을 권해 드립니다.","alt":[]},{"n":15,"t":"교실에 수업자료 배부하기","sec":4,"x":"교사 인증 후 열리는 기능 / 1 / 배부/철회하기 / 내 보관함에서 자료 표지에 마우스를 올리고 눌러요. / 2 / 교실 고르기 / '배부되지 않은 교실'에서 교실을 체크하고 배부를 눌러요. / 3 / 배부 현황 적용하기 / 오른쪽 아래 이 버튼까지 눌러야 배부가 끝나요. / 철회는 신중하게 / 배부를 철회하면 그 교실에 나간 수업자료가 완전히 삭제돼요. / 숨기기 / 잠깐 감추고 싶을 때는 교실 페이지 → 자료의 '관리' → '숨기기'를 써요.","no":"배부에서 가장 많이 놓치는 부분은 마지막 배부 현황 적용하기 버튼입니다. 표에서 교실을 옮긴 뒤 이 버튼까지 눌러야 배부가 최종 완료된다고 안내되어 있습니다.","alt":[]},{"n":16,"t":"수업자료에 넣을 수 있는 활동","sec":4,"x":"교사 인증 후 열리는 기능 / 파이썬 / 설치 없이 코드 실행, 자동 채점 문제 / 엔트리 / 블록 코딩, 목표 설정, 엔트리 파일 올리기 / 스크래치 / 블록 코딩, 쓰던 스크래치 자료 올리기 / 메이크코드 / 마이크로비트를 연결해 블록 코딩 / 퀴즈 / 연습문제(바로 채점) · 평가(한 번에 제출) / 활동지 / 서술형·설문·자기 평가, AI 튜터 피드백 / 보드 / 의견을 실시간으로 올리고 함께 보기 / PDF / PDF 교안을 올려 이론 설명 / 코답 / 표를 불러와 데이터 분석","no":"수업자료 하나에 이 활동들을 순서대로 넣어 차시를 구성합니다. 초등에서는 엔트리, 퀴즈, 활동지, 보드를 가장 많이 쓰실 것 같습니다. 퀴즈는 연습문제 퀴즈와 평가 퀴즈 두 가지가 있고, 공부방을 켜면 틀린 문제를 맞힐 때까지 다시 풀게 할 수 있습니다.","alt":[]},{"n":17,"t":"수업자료 직접 만들기","sec":4,"x":"교사 인증 후 열리는 기능 / 1 / 새 코스 만들기 / 콘텐츠 → 새 콘텐츠 만들기 → 새 코스 만들기 / 2 / 기본 설정 / 코스 제목, 공개 여부, 설명을 적어요. / 3 / ＋ 새 활동 / 원하는 자리에 퀴즈·엔트리·활동지 등을 넣어요. / 4 / 순서 정리 / 자유 이동으로 순서를 바꾸고, 주제별로 묶을 수 있어요. / 공개는 신중하게 / 한 번 공개한 자료는 다시 비공개로 바꿀 수 없어요. 학생 이름 같은 개인정보가 없는지 먼저 확인해 주세요.","no":"직접 만들 때는 코스라는 묶음 안에 활동을 하나씩 추가합니다. 공개로 설정하면 다른 선생님들도 콘텐츠 라이브러리에서 볼 수 있는데, 다시 비공개로 돌릴 수 없으니 처음에는 비공개로 만드시길 권합니다.","alt":[]},{"n":18,"t":"학생들의 학습 상황 확인하기","sec":5,"x":"교사 인증 후 열리는 기능 / 활동별 대시보드 / Basic 가능 / 활동마다 학생들의 결과를 모아 봐요. / 리더보드 / 자료별 평균 성취율과 성취율 분포, 활동별 성취율 / 인솔모드 / Basic 가능 / 선생님 화면에 맞춰 학생 화면을 함께 움직여요. / 교실 기상캐스터 · 실시간 탭 / Pro 전용 / 접속이 끊기거나 진행이 멈춘 학생을 알려 줘요. / 결과를 볼 때 / 기상캐스터의 '최고'·'흐림'은 진행 상태 표시일 뿐, 학생의 실력 순위가 아니에요.","no":"수업 중에는 활동별 대시보드와 리더보드로 학생들의 결과를 확인할 수 있습니다. 인솔모드는 선생님 화면과 학생 화면을 맞춰 함께 진행하는 기능입니다. 기상캐스터는 접속 끊김이나 진행 정체를 날씨로 보여 주는 Pro 기능인데, 코들 가이드에서도 학생의 우열을 나타내는 지표가 아니라고 설명하고 있습니다.","alt":[]},{"n":19,"t":"AI 도우미 켜고 쓰기","sec":5,"x":"교사 인증 후 열리는 기능 / 켜는 곳 / 교실 설정 → AI 기능 탭 / 활동지 도우미를 켜면 학생 학습 화면에 'AI 튜터에게 묻기' 버튼이 생겨요. / 수업 목적에 맞게 언제든 켜고 끌 수 있어요. / 활동지 도우미 / 학생이 답을 내기 전에 'AI 튜터에게 묻기'로 피드백을 받아요. / Basic 가능 / 복습 퀴즈 생성 / AI로 복습용 퀴즈를 만들어요. / Basic 가능 / 서술형 문제 생성 · 채점 / AI로 서술형 문항을 만들고 채점을 도와요. / Basic 가능 / 엔트리 도우미 / 엔트리 코딩을 AI가 도와요. / Basic 가능 / 파이썬 오류 도우미 / 파이썬 오류 해결을 돕고 맞춤 문제를 추천해요. / Pro 전용","no":"AI 도우미는 교실 설정의 AI 기능 탭에서 켜고 끕니다. Basic에서도 활동지 도우미, 복습 퀴즈 생성, 서술형 문제 생성과 채점, 엔트리 도우미를 쓸 수 있다고 요금제 비교표에 나와 있습니다. 학생이 AI에 지나치게 기대지 않도록 활동 목적에 따라 켜고 끄시면 좋겠습니다.","alt":[]},{"n":20,"t":"쓰기 전에 꼭 알아 둘 점","sec":6,"x":"교사 인증은 미리 / 승인까지 영업일 기준 하루쯤 걸려요. 연수 전에 신청해 주세요. / 학생과 함께 쓰려면 / 배움터 학생 배정과 에듀테크 활용 개인정보 동의서(가정통신문)가 먼저 필요해요. / 지우면 되돌릴 수 없어요 / 교실을 삭제하면 구성원, 배부 자료, 학생이 작성한 내용이 모두 사라져요. / 공개는 신중하게 / 한 번 공개한 수업자료는 다시 비공개로 바꿀 수 없어요.","no":"네 가지만 기억해 주시면 됩니다. 특히 교실 삭제와 배부 철회는 되돌릴 수 없어서, 학기 중에는 교실을 지우기보다 자료를 숨기는 쪽을 권해 드립니다. 학생 배정과 개인정보 동의서는 미리캔버스 때와 같은 절차입니다.","alt":[]},{"n":21,"t":"막힐 때는 오른쪽 아래 ? 버튼","sec":6,"x":"1 / ? 버튼 / 어느 화면에서든 오른쪽 아래에 있어요. / 2 / 채팅 문의 / 코들 담당자에게 바로 물어볼 수 있어요. / 3 / 가이드 / 교실 만들기부터 활동별 사용법까지 정리된 공식 안내예요. / TIP / 콘텐츠 북 보기에서는 코들 콘텐츠 소개 자료를 볼 수 있어요.","no":"이 안내서에 없는 기능은 물음표 버튼의 가이드에서 찾아보시면 됩니다. 교실 만들기, 수업자료 배부, 퀴즈 편집, 실시간 학습 추적까지 단계별로 정리되어 있습니다.","alt":["코들 화면 오른쪽 아래 도움말 메뉴"]},{"n":22,"t":"수업에 이렇게 써 보세요","sec":6,"x":"실과 코딩 수업 / 초등 실과 자료를 담아 배부 → 엔트리로 차시 실습 / 차시 마무리 퀴즈 / 연습문제 퀴즈 + 공부방으로 틀린 문제 다시 풀기 / 서술형 활동지 / 활동지 도우미로 제출 전에 AI 피드백 받기 / 의견 모으기 / 보드에 학생 각자 생각을 올리고 함께 보기 / 처음 써 보신다면 / 공개 수업자료 하나를 담아 그대로 배부해 보는 것부터 시작해 보세요. 직접 만들기는 그다음이에요.","no":"처음부터 자료를 직접 만들기보다는 라이브러리의 초등 실과 자료를 그대로 배부해 보시는 것이 부담이 적습니다. 익숙해지면 퀴즈나 활동지 하나씩 바꿔 가면서 우리 반에 맞게 고쳐 쓰시면 됩니다.","alt":[]},{"n":23,"t":"궁금한 점이 생기시면 교실로 찾아가겠습니다","sec":6,"x":"연수가 끝난 뒤에도 / 교사 인증 함께 하기 / 증빙 준비부터 신청까지 같이 해 드려요. / 교실 · 학생 초대 / 교실 만들기와 초대 코드 안내를 도와드려요. / 개인정보 동의서 / 학생 배정에 필요한 가정통신문을 인쇄해 드려요.","no":"오늘 연수는 여기까지입니다. 교사 인증이 아직이신 분은 오늘 신청해 두시면 영업일 기준 하루 뒤쯤 바로 쓰실 수 있습니다. 막히는 부분이 있으면 언제든 불러 주세요. 교실로 찾아가 함께 처리해 드리겠습니다.","alt":[]}],"offs":[[0,33894],[33894,48122],[82016,57416],[139432,55472],[194904,60246],[255150,49212],[304362,53974],[358336,54884],[413220,63404],[476624,49216],[525840,58908],[584748,59998],[644746,49454],[694200,56084],[750284,52130],[802414,56322],[858736,52064],[910800,59512],[970312,63758],[1034070,52128],[1086198,50608],[1136806,50522],[1187328,39198]],"toffs":[[0,2662],[2662,3968],[6630,4822],[11452,4270],[15722,4850],[20572,4140],[24712,4178],[28890,4348],[33238,4142],[37380,3790],[41170,4530],[45700,4472],[50172,4126],[54298,4224],[58522,3726],[62248,4164],[66412,3544],[69956,4488],[74444,4970],[79414,4130],[83544,3922],[87466,4202],[91668,3852]],"packSize":1226526,"thumbSize":95520}],"total":691,"built":"2026-10-07"};